pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * 12.0; // dead space penalty up to ~120
    } else if post_residual == 0 {
        score -= 40.0; // perfect fit strongly rewarded
    }

    // Reward tight fits relative to capacity (waste ratio).
    score += (post_residual as f64 / bin_capacity as f64) * 30.0;

    // Open-bin pressure: discourage spreading across many bins, but
    // allow opening new bins when the stream is early / few bins open.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (2.0 + 6.0 * (1.0 - progress));

    // Mean residual coupling: prefer bins whose residual is near the mean
    // (balanced packing), penalize outliers.
    score += (bin_residual as f64 - mean_residual).abs() * 0.5;

    // Last chance: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits in the post residual, reward this bin;
    // otherwise penalize leaving a gap the next item cannot use.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0;
        } else if post_residual > 0 {
            score += (next_item_size as f64 - post_residual as f64).min(20.0) * 1.5;
        }
    }

    // New-bin candidate: only attractive when the item is large and no
    // open bin offers a good fit, or many bins are already strained.
    if bin_residual == bin_capacity {
        let poor_alternatives = (fitting_bins_count == 0) as i32 as f64
            + ((fitting_bins_count == 1) as i32 as f64) * 0.5;
        let large_item = item_size as f64 / bin_capacity as f64;
        score = bin_capacity as f64 - poor_alternatives * 55.0 - large_item * 20.0
            + open_bins_count as f64 * 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are too small to host even the
    // smallest plausible item are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual == 0 {
        // Perfect fit: strongly rewarded.
        score -= 80.0;
    } else if post_residual >= 10 && post_residual < 25 {
        // Moderately small gap: mild penalty scaled by gap smallness.
        score += (25 - post_residual) as f64 * 0.8;
    }

    // Reward leaving a gap exactly matching the lookahead item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }
    // Penalize if the lookahead item cannot use the leftover gap.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // Last-chance pressure: if this is the only bin that fits, prefer using it
    // over opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage spreading across many bins when a tight
    // option exists; the more open bins, the stronger the push to fill one.
    score += open_bins_count as f64 * 2.0;

    // Alignment with mean residual: bins already below-average residual are
    // good consolidation targets.
    score -= (mean_residual - post_residual as f64) * 0.5;

    // New-bin candidate: make it attractive only when the item is large
    // relative to typical open-bin residuals (poor fits elsewhere).
    if bin_residual == bin_capacity {
        score = (bin_capacity - item_size) as f64 + 20.0;
        if fitting_bins_count == 1 {
            score += 40.0; // don't abandon the sole fitting bin easily
