pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that no realistic item can use are heavily penalized.
    // Minimum plausible item size is 1, but "usable" gaps should still accommodate a
    // meaningful item; treat gaps below a dead-zone threshold as wasted space.
    let dead_zone = 15.0f64;
    if (post_residual as f64) < dead_zone {
        score += (dead_zone - post_residual as f64) * 6.0;
    }

    // Perfect fits are excellent.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward tight fits relative to the bin's current slack.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= fill_ratio * 20.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: penalize spreading across many bins, encouraging
    // consolidation into existing bins rather than opening new ones.
    score += open_bins_count as f64 * 1.5;

    // New-bin candidate handling: an empty bin should only win when the current
    // bin would be left with awkward dead space or the fit is poor.
    if bin_residual == bin_capacity {
        // Baseline attractiveness of a fresh bin: proportional to item size,
        // since big items leave little residual either way.
        score = (bin_capacity - item_size) as f64 + 5.0;
        // If the current placement would leave a usable gap for the next item,
        // make the fresh bin less attractive.
        if post_residual >= next_item_size && next_item_size > 0 {
            score += 15.0;
        }
        // If opening a new bin is nearly inevitable (few fitting alternatives),
        // make it more attractive.
        if fitting_bins_count <= 2 {
            score -= 10.0;
        }
    } else {
        // Reward leaving a residual that exactly fits the lookahead item.
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 30.0;
        } else if next_item_size > 0 && post_residual >= next_item_size {
            // Small bonus for leaving a gap usable by the next item.
            score -= (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64) * 5.0;
        }
    }

    // Late in the stream, waste matters less than bin count; tighten consolidation.
    let progress = step_index as f64 / total_items as f64;
    score += progress * (dead_zone - post_residual as f64).max(0.0) * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in (0,10) are nearly unusable
    // for future items (min size 1..100 stream, but small gaps waste capacity).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // heavy penalty for creating tiny dead gaps
    }
    // Perfect fit is strongly rewarded.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward leaving a residual that exactly accommodates the lookahead item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }
    // Penalize residuals that are too small for the next item but nonzero.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    }

    // Open-bin pressure: discourage scattering items across many bins
    // unless the fit is genuinely good.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (2.0 + 3.0 * progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: an empty bin is a fallback; prefer it only
    // when the fit into open bins would be poor (large post_residual).
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, softened late in the stream.
        score = bin_capacity as f64 * 0.5 + open_bins_count as f64 * 2.0 - 20.0 * progress;
        // If it's a perfect fit for the next item too, opening is fine.
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 20.0;
        }
    }

    // Mild tie-breaker: prefer bins whose residual is already small
    // (best-fit flavor beyond raw post_residual).
    score += (mean_residual - bin_residual as f64).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual can
    // exactly or nearly accommodate the next item.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        score -= 300.0 - gap * 2.5;
        if gap == 0.0 {
            score -= 400.0; // chain of perfect fits
        }
    } else if next_item_size > 0 {
        // Penalize dead space that the next item cannot use,
        // worse when the leftover is small (unusable sliver).
        let dead = post_residual as f64;
        let next = next_item_size as f64;
        if dead < next {
            score += (next - dead) * 1.5;
        }
    }

    // Relative-to-mean coupling: prefer bins tighter than average.
    score += (mean_residual - bin_residual as f64) * 0.8;

    // Last-chance bin: strongly favor using it to avoid opening a bin.
    if fitting_bins_count == 1 {
        score -= 150.0;
    }

    // Mild penalty for spreading across many open bins late in stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * 0.3 * (1.0 - progress);

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        score += 120.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 40.0; // fresh bin still usable for next item
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Reward tight fits
    score -= 12.0 * (item_size as f64 / bin_residual.max(1) as f64);

    // Penalize dead space that can't fit the smallest plausible item
    if post_residual < 10 {
        score -= 25.0; // near-perfect fill
    } else if post_residual < next_item_size.max(1) as f64 && next_item_size > 0 {
        score += 8.0; // residual useless for lookahead item
    }

    // Lookahead: reward bins whose post-residual fits next item well
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size as u32) as f64;
        score -= 6.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        score += 4.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 3 {
        score += 2.0 * (fitting_bins_count as f64 - 3.0);
    }

    // Late in stream: consolidate, prefer fuller bins
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Penalize bins far from mean residual (fragmentation control)
    score += 0.15 * (post_residual as f64 - mean_residual).abs();

    // New-bin candidate: only attractive when open bins are crowded or fit is poor
    if bin_residual == bin_capacity {
        let crowding = if open_bins_count > 0 { open_bins_count as f64 } else { 0.0 };
        let poor_fit = (item_size as f64 / bin_capacity as f64) < 0.5;
        score = 55.0 - 3.0 * crowding * progress - if poor_fit { 10.0 } else { 0.0 };
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues modulo small divisors
    // reveal "nice" leftover sizes that pair well with common item sizes.
    let pr = post_residual;
    let r4 = (pr % 4) as f64;
    let r5 = (pr % 5) as f64;
    let r10 = (pr % 10) as f64;
    let r20 = (pr % 20) as f64;

    // Penalize awkward residues (dead space unlikely to be filled exactly).
    score += 0.6 * r4 + 0.8 * r5 + 1.0 * r10 + 0.5 * r20;

    // Reward exact fits and near-perfect harmonic alignment.
    if pr == 0 {
        score -= 50.0;
    } else if pr % 10 == 0 {
        score -= 6.0;
    } else if pr % 5 == 0 {
        score -= 3.0;
    }

    // Integer-division thresholds: how many "next items" fit the leftover.
    if next_item_size > 0 {
        let fits_next = pr / next_item_size;
        if fits_next >= 1 {
            score -= 4.0 * fits_next as f64;
        }
        // Perfect pairing: leftover exactly matches next item size.
        if pr == next_item_size {
            score -= 12.0;
        }
        // Leftover slightly above next item: small dead space risk.
        if pr > next_item_size && pr - next_item_size < 5 {
            score -= 2.0;
        }
        // Leftover just below next item size: unusable sliver.
        if pr > 0 && pr < next_item_size && pr < 10 {
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when the current item is
    // large and open bins are fragmented (high mean residual spread).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score = (bin_capacity as f64) * 0.5
            + fragmentation * 0.3
            + item_size as f64 * 0.4
            - progress * 10.0
            - (open_bins_count as f64) * 0.5;
        // Large items early: fresh bin gives clean space.
        if item_size >= 60 {
            score -= 8.0;
        }
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 5.0; // fresh bin can host current + next item together
        }
    }

    // Mild preference for tighter bins overall (low residual = well-packed).
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // Small global pressure to prefer existing bins as stream progresses.
    score += progress * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < 10 {
        score -= 300.0;
    }

    // 2-step lookahead: reward if next item exactly fills post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 900.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 200.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot fit here; penalize small post_residual dead space
            let dead = post_residual as f64;
            if dead < next_item_size as f64 {
                score += 0.5 * (next_item_size as f64 - dead);
            }
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score += 0.5 * (mean_residual - bin_residual as f64);

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // Penalize opening a new bin when decent fits exist
    if bin_residual == bin_capacity {
        score += 40.0 + 0.3 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size <= bin_residual {
            score -= 25.0; // fresh bin useful for the next item too
        }
    }

    // Late-stream consolidation: prefer filling existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual), with quadratic penalty on waste.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64 * 4.0);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, strongly favor.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual > next_item_size {
            // Chain-fit: mild reward proportional to how snug the chain is.
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot fit here; penalize leaving large unusable gaps
            // relative to the smallest plausible item.
            if post_residual < 10 {
                score -= 8.0; // dead space too small for any item is fine
            } else {
                score += (post_residual as f64) * 0.3;
            }
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Many fitting bins: competition is high, mildly prefer the emptiest-ish bin
    // (best-fit already handled); penalize bins far below mean residual to
    // consolidate space.
    if fitting_bins_count > 2 {
        let dev = mean_residual - bin_residual as f64;
        score += dev * 0.2;
    }

    // New-bin candidate logic: opening a new bin is attractive only when the
    // item is large (would leave open bins with big residuals anyway) or when
    // open bins are already crowded / few bins fit.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let item_frac = item_size as f64 / bin_capacity as f64;
        let new_bin_bonus = 40.0 * item_frac
            + 30.0 * (1.0 - progress)
            + if fitting_bins_count <= 2 { 20.0 } else { 0.0 }
            + if post_residual > 0 && post_residual < 10 { 15.0 } else { 0.0 };
        score -= new_bin_bonus;
    } else {
        // Using an existing bin: reward grows with stream progress (consolidate late).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * progress;
    }

    // Penalize creating residuals that no typical item can use efficiently.
    if post_residual > 0 && post_residual < 5 {
