    // post residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 20.0;
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / cap);
        } else {
            // next item won't fit here; mild penalty for wasting a good bin
            score += 3.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a
    // new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0 + 0.05 * (pr as f64);
    }

    // New-bin candidate: only attractive when no open bin fits well
    // (large item, many open bins with fragmented residuals).
    if bin_residual == bin_capacity {
        let base = 0.35 * cap; // neutral residual of a fresh bin
        score = base
            + if next_item_size > 0 && next_item_size <= item_size { -6.0 } else { 0.0 }
            + if fitting_bins_count == 0 { -25.0 } else { 0.0 }
            + if mean_residual < 0.25 * cap { -8.0 } else { 4.0 }
            + 0.02 * open_bins_count as f64;
    }

    // Slight progression tilt: early in the stream prefer tighter packing,
    // late in the stream prefer closing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 2.0 * (progress - 0.5) * (pr as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    // A post_residual that cannot fit even the smallest plausible item is wasted space.
    let dead_threshold = 10u32;
    if post_residual > 0 && post_residual < dead_threshold {
        score += 60.0 + (dead_threshold - post_residual) as f64 * 4.0;
    }

    // Penalize post_residual that is below the next item's size (won't chain),
    // scaled by how "close" it is to being useful.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 12.0 + (next_item_size - post_residual) as f64 * 0.5;
        } else {
            // Reward residual that can host the next item.
            score -= 8.0;
        }
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; favor tight fills.
    let open_pressure = open_bins_count as f64 / 20.0;
    score += open_pressure * (post_residual as f64 / bin_capacity as f64) * 30.0;

    // New-bin candidate: only attractive when current bin would leave a bad gap
    // or there are no good options; an empty bin has full residual, so make it
    // costly unless the fit here is poor.
    if bin_residual == bin_capacity {
        score += 35.0;
        // Allow new bin late in stream when open bins are crowded.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 10.0;
    }

    // Slight preference for bins tighter than the mean residual (better fills).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post-residual matches the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item fits here afterwards -> strong reward, scaled by tightness of match.
            let match_quality = 1.0 - ((post_residual - next_item_size) as f64) / (bin_capacity as f64);
            score -= 15.0 * match_quality;
            // Perfect chain (post_residual == next_item_size) is ideal.
            if post_residual == next_item_size {
                score -= 10.0;
            }
        } else {
            // Next item cannot use the leftover -> penalize dead space, worse when small.
            let dead = post_residual as f64;
            score += 0.05 * dead * dead / (bin_capacity as f64);
            // Extra penalty if next item nearly fits (wasted opportunity).
            if post_residual > 0 && next_item_size - post_residual <= 10 {
                score += 5.0;
            }
        }
    }

    // Relative-to-mean coupling: prefer bins tighter or looser than average contextually.
    let res = bin_residual as f64;
    if mean_residual > 0.0 {
        let rel = res / mean_residual;
        // Tight bins (below mean residual) get rewarded for being filled now.
        if rel < 1.0 {
            score -= 4.0 * (1.0 - rel);
        } else {
            score += 2.0 * (rel - 1.0);
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when no open bin is a good fit.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a new bin.
        score += 10.0;
        // If item is large, filling a fresh bin is fine; small items should go into open bins.
        let frac = item_size as f64 / bin_capacity as f64;
        score -= 12.0 * frac;
        // If several bins fit the item, discourage opening a new one.
        if fitting_bins_count > 1 {
            score += 8.0 * (fitting_bins_count as f64 - 1.0);
        }
        // Lookahead: if next item is large, a fresh bin gives flexibility.
        if next_item_size > 0 && next_item_size >= 50 {
            score -= 6.0;
        }
        // Late in the stream, avoid spawning bins with big leftovers.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 5.0 * progress * (1.0 - frac);
    }

    // Slight preference for filling bins almost exactly.
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score += 3.0 * tightness * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: strongly discount small post-residuals (non-linearly).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 55.0 * tightness * tightness;

    // Penalize dead space: residuals too small for likely future items
    // (min item size assumed ~10) are nearly unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post-residual,
    // this is a perfect chain — reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 25.0 * fill * fill;
        } else {
            // Next item won't fit here; small waste penalty scaled by waste size.
            let waste = (next_item_size - post_residual) as f64;
            score += 0.35 * waste;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate handling: an empty bin is only attractive when the item
    // is large relative to capacity or no open bin fits well.
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / bin_capacity as f64;
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let early = 1.0 - (step_index as f64 / (total_items.max(1) as f64));
        // Prefer new bins early on or for big items; penalize when open bins exist
        // and could still absorb the item.
        score += 30.0 * (1.0 - frac) + 22.0 * pressure;
        score -= 15.0 * early;
        if open_bins_count > 0 && fitting_bins_count > 0 {
            score += 20.0;
        }
        if item_size >= 80 {
            score -= 35.0;
        }
    }

    // Global state: many open bins with high mean residual → encourage
    // consolidating into existing bins rather than spreading.
    if open_bins_count > 3 {
        let consolidation = mean_residual / bin_capacity as f64;
        if bin_residual < bin_capacity {
            score -= 10.0 * consolidation;
        }
    }

    // Mild time-horizon term: late in the stream, prefer closing bins tightly
    // (minimize leftover) since fewer future items remain to fill gaps.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 8.0 * progress * tightness;

    // Slight penalty proportional to remaining residual to break ties toward fuller bins.
    score += 0.05 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = it / cap;
    let pr_norm = pr / cap;

    // Smooth polynomial base: reward tight fits (small post_residual), with
    // non-linear coupling to stream progress.
    let mut score = pr_norm.powf(1.0 + 1.5 * progress) * (1.0 + 0.5 * progress);

    // Quadratic coupling between item size and progress: large items early
    // should prefer filling existing bins; small items later can open bins.
    score -= 0.3 * fit_ratio * (1.0 - fit_ratio) * (1.0 - progress);

    // Dead-space penalty: residual too small for typical future items
    let dead = (pr / 100.0).max(0.0);
    score += 0.8 * (1.0 - dead).powi(3) * dead * 10.0;

    // Last-chance bonus: strongly prefer using a bin when it's the only fit
    if fitting_bins_count == 1 {
        score -= 5.0 + 3.0 * progress;
    }

    // Lookahead: if next item fits exactly into post_residual, reward heavily
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let leftover = (pr - nxt) / cap;
            score -= 2.5 * (1.0 - leftover).powi(2);
        } else {
            score += 0.5 * (nxt / cap);
        }
    }

    // Mean residual coupling: prefer bins deviating below the mean residual
    // (filling the emptiest bins first), smoothly weighted.
    score += 0.2 * (pr - mean_residual) / cap;

    // New-bin candidate: penalize slightly so open bins with decent fit win,
    // but relax as stream progresses and open bins accumulate.
    if bin_residual == bin_capacity {
        score += 3.0 - 2.0 * progress + 0.05 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small" residue classes (hard to reuse) are penalized.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Fraction of capacity left after placement.
    let post_frac = post / cap;

    // Integer-division thresholds: classify post_residual into buckets.
    // Bucket 0: post == 0 (perfect fit) -> strong reward.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        // dead space: too small for any item (min size 1..100 unknown, but
        // small leftovers are low value) -> penalize moderately.
        score += 8.0;
    } else if post_residual <= 25 {
        // awkward class: only small items fit later
        score += 4.0;
    } else if post_residual <= 50 {
        // mid class: decent
        score -= 3.0;
    } else {
        // large residual: flexible bin, reward
        score -= 6.0;
    }

    // Modulo-10 harmonic class of post_residual: certain residue classes
    // align with common item size multiples (10s), favoring them.
    let post_mod = post_residual % 10;
    if post_mod == 0 {
        score -= 5.0;
    } else if post_mod >= 7 {
        score += 2.5;
    }

    // Lookahead coupling: if the next item fits exactly into the post
    // residual, this is a harmonic match -> big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // next fits: mild reward scaled by how well it matches
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 - 0.15 * slack;
            // modulo harmony: next_item_size divides post residual class
            if post_residual % next_item_size == 0 && next_item_size > 0 {
                score -= 6.0;
            }
        } else {
            // next item cannot use this bin's leftover: penalize proportionally
            score += 3.0;
        }
    }

    // Last-chance bin: if only one open bin fits, prefer using it to avoid
    // opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: an empty bin has huge residual; only favor
    // it when current bins are crowded or the fit is terrible.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // base penalty so new bins are used only when justified
        score += 18.0;
        // if open bins are nearly full on average, opening is fine
        let mean_frac = mean_residual / cap;
        if mean_frac < 0.25 {
            score -= 25.0;
        }
        // late in stream, prefer consolidating less
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
        // large item with few fitting bins -> new bin reasonable
        if item_size > bin_capacity / 2 && fitting_bins_count <= 1 {
            score -= 15.0;
        }
    }

    // Tightness reward: item fills a large share of the bin.
    let fill = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fill;

    // Bin congestion: many open bins -> prefer filling existing ones.
    score += 0.4 * open_bins_count as f64;

    // Deviation from mean residual: prefer bins tighter than average.
    score += 0.05 * (post - mean_residual);

    // Small progress-dependent drift to break ties deterministically.
    score += 0.001 * ((step_index % 7) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftover gaps (1..=12) are effectively
    // unusable for typical items (min size 1, but small gaps rarely match future
    // demand), so penalize them hard beyond their raw value.
    if post_residual > 0 && post_residual <= 12 {
        score += (13 - post_residual as i32) as f64 * 6.0;
    }
    // Perfect fit is strongly rewarded.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Reward tight fits proportionally to fill ratio.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= fill * 10.0;

    // Open-bins pressure: many open bins -> prefer consolidating into existing
    // bins rather than spreading; scale with progress through the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 0.35 * (0.5 + 0.5 * progress);

    // Pull score toward mean residual: bins far above mean residual are
    // attractive targets (use up large leftovers), bins below mean are penalized.
    score += (mean_residual - bin_residual as f64) * 0.25;

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward;
    // if post residual is nonzero but too small for the next item, penalize.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 8.0;
        }
    }

    // New-bin candidate: only attractive when the current item is large and
    // no open bin offers a decent fit; otherwise make fresh bins unattractive.
    if bin_residual == bin_capacity {
        let poor_fit = fitting_bins_count == 0 || (item_size as f64 / bin_residual as f64) < 0.5;
        if poor_fit {
            score -= 15.0;
        } else {
            score += 25.0 + open_bins_count as f64 * 0.5;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: this bin's post-residual exactly fits the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Post-residual can still hold the next item: good chaining potential,
    // but prefer the tightest such fit (smaller post_residual wins naturally).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // Dead space: post_residual too small for the next item AND small in absolute
    // terms -> wasted capacity. Penalize strongly.
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.8;
    }

    // Very small unusable sliver (< 10) is pure waste regardless of lookahead.
    if post_residual < 10 {
        score += 20.0;
    }

    // Compare against mean residual: placing into a bin that stays near the
    // mean keeps balance; a bin far above mean is the natural "dump" target.
    let post_f = post_residual as f64;
    if post_f > mean_residual {
        score -= (post_f - mean_residual) * 0.3;
    } else {
        score += (mean_residual - post_f) * 0.3;
    }

    // Last-chance bin: if this is the only bin that fits, using it avoids
    // opening a new bin -> reward.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // no open bin offers a good fit (large item, poor residuals).
    if bin_residual == bin_capacity {
        // Base reluctance to open new bins.
        score += 30.0;
        // But if item nearly fills a fresh bin perfectly (item_size close to
        // capacity) or no other bin fits, new bin becomes attractive.
        if item_size >= bin_capacity - 5 {
            score -= 80.0;
        }
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // Late in the stream, prefer consolidating into existing bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 20.0;
    }

    // Tight fit reward: little slack left after placement relative to item size.
    let tightness = (item_size as f64) / (bin_residual.max(1) as f64);
    score -= tightness * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual), with quadratic penalty on waste.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64 * 4.0);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, strongly favor.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual > next_item_size {
            // Chain-fit: mild reward proportional to how snug the chain is.
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot fit here; penalize leaving large unusable gaps
            // relative to the smallest plausible item.
            if post_residual < 10 {
                score -= 8.0; // dead space too small for any item is fine
            } else {
                score += (post_residual as f64) * 0.3;
            }
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Many fitting bins: competition is high, mildly prefer the emptiest-ish bin
    // (best-fit already handled); penalize bins far below mean residual to
    // consolidate space.
    if fitting_bins_count > 2 {
        let dev = mean_residual - bin_residual as f64;
        score += dev * 0.2;
    }

    // New-bin candidate logic: opening a new bin is attractive only when the
    // item is large (would leave open bins with big residuals anyway) or when
    // open bins are already crowded / few bins fit.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let item_frac = item_size as f64 / bin_capacity as f64;
        let new_bin_bonus = 40.0 * item_frac
            + 30.0 * (1.0 - progress)
            + if fitting_bins_count <= 2 { 20.0 } else { 0.0 }
            + if post_residual > 0 && post_residual < 10 { 15.0 } else { 0.0 };
        score -= new_bin_bonus;
    } else {
        // Using an existing bin: reward grows with stream progress (consolidate late).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * progress;
    }

    // Penalize creating residuals that no typical item can use efficiently.
    if post_residual > 0 && post_residual < 5 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: prefer tight fits (small post_residual), scaled by stream progress
    let mut score = pr;

    // Smooth non-linear coupling: post_residual matters more later in the stream
    // (dead space is less recoverable as the stream matures)
    let progress_weight = 0.5 + 2.5 * progress * progress;
    score += progress_weight * pr * (pr / cap);

    // Reward filling a bin almost perfectly (post_residual near 0), smoothly
    let tightness = 1.0 - (pr / cap);
    score -= 12.0 * tightness * tightness * tightness;

    // Penalize leaving a residual that no typical item can use (dead space):
    // quadratic penalty for residuals below the smallest plausible item size (1..100 range)
    if pr < 10.0 {
        score += 20.0 * (10.0 - pr) * (10.0 - pr) / cap;
    }

    // Lookahead coupling: if the next item fits the post residual, reward it smoothly
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let fit_quality = 1.0 - ((pr - nx) / cap);
            score -= 6.0 * fit_quality * fit_quality;
        } else {
            // next item won't fit here: mild penalty growing with overshoot
            let over = (nx - pr) / cap;
            score += 4.0 * over * over * cap;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    } else if fitting_bins_count > 1 {
        // crowded choice: slight penalty to prefer tighter competition resolution
        score += 1.5 * (fitting_bins_count as f64).ln();
    }

    // Prefer bins with residual below mean (consolidate emptier space)
    score += 0.3 * (pr - mean_residual);

    // New-bin candidate handling: an empty bin has pr == cap; make it unattractive
    // unless all open bins are poor fits (fitting_bins_count == 0 handled by caller,
    // but if called with residual==capacity, push score up smoothly)
    if bin_residual == bin_capacity {
        score = 60.0 + 40.0 * progress - (item_size as f64) * 0.2;
        if fitting_bins_count == 0 {
            score = -10.0; // no open bin fits: open a new one
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residuals divisible by common size
    // classes (10, 20, 25, 50) are more reusable than "dead" residuals.
    let r = post_residual;
    let mut reusability = 0.0f64;
    if r % 50 == 0 { reusability += 18.0; }
    else if r % 25 == 0 { reusability += 12.0; }
    else if r % 20 == 0 { reusability += 10.0; }
    else if r % 10 == 0 { reusability += 7.0; }
    else if r % 5 == 0 { reusability += 3.0; }
    score -= reusability;

    // Lookahead coupling: reward if the next item's harmonic class matches
    // the post-residual class (exact or via integer-division thresholds).
    if next_item_size > 0 {
        if next_item_size == r {
            score -= 25.0; // perfect chaining
        } else if next_item_size <= r {
            // next item fits: reward proportional to how well it fills
            let fill = next_item_size as f64 / r.max(1) as f64;
            score -= 12.0 * fill;
            if r % next_item_size.max(1) == 0 {
                score -= 6.0; // exact divisibility: multiple future items tile it
            }
        } else {
            // next item won't fit here: penalize small leftover classes
            score += 4.0;
            if r < 10 { score += 10.0; } // dead space below min item size
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: only attractive if it offers a large fresh residual
    // relative to current mean residual across open bins.
    if bin_residual == bin_capacity {
        let mean_r = mean_residual;
        if post_residual as f64 > mean_r + 20.0 {
            score -= 10.0;
        } else {
            score += 20.0; // prefer reusing open bins otherwise
        }
    }

    // Small global pressure: early in the stream, be frugal with new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 5.0 * (1.0 - progress);
    }

    // Penalize near-miss residuals (just below common item sizes 30/50/70)
    for t in [30u32, 50u32, 70u32] {
        if r > 0 && r < t && r >= t - 8 {
            score += 6.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are too small to be useful later are wasteful.
    // Anything in (0, 10] is nearly unusable since items are >= 1 but small gaps
    // rarely match future items; penalize quadratically.
    if post_residual > 0 && post_residual <= 12 {
        score += (13.0 - post_residual as f64) * (13.0 - post_residual as f64) * 2.0;
    }

    // Perfect fit: strongly reward.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 15.0; // near-perfect fit, still very reusable
    }

    // Tight fit reward: item fills a large fraction of the bin residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 20.0;

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Lookahead: if the next item fits in the post residual, reward keeping
    // this bin open with that much space.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 5.0; // gap blocks the next item
        }
    }

    // Open-bin pressure: discourage spreading across many bins unless the fit is good.
    score += open_bins_count as f64 * 1.5;

    // New-bin candidate handling: a fresh empty bin is only attractive when
    // the item is large relative to capacity or existing residuals are poor.
    if bin_residual == bin_capacity {
        let base = 55.0;
        // If mean residual is high, existing bins are roomy; penalize new bin less.
        let adj = if mean_residual > item_size as f64 * 1.5 { -10.0 } else { 10.0 };
        score += base + adj - fill_ratio * 10.0;
        if fitting_bins_count == 1 {
            score += 60.0; // don't open new bin when an existing bin is the only option
        }
    }

    // Progress: later in the stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of next item into post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0; // perfect 2-item packing
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // penalize leftover slack after hypothetically placing next item
            score += slack * 0.6;
            if slack <= 10.0 {
                score -= 8.0; // near-perfect chain
            }
        } else {
            // next item cannot fit here; mild penalty scaled by overflow gap
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.15;
        }
    } else {
        // last item: prefer minimal final residual
        score += 5.0;
    }

    // Relative-to-mean coupling: bins tighter than mean are more valuable
    if (bin_residual as f64) > mean_residual {
        score += ((bin_residual as f64) - mean_residual) * 0.3;
    } else {
        score -= (mean_residual - bin_residual as f64) * 0.1;
    }

    // Last-chance bonus: only bin that fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Penalize opening a new bin when decent existing fits exist
    if bin_residual == bin_capacity {
        let waste_if_new = (bin_capacity - item_size) as f64;
        score += 15.0 + waste_if_new * 0.2;
        // but if next item pairs well with current item in a fresh bin, soften
        if next_item_size > 0 && (item_size + next_item_size) <= bin_capacity {
            let pair_slack = (bin_capacity - item_size - next_item_size) as f64;
            if pair_slack <= 10.0 {
                score -= 30.0;
            }
        }
    }

    // Dead-space penalty: tiny residuals are hard to use later
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 1.5;
    }

    // Slight preference for consolidating when many bins are open
    score += (open_bins_count as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize large dead space nonlinearly.
    if post_residual > 0 {
        score += (post_residual as f64).powf(1.35) * 0.08;
    }

    // Reward tight fits.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= fit_ratio * 12.0;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits in the post-residual, reward this placement.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 8.0;
    }
    // Penalize if next item would leave the bin almost useless but not usable.
    if next_item_size > 0 && next_item_size > post_residual && post_residual < 10 {
        score += 6.0;
    }

    // Time horizon: early in stream, be more selective (prefer good fits);
    // late in stream, avoid opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0;

    // Global state: many open bins with high mean residual -> prefer reusing bins.
    if bin_residual as f64 >= mean_residual {
        score -= 3.0;
    } else {
        score += 2.0;
    }
    if open_bins_count > 4 {
        score -= (open_bins_count as f64).min(10.0) * 0.5;
    }

    // New-bin candidate: penalize opening a new bin unless residuals are all low.
    if bin_residual == bin_capacity {
        let avg_open_residual = if open_bins_count > 0 { mean_residual } else { 0.0 };
        let scarcity = (avg_open_residual / bin_capacity as f64).min(1.0);
        score += 18.0 - scarcity * 22.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score += 4.0; // keeping space for a bigger next item
        }
    }

    // Small absolute dead-space bonus for exact fills.
    if post_residual == 0 {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with smooth polynomial shaping.
    let mut score = norm_pr * norm_pr * (1.0 + 2.0 * progress) + 0.5 * norm_pr;

    // Reward tight fits (small post_residual) more strongly later in the stream.
    score -= (1.0 - norm_pr).powi(3) * (0.5 + progress);

    // Penalize dead space that cannot fit a plausible next item.
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if pr < ns {
            score += (ns - pr) / cap * (1.0 + progress);
        } else {
            // Reward leaving room exactly usable by the next item (smooth coupling).
            score -= (1.0 - ((pr - ns) / cap).powi(2)) * 0.3;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 1.0 + 0.5 * progress;
    } else if fitting_bins_count > 1 {
        // Mild penalty when many alternatives exist, scaled by residual quality.
        score += 0.05 * (fitting_bins_count as f64 - 1.0) * norm_pr;
    }

    // Coupling with mean residual: prefer bins whose residual differs favorably from mean.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 0.2 * dev * dev - 0.15 * dev * (1.0 - progress);

    // Prefer consolidating into fewer bins when many are open.
    score += 0.01 * open_bins_count as f64 * norm_pr;

    // New-bin candidate: penalize opening a new bin unless it's genuinely better
    // (empty bin has norm_pr = 1, which already scores high; add extra guard).
    if bin_residual == bin_capacity {
        score += 0.6 + 0.4 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: small dead space is bad
    if post_residual < 10 {
        score += 60.0; // dead space below min item size is unusable
    }

    // Integer division thresholds: post_residual in harmonic classes of 10
    let post_class = post_residual / 10;
    score -= (post_class as f64) * 3.0;

    // If next item fits into post_residual, big reward (chain fit)
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 40.0 + (post_residual - next_item_size) as f64;
    } else if next_item_size > 0 {
        // next item won't fit here: penalize by wasted potential
        score += (next_item_size as f64) * 0.3;
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        // Opening a new bin is attractive when current item is small relative to capacity
        let frac = item_size as f64 / bin_capacity as f64;
        if frac < 0.35 {
            score -= 25.0;
        } else {
            score += 20.0;
        }
        // discourage opening new bins early in the stream
        let progress = step_index as f64 / total_items as f64;
        score += (1.0 - progress) * 10.0;
    }

    // Coupling with mean residual: prefer bins tighter than average
    score += (mean_residual - bin_residual as f64) * 0.5;

    // Modulo arithmetic on item size: items in coarse classes pack better together
    let m = item_size % 10;
    if m > 5 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual gaps that are too small to hold
    // any plausible item are pure waste — penalize them heavily.
    if post_residual > 0 {
        if post_residual < 10 {
            // Unusable sliver: dead space.
            score += 200.0 * (10.0 - post_residual as f64);
        } else if post_residual < 20 {
            // Marginal gap: likely dead unless tiny items exist.
            score += 40.0;
        } else if post_residual >= 40 && post_residual <= 60 {
            // Comfortable residual: can host mid/large future items.
            score -= 15.0;
        }
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Next-item lookahead: reward leaving room for the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            if slack < 10 {
                score -= 30.0; // near-exact two-item packing
            } else {
                score -= 8.0;
            }
        } else {
            // This placement strands the next item elsewhere.
            score += 12.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Open-bin pressure: when many bins are open, prefer consolidating into
    // tight fits rather than spreading; when few bins, be choosier.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * (post_residual as f64 / bin_capacity as f64) * 20.0;

    // Progress coupling: late in the stream, be more tolerant of residual gaps
    // since fewer items remain to fill them.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 10.0;

    // Prefer bins whose residual is already below average (tighter bins).
    score += (mean_residual - bin_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when the next item exactly fills this bin.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        // Perfect 2-step match => strong reward.
        score -= 60.0 * (1.0 - diff / (bin_capacity as f64)).max(0.0);
        // Exact match gets an extra bonus.
        if post_residual == next_item_size {
            score -= 40.0;
        }
        // Penalize leaving residual that is too small for the next item (dead space risk).
        if post_residual < next_item_size && post_residual > 0 {
            score += 25.0;
        }
    } else {
        // Last item: prefer tightest fit.
        score -= 30.0;
    }

    // Compare against mean residual: bins tighter than average are more attractive.
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Penalize opening a new bin when decent open bins exist (new-bin candidate detection).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let good_fit_exists = fitting_bins_count > 0
            && open_bins_count > 0
            && (bin_residual as i64 - item_size as i64 - post_residual as i64).abs() as u32 == 0;
        let _ = good_fit_exists;
        let waste = bin_capacity as f64 - item_size as f64;
        // New bin only attractive if item is large relative to capacity or many bins open.
        score += 70.0 - 0.3 * waste - 60.0 * progress;
        if item_size > 80 {
            score -= 50.0;
        }
        if open_bins_count == 0 {
            score -= 100.0; // must open first bin
        }
    }

    // Slight preference for tighter bins overall.
    score += 0.2 * (bin_residual as f64 / bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: prefer bins where the item fills a large fraction of the residual.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fit_ratio;

    // Penalize unusable dead space: small post-residuals that nothing can use are fine,
    // but moderate leftover space is wasted unless a known next item fits.
    if post_residual > 0 {
        if next_item_size > 0 && post_residual >= next_item_size {
            // Keep space for the lookahead item: reward leaving exactly a useful gap.
            let gap_use = next_item_size as f64 / post_residual as f64;
            score -= 20.0 * gap_use;
        } else {
            // Dead space that the known next item cannot use: penalize.
            score += 0.35 * post_residual as f64;
        }
    } else {
        // Perfect fill is the best outcome.
        score -= 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Opening a new bin is only attractive when the item is large and would
    // otherwise leave poor fragmentation, or when global residuals are bloated
    // but this item deserves fresh space.
    if bin_residual == bin_capacity {
        // Mild default preference against opening new bins.
        score += 12.0;
        // But if the item is huge relative to capacity, a fresh bin is reasonable.
        if item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 15.0;
        }
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 25.0 * progress;
    }

    // Global state coupling: when mean residual across open bins is high,
    // we should consolidate into existing bins rather than fragment further.
    if bin_residual != bin_capacity {
        if mean_residual > post_residual as f64 {
            score -= 8.0 * (mean_residual - post_residual as f64).min(20.0) / 20.0;
        }
        // Too many open bins: encourage closing them out via tight placements.
        score += 0.5 * open_bins_count as f64 * (1.0 - fit_ratio);
    }

    // Lookahead safety: if the next item would fit better in this bin's post
    // residual than anywhere else, add a small coupling bonus.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 10.0 / (1.0 + slack);
    }

    // Small time-horizon modulation: early in the stream, be more exploratory
    // (favor new bins slightly less penalized); later, consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 6.0 * progress * post_residual as f64 / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_post = post / cap;

    // Base: prefer small post residual, non-linearly
    let mut score = norm_post.powf(2.0 + 2.0 * progress) * cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let coupling = post * norm_post * (1.0 - progress);
    score += 0.35 * coupling;

    // Penalize large dead space more heavily late in the stream
    score += norm_post.powi(4) * cap * progress;

    // Reward tight fits (small post residual) especially when lookahead matches
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post - nxt).abs();
        score -= 0.5 * (1.0 - gap / cap).max(0.0) * (1.0 + progress);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // Mild penalty for spreading across many open bins vs consolidating
    score += 0.05 * open_bins_count as f64 * norm_post;

    // Prefer bins whose residual deviates favorably from the mean residual
    score -= 0.1 * (mean_residual - post) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes of post_residual: dead space in the lowest decade is worst.
    let class = post_residual / 10;
    match class {
        0 => {
            if post_residual == 0 { score -= 45.0; }      // perfect fit: strong reward
            else { score += 25.0; }                        // unusable sliver: penalize
        }
        1 => score += 8.0,
        2 => score += 2.0,
        _ => {}
    }

    // Modulo-5 harmony: post_residual divisible by 5 is more reusable by typical sizes.
    if post_residual > 0 && post_residual % 5 == 0 {
        score -= 3.0;
    }

    // Lookahead coupling: does the next item fit into the resulting residual?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0 + 0.05 * next_item_size as f64;
        } else {
            // residual wasted relative to what's coming
            score += 0.15 * next_item_size as f64;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that can fit this item.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize so open bins are preferred unless they'd create dead space.
    if bin_residual == bin_capacity {
        score += 20.0 + 0.2 * item_size as f64;
    }

    // Slight pressure toward consolidating residuals near the mean.
    score += 0.05 * ((post_residual as f64) - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are too small for typical future
    // items (unusable gaps) are heavily penalized.
    if post_residual > 0 && post_residual < 20 {
        score += 40.0 - (post_residual as f64) * 2.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 30.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    score -= (item_size as f64) / (bin_residual as f64 + 1.0) * 10.0;

    // Last-chance bonus: if this is the only bin that fits, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage opening new bins when many bins are open.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += open_bins_count as f64 * 3.0 + 10.0;
    } else {
        score -= open_bins_count as f64 * 0.5;
    }

    // Lookahead: if the next item fits exactly into the post_residual,
    // reward this placement strongly.
    if next_item_size > 0 && post_residual > 0 && next_item_size == post_residual {
        score -= 35.0;
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        // Next item cannot use the leftover: mild dead-space penalty.
        score += (post_residual as f64) * 0.3;
    }

    // Mean residual coupling: prefer bins that bring their residual toward
    // the mean (balanced depletion) early, avoid extremes late.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (mean_residual - post_residual as f64).abs() * (1.0 - progress) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: bin becomes exactly sized for the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            // Slack left after also placing the next item later: mild reward
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Dead space unusable by next item: penalize proportionally
            let dead = (next_item_size - post_residual) as f64;
            score += 0.5 * dead;
        }
    } else {
        // Last item: reward tightest fit
        score -= 20.0;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize leaving residuals below the minimum item size (unusable waste)
    if post_residual > 0 && post_residual < 1 {
        score += 100.0;
    }

    // Slight preference for bins with residuals above mean (keep balanced bins)
    score += 0.1 * (mean_residual - bin_residual as f64);

    // Early in stream: mild preference for opening new bins to build flexibility
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 5.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: prefer bins where item fills a large fraction of residual.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 45.0 * fill_ratio * fill_ratio;

    // Penalize small dead space that no future item (>=10) can use.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size < post_residual {
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item cannot use this bin's leftover: mild penalty scaled by waste.
            score += 6.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
    }

    // Global state: many open bins with high mean residual -> prefer consolidating
    // into bins below the mean residual (reducing fragmentation).
    if open_bins_count > 1 {
        let rel = (mean_residual - bin_residual as f64) / bin_capacity as f64;
        score += 20.0 * rel;
    }

    // Time horizon: early in stream, prefer keeping residuals large & flexible;
    // late in stream, prioritize closing bins tightly.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - t) * 10.0 * (post_residual as f64 / bin_capacity as f64);
    score -= t * 15.0 * fill_ratio;

    // New-bin candidate: opening a bin should only win when fit is poor elsewhere.
    if bin_residual == bin_capacity && item_size < bin_capacity {
        score += 55.0 + 0.4 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 120.0; // no alternative: new bin is correct
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: penalize wasted post residual, non-linearly.
    let mut score = norm_pr * norm_pr * 60.0 + norm_pr * 40.0;

    // Smooth interaction: later in the stream, tight fits matter more.
    let tightness = 1.0 - norm_pr;
    score -= tightness * tightness * (20.0 + 40.0 * progress);

    // Reward bins with small residuals relative to mean residual (compactness).
    let mean_norm = mean_residual / cap;
    score += (norm_pr - mean_norm) * 15.0;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Lookahead: if next item fits exactly in the post residual, reward; if post residual
    // is too small for the next item but nonzero, mildly penalize dead space.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let fit_quality = 1.0 - ((pr - nxt) / cap);
            score -= fit_quality * fit_quality * 30.0;
        } else {
            score += 8.0 * (1.0 - pr / nxt.max(1.0));
        }
    }

    // Slight preference for consolidating into fewer bins early on.
    score += (open_bins_count as f64) * (1.0 - progress) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual falls into
    // "small residue" classes (dead space) are penalized.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Fractional fill of the bin after placement
    let fill = 1.0 - pr / cap;

    // Reward high fill strongly (non-linear)
    score -= 60.0 * fill * fill;

    // Harmonic classes: post_residual modulo 10 buckets.
    // Residuals that are multiples of 10 pair well with typical item sizes.
    let harmonic = post_residual % 10;
    if harmonic == 0 {
        score -= 8.0; // perfectly aligned residual, easy to reuse
    } else if harmonic >= 8 {
        score += 5.0; // nearly full, awkward sliver
    } else {
        score += 2.0 * harmonic as f64; // progressively awkward dead space
    }

    // Integer-division threshold: can next item fit in post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Reward proportional to how snugly the next item fits
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / cap);
        } else {
            // Next item cannot follow here; penalize more when bin is half-empty
            if post_residual > bin_capacity / 2 {
                score += 10.0;
            }
        }
    } else {
        // Last item: just fill tightest
        score -= 5.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive
    // when the item is large and no good fit exists.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Penalize opening new bins when existing bins fit well
        let pressure = if fitting_bins_count == 0 { 0.0 } else {
            (item_size as f64 / cap).powi(2) * 40.0
        };
        // A new bin is good if the item is big (leaves small residue)
        let residue_bonus = (bin_capacity - item_size) as f64;
        score = score * 0.5 + residue_bonus + pressure;
    }

    // Mild consolidation pressure: many open bins -> prefer filling existing ones
    score += (open_bins_count as f64) * 0.3;

    // Slight progress adaptation: later in stream, tighten packing
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 4.0 * progress * (1.0 - fill);

    // Mean residual coupling: when average residual is large, prefer
    // bins below the mean (rebalance toward tighter bins)
    score += 0.15 * (mean_residual - pr).max(-50.0).min(50.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for the smallest plausible item are wasted.
    // Treat residual < 10 (or < next_item_size) as unusable gap -> strong penalty.
    let min_useful = if next_item_size > 0 { next_item_size.min(20) } else { 10 };
    if post_residual < min_useful {
        score += 25.0 + (min_useful - post_residual) as f64;
    } else if post_residual < 10 {
        score += 30.0;
    }

    // Reward tight fits (low post_residual relative to item size).
    let tightness = item_size as f64 / (bin_residual as f64).max(1.0);
    score -= 15.0 * tightness;

    // Reward bins whose residual is close to the item (perfect match).
    let diff = (bin_residual as i64 - item_size as i64) as f64;
    score -= 10.0 / (1.0 + diff.abs());

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.4 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // New-bin candidate: penalize unless open bins are badly fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - item_size as f64).abs();
        let base = 18.0 + 0.3 * open_bins_count as f64;
        // If mean residual is large and fits item easily, opening new bin is wasteful.
        score += base + fragmentation.max(0.0) * 0.2;
        if mean_residual >= item_size as f64 + 10.0 {
            score += 12.0;
        }
        // Late in stream, prefer filling existing bins.
        score += 10.0 * progress;
    }

    // Slight preference for bins below mean residual (balance residual distribution).
    score += 0.05 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward post_residual close to next_item_size
    if next_item_size > 0 {
        let lookahead_gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 / (1.0 + lookahead_gap);
        // Perfect match: post_residual exactly equals next item size
        if post_residual == next_item_size {
            score -= 40.0;
        }
        // Penalize leaving dead space that next item can't use
        if post_residual < next_item_size {
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Penalize small unusable residuals (dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Reward tight fits relative to mean residual
    if (post_residual as f64) < mean_residual {
        score -= 0.3 * (mean_residual - post_residual as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate: penalize slightly so it's chosen only when open bins fit poorly
    if bin_residual == bin_capacity {
        score += 15.0;
    }

    // Mild phase term: prefer consolidation early in stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0 * (open_bins_count as f64).ln();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize leaving small, hard-to-use dead space (post_residual in awkward range).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // next item cannot use leftover; penalize proportionally
            score += 5.0 * (1.0 - post_residual as f64 / next_item_size as f64).min(1.0);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current bins are bad fits.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let open_penalty = open_bins_count as f64 * 3.0;
        // Base cost of a fresh bin; reduced late in stream when fragmentation accumulates.
        score += 45.0 + open_penalty - 20.0 * progress;
        // If mean residual across open bins is large, opening a new bin is wasteful.
        score += 0.3 * mean_residual;
        // If many bins fit, definitely don't open a new one.
        if fitting_bins_count > 1 {
            score += 20.0 * (fitting_bins_count as f64 - 1.0);
        }
    }

    // Mild preference for bins with below-mean residual (consolidate fragmented space).
    if bin_residual != bin_capacity {
        score += 0.1 * (bin_residual as f64 - mean_residual);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_post = post / cap;

    // Smooth polynomial coupling of post_residual with stream progress.
    // Early on: tolerate larger post_residuals (keep bins flexible).
    // Late: strongly prefer tight fits (low post_residual).
    let progress_coupling = progress * (1.0 - progress) * 4.0; // peaks mid-stream
    let poly = norm_post * norm_post * (1.0 + 2.0 * progress)
             + norm_post * (0.5 - 0.5 * progress);

    let mut score = post + 40.0 * poly;

    // Dead-space penalty: post_residual too small to fit typical items.
    if post > 0.0 {
        let dead = (1.0 - post / cap.max(1.0)).max(0.0);
        score += 10.0 * dead * norm_post * (1.0 + progress_coupling);
    }

    // Perfect fit reward (smooth, no hard cutoff).
    let fit_quality = 1.0 - (post / cap).powf(2.0);
    score -= 15.0 * fit_quality * (1.0 - progress);

    // Last-chance bin: strong reward to avoid opening new bins.
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * (1.0 - norm_post);
    }

    // Lookahead: reward if next item fits into the post-residual.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if post >= ni {
            score -= 12.0 * (1.0 - (ni / cap)) * (1.0 + progress);
        } else {
            score += 8.0 * (ni - post) / cap;
        }
    }

    // New-bin candidate handling: penalize opening a fresh bin unless
    // open bins are crowded or this is a large item needing space.
    if bin_residual == bin_capacity {
        let crowd = open_bins_count as f64 / (1.0 + mean_residual / cap);
        let need = item_size as f64 / cap;
        score += 30.0 * (1.0 - need) - 10.0 * crowd.min(3.0) + 15.0 * progress;
    }

    // Mild dispersion penalty: prefer bins near the mean residual.
    let dev = (bin_residual as f64 - mean_residual).abs() / cap;
    score += 5.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class logic on post_residual (capacity fractions / integer division) ---
    // Perfect fit: strongest reward.
    if post_residual == 0 {
        score -= 60.0;
    } else {
        // Integer-division class: dead-space severity grows superlinearly per decade.
        let decade = post_residual / 10; // class 0..=9
        score += (decade * decade) as f64 * 0.8;

        // Modulo-10 harmonic alignment: round residuals (multiples of 10) are
        // more reusable by the unknown item distribution -> reward them.
        if post_residual % 10 == 0 {
            score -= 6.0;
        } else if post_residual % 5 == 0 {
            score -= 3.0;
        }
    }

    // Small residual band: near-perfect fits get an extra multiplicative pull.
    if post_residual <= 5 && post_residual > 0 {
        score -= 12.0;
    }

    // --- Lookahead coupling (k=2) ---
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // This residual can host the next item: residual is not dead space.
            let waste_gap = post_residual - next_item_size;
            score -= (6.0 - (waste_gap as f64) * 0.3).max(0.0);
        } else {
            // Residual cannot fit the next item -> likely permanent dead space.
            // Penalize proportionally to how far off it is, scaled by item size class.
            let gap = next_item_size - post_residual;
            score += (gap as f64) * 0.25;
        }
    }

    // --- Last-chance pressure ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        // This is the only open bin that fits; avoid forcing a new bin.
        score -= 25.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Brand-new empty bin: post_residual = capacity - item_size already in score.
        // Make it a mediocre default: it should only win when all existing fits are bad.
        // Larger items leave less residual in a fresh bin -> slightly favored.
        score += 40.0 - (item_size as f64) * 0.15;

        // Late in the stream, opening bins is cheaper than carrying many slivers.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= progress * 8.0;

        // If many bins are open with large mean residual, prefer reusing them.
        if open_bins_count > 2 && mean_residual > item_size as f64 {
            score += 10.0;
        }
    } else {
        // Existing-bin reuse bonus, stronger when the bin is already well-loaded.
        let load_frac = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= load_frac * 8.0;
    }

    // --- Mean-residual global coupling: reward bins tighter than the fleet average ---
    if (post_residual as f64) < mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // even the smallest plausible item are pure waste -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10.0 - post_residual as f64) / 10.0;
    }
    if post_residual == 0 {
        // Perfect fit: strongly reward closing the bin exactly.
        score -= 60.0;
    }

    // Reward residuals that can still host typical items (usable space).
    if post_residual >= 10 {
        score -= 8.0;
    }

    // Dead-space coupling with lookahead: if the next item cannot use
    // the leftover, the gap is even more likely to become waste.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    }

    // Last chance bin: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is truly terrible.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Open-bin pressure: discourage proliferation of open bins.
    score += open_bins_count as f64 * 0.8;

    // Prefer bins below the mean residual (tighter, more committed bins)
    // when the fit leaves usable space.
    if post_residual >= 10 {
        score += 0.3 * ((bin_residual as f64) - mean_residual);
    }

    // New-bin candidate: an empty bin has residual == capacity. Make it
    // moderately attractive only when the current fit is bad, otherwise
    // prefer existing bins.
    if bin_residual == bin_capacity {
        score += 15.0;
        // Opening fresh is better when many bins are open and mean
        // residual is small (existing bins are nearly full).
        score -= (open_bins_count as f64).ln().max(0.0) * 2.0;
        score -= 0.1 * mean_residual;
    }

    // Slight stream-position adaptation: late in the stream, be more
    // aggressive about exact packing (fewer chances left to recover).
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score -= 6.0 * progress * (1.0 - (post_residual as f64 / bin_capacity as f64));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead matching: strongly reward when the next item
    // exactly fills the post-residual, or fits very well into it.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack_after_next = post_residual - next_item_size;
            // Perfect 2-step match: huge reward.
            if slack_after_next == 0 {
                score -= 60.0;
            } else if slack_after_next <= 5 {
                score -= 25.0 - slack_after_next as f64 * 3.0;
            } else {
                // Reward proportional to how well next item fits the leftover.
                score -= 12.0 * (1.0 - slack_after_next as f64 / post_residual as f64);
            }
        } else {
            // Next item cannot use the residual: penalize dead space creation.
            score += 8.0;
        }
    }

    // Compare post-residual against mean residual across open bins:
    // leaving less than average residual is good (tight packing).
    let diff = post_residual as f64 - mean_residual;
    score += 0.15 * diff;

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: only attractive when the item is large
    // relative to capacity or no tight fit exists elsewhere.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        score += 25.0; // default penalty: prefer existing bins
        if fill_ratio > 0.7 {
            score -= 30.0; // large items justify a fresh bin
        }
        if next_item_size > 0 && next_item_size as f64 > (bin_capacity - item_size) as f64 {
            score -= 10.0; // next item won't fit in residual anyway
        }
    }

    // Late in the stream: tighten packing, avoid opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 5.0 * (post_residual as f64 / bin_capacity as f64);

    // Small residual waste penalty (dead space below typical item size).
    if post_residual < 10 {
        score -= 15.0; // near-perfect fill
    } else if post_residual < 20 {
        score -= 5.0;
    }

    // Mild bonus for using fuller bins.
    score -= 0.2 * (item_size as f64 / bin_capacity as f64) * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (low post-residual) with a non-linear bonus.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Penalize dead space: residuals too small for typical future items are wasteful.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item cannot use leftover space: mild penalty scaled by waste.
            score += 5.0 * (next_item_size - post_residual) as f64 / 100.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Global pressure: many open bins with low mean residual -> prefer filling existing bins.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual);
    score -= 3.0 * pressure.min(10.0);

    // Time horizon: early in the stream, be picky (penalize mediocre fits);
    // late in the stream, just pack tightly anywhere.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pickiness = 1.0 - progress;
    if post_residual as f64 > mean_residual {
        score += 10.0 * pickiness * ((post_residual as f64 - mean_residual) / bin_capacity as f64);
    }

    // New-bin candidate: only attractive when no open bin fits well or stream is early
    // with large item relative to best residuals.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        score -= 20.0 * desperation;
        score += 12.0 * pickiness * (item_size as f64 / bin_capacity as f64);
        // Opening a bin for a small item is wasteful.
        if item_size < 30 {
            score += 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: f64, fitting_bins_count: usize) -> f64 {
