    // Modulo classes on post_residual w.r.t. common item sizes (harmonic classes)
    // Residues that are multiples of small sizes are more reusable
    let divisible_bonus = [10u32, 20, 25, 50].iter().any(|&d| post_residual % d == 0 && post_residual > 0);
    if divisible_bonus {
