            score += 0.5 * post;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // New-bin candidate handling: neutral-ish score, slightly above good fits
    if bin_residual == bin_capacity {
