    score += 0.05 * ((bin_residual - item_size) as f64).abs();

    // Progress-based exploration of modulo thresholds: early stream favor tight packing
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 5.0 * (1.0 - frac);

