pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // are "dead space". Penalize heavily when the gap cannot fit the next item
    // or falls below the minimum plausible item size.
    if post_residual > 0 {
        if next_item_size > 0 && post_residual < next_item_size {
            score += 25.0; // gap cannot host the upcoming item
        }
        if post_residual < 10 {
            score += 40.0; // unusable sliver below minimum item size
        }
        // Non-linear dead-space penalty: small-but-not-zero gaps are worst.
        let pr = post_residual as f64;
        score += 60.0 / (pr * 0.25 + 1.0);
    } else {
        // Perfect fit: reward strongly.
        score -= 30.0;
    }

    // Reward tight fits relative to the item size.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * tightness;

    // Last-chance pressure: if this is the only bin that fits, prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading into new bins,
    // encourage filling existing ones (especially the emptiest ones).
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64 / 10.0).min(3.0) * (0.5 + progress);
    score += pressure * (post_residual as f64 / bin_capacity as f64);

    // Prefer bins whose residual deviates from the mean in a useful way:
    // bins with larger-than-mean residual can absorb big future items.
    if (bin_residual as f64) > mean_residual {
        score -= 3.0;
    } else {
        score += 3.0;
    }

    // New-bin candidate handling: an empty bin is a fallback. Make it
    // moderately attractive only when the item is large or fits would waste
    // space elsewhere; otherwise keep it slightly penalized so existing bins
    // with good fits win.
    if bin_residual == bin_capacity {
        let big_item = item_size as f64 / bin_capacity as f64;
        score += 12.0;              // base cost of opening a new bin
        score -= 25.0 * big_item;   // large items justify a fresh bin
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;          // fresh bin can also host next item
        }
        if post_residual < 10 {
            score += 20.0;          // opening a bin for a huge item is fine
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: smaller post_residual is better.
    score -= 40.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // 2-step lookahead: reward when next item exactly fills post_residual.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let pr = post_residual as f64;
        if pr >= next {
            let gap = pr - next;
            // Perfect chain match strongly rewarded
            score -= 60.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Post-residual too small for next item: penalize dead space
            score += 25.0 * (next - pr) / bin_capacity as f64;
        }
    }

    // Penalize deviation from mean residual (keep balance across bins)
    score += 0.15 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 50.0;
    }

    // Penalize opening a new bin when open bins fit well
    if bin_residual == bin_capacity {
        score += 30.0;
        // New bin more acceptable early in stream
        score -= 20.0 * (step_index as f64 / total_items.max(1) as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tightness of the fit: reward near-perfect fills.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 18.0 * fit_ratio * fit_ratio;

    // Penalize dead space that nothing else can plausibly use:
    // small post_residual (< 10) is excellent; mid-range residue is wasted.
    if post_residual > 0 {
        let pr = post_residual as f64;
        if pr < 10.0 {
            score -= 8.0;
        } else if pr < 25.0 {
            score += 0.35 * (pr - 10.0);
        }
    }

    // Lookahead coupling: if the next item fits exactly into the post-residual,
    // strongly favor this bin; if next item cannot fit anywhere after placement,
    // penalize slightly.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= post_residual as f64 {
            let slack = (post_residual as f64 - nx).abs();
            score -= 12.0 * (1.0 - slack / cap);
        } else {
            score += 3.0;
        }
    }

    // Last-chance bonus: only one open bin can fit this item — keep it usable.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // Global pressure: many open bins with high mean residual -> prefer
    // consolidating into existing bins rather than opening new ones.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / cap);
    score += 0.05 * pressure;

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // no good existing option exists (few fitting bins) or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let desperation = (fitting_bins_count as f64).recip();
        let early_bonus = 6.0 * (1.0 - progress);
        score += 14.0 - desperation * 10.0 - early_bonus;
    }

    // Mild time horizon shaping: later in stream, punish large leftovers more
    // (less future to amortize them).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 4.0 * progress * (post_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let pr = post / cap; // normalized post residual

    // Base: prefer smaller post residual, with smooth polynomial shaping.
    let mut score = post;

    // Non-linear penalty on large dead space (quartic-ish growth in wasted space).
    score += 40.0 * pr * pr * pr;

    // Reward tight fits: quadratic bonus peaking when post_residual is small.
    let tight = (1.0 - pr).clamp(0.0, 1.0);
    score -= 12.0 * tight * tight;

    // Perfect fit reward (smoothed exponential decay of residual).
    score -= 60.0 * (-post as f64 / 8.0).exp();

    // Lookahead coupling: if the next item fits exactly into post_residual, reward strongly.
    if next_item_size > 0 && next_item_size <= post_residual {
        let look = next_item_size as f64 / cap;
        score -= 25.0 * (1.0 - (post - next_item_size as f64) / cap) * (1.0 - progress * 0.5);
        let _ = look;
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item cannot use this residual: penalize leaving medium dead space more.
        score += 10.0 * pr * (1.0 - progress);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + 20.0 * progress;
    }

    // New-bin candidate handling: make empty bins mildly attractive early, unattractive late
    // unless no good fit exists.
    if bin_residual == bin_capacity {
        let early_bias = 1.0 - progress;
        score += 8.0 + 30.0 * progress; // harder to justify a new bin as stream progresses
        score -= 5.0 * early_bias;
    }

    // Coupling with mean residual: avoid bins far from the fleet mean (smooth interaction).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 6.0 * dev * dev * (0.5 + progress);

    // Slight preference for fuller bins as stream progresses (non-linear in progress).
    score -= 15.0 * progress * tight * tight;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: quantize leftover space into capacity fractions.
    let frac = post_residual as f64 / bin_capacity as f64;

    // Reward placements whose leftover falls into a "useful" harmonic class.
    // Classes keyed by capacity/8 divisions (12, 25, 37, 50, 62, 75, 87).
    let class = (post_residual * 8) / bin_capacity; // 0..=7 integer division class
    let class_bonus: f64 = match class {
        0 => 40.0,            // dead space <= 12 : excellent fit
        1 => 25.0,            // <= 25
        2 => 15.0,            // <= 37
        3 => 8.0,             // <= 50
        4 => 2.0,             // <= 62
        5 => -6.0,            // <= 75 : wasteful
        6 => -14.0,           // <= 87 : very wasteful
        _ => -22.0,           // nearly empty bin usage
    };
    score -= class_bonus;

    // Exact fill is perfect.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Modulo coupling: leftover that pairs with typical small items (multiples of 10)
    // is more reusable than arbitrary leftovers.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 10.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, strongly favor.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 55.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.35;
        } else {
            // Next item cannot use this leftover: penalize proportional waste.
            score += (next_item_size as f64) * 0.12;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a bin should only win when all open bins
    // are tight or the item is large.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = mean_residual / bin_capacity as f64;
        // Penalize new bins; relax penalty when open bins are nearly full.
        score += 45.0 - 25.0 * (1.0 - pressure).min(1.0) + 10.0 * progress;
        if item_size >= 70 {
            score -= 20.0; // large items open bins cheaply
        }
    }

    // Mild preference for tighter bins overall (residual below mean).
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    }

    // Slight decay of large-residual penalties late in the stream (consolidate).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if frac > 0.5 {
        score -= 8.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

