    }

    // Reward fits that leave room for the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Last-chance bonus: only bin that fits -> avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: prefer using existing bins over opening new ones.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to how many bins are open.
        score += 15.0 + 2.0 * open_bins_count as f64;
        // Allow opening a new bin if existing residuals are all small (poor fits).
        if mean_residual < item_size as f64 * 0.5 {
            score -= 30.0;
        }
    } else {
        score -= 5.0;
    }

    // Mild stream-progress term: be slightly more conservative early.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 3.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

