            score -= 20.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item does NOT fit here: penalize leaving a gap that
            // strands the lookahead item.
            let gap = (next_item_size - post_residual) as f64;
            score += 8.0 * (gap / 100.0);
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate logic: an empty bin is only attractive when the
    // current item is large and would leave a badly fragmented state, or
    // when no open bin offers a good fit. Penalize opening new bins when
    // decent fits already exist.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin.
        score += 45.0;
        // Large items are better placed in fresh bins (avoid fragmentation).
        if item_size > bin_capacity / 2 {
            score -= 35.0;
        }
        // If the item fits very poorly everywhere else (post_residual tiny
        // relative to item), a fresh bin becomes attractive.
        if post_residual < item_size / 4 {
            score -= 20.0;
        }
        // Late in the stream, avoid opening new bins unless truly necessary.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Global state coupling: prefer bins whose residual is above the mean
    // (keep near-empty bins flexible, drain fuller bins first).
    let dev = bin_residual as f64 - mean_residual;
    score -= 0.15 * dev;

    // When many bins are open, consolidate into existing ones instead of
    // spreading out.
    if open_bins_count > 4 {
        score -= 0.5 * open_bins_count as f64 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = step_index as f64 / (total_items.max(1) as f64);

    // Normalized post-residual and fit quality
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;

    // Smooth non-linear coupling: dead space penalized more strongly as stream progresses
    let dead_space_penalty = pr_norm * pr_norm * (0.5 + 2.0 * progress);
    score += 40.0 * dead_space_penalty;

    // Reward tight fits (post_residual near zero) with smooth exponential-like term
    score -= 30.0 * (1.0 - pr_norm) * (1.0 - pr_norm) * (1.0 - pr_norm);

    // Perfect fit bonus (smooth, no hard threshold)
    score -= 25.0 * (-(pr as f64) / 12.0).exp();

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 60.0 * (0.5 + progress);
    }

    // Scarcity pressure: fewer fitting bins relative to open bins -> favor existing bin
    let scarcity = 1.0 - (fitting_bins_count as f64) / ((open_bins_count.max(1) as f64) + 1.0);
    score -= 20.0 * scarcity * scarcity;

    // Lookahead: if next item fits the post-residual, reward this placement smoothly
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score -= 15.0 * (-(gap) / 20.0).exp() * (0.5 + 0.5 * progress);
    } else {
        // Last item: strongly prefer filling existing bins
        score -= 50.0;
    }

    // Mean residual coupling: prefer bins deviating from mean when mean is high (consolidate)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 10.0 * dev * dev * progress;

    // Mild preference for opening new bins early (bins are cheap early)
    score -= 15.0 * (1.0 - progress) * (1.0 - progress) * (pr_norm - 0.5);

    // Tie-breaker: prefer bins with more residual used already
    score -= 0.05 * (bin_residual as f64 - pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls in
    // "usable" classes (small, or large enough to host a typical item)
    // are preferred; the dead zone in between is heavily penalized.
    let pr = post_residual;
    let class: f64 = if pr == 0 {
        -8.0 // perfect fit is king
    } else if pr <= 10 {
        -4.0 // near-perfect, tiny waste
    } else if pr >= 25 && pr <= 60 {
        6.0 // dead zone: too big to ignore, too small for most items
    } else if pr > 60 {
        -1.0 // roomy leftover, still reusable
    } else {
        0.0 // 11..24: mildly awkward
    };
    score += class;

    // Modulo arithmetic on post_residual: leftovers that are multiples of
    // common item sizes (10, 20, 25, 50) are more likely to be exactly
    // filled later — reward them.
    if pr != 0 {
        if pr % 10 == 0 { score -= 1.5; }
        if pr % 20 == 0 { score -= 1.0; }
        if pr % 25 == 0 || pr % 50 == 0 { score -= 1.0; }
    }

    // Lookahead coupling: if the next item fits exactly into the post
    // residual, this is a golden chain — reward strongly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 10.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 3.0 * (1.0 - slack / cap); // tighter next-fit is better
        } else {
            // next item cannot use this leftover; penalize proportionally
            score += 2.0 * (next_item_size as f64 - post_residual as f64) / cap;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 5.0 + 0.02 * (open_bins_count as f64);
    }

    // New-bin candidate handling: an empty bin has full residual. It should
    // only win when no open bin offers a decent fit. Penalize the fresh bin
    // so it is chosen only when open bins are in the dead zone or scarce.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 4.0 + 3.0 * progress;
        if open_bins_count == 0 {
            score -= 10.0; // must open the first bin
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 2.0; // fresh bin pairs well with a big next item
        }
    }

    // Prefer packing into bins whose residual deviates below the mean
    // (consolidating waste), slight effect.
    let resid_f = bin_residual as f64;
    if resid_f < mean_residual {
        score -= 0.5 * (mean_residual - resid_f) / cap;
    } else {
        score += 0.5 * (resid_f - mean_residual) / cap;
    }

    // Bigger items deserve tighter bins: reward low post_residual relative
    // to item size.
    score -= 0.5 * (item_size as f64 / cap) * (1.0 - post_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // any plausible future item (<= 10) are heavily penalized.
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0 * (11.0 - post_residual as f64);
    }

    // Perfect fit is maximally rewarded.
    if post_residual == 0 {
        score -= 120.0;
    }

    // Reward bins whose post-residual can still host the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0 + 0.5 * next_item_size as f64;
        } else if post_residual > 0 {
            // residual becomes dead space relative to the known next item
            score += 30.0;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, avoid spreading; with few,
    // be more willing to fill a bin tightly.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += 4.0 * pressure * (post_residual as f64 / bin_capacity as f64);

    // Prefer bins already below the mean residual (tighter bins first).
    score += 0.3 * (mean_residual - bin_residual as f64);

    // New-bin candidate: neutral baseline, slightly penalized so it only
    // wins when every open bin would create dead space.
    if bin_residual == bin_capacity {
        score += 15.0 + 2.0 * pressure;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fills (low post_residual).
    score = post_residual as f64;

    // Aggressive 2-step lookahead: strongly reward post_residual == next_item_size
    // (perfect chaining), penalize small-but-unusable gaps.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 30.0 * (1.0 - gap / bin_capacity as f64).max(0.0);

        // Exact match: huge bonus.
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Post residual too small for the next item: dead space penalty.
        if post_residual < next_item_size {
            score += 8.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        }
    } else {
        // Last item: pure tightest-fit.
        score = post_residual as f64;
    }

    // Compare against mean residual: bins already tight are precious; prefer
    // placing into bins with above-average residual (waste them first).
    score -= 0.5 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: only attractive when item is huge relative to residual
    // landscape or fits would be terrible. Penalize mildly by default.
    if bin_residual == bin_capacity {
        score += 15.0;
        // But if item is large (>60% of capacity), a fresh bin is fine.
        if item_size * 5 >= bin_capacity * 3 {
            score -= 20.0;
        }
    }

    // Early in the stream, tolerate new bins slightly more (future flexibility).
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        if bin_residual == bin_capacity {
            score -= 10.0 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near zero is good.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 20.0;
    }

    // Penalize creating dead space that no future item (min size 1, typical 10+)
    // can use; dead space below 10 is nearly unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last chance: only one open bin can fit this item -> strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Lookahead: if next item fits into this bin's post_residual, bonus.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0 + 0.2 * next_item_size as f64;
        } else {
            // Next item won't fit here; slight penalty proportional to mismatch.
            score += 0.1 * (next_item_size as f64 - post_residual as f64).min(50.0);
        }
    }

    // Time horizon: early in stream, prefer consolidating into open bins;
    // late in stream, avoid opening new bins even more (wasted capacity).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses and when
        // open bins could still hold the item.
        score += 35.0 + 45.0 * progress;
        if fitting_bins_count > 0 {
            score += 30.0;
        }
        // Early stream: opening a bin is cheaper.
        score -= 20.0 * (1.0 - progress);
    } else {
        // Using an open bin: reward more as stream progresses.
        score -= 10.0 * progress;
    }

    // Global state coupling: if mean residual across bins is high, we have
    // slack everywhere -> discourage adding to fragmentation; prefer bins
    // whose residual is below mean (tighter bins absorb items).
    let res = bin_residual as f64;
    if mean_residual > 0.0 {
        score += 0.15 * (res - mean_residual);
    }

    // Many open bins: encourage filling existing ones rather than spreading.
    score += 0.5 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Prefer bins whose residual is close to item size (minimal overshoot).
    score += 0.05 * (bin_residual - item_size) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Base: post-residual, with non-linear penalty for awkward dead space
    let mut score = pr
        + 40.0 * norm_pr * norm_pr
        - 25.0 * norm_item * (1.0 - norm_pr) * (1.0 - progress);

    // Smooth coupling: tight fits rewarded more as stream progresses
    let tightness = 1.0 - norm_pr;
    score -= 30.0 * tightness * tightness * (0.5 + progress);

    // Lookahead synergy: reward if next item fits the post-residual
    if next_item_size > 0 {
        let fits_next = if (next_item_size as f64) <= pr { 1.0 } else { 0.0 };
        let gap = (pr - next_item_size as f64).abs() / cap;
        score -= 20.0 * fits_next * (1.0 - gap);
        score += 8.0 * (1.0 - fits_next) * norm_pr;
    }

    // Last-chance bonus when few fitting bins
    if fitting_bins_count <= 1 {
        score -= 15.0 * (1.0 - norm_pr);
    }

    // Mild penalty when this bin's residual deviates from mean (smooth)
    let dev = (pr - mean_residual) / cap;
    score += 5.0 * dev * dev;

    // New-bin candidate: penalize slightly more when open bins are fragmented
    if bin_residual == bin_capacity {
        score += 6.0 + 2.0 * open_bins_count as f64 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: quantize dead space into capacity fractions.
    let frac = post_residual as f64 / bin_capacity as f64;

    // Reward near-perfect fits: post_residual in {0, 1..=5, 6..=10} classes.
    if post_residual == 0 {
        score -= 50.0; // perfect fill
    } else if post_residual <= 5 {
        score -= 30.0;
    } else if post_residual <= 10 {
        score -= 15.0;
    }

    // Penalize awkward dead-space classes via modulo structure.
    // Residuals that are NOT representable as sums of typical item sizes (10..80)
    // are dead space. Odd / prime-ish residues below 10 are least reusable.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 2.0;
    }
    // Harmonic penalty: residue classes mod 10 that are hard to fill
    // (e.g. 1,3,7,9 mod 10 are awkward for 10-multiple items).
    let m = post_residual % 10;
    if post_residual > 0 && (m == 1 || m == 3 || m == 7 || m == 9) {
        score += 6.0;
    }

    // Tightness reward: relative fit quality (non-linear).
    score -= (1.0 - frac).powi(3) * 12.0;

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            let slack = post_residual - next_item_size;
            if slack <= 10 {
                score -= 10.0;
            }
        } else {
            // next item won't fit here: slight penalty for stranding space
            score += 3.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: reserve new bins for large items or when
    // no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = bin_capacity as f64 * 0.75;
        // Attractive when item is large (would leave small residue anywhere).
        if item_size >= 60 {
            score -= 15.0;
        }
        if item_size >= 80 {
            score -= 10.0;
        }
        // If existing bins are fragmented (high mean residual spread vs fit),
        // opening fresh is fine; if open bins are nearly full, prefer them.
        if mean_residual < 30.0 && fitting_bins_count >= 1 {
            score += 20.0;
        }
        // Late in the stream, avoid opening bins that will be nearly empty.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if progress > 0.9 && item_size < 50 {
            score += 15.0;
        }
        // If next item is small, a fresh bin can host the pair.
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 8.0;
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftovers are nearly unusable dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10 - post_residual) as f64;
    } else if post_residual == 0 {
        // Perfect fit is highly desirable.
        score -= 50.0;
    } else {
        // Larger leftovers are more reusable; reward proportionally.
        score -= 0.3 * post_residual as f64;
    }

    // Reward tight fits relative to item size.
    score -= 0.5 * (item_size as f64 / bin_capacity as f64) * 100.0;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones
    // and encourage consolidating into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.5 + progress);
    if bin_residual < bin_capacity {
        score -= pressure * 0.4;
    } else {
        // New-bin candidate: penalize more when many bins are open.
        score += pressure * 0.8;
    }

    // Lookahead: if next item fits into this bin's post residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
        // Dead space that blocks the next item: extra penalty.
        score += 20.0;
    }

    // Prefer bins whose residual is close to the mean (balanced packing),
    // penalize outliers to keep residuals usable.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.1 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual, but compare against mean residual.
    let mean_r = if mean_residual.is_finite() { mean_residual } else { bin_capacity as f64 };

    // Penalize leaving dead space relative to the mean residual across open bins.
    score += 0.35 * (post_residual as f64 - mean_r).abs();

    // Aggressive 2-step lookahead: if the NEXT item fits exactly into post_residual,
    // strongly reward this bin (perfect chain fit).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64 - nxt).abs() < f64::EPSILON {
            score -= 60.0; // exact 2-step chain: post_residual == next item
        } else if post_residual >= next_item_size {
            // next item fits: reward proportional to how snugly it nests
            let slack = (post_residual as f64 - nxt) / bin_capacity as f64;
            score -= 30.0 * (1.0 - slack);
        } else {
            // next item cannot use this bin's leftover: penalize dead space
            let unusable = nxt - post_residual as f64;
            score += 0.5 * unusable.min(nxt);
        }

        // If next item is huge, avoid wasting large-capacity bins now;
        // keep post_residual small so a big next item needs a fresh bin anyway.
        if nxt > 0.5 * bin_capacity as f64 && post_residual < nxt {
            score -= 8.0;
        }
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin has high post_residual,
    // which naturally loses to good fits; but if no open bin fits well
    // (post_residual of best open bin would be tiny/dead), opening fresh
    // is fine. Slightly bias against opening new bins early in the stream.
    if bin_residual == bin_capacity {
        score += 12.0 * (1.0 - step_index as f64 / (total_items.max(1) as f64));
        // If many bins are open already, discourage excessive bin proliferation.
        score += 0.5 * open_bins_count as f64;
    }

    // Prefer filling bins that are already partially loaded (fewer open bins).
    if bin_residual < bin_capacity {
        score -= 0.15 * (bin_capacity - bin_residual) as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize dead space quadratically; small residuals are nearly unusable.
    let dead = post_residual as f64;
    score += 0.35 * (dead / 10.0).powi(2);

    // Lookahead: reward if the next item fits in the post-residual (chain packing).
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 6.0 + 0.1 * next_item_size as f64;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item cannot follow here: penalize proportionally to wasted potential.
        score += 3.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Prefer tighter bins: reward small residual relative to mean residual.
    if mean_residual > 0.0 {
        score -= 2.0 * (1.0 - bin_residual as f64 / mean_residual).clamp(-1.0, 1.0);
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin is a poor fit
    // and there's room in the stream to amortize it.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 30.0 - 10.0 * progress;
        if fitting_bins_count > 0 {
            score += 15.0;
        }
        // Attractive if mean residual across open bins is too small to be useful.
        if mean_residual < item_size as f64 {
            score -= 20.0;
        }
    }

    // Prefer bins whose residual is close to the item (best-fit flavor).
    let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score += 8.0 * tightness;

    // Late in the stream, consolidate: penalize spreading across many open bins.
    score += 0.5 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Smooth non-linear polynomial coupling of post_residual with stream progress.
    let base = pr
        + 30.0 * norm_pr * norm_pr * (1.0 - progress)
        - 12.0 * norm_pr * progress;

    // Reward tight fits via smooth quadratic term.
    let fit_ratio = item_size as f64 / cap;
    let tightness = -20.0 * fit_ratio * (1.0 - norm_pr);

    // Last-chance bonus (smooth penalty for alternatives).
    let last_chance = if fitting_bins_count == 1 { -25.0 } else { 0.0 };

    // Lookahead: reward bins whose post-residual can fit the next item (smooth gate).
    let lookahead = if next_item_size > 0 {
        let fits_next = if pr >= next_item_size as f64 { 1.0 } else { 0.0 };
        -15.0 * fits_next * (1.0 - progress)
    } else {
        0.0
    };

    // Mild penalty for spreading across many bins, scaled by mean residual.
    let spread = 2.0 * open_bins_count as f64 * (mean_residual / cap) * progress;

    base + tightness + last_chance + lookahead + spread
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: integer division into capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual;
    let class = pr / (bin_capacity / 4); // 0..4 quarter classes

    // Reward tight fits: post_residual in the smallest class gets strong bonus.
    match class {
        0 => score -= 40.0,                       // nearly full bin — excellent
        1 => score -= 12.0,                       // quarter left — decent
        2 => score -= 0.0,                        // half left — neutral
        _ => score += 15.0,                       // mostly empty after placement — wasteful
    }

    // Exact fit gets a big bonus.
    if pr == 0 {
        score -= 60.0;
    }

    // Lookahead coupling: does post_residual accommodate the next item?
    if next_item_size > 0 {
        if pr >= next_item_size {
            // Next item fits too: harmonic residue classes of pr and next_item_size.
            let gap = (pr - next_item_size) as f64;
            let gap_class = ((pr - next_item_size) / (bin_capacity / 5)) as f64;
            score -= 20.0 - gap_class * 5.0;      // snug follow-up fit preferred
            if gap < 5.0 {
                score -= 10.0;                     // near-exact chain fit
            }
        } else {
            // Next item won't fit here: penalize small dead residues that
            // nothing in 1..100 range can use later.
            let dead_zone = pr < 10;
            if dead_zone {
                score += 25.0;
            } else {
                score += 5.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless current placements
    // are all terrible (few fitting bins, large post_residual waste).
    if bin_residual == bin_capacity {
        score += 35.0;
        if fitting_bins_count == 0 {
            score -= 100.0;                        // no alternative: must open
        } else if fitting_bins_count == 1 {
            score += 10.0;                         // keep last-chance bin attractive
        }
        // Early in the stream, a fresh bin is more acceptable.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 10.0;
    }

    // Modulo harmonic bonus: post_residual divisible by common item sizes
    // (10/20/25) is more likely reusable by future items.
    if pr > 0 && (pr % 10 == 0 || pr % 25 == 0) {
        score -= 8.0;
    }

    // Mild pressure to consolidate when many bins are open relative to mean residual.
    if open_bins_count > 4 && (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual that is too small for the minimum plausible item (<= ~10) is dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Penalize gaps too small for the lookahead item (would be wasted for it).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Reward near-perfect fits (post_residual close to 0 or exactly reusable).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual == bin_residual - item_size && post_residual >= 10 {
        // gap still usable for smallest items: mild bonus
        score -= 2.0;
    }

    // Prefer bins with tighter current residual (best-fit flavor).
    score += (bin_residual as f64 - item_size as f64) * 0.15;

    // Open-bin pressure: when many bins are open, discourage spreading;
    // when few bins are open and this is the last fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }
    score += open_bins_count as f64 * 0.5;

    // New-bin candidate: only attractive when the item fits poorly everywhere
    // (large post_residual elsewhere) or few bins fit; add a mild opening cost
    // so it wins only in genuinely bad-fit situations.
    if bin_residual == bin_capacity {
        score += 15.0;
        // opening a fresh bin is good if the item is large relative to capacity
        if item_size >= 60 {
            score -= 10.0;
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0; // pairing large items into fresh bins
        }
    }

    // Mean-residual coupling: if this bin's post-residual is far below the mean,
    // it is consolidating space well.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Stream progression: late in the stream, avoid opening bins and prefer filling.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;
    if bin_residual == bin_capacity {
        score += progress * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item fits the post-residual exactly.
    if next_item_size > 0 {
        let nr = next_item_size as f64;
        if (post_residual as f64 - nr).abs() < 0.5 {
            // Perfect chain fit: place here, next item seals the bin.
            score -= 40.0;
        } else if post_residual >= next_item_size {
            // Next item also fits here: good compaction, reward proportionally.
            score -= 8.0 + 12.0 * (next_item_size as f64 / 100.0);
        } else {
            // Dead space: penalize unusable leftover relative to next item size.
            let waste = post_residual as f64;
            score += waste * 0.5 + nr * 0.2;
        }
    }

    // Compare against mean residual across open bins: prefer bins that are
    // already tighter than average (keeps loose bins available for big items).
    score += (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Early in the stream, prefer keeping bins open and compact.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.1 * (1.0 - progress);

    // Mild penalty for scattering across many open bins.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual relative to capacity.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 8.0 * fit_ratio * fit_ratio; // superlinear penalty on wasted space

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 10.0; // near-perfect fit creates unusable sliver anyway, but keeps bin count low
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item can fit into the post-residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
        // Extra reward if next item nearly fills the bin after placement.
        let chain_post = post_residual - next_item_size;
        if chain_post < 10 {
            score -= 8.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Post residual is dead space relative to the next item: penalize proportionally.
        score += 4.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
    }

    // Penalize opening new bins when many bins are already open and mean residual is high.
    if bin_residual == bin_capacity {
        // New-bin candidate score: base at mean residual level, adjusted.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = mean_residual * 0.8 + 20.0 * (1.0 - progress);
        if fitting_bins_count > 0 {
            score += 35.0; // discourage new bin when alternatives exist
        }
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 3.0; // fresh bin is flexible for the next item
        }
        return score;
    }

    // Mild preference for bins with larger residuals among fitting bins (best-fit bias).
    score -= 0.02 * bin_residual as f64;

    // Time-horizon modulation: late in the stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - fit_ratio);

    // Spread penalty: if many bins fit the item, prefer the tightest (post_residual already does this),
    // but add slight penalty proportional to fitting count to break ties toward scarce options.
    if fitting_bins_count > 1 {
        score += 1.5 * (fitting_bins_count as f64).ln();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap; // normalized post residual in [0,1]
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Smooth non-linear polynomial coupling of post_residual with stream progress:
    // residual waste is penalized progressively more as the stream advances.
    let waste_penalty = norm_pr * norm_pr * (0.5 + progress);
    score += 25.0 * waste_penalty;

    // Slight cubic shaping: mid-range residuals are mildly discouraged,
    // very tight fits (small post_residual) stay attractive.
    score += 8.0 * norm_pr * norm_pr * norm_pr * (1.0 - progress);

    // Reward bins that leave room for the lookahead item (smooth interaction).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt) / cap;
        let fit_quality = 1.0 - (gap.abs() * gap.abs());
        score -= 10.0 * fit_quality.max(0.0) * (1.0 - progress);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin, scaled smoothly by tightness of fit.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        let tightness = 1.0 - norm_pr;
        score -= 30.0 * (0.5 + tightness);
    }

    // Penalize opening a new bin when open bins have plenty of average room.
    if bin_residual == bin_capacity {
        let mean_over = mean_residual / cap;
        score += 15.0 * mean_over * (1.0 + progress);
    }

    // Smooth diversity pressure: many open bins -> prefer consolidating.
    let bin_pressure = (open_bins_count as f64).ln1p();
    score += 2.0 * bin_pressure * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover is divisible by
    // common item sizes (harmonic classes) are more reusable.
    let pr = post_residual;
    if pr > 0 {
        // Perfect fit: huge reward.
        if pr == 0 { score -= 1000.0; }
        // Dead-space penalty for tiny unusable leftovers (< smallest plausible item).
        if pr < 10 {
            score += 60.0 * (10 - pr) as f64;
        }
        // Harmonic class bonus: leftover divisible by 10/20/25/50 is "usable".
        if pr % 10 == 0 { score -= 12.0; }
        if pr % 20 == 0 { score -= 6.0; }
        if pr % 25 == 0 { score -= 6.0; }
        if pr % 50 == 0 { score -= 4.0; }

        // Integer-division threshold: leftover in [next_item_size .. next_item_size + slack]
        // can host the lookahead item -> reward.
        if next_item_size > 0 && pr >= next_item_size {
            score -= 10.0;
            // Exact harmonic match with lookahead class (same mod-10 bucket).
            if pr % 10 == next_item_size % 10 {
                score -= 8.0;
            }
            // Lookahead fits leaving another harmonic leftover.
            let pr2 = pr - next_item_size;
            if pr2 % 10 == 0 { score -= 5.0; }
        }
        // Penalize leftovers just barely too small for the lookahead item.
        if next_item_size > 0 && pr < next_item_size && next_item_size - pr <= 5 {
            score += 15.0;
        }
    }

    // Capacity-fraction coupling: reward filling to common fraction thresholds.
    let fill = (bin_capacity - bin_residual + item_size) as f64 / bin_capacity as f64;
    if (fill * 4.0).fract() < 1e-9 { score -= 8.0; }      // 25% multiples
    if (fill * 2.0).fract() < 1e-9 { score -= 4.0; }      // 50% multiples

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: make it costly unless open bins are nearly all full.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let avg_fill = 1.0 - mean_residual / bin_capacity as f64;
        // Open new bin only if existing bins are well packed.
        score += 55.0 - 45.0 * avg_fill - 15.0 * progress;
    }

    // Mild preference for tighter bins as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any item (1..=100, min size 1)
    // are pure waste; penalize heavily when post_residual falls into an unusable gap.
    if post_residual > 0 {
        // dead space = unusable if smaller than the smallest plausible upcoming item
        let dead = (post_residual as f64) < next_item_size.max(1) as f64;
        if dead {
            score += 60.0 + 0.5 * post_residual as f64;
        }
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 40.0;
    }

    // Tight fit reward: small post_residual relative to capacity
    score -= 25.0 * (1.0 - (post_residual as f64 / bin_capacity as f64)).powi(6);

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: discourage proliferation of bins
    score += 0.6 * open_bins_count as f64;

    // New-bin candidate: only attractive if no open bin is a good fit;
    // make empty bin mildly unattractive unless residuals are fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score += 30.0 - 0.2 * fragmentation;
        // If many open bins can fit, opening new bin is wasteful
        if fitting_bins_count > 1 {
            score += 25.0;
        }
        // Early stream: keep bins open longer
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * (1.0 - progress);
    }

    // Lookahead: if next item fits into post_residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }

    // Prefer bins below mean residual (more roomy bins for future items)
    score += 0.15 * ((bin_residual as f64) - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong penalty for unusable dead space: residual too small for any plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // 2-step lookahead: reward exact match of post_residual to next item size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 40.0 / (1.0 + diff);
        // Perfect chain fit: post_residual == next_item_size
        if post_residual as i64 == next_item_size as i64 {
            score -= 35.0;
        }
        // Penalize if next item won't fit here but a near-fit elsewhere exists
        if post_residual < next_item_size {
            score += 25.0;
        }
    }

    // Relative to mean residual: prefer bins tighter than average.
    score += (mean_residual - bin_residual as f64) * 0.6;

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: penalize slightly unless current bins create bad dead space.
    if bin_residual == bin_capacity {
        score += 15.0;
        if post_residual as i64 == next_item_size as i64 {
            score -= 50.0; // open a fresh bin for a perfect next-item fit
        }
    }

    // Mild early-stream exploration bonus for filling bins tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let is_new_bin = bin_residual == bin_capacity;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    if !is_new_bin {
        // Reward tight fits: minimize post_residual more aggressively.
        let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
        score -= 6.0 * tightness * (post_residual as f64);

        // Penalize dead space that cannot fit the next item (lookahead coupling).
        if next_item_size > 0 {
            if post_residual < next_item_size && post_residual > 0 {
                score += 12.0 * (1.0 - (post_residual as f64) / (next_item_size as f64));
            } else if post_residual >= next_item_size {
                // Reward bins that can also host the next item.
                score -= 4.0 * (1.0 - (post_residual as f64) / (bin_capacity as f64));
            }
        }

        // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
        if fitting_bins_count == 1 {
            score -= 25.0;
        }

        // Mild preference toward bins whose residual deviates below the mean
        // (concentrating packing into tighter bins).
        let dev = mean_residual - bin_residual as f64;
        score += 0.05 * dev;

        // Late in the stream, be greedier about filling existing bins to avoid
        // leaving many nearly-empty open bins.
        score -= 10.0 * progress * (1.0 - (post_residual as f64) / (bin_capacity as f64));
    } else {
        // New-bin candidate: baseline penalty so existing bins win on decent fits.
        score += 8.0;

        // Opening a new bin is attractive when the current fit is very poor
        // (large post_residual) and few alternatives exist.
        let fit_pressure = (post_residual as f64) / (bin_capacity as f64);
        score -= 20.0 * fit_pressure * fit_pressure;

        if fitting_bins_count <= 1 && next_item_size > 0 && post_residual < next_item_size {
            score -= 15.0; // poor fit + last chance + next item won't fit either
        }

        // Early in the stream, opening bins is cheaper (more future items to place).
        score -= 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let item = item_size as f64;
    let nxt = next_item_size as f64;

    let mut score = pr;

    // Smooth non-linear coupling: quadratic post-residual penalty scaled by progress
    score += 40.0 * norm_pr * norm_pr * (0.3 + 0.7 * progress);

    // Reward tight fits more strongly as the stream progresses
    score -= 25.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * progress;

    // Penalize residual that cannot fit the lookahead item (smooth logistic gate)
    if nxt > 0.0 {
        let fit_gap = (pr - nxt).abs();
        let gate = 1.0 / (1.0 + (pr - nxt) / cap * 8.0).exp();
        score += 12.0 * (fit_gap / cap) * gate;
    }

    // Last-chance bonus: only one fitting bin -> smooth reward
    if fitting_bins_count <= 1 {
        score -= 18.0 * (1.0 - norm_pr);
    }

    // Mild pressure from many open bins, coupled with progress
    score += 0.5 * open_bins_count as f64 * (0.5 + 0.5 * progress) * norm_pr;

    // Deviation from mean residual (fragmentation signal), smooth quadratic
    score += 6.0 * (pr - mean_residual).abs() / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: exact-fill and "harmonic" remainders
    // (divisors of capacity) are more likely to be completed by future items.
    let harmonic = |r: u32| -> f64 {
        if r == 0 { return -8.0; } // perfect fill
        let mut h = 0.0;
        for d in [10u32, 20, 25, 50] {
            if r % d == 0 { h -= 1.5; }
        }
        if r <= 5 { h -= 2.0; }    // tiny dead space is cheap
        if r > 50 { h += 1.0; }    // large leftover wastes a bin slot
        h
    };
    score += harmonic(post_residual);

    // Reward pairing with lookahead item when it fits snugly into post_residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        let snug = (post_residual - next_item_size) as f64;
        score -= 3.0 * (1.0 - snug / bin_capacity as f64);
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 1.0; // lookahead cannot use this leftover
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 6.0;
    }

    // New-bin candidate: only attractive when no open bin fits or residuals
    // are badly fragmented (mean residual small but many bins open).
    if bin_residual == bin_capacity {
        let frag = mean_residual / bin_capacity as f64;
        if fitting_bins_count == 0 {
            score -= 10.0;
        } else if frag < 0.15 && open_bins_count > 2 {
            score -= 1.0;
        } else {
            score += 4.0 + 0.1 * open_bins_count as f64;
        }
    }

    // Mild progress pressure: late in the stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 0.5 * progress * harmonic(bin_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual <= 15 {
        score += (16.0 - post_residual as f64) * 12.0;
    } else if post_residual > 15 && post_residual < 30 {
        score += (30.0 - post_residual as f64) * 2.0;
    }

    // Reward tight fits (near-zero waste) strongly.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // Open-bin pressure: prefer consolidating into fewer bins.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: make an empty bin unattractive unless
    // no good fit exists (dead-space penalties above dominate).
    if bin_residual == bin_capacity {
        score += 120.0;
        // Slightly cheaper to open new bins early in the stream.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= progress * 60.0;
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // reward this placement (creates a perfect follow-up fit).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 80.0;
        } else if post_residual > next_item_size && post_residual - next_item_size <= 5 {
            score -= 30.0;
        } else if next_item_size > post_residual && next_item_size > 0 && post_residual > 0 {
            // Next item won't fit here; mild penalty for leaving a large gap.
            score += (post_residual as f64 - mean_residual).abs() * 0.5;
        }
    }

    // Penalize placements far below the mean residual (wasting big bins).
    if (post_residual as f64) > mean_residual * 1.5 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward when the next item exactly fills this bin's post residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 60.0 * (1.0 - slack / bin_capacity as f64);
    }

    // Penalize post residuals that are dead space: too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Favor bins whose residual is below mean residual (tight fits) mildly.
    score -= 0.3 * (mean_residual - bin_residual as f64);

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Prefer opening a new bin when current bin would leave a large, awkward residual
    // and the next item is large (won't fit the leftover).
    if next_item_size > post_residual {
        score += 0.25 * post_residual as f64;
    }

    // New-bin candidate tuning: empty bins should only win when open bins fit poorly.
    if bin_residual == bin_capacity {
        score += 8.0 + 0.1 * open_bins_count as f64;
    }

    // Mild late-stream consolidation: fewer wasted bins as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) especially when scarce.
    if fitting_bins_count <= 1 {
        score -= 25.0;
    } else {
        score += 3.0 * (fitting_bins_count as f64).min(10.0);
    }

    // Lookahead: if next item fits in the post residual, reward this bin strongly.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 18.0 + 0.2 * (post_residual as f64 - next_item_size as f64).min(40.0);
        } else {
            // penalize leaving residual that next item cannot use (dead space)
            score += 0.15 * (post_residual as f64).min(60.0);
        }
    } else {
        // last item: maximize fill, penalize any residual
        score += 0.5 * post_residual as f64;
    }

    // Penalize opening a new bin unless nothing fits well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // new bin baseline penalty, softened when mean residual is high (open bins are full)
        score += 40.0 - 0.3 * mean_residual - 10.0 * progress;
    }

    // Prefer using bins with lower residual (waste minimization) mildly.
    score += 0.1 * (bin_residual as f64 - mean_residual).max(-30.0).min(30.0);

    // Slight preference for bins that become exactly full.
    if post_residual == 0 {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let base = pr;
    // normalized stream progress
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    // normalized post-residual fraction
    let f = pr / cap;
    // smooth non-linear coupling: dead-space penalty grows with progress and with residual squared
    let dead = f * f * (0.5 + t);
    // reward tight fits (small post residual) more strongly later in the stream
    let tight = -(1.0 - f) * (1.0 - f) * (0.3 + 0.7 * t);
    // last-chance bonus: strongly favor the only bin that fits
    let last_chance = if fitting_bins_count == 1 { -2.0 * (1.0 + t) } else { 0.0 };
    // lookahead: penalize if next item cannot use the post-residual
    let look = if next_item_size > 0 {
        let ns = next_item_size as f64;
        if ns > pr { 0.8 + 0.4 * t } else { -(1.0 - (pr - ns) / cap) * 0.5 }
    } else { 0.0 };
    // mild preference for filling bins with large residuals relative to mean
    let mean_pull = (mean_residual - pr) / cap * 0.3;
    let mut score = base + dead * cap * 0.5 + tight * cap * 0.5 + last_chance + look + mean_pull;
    // slight bias toward existing bins over opening new ones, decaying with progress
    if bin_residual == bin_capacity {
        score += 1.5 - 1.0 * t;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: classify post_residual by capacity fraction buckets.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / cap; // 0..1

    // Penalize residuals in "dead zones" that few item sizes (1..100) can use well.
    // Class boundaries at multiples of capacity/10 (integer-division style thresholds).
    let class = (post_residual * 10) / bin_capacity; // 0..=10 integer class
    let class_penalty: [f64; 11] = [
        0.0,   // 0: perfect fit
        6.0,   // 1: tiny dead space, nearly unusable
        8.0,   // 2
        10.0,  // 3
        9.0,   // 4
        6.0,   // 5: half-full residual still flexible
        4.0,   // 6
        3.0,   // 7
        2.0,   // 8
        1.0,   // 9: nearly empty residual, very flexible
        0.0,   // 10: untouched bin
    ];
    score += class_penalty[class as usize];

    // Modulo harmony: residual divisible by small item sizes is reusable.
    if post_residual > 0 {
        let mut harmony = 0.0;
        for d in [10u32, 20, 25, 50] {
            if post_residual % d == 0 { harmony += 2.5; }
        }
        score -= harmony * frac;
    }

    // Lookahead: reward if next item fits exactly into post_residual (perfect chain).
    if next_item_size > 0 && next_item_size <= post_residual {
        if next_item_size == post_residual {
            score -= 12.0; // exact follow-up fit
        } else if post_residual - next_item_size <= 10 {
            score -= 6.0; // near-exact chain leaves tiny waste
        } else {
            score -= 2.0; // next item fits at all
        }
    } else if next_item_size > post_residual && next_item_size > 0 {
        score += 4.0; // next item won't fit here; residual likely wasted
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Prefer tightest relative fit.
    score += frac * 5.0;

    // Slight preference to fill bins as stream progresses (consolidation).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (mean_residual - post) * 0.05 * (1.0 + progress);

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let best_existing = if fitting_bins_count > 0 { 1.0 } else { 0.0 };
        score += 20.0 * best_existing - 5.0 * (1.0 - best_existing) * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps (1..=15) are highly unusable.
    if post_residual > 0 && post_residual <= 15 {
        score += 60.0 * (16.0 - post_residual as f64) / 16.0;
    }
    // Perfect fit reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Prefer bins whose residual tightly matches the item (relative waste).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * tightness;

    // Open-bins pressure: with many open bins, favor filling existing bins
    // over opening new ones; with few bins, be more permissive.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open.
        score += 15.0 + 8.0 * pressure;
        // But if only this new bin can fit, allow it.
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
    } else if fitting_bins_count == 1 {
        // Last chance bin: strong reward to use it.
        score -= 40.0;
    }

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && (post_residual as i64 - next_item_size as i64) >= 0 {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && (post_residual as i64 - next_item_size as i64) < 0 {
        score += 8.0;
    }

    // Slight preference for bins below mean residual (consolidate fuller bins).
    score += 0.3 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual exactly matches next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
            // next item fits, penalize leftover gap after both placements
            let gap = post_residual - next_item_size;
            score += gap as f64 * 0.3;
        } else {
            // next item won't fit here; penalize small post residuals (dead space)
            let progress = step_index as f64 / total_items.max(1) as f64;
            score += (next_item_size - post_residual) as f64 * 0.2 * (0.5 + progress);
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score += (post_residual as f64 - mean_residual) * 0.4;

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 250.0;
    }

    // Penalize opening a new bin when good open bins exist
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 60.0 + 80.0 * progress;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 40.0; // new bin can serve next item too
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Penalize small unusable dead space (harder to fill later)
    if post > 0.0 && post < 10.0 {
        score += 25.0 * (10.0 - post) / 10.0;
    }
    // Reward near-perfect fills
    if post == 0.0 {
        score -= 40.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            score -= 12.0 * (1.0 - (post - nxt) / cap);
        } else {
            score += 6.0; // leaves dead space relative to lookahead
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Fragmentation pressure: prefer bins with residual above mean (keep big holes available)
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Time horizon: early on, prefer tight packing; late, prefer consolidating into few bins
    let t = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - t) * 5.0 * (post / cap);
    score += t * 2.0 * open_bins_count as f64;

    // New-bin candidate: only attractive when no open bin fits or item is huge
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 100.0;
        } else {
            score += 15.0 + 0.5 * open_bins_count as f64;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, but with non-linear decay so tiny
    // residuals are heavily favored (tight fits get exponentially better).
    let mut score = norm_pr * (1.0 + 2.5 * norm_pr * norm_pr);

    // Smooth polynomial coupling of post-residual with stream progress:
    // early in the stream, dead space matters less; late, it's critical.
    let coupling = norm_pr * (0.5 + 3.0 * progress * progress);
    score += coupling;

    // Reward bins whose residual matches the lookahead item (smooth bump).
    if next_item_size > 0 {
        let diff = (pr - next_item_size as f64).abs() / cap;
        score -= 0.8 * (1.0 - diff).max(0.0) * (1.0 - diff).max(0.0);
    } else {
        // Last item: any residual is dead weight; penalize quadratically.
        score += 1.5 * norm_pr * norm_pr;
    }

    // Last-chance bin bonus: smooth ramp, stronger as stream progresses.
    if fitting_bins_count == 1 {
        score -= 1.2 + 0.8 * progress;
    }

    // Mild penalty for spreading across many bins vs. mean residual context.
    let mean_norm = mean_residual / cap;
    score += 0.3 * (norm_pr - mean_norm) * (norm_pr - mean_norm);

    // New-bin candidate: neutral mid score, slightly worse late in stream
    // unless residual waste would be large; smooth rather than piecewise.
    if bin_residual == bin_capacity {
        score = 1.0 + 0.5 * progress - 0.4 * (item_size as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: classify post_residual by
    // integer division into capacity fractions (harmonic bins of the capacity).
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Class index: which harmonic band (0 = perfect fill, higher = more waste)
    let class = (post_residual * 4) / bin_capacity; // 0..3 bands of size cap/4
    let band_center = (class as f64 + 0.5) * cap / 4.0;
    // Reward being near a harmonic boundary (residual close to multiples of cap/4)
    let boundary_dist = (post - (class as f64) * cap / 4.0).abs();
    score -= (cap / 4.0 - boundary_dist) * 0.6;

    // Modulo arithmetic on post_residual: residues mod 10, 20, 25 (harmonic divisors of 100)
    let r10 = (post_residual % 10) as f64;
    let r20 = (post_residual % 20) as f64;
    let r25 = (post_residual % 25) as f64;
    score -= (10.0 - r10) * 0.25;
    score -= (20.0 - r20) * 0.15;
    score -= (25.0 - r25) * 0.15;

    // Penalize dead space that no plausible item can fill: post_residual < 10
    if post_residual < 10 && post_residual > 0 {
        score += 12.0;
    }
    // Perfect fit reward
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size < post_residual {
            let npost = post_residual - next_item_size;
            // favor chains where the second leftover also lands on a harmonic residue
            let nr = (npost % 10) as f64;
            score -= (10.0 - nr) * 0.3;
            if npost == 0 { score -= 20.0; }
        } else {
            // next item won't fit here; mildly penalize if this was the only fitting bin
            if fitting_bins_count == 1 {
                score += 8.0;
            }
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin should lose unless current open bins are tight
    if bin_residual == bin_capacity {
        let pressure = mean_residual / cap; // high = lots of slack around
        score += 18.0 * (1.0 - pressure);
        if open_bins_count == 0 { score -= 25.0; }
        // late in stream, avoid spawning bins unnecessarily
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * (1.0 - progress);
    }

    // Mild preference to fill bins below mean residual (balance avoidance of fragmentation)
    score += 0.1 * (mean_residual - bin_residual as f64).abs().sqrt();

    // Slight scaling with item size: prefer placing large items into tight bins
    score -= (item_size as f64 / cap) * (cap - post) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (below min item size 10)
    // are the worst outcome; penalize them heavily.
    if post_residual < 10 {
        score += 25.0 + (10 - post_residual) as f64 * 2.0;
    } else {
        // Prefer tight fits: reward small (but usable) post_residual.
        let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= 6.0 * tightness;
        // Non-linear penalty on medium dead space that is hard to fill later.
        if post_residual <= 30 {
            score += 0.15 * post_residual as f64;
        }
    }

    // Last chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += 0.4 * open_bins_count as f64;

    // New-bin candidate handling: opening a bin is only attractive when the
    // fit elsewhere would be poor (large post_residual or unusable gap).
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        let mut new_bin_cost = 14.0 + 0.5 * open_bins_count as f64;
        // If the lookahead item is large and current item leaves a bad gap,
        // opening a fresh bin becomes more attractive.
        if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
            new_bin_cost -= 8.0;
        }
        // Early in the stream, keeping bins tight matters less.
        let progress = step_index as f64 / total_items.max(1) as f64;
        new_bin_cost *= 1.0 + 0.5 * progress;
        score += new_bin_cost;
    }

    // Slight bonus when this bin's residual is above mean (use big spaces first).
    if bin_residual as f64 > mean_residual {
        score -= 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item fits the post residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Perfect chain: next item exactly fills the remainder
            if post_residual == next_item_size {
                score -= 40.0;
            } else {
                // Fractional match quality: closer post_residual to next_item_size = better
                let slack = (post_residual - next_item_size) as f64;
                score -= 25.0 * (1.0 - slack / bin_capacity as f64);
            }
        } else {
            // Next item won't fit here; penalize proportionally to overflow
            let overflow = (next_item_size - post_residual) as f64;
            score += 0.35 * overflow;
        }
    }

    // Relative to mean residual: prefer bins with less residual than average (tight fits)
    let residual_diff = post_residual as f64 - mean_residual;
    score += 0.30 * residual_diff;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Penalize creating tiny unusable dead space
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 12.0 };
        score += pressure + 0.5 * mean_residual;
        // Early in stream, keep bins open (amortize)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 8.0 * (1.0 - progress);
    }

    // Prefer filling more-open-bins regimes tightly
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more than linearly.
    let tight = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tight * tight;

    // Penalize dead space that is too small to ever be useful (below min item size 1..100).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Lookahead: reward bins whose post_residual can still host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            score += 6.0; // would strand the bin before next item arrives
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Penalize opening a new bin when existing bins fit, scaled by stream progress.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 45.0 + 30.0 * progress;
        if fitting_bins_count > 0 {
            score += 20.0;
        }
    }

    // Prefer bins with residual above the mean (keep small-residual bins for small items).
    let diff = (bin_residual as f64) - mean_residual;
    score += 0.15 * diff;

    // Mild load balancing: favor bins with larger residual when many bins are open.
    score += 0.05 * (open_bins_count as f64) * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let mut score = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let pr = post_residual as f64;
    let pr_norm = pr / bin_capacity as f64;
    let poly = pr_norm * pr_norm * (1.0 + progress) - pr_norm * progress * progress;
    score += 40.0 * poly;

    // Tight fits are rewarded, more so late in the stream
    let tightness = 1.0 - pr_norm;
    score -= tightness * tightness * (20.0 + 40.0 * progress);

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 + 25.0 * progress;
    }

    // Dead-space penalty: residuals too small for likely future items
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead: prefer bins whose post_residual fits the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        score += 4.0 * progress;
    }

    // Prefer fuller bins when many bins are open
    score -= (bin_residual as f64 / bin_capacity as f64) * (open_bins_count as f64).ln().max(1.0) * 5.0;

    // New-bin candidate: mildly penalize so it only wins when open bins are poor
    if bin_residual == bin_capacity {
        score += 12.0 + 30.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover fits small "companion" sizes
    // (the classic 50/34/33/25/20 residue classes) are valuable; penalize dead zones.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit is ideal
    } else {
        // Reward residuals that are harmonic divisors of capacity (50, 33, 25, 20, 10...)
        let harmonic = (bin_capacity % pr == 0) as f64;
        score -= 25.0 * harmonic;
        // Dead zone: leftover too small for the minimum item (1..100 range, be safe: < next_item_size)
        if next_item_size > 0 && pr < next_item_size {
            score += 45.0; // unusable residue unless nothing better exists
        }
        // Modulo-class coupling: leftover in [1..9] is nearly dead space
        if pr < 10 {
            score += 18.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 55.0;
    }

    // Lookahead: if the next item fits exactly in post_residual, big reward
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    } else if next_item_size > 0 && post_residual > next_item_size {
        score -= 10.0; // leaves a viable bin for the next item
    }

    // Prefer filling bins with low residual relative to the mean (best-fit flavor)
    let frac = post_residual as f64 / bin_capacity as f64;
    score += 15.0 * (frac - mean_residual / bin_capacity as f64);

    // Many open bins: encourage consolidation onto existing bins
    if open_bins_count > 4 {
        score -= 2.0 * open_bins_count as f64 * (1.0 - frac);
    }

    // New empty bin candidate: penalize opening a bin unless current bins are poor fits
    if bin_residual == bin_capacity {
        let urgency = if fitting_bins_count == 0 { 0.0 } else { 30.0 };
        score += urgency + 12.0 * mean_residual / bin_capacity as f64;
        // Late in stream, avoid opening new bins
        if total_items > 0 {
            let progress = step_index as f64 / total_items as f64;
            score += 25.0 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable dead space: residuals too small for typical future items
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Strongly prefer exact/tight fits
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward fitting into a bin when it's the only fitting bin (last chance)
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Pressure from number of open bins: discourage opening new bins when many are open
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 8.0;
    }

    // Lookahead: if next item fits in post_residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }

    // Penalize large post_residual waste relative to mean residual
    if (post_residual as f64) > mean_residual {
        score += ((post_residual as f64) - mean_residual) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: strongly favor bins whose post_residual
    // exactly matches the next item (perfect 2-chain), and reward when the
    // next item still fits in the leftover space.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        let diff = (post - nxt).abs();
        if nxt <= post {
            // next item fits: reward closeness to a perfect wrap
            score -= 25.0 * (1.0 - diff / bin_capacity as f64);
            if diff == 0.0 {
                score -= 40.0; // perfect two-item packing
            }
        } else {
            // next item won't fit: mild penalty proportional to overshoot
            score += 0.15 * (nxt - post);
        }
    }

    // Penalize leaving dead space that is too small for typical items
    // (unusable sliver), scaled by stream progression.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if post_residual > 0 && post_residual < 10 {
        score += 30.0 + 20.0 * progress;
    }

    // Compare against mean residual: prefer bins tighter than average
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate: make it attractive only when no open bin offers a
    // good fit (post_residual large relative to capacity means a fresh bin).
    if bin_residual == bin_capacity {
        // Neutral-ish baseline: fresh bin keeps flexibility early,
        // less desirable late in the stream.
        score = bin_capacity as f64 * 0.5 + 40.0 * (1.0 - progress);
        if next_item_size > 0 && (next_item_size as f64) <= (bin_capacity as f64) {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post-residual), with non-linear squash.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 45.0 * tightness * tightness;

    // Penalize dead space that no future item (size >= 10 normally) can use.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item exactly or well.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 70.0;
        } else if post_residual >= next_item_size {
            score -= 25.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here: mild penalty scaled by how much we strand.
            score += 8.0 + 0.15 * post_residual as f64;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + 0.3 * (bin_residual - item_size) as f64;
    }

    // New-bin candidate: prefer it only when residual is small and item is large,
    // or when open bins are mostly full (mean residual low).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let item_frac = item_size as f64 / bin_capacity as f64;
        // Opening a new bin is attractive for large items late in the stream
        // or when existing bins have little room.
        let open_bias = 12.0 * item_frac + 20.0 * progress
            + 15.0 * (1.0 - mean_residual / bin_capacity as f64);
        score += 55.0 - open_bias;
    } else {
        // Mild penalty for spreading across many open bins when mean residual is high.
        if mean_residual > bin_capacity as f64 * 0.5 {
            score += 5.0;
        }
    }

    // Slight preference to fill earlier-opened bins as stream progresses.
    score += 0.02 * open_bins_count as f64 * (1.0 - step_index as f64 / (total_items.max(1) as f64));

    // Exact-fill jackpot.
    if post_residual == 0 {
        score -= 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let r = bin_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_frac = item_size as f64 / cap;
    let pr_norm = pr / cap;

    // Base: prefer small post-residual, with smooth non-linear shaping
    let mut score = pr + 6.0 * pr_norm * pr_norm * cap;

    // Smooth polynomial coupling between post-residual and stream progress:
    // early on, waste matters more (bins are "cheap" in count but long horizon);
    // late, tight packing dominates.
    let coupling = (1.0 - progress) * (pr_norm * pr_norm) + progress * (pr_norm * pr_norm * pr_norm);
    score += 30.0 * coupling * cap;

    // Reward high fill ratio smoothly (quadratic in fit fraction)
    score -= 20.0 * fit_frac * fit_frac * cap * 0.1;

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits exactly in post_residual, reward strongly
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let tight = 1.0 - (pr - nxt) / cap;
            score -= 10.0 * tight * tight;
        } else {
            // penalize leaving residual that next item can't use
            score += 4.0 * (nxt - pr) / cap;
        }
    }

    // Mild penalty for spreading across many open bins relative to mean residual
    let dev = (r - mean_residual).abs() / cap;
    score += 3.0 * dev * dev * cap * 0.1;

    // New-bin candidate: discourage unless current bin would be badly wasted
    if bin_residual == bin_capacity {
        let waste = pr_norm; // = 1 - fit_frac for empty bin
        score += 15.0 + 40.0 * waste * waste * cap * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: quantize dead space into buckets
    // (0-5 perfect, 6-15 great, 16-30 ok, 31-50 poor, 51+ terrible).
    let class = match post_residual {
        0 => 0.0,
        1..=5 => 2.0,
        6..=15 => 6.0,
        16..=30 => 14.0,
        31..=50 => 30.0,
        _ => 55.0,
    };
    score += class * 1.5;

    // Exact-fill bonus: zero dead space is golden.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: does the leftover space fit the next item?
    // Harmonic pairing: post_residual and next_item in the same "size class"
    // (same integer division band) means the residual is reusable.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Residual is reusable: reward proportionally to tightness of the pairing.
            let tight = 1.0 - (post_residual - next_item_size) as f64 / cap_f;
            score -= 12.0 * tight;
            // Same harmonic band (both /10) => strong pairing bonus.
            if post_residual / 10 == next_item_size / 10 {
                score -= 8.0;
            }
        } else {
            // Residual cannot serve the next item: penalize dead space harder
            // when next item is small (it will need a compact slot elsewhere).
            let waste = (next_item_size - post_residual) as f64;
            score += 0.15 * waste;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate (empty bin): penalize so we only open when open bins fit poorly.
    if bin_residual == bin_capacity {
        score += 30.0;
        // Exception: big items late in the stream deserve fresh bins when
        // the next item is also big (pairing large items together).
        if next_item_size >= 50 && item_size >= 50 && post_residual == 0 {
            score -= 60.0;
        }
    }

    // Early stream: be frugal with bins; late stream: consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (mean_residual / cap_f);

    // Prefer bins whose residual deviates from the mean (specialized bins).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harder than large ones.
    // A residual below the minimum item size (1..100 unknown, assume ~10 threshold) is dead space.
    let dead_threshold = 10.0;
    if (post_residual as f64) < dead_threshold {
        score += 60.0;
    } else if (post_residual as f64) < 2.0 * dead_threshold {
        score += 25.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Open-bin pressure: discourage spreading across many bins when alternatives exist.
    score += 0.35 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: make it moderately attractive only when current fit is poor
    // (post_residual leaves a large unusable gap relative to capacity).
    if bin_residual == bin_capacity {
        // neutral base: capacity residual, plus slight bias toward consolidation
        score += 8.0;
        // if lookahead item fits well in a fresh bin, tilt toward opening
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 5.0;
        }
    }

    // Coupling with mean residual: prefer bins whose residual deviates beneficially
    // (using a bin with residual below mean consolidates fragmentation).
    score -= (mean_residual - bin_residual as f64) * 0.15;

    // Late-stream tightening: as stream progresses, avoid creating any residual at all.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.5;

    // Lookahead synergy: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0;
    } else if next_item_size > post_residual {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

