    // Relative-to-mean coupling: prefer bins tighter than average.
    score += (mean_residual - bin_residual as f64) * 0.8;

    // Last-chance bin: strongly favor using it to avoid opening a bin.
    if fitting_bins_count == 1 {
        score -= 150.0;
    }

    // Mild penalty for spreading across many open bins late in stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * 0.3 * (1.0 - progress);

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        score += 120.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 40.0; // fresh bin still usable for next item
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
