        let ns = next_item_size as f64;
        let gap = (pr - ns).abs();
        score -= 6.0 * (1.0 - gap / cap) * (1.0 - gap / cap);
        if pr >= ns {
            score -= 4.0;
        }
    }

    // Mild penalty for spreading across too many open bins.
    score += 0.05 * open_bins_count as f64 * (pr / cap);

    // Prefer placing large items into tight bins (small residual before).
    score -= 0.1 * (item_size as f64 / cap) * (bin_residual as f64 / cap) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual modulo 10: small "harmonic" residuals
    // (multiples of 10) are more reusable, reward them.
    let harmonic = (post_residual % 10) as f64;
    score += harmonic * 0.8;

    // Integer-division thresholds: post_residual in a "dead zone" (< 10)
    // is nearly unusable; penalize proportionally.
    if post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 8.0;
    }

    // Reward tight fits (post_residual small but nonzero).
    if post_residual > 0 && post_residual <= 5 {
        score -= 12.0;
    }

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Coupling with next item: if next item fits exactly into post_residual,
    // strongly reward leaving that residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 10.0 - slack * 0.3;
        if slack <= 5.0 {
            score -= 8.0;
        }
    }
    // If next item cannot fit in this residual, mildly penalize holding space.
    if next_item_size > post_residual && post_residual > 0 {
        score += 4.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless current fit is bad.
    if bin_residual == bin_capacity {
        score += 18.0;
        // If the item is large, opening a new bin is more attractive.
        score -= (item_size as f64) * 0.15;
        // Early in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += (1.0 - progress) * 10.0;
    }

    // Prefer bins whose residual is far from the mean residual (diversity of classes).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Many open bins: discourage spreading, favor filling existing ones.
    score += (open_bins_count as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in [1,9] are nearly unusable
    // (min item size is 10 in the classic regime) -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 60.0;
    }

    // Mild reward for leaving a gap that exactly fits the lookahead item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }
    // Penalize a gap that is too small even for the next item but nonzero.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor tight fills.
    let open_pressure = (open_bins_count as f64).ln().max(0.0) * 4.0;
    score += open_pressure * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when the item leaves a large,
    // reusable residual and existing bins are tightly packed.
    if bin_residual == bin_capacity {
        score += 12.0;
        if post_residual >= 10 {
            score -= 8.0;
        }
        // If mean residual across open bins is small, opening fresh is fine.
        score -= (mean_residual / bin_capacity as f64) * 10.0;
    }

    // Late in the stream, consolidate: prefer filling existing bins tighter.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    // Post residual can still fit the next item: strong reward.
    else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0 + (post_residual - next_item_size) as f64 * 0.1;
    }
    // Next item cannot use the leftover: penalize dead space, worse when small.
    else if next_item_size > 0 && post_residual < next_item_size {
        score += 20.0 + (next_item_size - post_residual) as f64 * 0.5;
    }

    // Last-chance bin: strong incentive to use it before opening a new one.
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // Penalize opening a new bin when open bins have plenty of room.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 80.0;
        }
        // New bin is attractive only if it promises a tight future fit.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 30.0;
        }
    }

    // Prefer bins tighter than the mean residual (compact packing).
    score -= (mean_residual - bin_residual as f64) * 0.3;

    // Slight preference to keep many small leftovers consolidated early.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * 0.2 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;

    if is_new_bin {
        // Opening a new bin: base cost = wasted capacity of the fresh bin.
        // If other bins can fit the item, opening a new one is usually wasteful,
        // unless the existing fits are terrible (huge post_residual) or the
        // next item is large and we want a big empty canvas.
        let existing_penalty = if fitting_bins_count == 0 {
            -1000.0 // no alternative: new bin is mandatory, always attractive
        } else {
            // how bad would the best alternative be? approximate via mean_residual
            let alt_waste = (mean_residual - item_size as f64).max(0.0);
            // penalty scales with number of alternatives and their quality
            let alternatives = fitting_bins_count as f64;
            15.0 + 2.0 * alternatives + 0.5 * alt_waste
        };

        // Lookahead: if next item is large, a fresh bin is slightly more valuable
        let lookahead_bonus = if next_item_size > 0 && next_item_size >= 50 {
            -8.0 * (next_item_size as f64 / bin_capacity as f64)
        } else {
            0.0
        };

        // Late in the stream, avoid opening new bins (fewer items to fill them)
        let late_penalty = 10.0 * progress;

        score = post_residual as f64 + existing_penalty + lookahead_bonus + late_penalty;
    } else {
        // Existing bin: reward tight fits strongly (small post_residual).
        // Perfect fit gets a big bonus.
        if post_residual == 0 {
            score -= 50.0;
        } else {
            // dead-space penalty: relative waste grows if residual becomes unusable
            let waste_ratio = post_residual as f64 / bin_capacity as f64;
            score += 5.0 * waste_ratio * waste_ratio;
        }

        // Last-chance bin (only one fitting bin): strongly favor using it
        if fitting_bins_count == 1 {
            score -= 12.0;
        }

        // Lookahead synergy: if next item fits exactly in the post_residual,
        // this placement sets up a perfect follow-up.
        if next_item_size > 0 {
            if post_residual == next_item_size {
                score -= 20.0;
            } else if post_residual < next_item_size {
                // post_residual too small for next item: mild penalty (dead space)
                score += 3.0;
            }
        }

        // Prefer filling bins that are already quite full (consolidate waste)
        let fullness = 1.0 - (bin_residual as f64 / bin_capacity as f64);
        score -= 4.0 * fullness;

        // Slight preference early on to keep many bins partially open for flexibility
        score += 1.5 * (1.0 - progress) * (open_bins_count as f64).ln().max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual

    // Base: prefer small post residual (tight fit), with non-linear polynomial shaping
    let mut score = pr as f64;

    // Non-linear coupling: tight fits are rewarded more as the stream progresses
    let tightness = 1.0 - x; // 0 = empty-ish, 1 = perfect fit
    score -= (progress * tightness * tightness) * 30.0;

    // Penalize mid-range dead space (unusable chunks) with a smooth bump
    let bump = 4.0 * x * (1.0 - x); // peaks at x=0.5
    score += bump * 12.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Lookahead coupling: reward leaving room for the next item
    let nx = next_item_size as f64;
    if nx > 0.0 {
        let gap = (x - nx / cap).abs();
        score += gap * 15.0 * (1.0 - progress);
        if nx <= pr as f64 {
            score -= 8.0;
        }
    }

    // Mild penalty for spreading across too many open bins
    score += (open_bins_count as f64) * 0.4 * (1.0 - progress);

    // Deviation from mean residual: prefer bins whose residual stays near average
    score += (mean_residual - pr).abs() * 0.15;

    // Smooth saturation penalty for very large post residuals
    score += x * x * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space into capacity fractions
    let cap_f = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / cap_f; // fraction of capacity left over

    // Penalize leftovers in "dead zones": tiny slivers (0 < frac < 0.1) and
    // awkward mid-gaps (0.3..0.5) that few future items can exploit.
    if post > 0 {
        if frac < 0.1 {
            score += 12.0; // nearly-full bin: fine actually, keep it cheap? no — small leftover is GOOD
        }
    }
    // Correct: tiny leftover is desirable (tight fit). Reward it.
    if post > 0 && frac < 0.1 {
        score -= 10.0;
    } else if frac >= 0.3 && frac < 0.5 {
        score += 8.0; // awkward gap class
    } else if frac >= 0.5 {
        score += 3.0; // half-empty: mediocre
    }

    // Integer-division threshold classes on post_residual
    let cls = post_residual / 10; // decile class
    score += match cls {
        0 => -6.0,
        1 => -3.0,
        2 => 0.0,
        3 => 4.0,
        4 => 6.0,
        5 => 2.0,
        6 => 5.0,
        7 => 7.0,
        8 => 4.0,
        _ => 1.0,
    } as f64;

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 15.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size < 10 {
            score -= 8.0; // next item leaves near-zero waste
        } else if next_item_size > post_residual && next_item_size > item_size {
            score += 5.0; // next item won't fit here anyway; mild penalty for wasting big gap
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 14.0;
    }

    // New-bin candidate: neutral-ish score anchored at capacity, modulated by stream position
    if bin_residual == bin_capacity {
        score = cap_f * 0.9 + (open_bins_count as f64) * 2.0
            - (step_index as f64 / total_items.max(1) as f64) * 5.0;
        if next_item_size > 0 && next_item_size >= 70 {
            score -= 20.0; // big item coming: fresh bin attractive
        }
    }

    // Slight preference for filling bins with high residual relative to mean
    score -= 0.05 * (bin_residual as f64 - mean_residual);

    // Harmonic modulo coupling: reward when item_size and residual share residue class
    if bin_residual % 10 == item_size % 10 && bin_residual >= item_size {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftovers are nearly unusable (min item 1..100)
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // unusable sliver
    } else if post_residual < 20 {
        score += 15.0;
    } else if post_residual < 35 {
        score += 5.0;
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Open-bin pressure: with many open bins, prefer compacting into existing bins
    let pressure = (open_bins_count as f64).ln().max(0.0) * 6.0;
    if bin_residual < bin_capacity {
        score -= pressure;
    } else {
        // New bin candidate: penalize opening unless it enables a good future fit
        score += pressure + 10.0;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 25.0; // new bin can host the lookahead item
        }
    }

    // Lookahead synergy: if next item fits the post residual, reward this placement
    if next_item_size > 0 && bin_residual < bin_capacity && next_item_size <= post_residual {
        score -= 20.0;
    }
    // Penalize leaving a gap just barely too small for the next item
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // Early stream: be a bit more willing to open bins for flexibility
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= (1.0 - progress) * 15.0;
    }

    // Prefer bins tighter than average (best-fit flavor)
    score -= (mean_residual - bin_residual as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: huge reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if next item fits exactly or well into post_residual, reward
    if next_item_size > 0 && next_item_size <= post_residual {
        let next_fit_quality = (post_residual - next_item_size) as f64;
        score -= 40.0 - next_fit_quality * 0.3;
        // Exact two-item chain closure
        if post_residual == next_item_size {
            score -= 500.0;
        }
    } else if next_item_size > 0 {
        // next item won't fit here: penalize proportionally to wasted residual
        score += post_residual as f64 * 0.5;
    }

    // Penalize small dead space that nothing can use (sizes >= 1, so any residual usable,
    // but small residuals relative to mean are less valuable)
    if post_residual > 0 && (post_residual as f64) < mean_residual * 0.5 {
        score += 15.0;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: penalize opening a new bin when decent fits exist,
    // unless the item fits poorly everywhere (large post_residual elsewhere)
    if bin_residual == bin_capacity {
        score += 80.0;
        // If lookahead item is large, a fresh bin may be valuable
        if next_item_size > 0 && next_item_size as f64 > bin_capacity as f64 * 0.6 {
            score -= 60.0;
        }
    }

    // Prefer filling bins with low residual relative to mean (compact bins)
    score += (bin_residual as f64 - mean_residual) * 0.2;

    // Late in stream: consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * post_residual as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic penalty on wasted space, stronger for near-full bins
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tight * tight;

    // Lookahead coupling: bonus if the next item fits the post-residual exactly-ish
    if next_item_size > 0 && (post_residual as i64 - next_item_size as i64) >= 0 {
        let gap = (post_residual as f64 - next_item_size as f64) / bin_capacity as f64;
        score -= 15.0 * (1.0 - gap);
    } else if next_item_size > 0 {
        // next item won't fit: mild penalty proportional to leftover unusable space
        score += 4.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless residuals are all tiny
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 - 25.0 * pressure - 10.0 * progress;
    }

    // Penalize bins far below mean residual (fragmented space hoarding)
    score += 0.5 * (mean_residual - bin_residual as f64).abs();

    // Late stream: prefer filling existing bins more aggressively
    let horizon = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * horizon;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: f64, fitting_bins_count: usize) -> f64 {
    let _ = item_size;
    let _ = bin_residual;
    let _ = open_bins_count;
    let _ = mean_residual;
    let _ = next_item_size;
    let _ = fitting_bins_count;
    let mut score = post_residual;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residuals divisible by large
    // class sizes are more likely to be filled by future items.
    let pr = post_residual;
    if pr > 0 {
        let mut bonus = 0.0;
        if pr % 50 == 0 { bonus += 12.0; }
        if pr % 25 == 0 { bonus += 6.0; }
        if pr % 10 == 0 { bonus += 4.0; }
        if pr % 5 == 0 { bonus += 2.0; }
        // Small residuals are dead space; penalize the awkward band 1..=9.
        if pr < 10 { score += 30.0; }
        score -= bonus;
    } else {
        // Perfect fit: strongly reward.
        score -= 60.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // this is a chained perfect fit — reward heavily.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0;
        } else if next_item_size <= pr {
            // Next item fits: reward proportional to how well it fills.
            let fill = next_item_size as f64 / pr as f64;
            score -= 10.0 * fill;
            if pr % next_item_size == 0 && next_item_size > 0 {
                score -= 8.0; // divisible residual: likely exact future fill
            }
        } else {
            // Next item won't fit here: mild penalty if this bin would be left
            // in the awkward small-residual band anyway.
            if pr < 10 { score += 10.0; }
        }
    }

    // Last-chance bin: if this is the only bin that can fit the item, using it
    // avoids opening a new bin — reward.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // Many candidates: prefer tighter fits, penalize loose ones mildly.
        score += 2.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // New-bin candidate handling: an empty bin has high residual; only prefer
    // it when no open bin offers a good fit (i.e. when its raw score would
    // otherwise win). Penalize opening new bins while open bins are plentiful,
    // scaled by stream progression.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let new_bin_penalty = 20.0 + 25.0 * (1.0 - progress) + 2.0 * open_bins_count as f64;
        score += new_bin_penalty;
        // But if the item is large and would leave a tiny residual anywhere,
        // a fresh bin is attractive: soften penalty for big items.
        if item_size >= 70 {
            score -= 30.0;
        }
    }

    // Mean residual coupling: if this bin's residual is far below the mean,
    // it is already tight — prefer using it to consolidate.
    let dev = mean_residual - bin_residual as f64;
    score -= 0.15 * dev;

    // Mild reward for keeping mean residual high (balanced packing) when the
    // bin remains usable after placement.
    if post_residual >= 20 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps (< 10, minimum item size)
    // are permanently unusable -> heavy penalty; usable gaps are fine.
    if post_residual < 10 {
        score += 60.0 * (1.0 - post_residual as f64 / 10.0);
    } else {
        // Reward tight fits: smaller post_residual relative to capacity is good,
        // but reward exact/near-exact fills even more.
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        score -= 25.0 * fill_ratio;
    }

    // Penalize leaving gaps that the next item cannot use (lookahead coupling).
    if next_item_size > 0 && post_residual > 0 {
        if post_residual < next_item_size {
            score += 12.0;
        } else {
            score -= 8.0 * (next_item_size as f64 / post_residual as f64).min(1.0);
        }
    }

    // Open-bin pressure: prefer spreading into existing bins when many are open,
    // so we don't keep too many bins alive; but if this is the LAST fitting bin,
    // strongly reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    } else {
        score += 2.0 * open_bins_count as f64;
    }

    // New-bin candidate handling: an empty bin has large residual; make it
    // unattractive unless existing bins would create bad dead space.
    if bin_residual == bin_capacity {
        score += 45.0 + 3.0 * open_bins_count as f64;
    }

    // Slight preference for bins with lower-than-mean residual (denser bins first).
    score += 0.15 * (mean_residual - bin_residual as f64);

    // Late-stream consolidation: as the stream progresses, tighten packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: item + next item exactly fills the bin -> strongly reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual > next_item_size {
            // Next item fits too; reward tightness of the two-step fit.
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; penalize leaving a small dead gap.
            let gap = (next_item_size - post_residual) as f64;
            if post_residual < 10 {
                score += 40.0; // nearly unusable dead space
            } else {
                score += gap * 0.5;
            }
        }
    }

    // Relative-to-mean coupling: prefer bins whose post residual stays near mean residual
    // (balanced packing), unless it's a tight two-step match.
    score += 0.3 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize wasting a fresh empty bin when the item is small relative to capacity.
    if bin_residual == bin_capacity {
        score += 10.0 + item_size as f64 * 0.2;
        // But opening a new bin is fine for large items or when nothing fits well elsewhere.
        if item_size >= 50 && next_item_size > 0 && next_item_size > item_size {
            score -= 25.0;
        }
    }

    // Late in the stream, prefer consolidating into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Reward tight fits
    score -= 12.0 * (item_size as f64 / bin_residual.max(1) as f64);

    // Penalize dead space that can't fit the smallest plausible item
    if post_residual < 10 {
        score -= 25.0; // near-perfect fill
    } else if post_residual < next_item_size.max(1) as f64 && next_item_size > 0 {
        score += 8.0; // residual useless for lookahead item
    }

    // Lookahead: reward bins whose post-residual fits next item well
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size as u32) as f64;
        score -= 6.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        score += 4.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 3 {
        score += 2.0 * (fitting_bins_count as f64 - 3.0);
    }

    // Late in stream: consolidate, prefer fuller bins
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Penalize bins far from mean residual (fragmentation control)
    score += 0.15 * (post_residual as f64 - mean_residual).abs();

    // New-bin candidate: only attractive when open bins are crowded or fit is poor
    if bin_residual == bin_capacity {
        let crowding = if open_bins_count > 0 { open_bins_count as f64 } else { 0.0 };
        let poor_fit = (item_size as f64 / bin_capacity as f64) < 0.5;
        score = 55.0 - 3.0 * crowding * progress - if poor_fit { 10.0 } else { 0.0 };
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, shaped by a smooth polynomial in stream progress.
    // Early on, prefer tight fits moderately; later, dead space matters more.
    let progress_weight = 0.5 + 1.5 * progress * progress;
    let mut score = pr * progress_weight;

    // Non-linear coupling: quadratic dead-space penalty scaled by progress.
    score += 30.0 * norm_pr * norm_pr * (0.3 + progress);

    // Reward near-perfect fits with a smooth bell-shaped bonus.
    let fit_quality = 1.0 - norm_pr;
    score -= 25.0 * fit_quality * fit_quality * fit_quality * fit_quality;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 40.0 * (1.0 - 0.5 * progress);
    }

    // Penalize bins whose residual deviates badly from the mean (fragmentation).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 8.0 * dev * dev;

    // Lookahead: reward bins that can also accommodate the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let snug = (post_residual - next_item_size) as f64 / cap;
        score -= 12.0 * (1.0 - snug * snug);
    } else if next_item_size > 0 {
        score += 10.0 * progress;
    }

    // New-bin candidate: judge whether opening a fresh bin is attractive.
    if bin_residual == bin_capacity {
        // Attractive early or when existing bins are very full / few fit.
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let tight = (mean_residual / cap).max(0.0).min(1.0);
        let newbin_appeal = 55.0 + 60.0 * (1.0 - progress) * (1.0 - tight) + 35.0 * scarcity;
        // Compare against typical placement scores: keep it high unless placement is bad.
        score = newbin_appeal + pr * 0.2 - (item_size as f64) * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: penalize residuals in "dead zones"
    // that few plausible item sizes (1..=100) can fill.
    let cap_f = bin_capacity as f64;
    let pr = post_residual as f64;

    // Fraction of capacity remaining after placement.
    let frac = pr / cap_f;

    // Harmonic class: bucket post_residual into 10 classes via integer division.
    let class = post_residual / 10;
    // Residuals in the lowest classes (tiny slivers) are worst; reward large usable classes.
    let class_bonus: f64 = match class {
        0 => 18.0,            // 0..9: nearly unusable
        1 => 12.0,            // 10..19
        2 => 7.0,             // 20..29
        3 => 3.0,             // 30..39
        4 => 0.0,             // 40..49: neutral
        5 => -3.0,            // 50..59
        6 => -5.0,            // 60..69
        7 => -6.0,            // 70..79
        8 => -6.5,            // 80..89
        9 => -7.0,            // 90..99
        _ => -8.0,            // full empty bin
    };
    score += class_bonus;

    // Exact-fill reward: perfect packing is ideal.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Modulo coupling: if next_item_size fits exactly into post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0;
        if post_residual % next_item_size == 0 {
            score -= 12.0; // next item tiles the remainder perfectly
        }
        // next item leaves a harmonic-class-friendly remainder too
        let next_post = post_residual - next_item_size;
        if next_post % 10 == 0 {
            score -= 4.0;
        }
    } else if next_item_size > 0 {
        // Next item cannot use this remainder: penalize proportional to dead space.
        score += 0.05 * pr.min(next_item_size as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin is a fallback; make it slightly
    // attractive only when current fit is poor (large post_residual dead space).
    if bin_residual == bin_capacity {
        score += 4.0 + 0.10 * (open_bins_count as f64);
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    // Stream progression: late in the stream, tighten packing (avoid new bins).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 6.0 * progress * (1.0 - frac);

    // Mean residual coupling: if this bin's residual is far below mean, it's a
    // good "garbage collector" bin; reward closing the gap.
    let gap = mean_residual - (bin_residual as f64);
    score += 0.08 * gap;

    // Small tie-breaker on tight fits.
    score += 0.02 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever
    // accommodate even the smallest plausible item are pure waste.
    let dead_threshold = 10u32;
    if post_residual < dead_threshold {
        // Perfect fill is ideal; tiny unusable gap is penalized hard.
        score += (dead_threshold - post_residual) as f64 * 3.0;
    } else if post_residual == 0 {
        score -= 40.0; // exact fill reward
    }

    // Penalize moderate dead space proportionally (wasted capacity).
    if post_residual >= dead_threshold {
        score += (post_residual as f64 / bin_capacity as f64) * 12.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins rather than opening new ones.
    let open_pressure = open_bins_count as f64 / (1.0 + (total_items as f64).max(1.0) / 20.0);
    if bin_residual == bin_capacity {
        // Candidate is a brand-new empty bin: only attractive when current
        // bins are nearly full on average (poor fits elsewhere).
        score += 55.0 + open_pressure * 8.0;
        if mean_residual < 25.0 {
            score -= 30.0; // existing bins are tight, new bin justified
        }
    } else {
        // Reward using an existing bin, more so under open-bin pressure.
        score -= 8.0 + open_pressure * 2.0;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid forcing a
    // new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post
    // residual, strongly favor this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here anyway; a snug-but-not-perfect fit is fine.
        score += (next_item_size as f64 - post_residual as f64).min(20.0) * 0.3;
    }

    // Progression: late in the stream, tighten up — less tolerance for
    // leftover slack since fewer chances to recover remain.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * progress * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward post_residual that exactly matches next_item_size
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += gap * 0.8;
        // Perfect two-item fill: huge reward
        if post_residual == next_item_size {
            score -= 60.0;
        }
        // Next item still fits after this placement: mild reward
        if post_residual >= next_item_size {
            score -= 10.0;
        } else if post_residual > 0 && post_residual < 10 {
            // tiny dead space below min item size: penalize heavily
            score += 40.0;
        }
    } else {
        // Last item: just minimize leftover
        score += post_residual as f64 * 0.5;
    }

    // Relative to mean residual: prefer bins tighter than average
    score -= (mean_residual - bin_residual as f64) * 0.3;

    // Last chance bin: strong bonus to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize opening a new bin when decent open bins exist
    if bin_residual == bin_capacity {
        // new-bin candidate: base cost plus pressure from open bins
        score += 5.0 + open_bins_count as f64 * 2.0;
        // but if lookahead would fit perfectly in a fresh bin, soften
        if next_item_size > 0 && (bin_capacity as i64 - item_size as i64 - next_item_size as i64) == 0 {
            score -= 30.0;
        }
    }

    // Dead-space penalty for large unusable leftovers
    if post_residual > 0 && next_item_size > post_residual {
        score += post_residual as f64 * 0.4;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual) nonlinearly.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += fit_ratio * fit_ratio * 30.0;

    // Penalize large dead space when the leftover cannot fit the lookahead item.
    if next_item_size > 0 && (post_residual as f64) < next_item_size as f64 {
        score += 25.0 + (next_item_size as f64 - post_residual as f64) * 0.5;
    } else if next_item_size > 0 {
        // Reward bins that can still host the next item.
        score -= 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize unless current bin residuals are all poor fits.
    if bin_residual == bin_capacity {
        let poor_fits = (mean_residual - item_size as f64).abs();
        let threshold = 15.0 + 25.0 * (step_index as f64 / total_items.max(1) as f64);
        if poor_fits < threshold && fitting_bins_count > 0 {
            score += 40.0; // keep using open bins early / when fits exist
        } else {
            score -= 5.0; // allow fresh bin for bad fits or late stream
        }
    }

    // Slight preference for bins with residuals close to the mean (balanced packing).
    score += ((bin_residual as f64 - mean_residual).abs()) * 0.15;

    // Time horizon: late in the stream, be more conservative with leftovers.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.2;

    // Many open bins: encourage filling existing ones rather than spreading.
    score += (open_bins_count as f64).ln().max(0.0) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Base: prefer tight fits (small post_residual), with non-linear emphasis
    let mut score = post * (1.0 + 2.0 * norm_post * norm_post);

    // Polynomial coupling with stream progress: early on tolerate slack,
    // later demand tight packing
    let progress_weight = 0.5 + 2.5 * t * t;
    score += progress_weight * post * norm_post;

    // Reward near-exact fits with smooth quadratic bonus
    let exactness = 1.0 - norm_post;
    score -= 30.0 * exactness * exactness * exactness;

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * t;
    }

    // Penalize bins whose residual deviates from the mean (balance pressure)
    score += 0.15 * (post - mean_residual).abs();

    // Lookahead: if next item fits in post_residual, reward this placement
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            score -= 8.0 * (1.0 - (post - nxt) / cap);
        } else {
            score += 5.0 * (nxt - post) / cap;
        }
    }

    // Mild pressure against proliferating open bins early in the stream
    score += 0.5 * open_bins_count as f64 * (1.0 - t);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: capacity divided into 10 classes of 10 units.
    let class = post_residual / 10;
    // Small post-residual classes (tight fits) are desirable: reward them.
    match class {
        0 => score -= 45.0,               // near-perfect fill
        1 => score -= 30.0,               // excellent fill
        2 => score -= 18.0,               // good fill
        3 => score -= 8.0,                // decent fill
        4 => score += 4.0,                // half-full: mediocre
        5 => score += 10.0,               // awkward zone
        6 => score += 16.0,
        7 => score += 20.0,
        8 => score += 14.0,               // large residual may still host big items
        _ => {}                            // nearly empty bin: leave as-is
    }

    // Integer-division coupling: does the residual class fit the next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item can follow into this bin: reward proportional to how well it nests.
            let slack = post_residual - next_item_size;
            score -= 12.0 + (slack as f64).min(40.0) * 0.25;
            // Bonus when next item lands in the same tight class band.
            if (next_item_size / 10) == class {
                score -= 10.0;
            }
        } else {
            // Next item cannot fit here: penalize unless post residual is tiny anyway.
            score += 8.0;
            if post_residual < 10 {
                score -= 6.0; // dead space is already minimal, acceptable
            }
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded or fit is bad.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let pressure = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
        let bad_fit = if post_residual >= next_item_size && next_item_size > 0 { 0.0 } else { 20.0 };
        score += 55.0 * (1.0 - pressure) + bad_fit;
        // Late in the stream, new bins are cheaper to open than to fragment.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 15.0 * progress;
    }

    // Mild penalty when this bin is far below the mean residual (fragmenting outlier).
    let dev = mean_residual - post_residual as f64;
    if dev > 0.0 {
        score += dev * 0.15;
    }

    // Tie-break: prefer bins with tighter original residual (denser bins first).
    score += bin_residual as f64 * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for any item (1..100, min size 1)
    // are pure waste; small gaps below typical item sizes are heavily penalized.
    if post_residual == 0 {
        // Perfect fit: strongly rewarded.
        score -= 60.0;
    } else if post_residual < 10 {
        // Unusable dead space: severe penalty.
        score += 80.0;
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 40 {
        score += 8.0;
    }

    // Reward leaving room for the lookahead item (k=2 lookahead).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // This bin can still host the next item: reward proportionally.
            score -= 6.0 + 0.15 * next_item_size as f64;
        } else {
            // Placement strands the next item elsewhere: mild penalty scaled by waste.
            let waste = (next_item_size as f64 - post_residual as f64).min(40.0);
            score += 0.2 * waste;
        }
    }

    // Last-chance pressure: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: prefer spreading into already-open bins when many are open,
    // but slightly prefer emptier bins (higher residual) to consolidate load.
    score -= 0.4 * open_bins_count as f64;
    score -= 0.05 * (bin_residual as f64 - mean_residual);

    // New-bin candidate handling: an empty bin should only win when no open bin
    // offers a decent fit (post_residual of a fit into an open bin is small/good).
    if bin_residual == bin_capacity {
        // Penalize opening a new bin; escalate with stream progress (sunk capacity).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 30.0 + 40.0 * progress;
        // If no existing bin can fit the item, new bin is the only choice: soften.
        if fitting_bins_count == 0 {
            score -= 70.0;
        }
    }

    // Mild tightness reward: relative fill quality of this placement.
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= 10.0 * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward when the next item exactly fills the post residual (perfect 2-step chain).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            let gap = (post_residual - next_item_size) as f64;
            // Reward tight fits for the next item, decaying with gap.
            score -= 30.0 * (1.0 - gap / bin_capacity as f64).max(0.0);
        } else {
            // Next item cannot fit here: penalize leaving awkward dead space.
            let dead = (next_item_size - post_residual) as f64;
            score += 0.35 * dead.min(60.0);
        }
    }

    // Prefer bins whose residual is already below average (compact bins absorb items well).
    score += 0.25 * (mean_residual - bin_residual as f64);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize new-bin candidate slightly unless residuals are all tight.
    if bin_residual == bin_capacity {
        score += 12.0 + 0.4 * mean_residual;
    }

    // Mild late-stream pressure to close out bins rather than spread across many.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.1 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress of the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // ---- New-bin candidate handling ----
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // A new bin has perfect post_residual = capacity - item_size, which looks
        // artificially good. Penalize it so we only open a new bin when no open
        // bin offers a decent fit.
        score += 25.0;

        // Late in the stream, or when many bins fit, strongly discourage new bins.
        if fitting_bins_count > 1 {
            score += 30.0;
        }
        if progress > 0.7 {
            score += 15.0 * progress;
        }
        // If the current item leaves a lot of dead space AND the next item is small,
        // an existing bin with room for the next item may be better; still mildly
        // penalize the fresh bin.
        if next_item_size > 0 && (next_item_size as f64) <= post_residual as f64 {
            score += 10.0;
        }
        // Last-chance scenario: only one fitting bin, so a new bin is competitive.
        if fitting_bins_count <= 1 {
            score -= 20.0;
        }
    }

    // ---- Lookahead coupling: reward bins whose post_residual can host next item ----
    if next_item_size > 0 && !is_new_bin {
        if (next_item_size as u32) <= post_residual {
            // Chain fit: excellent packing, reward proportionally to how tight it is.
            let tightness = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 8.0 + 12.0 * tightness;
        } else {
            // Next item won't fit here; penalize large dead space that likely becomes waste.
            score += 0.05 * (post_residual as f64 - next_item_size as f64).max(0.0);
        }
    }

    // ---- Perfect/near-perfect fit reward ----
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    } else if post_residual < 10 {
        // Small dead space threshold: bins below 10 residual are nearly useless.
        score -= 10.0;
    }

    // ---- Penalize leaving residuals that are hard to fill later ----
    // Residuals in (10, 30) are awkward: too small for typical items, too big to ignore.
    if post_residual > 10 && post_residual < 30 {
        score += 6.0;
    }

    // ---- Global state coupling ----
    // When many bins are open, prefer tightening existing ones (consolidation).
    let open_pressure = open_bins_count as f64 / (1.0 + mean_residual.max(1.0) / 10.0);
    if !is_new_bin {
        score -= 0.02 * open_pressure * (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    }

    // ---- Deviation from mean residual: prefer bins that reduce residual spread ----
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.03 * dev * (1.0 - progress);

    // ---- Last-chance bonus: if this is the only bin that fits, use it ----
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 15.0;
    }

    // ---- Time horizon: early on, be flexible (mild penalty for very tight fits
    // that could be saved), late in stream, pack greedily. ----
    if progress < 0.3 && post_residual < 15 && post_residual > 0 {
        score += 5.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    // Base: penalize wasted post-residual, but with diminishing quadratic penalty
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth coupling: wasted space matters more later in the stream
    let urgency = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score += urgency * 12.0 * norm_pr * norm_pr * cap;

    // Reward tight fits (small post_residual relative to item)
    score -= 15.0 * norm_item * (1.0 - norm_pr).max(0.0);

    // Lookahead: reward if next item fits the post-residual exactly-ish
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        let fit_next = (1.0 - gap / cap).max(0.0);
        score -= 10.0 * fit_next * fit_next;
        // penalize post-residual that is just barely too small for next item
        if pr < next_item_size as f64 {
            score += 6.0 * (1.0 - pr / next_item_size.max(1) as f64) * progress;
        }
    }

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 20.0 + 25.0 * progress;
    }

    // Mild pressure to consolidate when many bins are open relative to mean residual
    let mean_gap = (mean_residual - pr) / cap;
    score -= 5.0 * mean_gap;

    // Slight preference for using existing bins over opening new ones,
    // decaying as stream progresses (late stream: allow new bins for clean fits)
    let is_new_bin = (bin_residual as f64 - cap).abs() < 1e-6;
    if is_new_bin {
        score += 8.0 * (1.0 - progress) + 4.0 * norm_item * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small residue" classes (hard to reuse) get penalized.
    let cap = bin_capacity as f64;
    let pr = post_residual;
    let residue_class = pr % 10; // decade class of leftover
    let dead_penalty = match residue_class {
        0 => -6.0,           // perfectly reusable decade leftover
        1..=3 => 2.0,        // sliver leftovers are near-dead space
        4..=7 => 0.0,
        8..=9 => 1.5,
        _ => 0.0,
    };
    score += dead_penalty;

    // Integer-division thresholds: leftover that can still host the next item is golden.
    if next_item_size > 0 && pr >= next_item_size {
        score -= 8.0 + 0.15 * (pr - next_item_size) as f64;
        // exact harmonic pairing: post_residual is an integer multiple of next item
        if pr % next_item_size == 0 {
            score -= 5.0;
        }
    } else if next_item_size > 0 {
        // leftover cannot host the lookahead item -> dead space risk
        score += 4.0;
    }

    // Fraction-of-capacity classes for post residual
    let frac = pr as f64 / cap;
    if frac < 0.05 { score += 6.0; }        // nearly full: excellent, keep it cheap
    else if frac < 0.15 { score -= 2.0; }
    else if frac < 0.35 { score -= 1.0; }
    else { score += 1.0 * frac; }           // big leftovers: mild penalty

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: penalize mildly so it's chosen only when open bins are bad,
    // but reward it late in the stream or when few bins fit.
    if bin_residual == bin_capacity {
        score += 12.0;
        if fitting_bins_count == 0 { score -= 30.0; }
        if fitting_bins_count == 1 { score -= 6.0; }
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if progress > 0.8 { score += 3.0; }
    }

    // Tight-fill bonus: item consumes a harmonic fraction of the bin
    let fill = item_size as f64 / cap;
    if (fill * 4.0).round() / 4.0 == fill { score -= 2.0; } // 25/50/75/100% fills

    // Coupling with mean residual: prefer bins below mean (concentrate fill)
    score += 0.5 * (bin_residual as f64 - mean_residual).max(0.0) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to fit any
    // plausible future item are wasted. Penalize unusable gaps heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 25.0;
    } else if post_residual >= 20 && post_residual < 35 {
        score += 10.0;
    } else {
        // Large usable gaps are good: reward them.
        score -= (post_residual as f64) * 0.15;
    }

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when open bins are crowded
    // (mean residual low) or the fit here would create dead space.
    if bin_residual == bin_capacity {
        let crowded = mean_residual < item_size as f64 * 1.2;
        if crowded {
            score -= 20.0;
        } else {
            score += 45.0;
        }
        // Early in the stream, avoid proliferating bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += (1.0 - progress) * 15.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins rather than spreading.
    if bin_residual != bin_capacity {
        score -= (open_bins_count as f64) * 1.5;
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // this placement is excellent; if next item cannot fit, penalize
    // leaving a gap that only the next item could have used.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size > post_residual && post_residual > 0 && post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Mild preference for tighter existing bins (smaller residual before placement).
    score += (bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 50.0;
    }

    // Near-match: post_residual close to next item size (within 5).
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if gap < 5.0 {
            score -= (5.0 - gap) * 4.0;
        }
        // Penalize leaving residual that can't fit the next item but is large dead space.
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Penalize residual far above the mean residual (hoarding space in this bin).
    score += (post_residual as f64 - mean_residual).max(0.0) * 0.5;

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Penalize very small unusable residuals (dead space), but not at end of stream.
    if post_residual < 10 && post_residual > 0 {
        score += (10 - post_residual) as f64 * 1.5;
    }

    // Mild preference for tighter fits overall.
    score += (item_size as f64 / bin_capacity as f64) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: perfect fill gets a big bonus.
    if post_residual == 0 {
        score -= 50.0;
    } else {
        // Penalize dead space that is too small to fit typical future items.
        let dead = post_residual as f64;
        if dead < 10.0 {
            score += 20.0; // tiny unusable sliver
        }
        // Reward residuals that could still fit a mid-range item.
        score -= (dead / (dead + 20.0)) * 15.0;
    }

    // Lookahead coupling: if the next item fits in the post-residual, reward.
    if next_item_size > 0 {
        if (post_residual as u64) >= (next_item_size as u64) {
            score -= 12.0 + 0.15 * (next_item_size as f64);
        } else if (post_residual as u64) < (next_item_size as u64)
            && (bin_residual as u64) >= (next_item_size as u64)
        {
            // Using this bin for the current item wastes space the next item needed.
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Time horizon: early in the stream, be more conservative (prefer new bins
    // for large items to keep flexibility); later, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 10.0;

    // Global state coupling: many open bins with high mean residual -> consolidation pressure.
    if open_bins_count > 2 {
        score += 0.05 * (open_bins_count as f64 - 2.0);
        score -= 0.05 * mean_residual;
    }

    // Slight penalty for filling a nearly-full bin with a huge item leaving awkward residue.
    if post_residual > 0 && post_residual < item_size / 2 {
        score += 5.0;
    }

    // New-bin candidate: only attractive when it beats consolidating poorly.
    if bin_residual == bin_capacity {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress.
    let p2 = progress * progress;
    let p3 = p2 * progress;

    // Base cost: wasted space, weighted more heavily as stream progresses.
    let mut score = pr * (1.0 + 0.8 * p2 + 0.6 * p3);

    // Non-linear penalty for very small post_residual (dead space) growing with progress.
    let tight = 1.0 - norm_pr; // 1 when item fills bin almost perfectly
    score -= 12.0 * tight * tight * (0.5 + progress);

    // Reward bins whose residual matches the next item (smooth quadratic gap term).
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score -= 6.0 * (1.0 - gap / cap).max(0.0) * (1.0 - gap / cap);
    } else {
        // Last item: strongly prefer filling bins tightly.
        score += 2.0 * pr;
    }

    // Penalize spreading across many open bins (encourage consolidation), smoothly.
    score += 0.35 * open_bins_count as f64 * norm_pr;

    // Deviation from mean residual: prefer bins with less residual (denser bins).
    score += 0.5 * (pr - mean_residual);

    // Last-chance bonus: only one fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 10.0 * (1.0 + progress);
    }

    // Mild penalty for opening a brand-new bin when alternatives exist.
    if bin_residual == bin_capacity {
        score += 8.0 + 6.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: capacity fractions
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap;

    // Reward placements that leave residuals in "harmonic" reusable classes
    // (multiples of 10 or near-capacity-fraction values are easier to fill later)
    let class_bonus = if post_residual == 0 {
        -30.0 // perfect fill is best
    } else if post_residual % 10 == 0 {
        -12.0 - (pr / 20.0) // exact decile residual: highly reusable
    } else if frac > 0.7 {
        -8.0 // large residual still flexible
    } else if frac > 0.4 {
        0.0
    } else {
        10.0 + (0.4 - frac) * 40.0 // dead space penalty grows for tiny residuals
    };
    score += class_bonus;

    // Tight fit reward: item fills most of the bin
    let tightness = item_size as f64 / bin_residual as f64;
    score -= tightness * 15.0;

    // Lookahead coupling via integer-division thresholds on next_item_size
    if next_item_size > 0 {
        let nxt = next_item_size;
        if post_residual >= nxt {
            // next item fits here too: strong reward, scaled by how "classy" the pair is
            let pair_fit = ((post_residual - nxt) % 10 == 0) as i32 as f64;
            score -= 10.0 + pair_fit * 8.0;
        } else {
            // next item won't fit: penalize leaving residual that matches a bad class
            let cls = (post_residual / nxt.max(1)) as f64;
            score += 4.0 + cls.min(5.0);
        }
        // Harmonic modulo check: item + next divisible into capacity nicely
        if (item_size + nxt) % 100 == 0 && post_residual == 0 {
            score -= 20.0;
        }
    } else {
        // last item: strongly prefer zero residual
        score -= 5.0;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate handling: only attractive early or when all fits are terrible
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        let open_cost = 25.0 + open_bins_count as f64 * 3.0;
        score += open_cost * (1.0 - 0.3 * progress);
        // allow new bin if mean residual is very fragmented
        if mean_residual < 15.0 {
            score -= 20.0;
        }
    }

    // Mild pressure to consolidate when many bins are open
    score += open_bins_count as f64 * 0.5 - mean_residual * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are too small to host even the
    // smallest plausible item are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual == 0 {
        // Perfect fit: strongly rewarded.
        score -= 80.0;
    } else if post_residual >= 10 && post_residual < 25 {
        // Moderately small gap: mild penalty scaled by gap smallness.
        score += (25 - post_residual) as f64 * 0.8;
    }

    // Reward leaving a gap exactly matching the lookahead item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }
    // Penalize if the lookahead item cannot use the leftover gap.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // Last-chance pressure: if this is the only bin that fits, prefer using it
    // over opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage spreading across many bins when a tight
    // option exists; the more open bins, the stronger the push to fill one.
    score += open_bins_count as f64 * 2.0;

    // Alignment with mean residual: bins already below-average residual are
    // good consolidation targets.
    score -= (mean_residual - post_residual as f64) * 0.5;

    // New-bin candidate: make it attractive only when the item is large
    // relative to typical open-bin residuals (poor fits elsewhere).
    if bin_residual == bin_capacity {
        score = (bin_capacity - item_size) as f64 + 20.0;
        if fitting_bins_count == 1 {
            score += 40.0; // don't abandon the sole fitting bin easily
        }
        if next_item_size > 0 && (bin_capacity - item_size) as f64 >= next_item_size as f64 {
            score -= 15.0; // new bin leaves useful space for lookahead
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual with next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match bonus (strong)
        if diff == 0.0 {
            score -= 200.0;
        } else {
            score += diff * 1.5;
        }
        // If next item can't fit in the post-residual, penalize dead space creation.
        if (post_residual as u64) < (next_item_size as u64) && post_residual > 0 {
            score += post_residual as f64 * 0.8;
        }
    }

    // Reward tight fits relative to mean residual of open bins.
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += (tightness - mean_residual / bin_capacity as f64) * 30.0;

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 50.0;
    }

    // New-bin candidate (empty bin): penalize moderately so we prefer reusing
    // open bins unless the fit is genuinely bad; allow opening when post_residual
    // would leave large unusable waste in an existing bin.
    if bin_residual == bin_capacity {
        score += 120.0 - tightness * 0.0;
        // Opening a new bin is attractive if current item is small relative to capacity
        // (fresh bin keeps flexibility for future items).
        score -= (bin_capacity - item_size) as f64 * 0.5;
    }

    // Early in stream: slight preference for consolidating into few bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * (open_bins_count as f64) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: squared waste penalty
    score += (post_residual as f64).powi(2) / (bin_capacity as f64 * 2.0);

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current bins are poor fits
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin
        score += 20.0;
        // If the item would leave lots of dead space in existing bins, new bin is more attractive
        let avg_waste_elsewhere = (mean_residual - item_size as f64).abs();
        if avg_waste_elsewhere > 40.0 {
            score -= 18.0;
        }
        // Early in stream, opening bins is cheaper; late in stream, consolidate
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
        // If many open bins, discourage new bins
        score += (open_bins_count as f64).ln().max(0.0) * 3.0;
    }

    // Lookahead compatibility: reward if next item fits the post-residual of this bin
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            // dead space that next item cannot use
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
        // reward bins whose residual after placement matches next item exactly
        if post_residual == next_item_size {
            score -= 12.0;
        }
    }

    // Prefer filling bins that are already mostly full (low residual) over sparse bins
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 6.0 * fill_ratio;

    // Penalize bins whose residual deviates strongly from mean residual (keep bin profile balanced)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Slight preference for larger items going into larger-residual bins
    if item_size as f64 > mean_residual {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with non-linear sharpening
    let mut score = pr * (1.0 + 0.5 * norm_pr * norm_pr);

    // Smooth coupling with stream progress: later in stream, penalize waste more strongly
    score += 8.0 * pr * (progress * progress);

    // Penalize dead space that no plausible next item can use
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - pr).max(0.0);
        score += 0.4 * gap * (1.0 + progress);
    } else {
        // last item: strongly prefer near-zero residual
        score -= 6.0 * (1.0 - norm_pr) * (1.0 - norm_pr);
    }

    // Last-chance bonus: if this is the only fitting bin, reward using it
    if fitting_bins_count == 1 {
        score -= 10.0 + 5.0 * progress;
    }

    // Mild penalty when bin residual deviates from mean residual (keeps pool homogeneous)
    score += 0.05 * (pr - mean_residual).abs() * (1.0 + 0.5 * progress);

    // Slight preference to fill existing bins over opening new ones as stream grows
    score += 0.02 * (open_bins_count as f64) * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: small post_residual is good.
    let c = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / c; // capacity fraction left over

    // Penalize dead space in coarse harmonic bands (0, 10, 20, ... 100).
    let band = (post_residual / 10) as f64;
    score += 0.8 * band * band;

    // Reward perfect or near-perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    } else if post_residual <= 10 {
        score -= 15.0;
    }

    // Lookahead: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size < post_residual {
            // next item fits: reward proportional to how snugly
            let slack = (post_residual - next_item_size) as f64;
            if slack <= 10.0 {
                score -= 40.0 - 2.0 * slack;
            } else {
                score -= 15.0;
            }
        } else {
            // next item will NOT fit here: penalize wasting a large residual
            score += 0.5 * ((next_item_size - post_residual) as f64);
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Prefer fuller bins overall (compare against mean residual).
    score += 0.3 * (mean_residual - (bin_residual as f64));

    // Modulo-class logic: residuals that are multiples of 10 are "reusable"
    // harmonic slots for typical item sizes; reward them slightly.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 5.0;
    }

    // Early in the stream, be more willing to open/keep bins flexible;
    // late in the stream, pack tight (weight the dead-space penalty).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.3 * progress;

    // New-bin candidate: neutral-ish baseline; only choose it if it beats
    // genuinely bad fits. Give it a mild penalty that shrinks as stream grows.
    if bin_residual == bin_capacity {
        score += 45.0 - 20.0 * progress;
        // But if current item is large, a fresh bin is attractive.
        if item_size > bin_capacity / 2 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps more than proportionally.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Favor bins whose residual can still fit the lookahead item after placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones.
    if bin_residual == bin_capacity {
        score += 15.0 + 3.0 * open_bins_count as f64;
    }

    // Slight preference for fuller bins relative to the mean residual.
    score += 0.3 * ((mean_residual - bin_residual as f64).max(0.0));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Two-step lookahead: reward when the leftover space exactly matches the next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match: strong reward.
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual > next_item_size {
            // Next item could still fit here: mild reward proportional to closeness.
            score -= (20.0 / (1.0 + diff / 10.0));
        } else {
            // Dead space the next item cannot use: penalize.
            score += diff * 0.5;
        }
    }

    // Penalize very tight leftovers that become unusable dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // Perfect fill: strong reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Compare against mean residual: prefer bins that are already relatively full
    // (low residual) so emptier bins stay flexible.
    score += (mean_residual - bin_residual as f64) * 0.4;

    // Last-chance bonus: if this is the only bin that fits, using it avoids a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: prefer it only when no good fit exists elsewhere.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin, softened late in the stream or
        // when many bins are open (fragmented state).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 55.0 - 20.0 * progress + 2.0 * open_bins_count as f64;
        // If the next item is large, an empty bin is more valuable.
        if next_item_size > 60 {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 20.0;

    // Penalize dead space: residuals too small for likely future items
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Lookahead: reward if next item fits into post_residual
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0;
            // extra reward for near-exact pair fit
            let pair_waste = post_residual as f64 - next_item_size as f64;
            score -= (1.0 - pair_waste / bin_capacity as f64) * 10.0;
        } else {
            // penalize blocking the next item
            score += 8.0;
        }
    }

    // New-bin candidate handling: empty bin is a fallback; make it less attractive
    // unless current bin would leave large unusable residual
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 30.0;
        // cheaper to open a new bin early in the stream (more future to amortize)
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (1.0 - progress) * 15.0;
        // if many open bins already, opening new bins is worse (fragmentation)
        score += open_bins_count as f64 * 1.5;
    }

    // Global state coupling: if mean residual is high, prefer spreading load
    // into bins with residual below mean (balance), above mean (consolidate)
    let dev = bin_residual as f64 - mean_residual;
    score += dev * 0.1;

    // Prefer filling bins with larger residuals when few bins remain open
    if open_bins_count > 0 {
        score -= (bin_residual as f64 / bin_capacity as f64) * (open_bins_count as f64).ln().max(1.0) * 3.0;
    }

    // Late-stream urgency: consolidate aggressively as stream ends
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * (bin_capacity - post_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: quadratic penalty on post residual, modulated by stream progress.
    // Early in the stream, residual space is valuable (future items may fit);
    // late in the stream, minimizing residual per bin matters more.
    let mut score = pr * (1.0 + progress * norm_pr * 2.0);

    // Smooth cubic coupling: penalize large residuals more as progress grows.
    score += progress * norm_pr * norm_pr * 40.0;

    // Dead-space penalty: residual that no plausible item can use.
    // Penalize residuals in the awkward low range (below typical item sizes),
    // smoothly via a bump function rather than piecewise constants.
    let bump = (-(norm_pr * 6.0 - 1.5) * (norm_pr * 6.0 - 1.5)).exp();
    score += bump * 15.0 * (0.5 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly reward using it
    // (avoid opening a new bin unnecessarily).
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - progress * 0.5);
    }

    // Prefer bins with residuals close to the item (tight fits) via smooth term.
    let tightness = 1.0 - (bin_residual as f64 - item_size as f64) / cap;
    score -= tightness * 8.0;

    // Lookahead: reward leaving room for the next item if it would fit.
    if next_item_size > 0 {
        if (next_item_size as f64) <= pr {
            score -= 10.0 * (1.0 - pr / cap);
        } else {
            score += 5.0;
        }
    }

    // Mildly prefer keeping the number of open bins low early on; late, spread is fine.
    score += open_bins_count as f64 * (1.0 - progress) * 0.5;

    // Slight preference for bins whose residual is near the mean residual (balance).
    score += ((pr - mean_residual) / cap).abs() * 5.0;

    // New-bin candidate: make empty bins attractive only when post-fit residual is large
    // and existing fits are poor; penalize otherwise via smooth gate.
    if bin_residual == bin_capacity {
        score += 30.0 - 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
