pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold even the
    // smallest plausible future item are dead space. Penalize hard, and
    // increasingly so as the gap shrinks below the danger threshold.
    let dead_threshold: f64 = 10.0;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 12.0;
    }

    // Perfect / near-perfect fits are gold: reward subtracting from score.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 2 {
        score -= 15.0;
    }

    // Reward bins whose residual after placement can still host the
    // lookahead item (good chaining), penalize if it just barely cannot.
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 6.0;
        } else if (bin_residual as u32) >= next_item_size && (post_residual as u32) < next_item_size {
            score += 4.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, using it avoids
    // opening a new bin. Strong reward.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading into
    // fresh space; prefer filling existing bins tighter.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * 2.5;

    // New-bin candidate: only attractive when the item is huge relative to
    // typical residuals or no good fit exists. Penalize default new-bin
    // score so it is chosen only when open bins waste space badly.
    if bin_residual == bin_capacity {
        score += 20.0;
        // If the current item plus the next one would both fit nicely in a
        // fresh bin, make the new bin more appealing.
        if next_item_size > 0 && (next_item_size as u32) <= post_residual {
            score -= 12.0;
        }
        // Late in the stream, consolidating is cheaper than opening bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 * progress;
    }

    // Mild coupling with mean residual: if the average open-bin residual is
    // large, prefer bins that reduce spread (post_residual near mean).
    let diff = (post_residual as f64 - mean_residual).abs();
    score += diff * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item exactly fills post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            // next item fits here afterwards: mild reward proportional to closeness
            let gap = (post_residual - next_item_size) as f64;
            score -= 120.0 / (1.0 + gap / 10.0);
        } else {
            // next item cannot use post_residual: penalize dead space
            let waste = (next_item_size - post_residual) as f64;
            score += 0.6 * waste;
        }
    }

    // Compare post_residual against mean residual: avoid creating below-average usable space
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it instead of opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is terrible
    if bin_residual == bin_capacity {
        score += 250.0;
        if post_residual as f64 > mean_residual + 20.0 {
            score -= 100.0;
        }
    }

    // Late in stream: prefer tighter packing
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio;

    // Penalize dead space that cannot fit the next item (lookahead coupling).
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Wasted space relative to lookahead need.
            score += 0.5 * (next_item_size - post_residual) as f64;
        } else {
            // Space usable by next item: reward.
            score -= 0.3 * next_item_size as f64;
        }
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 10 {
        // Nearly perfect fit, hard to reuse tiny slivers anyway.
        score -= 20.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    } else if fitting_bins_count > 1 {
        // Many alternatives: prefer the tightest, mild penalty for slack.
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Global residual state: if mean residual is large, prefer reusing
    // existing capacity rather than spreading items.
    if bin_residual as f64 > mean_residual {
        score += 0.2 * (bin_residual as f64 - mean_residual);
    } else {
        score -= 0.1 * (mean_residual - bin_residual as f64);
    }

    // Time horizon: early in stream, be pickier about slack (long future);
    // late in stream, just close bins out.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let horizon = 1.0 - progress;
    score += horizon * 0.15 * post_residual as f64;
    score -= progress * 15.0;

    // New-bin candidate: penalize opening a new bin unless current bin
    // would be left with unusable sliver or no open bin fits well.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        let poor_fit = post_residual > 0 && post_residual < 10;
        let many_open = open_bins_count > 3;
        if !(poor_fit && many_open) {
            score += 25.0 + 0.5 * open_bins_count as f64;
        } else {
            score += 5.0;
        }
    }

    // Mild preference for bins whose residual after placement is a
    // "round" reusable size (multiples of 10).
    if post_residual > 0 && post_residual % 10 == 0 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let prn = pr / cap;

    // Base: prefer small post-residual, with non-linear polynomial shaping
    let mut score = pr * (1.0 + 0.8 * prn * prn);

    // Progress coupling: later in stream, penalize residual more strongly (quadratic ramp)
    score += prn * (1.0 + progress * progress * 40.0);

    // Reward tight fits (small post_residual) more as stream progresses
    score -= (1.0 - prn) * (1.0 - prn) * (10.0 + 30.0 * progress);

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    } else {
        // slight penalty when many bins compete (encourage spreading)
        score += (fitting_bins_count as f64).ln().max(0.0) * 2.0;
    }

    // Dead-space penalty: post_residual too small for typical future items
    if pr > 0.0 && pr < 10.0 {
        score += (10.0 - pr) * 2.5;
    }

    // Lookahead: if next item fits in post_residual, reward; else penalize
    if next_item_size > 0 {
        if (next_item_size as f64) <= pr {
            score -= 8.0 * (1.0 - pr / cap);
        } else {
            score += 4.0 * (next_item_size as f64 - pr).min(40.0) / 10.0;
        }
    }

    // Mean-residual coupling: penalize bins far from mean residual (deviation)
    let dev = (pr - mean_residual).abs();
    score += dev * 0.15;

    // Mild penalty on opening new bins when open bins exist, scaled by progress
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 15.0 + 25.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class: bins whose post_residual falls in "usable" residue classes
    // (multiples of 10, since min item is 10) are less dead than odd residuals.
    let res_mod = post_residual % 10;
    if res_mod == 0 {
        score -= 8.0; // perfect harmonic slot, future small items can fill exactly
    } else {
        score += (10 - res_mod) as f64 * 1.5; // dead space penalty grows with distance to harmony
    }

    // Fraction-of-capacity classes: post_residual in (0,10] is nearly dead
    if post_residual > 0 && post_residual <= 10 {
        score += 25.0;
    } else if post_residual <= 20 {
        score += 10.0;
    } else if post_residual >= 40 {
        score -= 6.0; // roomy enough for medium items
    }

    // Lookahead coupling: if next item fits harmonically into post_residual, reward strongly
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0; // perfect closure
        } else if next_item_size < post_residual {
            let gap = post_residual - next_item_size;
            let gap_mod = gap % 10;
            score -= 10.0;
            if gap_mod == 0 { score -= 8.0; } else { score += gap_mod as f64 * 1.2; }
        } else {
            score += 5.0; // next item won't fit here anyway
        }
    }

    // Last-chance bin: avoid forcing a new bin when this is the only fitting one
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate: penalize slightly so we prefer decent existing fits,
    // but allow opening when existing residuals are all poor (harmony-aware).
    if bin_residual == bin_capacity {
        score += 12.0;
        // if mean residual across open bins is in a bad harmonic class, opening is fine
        let mean_mod = (mean_residual as u32) % 10;
        if mean_mod != 0 { score -= 10.0; }
        if post_residual as f64 > mean_residual { score -= 4.0; }
    }

    // Progression: late in the stream, consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 3.0 * (post_residual as f64 / bin_capacity as f64);

    // Tight fit reward
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 10.0;

    // Mild pressure to use many-open-bins state
    score += open_bins_count as f64 * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small nonzero gaps are worst (unusable slivers).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual <= 20 {
        score += 15.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Reward residual that matches the lookahead item (pre-packing).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 50.0;
    }

    // Open-bin pressure: many open bins -> discourage fragmenting space further.
    score += (open_bins_count as f64) * 1.5;

    // Prefer bins tighter than the mean residual (denser bins).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // New-bin candidate: penalize opening a new bin unless the item is huge
    // relative to residual or fits are scarce.
    if bin_residual == bin_capacity {
        let scarce = if fitting_bins_count == 0 { 0.0 } else { 80.0 };
        score += 120.0 + scarce - (item_size as f64) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual already does this).

    // 2-step lookahead: reward bins whose post_residual matches the next item size.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let match_bonus = 40.0 / (1.0 + (post_residual as f64 - next).abs() / 10.0);
        score -= match_bonus;
        // If next item cannot fit in post_residual, penalize dead space creation.
        if (post_residual as u32) < next_item_size {
            score += 15.0 * (next - post_residual as f64) / 50.0;
        }
    }

    // Relative-to-mean coupling: bins tighter than average are valuable, use them;
    // bins much looser than average are poor targets unless fit is tight.
    let pr = post_residual as f64;
    if pr > mean_residual + 20.0 {
        score += 8.0;
    } else if pr < mean_residual - 20.0 {
        score -= 5.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are hopeless.
    if bin_residual == bin_capacity {
        score += 30.0;
        // But if lookahead item is large and this item is small, fresh bin is fine.
        if next_item_size >= 60 && item_size <= 30 {
            score -= 35.0;
        }
        // Late in the stream, prefer closing out existing bins.
        if total_items > 0 && (step_index as f64) / (total_items as f64) > 0.8 {
            score += 15.0;
        }
    }

    // Perfect fill reward.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: prefer bins whose post-residual is small.
    let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score += 40.0 * tightness;

    // Exact fill is ideal.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 55.0;
        } else if next_item_size <= post_residual {
            // next item fits but leaves more waste; mild penalty proportional to gap
            score += 0.4 * (post_residual - next_item_size) as f64;
        } else {
            // next item won't fit here regardless; penalize leaving large stranded residuals
            score += 0.15 * post_residual as f64;
        }
    }

    // Last chance: only one bin can fit the item -> strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Prefer fuller bins relative to the fleet average residual.
    score += 0.5 * (mean_residual - bin_residual as f64);

    // Penalize opening new bins when many bins are already open and this one fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // New bin baseline: only attractive if the item is large or no good fit exists.
        score += 25.0 + 0.3 * (item_size as f64);
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative, must open
        }
        // Late in stream, avoid proliferating bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
    }

    // Slight preference for bins that will end with residual in the "dead zone" (1..10)
    if post_residual >= 1 && post_residual <= 10 {
        score += 12.0; // such slivers are nearly useless
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - norm_item);
    score += 40.0 * poly * (0.5 + progress);

    // Reward tight fits more strongly as stream progresses
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * 30.0 * (0.4 + 0.6 * progress);

    // Penalize post-residual that is too small for typical future items but nonzero
    if pr > 0 {
        let dead = (10.0_f64.min(pr as f64) / 10.0) * (1.0 - (pr as f64 / 100.0));
        score += 8.0 * dead * (1.0 - progress);
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 25.0 * (0.5 + 0.5 * progress);
    }

    // Lookahead: reward if next item fits the post residual
    if next_item_size > 0 && (post_residual as f64) >= norm_next * cap && next_item_size as f64 <= pr {
        score -= 15.0 * (next_item_size as f64 / cap) * (1.0 - progress * 0.5);
    }
    // Penalize if post residual nearly fits next item but not quite (wasted space)
    if next_item_size > 0 && pr < next_item_size && pr > 0 {
        let gap = (next_item_size as f64 - pr) / cap;
        score += 12.0 * gap * (1.0 - gap) * 4.0 * progress;
    }

    // Mild penalty when bin residual deviates from mean residual (spread control)
    score += 0.05 * ((bin_residual as f64 - mean_residual) / cap).abs() * (1.0 - progress);

    // New-bin candidate: penalize slightly unless current bins are very full
    if bin_residual == bin_capacity {
        let avg_fill = 1.0 - mean_residual / cap;
        score += 6.0 + 20.0 * (1.0 - avg_fill) * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space quantization
    // Small post_residual (< 10) is essentially dead -> big penalty via non-linearity
    if post_residual > 0 {
        let pr = post_residual as f64;
        let class = post_residual % 10;
        // penalize awkward leftover classes (1..9) more than clean multiples of 10
        if class != 0 {
            score += 12.0 * (1.0 - class as f64 / 10.0);
        }
        // dead-space curve: very small leftovers are worst
        if post_residual < 10 {
            score += 25.0 * (1.0 - pr / 10.0);
        }
    } else {
        // perfect fit: strong reward
        score -= 60.0;
    }

    // Reward tight fits relative to item size
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * tightness * tightness;

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            score -= 8.0;
        } else {
            // next item cannot use the leftover: leftover likely wasted
            score += 6.0;
        }
        // harmonic check: post_residual - next_item_size lands on a clean class
        if post_residual >= next_item_size && (post_residual - next_item_size) % 10 == 0 {
            score -= 10.0;
        }
    } else {
        // last item: prefer any bin, waste matters less
        score -= 20.0;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new one
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin gets a baseline near capacity cost,
    // only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 * 0.9;
        // if item is large, a fresh bin is fine
        if item_size >= bin_capacity / 2 {
            score -= 15.0;
        }
        // early in stream with few bins, opening new bins is cheap
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
        // many open bins with high mean residual: prefer filling them instead
        if open_bins_count > 2 && mean_residual > item_size as f64 {
            score += 20.0;
        }
    } else {
        // mild preference for fuller bins (lower residual) among open bins
        score += 0.05 * (bin_residual as f64 - mean_residual);
    }

    // Modulo coupling between item class and post_residual class
    if (item_size % 10) == (post_residual % 10) && post_residual > 0 {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Penalize moderate dead space that likely cannot fit future items (min size 10)
    if post_residual > 0 && post_residual < item_size {
        score += 8.0;
    }

    // Reward tight fits (small post_residual relative to item size)
    let fit_ratio = post_residual as f64 / (item_size.max(1) as f64);
    score -= 15.0 * (1.0 - fit_ratio.min(1.0));

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 30.0;
    }

    // Open bins pressure: penalize creating new bins when many are open
    if bin_residual == bin_capacity {
        score += 25.0 + 5.0 * open_bins_count as f64;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Lookahead: if next item fits in post_residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // Penalize if next item would leave this bin's residual wasted
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 15.0;
    }

    // Mild preference for fuller bins vs. mean residual (balance avoidance)
    if (bin_residual as f64) > mean_residual {
        score -= 3.0;
    } else {
        score += 3.0;
    }

    // Late-stream pressure: consolidate more aggressively toward the end
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (post_residual as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward perfect match of post_residual with next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 / (1.0 + diff);
        // Bonus if next item fits exactly after this placement.
        if post_residual == next_item_size {
            score -= 40.0;
        }
        // Penalize if next item cannot fit anywhere else but could fit here after placement.
        if next_item_size > post_residual && fitting_bins_count <= 1 {
            score += 15.0;
        }
        // Reward if post_residual is small but still fits next item (tight chain).
        if next_item_size <= post_residual && post_residual < (bin_capacity as f64 * 0.25) as u32 {
            score -= 20.0;
        }
    } else {
        // Last item: strongly prefer tightest fit.
        score += 0.0;
        score -= 30.0 / (1.0 + post_residual as f64);
    }

    // Relative to mean residual: prefer bins that become tighter than average.
    let mean_post = mean_residual - item_size as f64;
    if mean_post > 0.0 {
        score -= (mean_post - post_residual as f64).max(0.0) * 0.3;
        score += (post_residual as f64 - mean_post).max(0.0) * 0.2;
    }

    // Last-chance bin bonus: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin (unless post_residual is huge dead space).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        let dead = post_residual as f64 / bin_capacity as f64;
        if dead < 0.10 {
            score -= 50.0;
        } else {
            score -= 50.0 * (1.0 - dead);
        }
    }

    // Penalize creating tiny unusable slivers (< 10, min item size).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // New-bin candidate: only attractive when current fit is poor (large post_residual)
    // or no real bin is a tight match. Base new-bin score is its residual (capacity).
    if bin_residual == bin_capacity {
        // Mild penalty so a decent existing fit beats opening a new bin.
        score += 5.0;
        // But if post_residual here is large (wasteful placement), new bin becomes better naturally.
        if next_item_size > 0 && next_item_size > post_residual {
            score -= 10.0;
        }
    }

    // Slight late-stream consolidation: prefer already-open bins as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual != bin_capacity {
        score -= 5.0 * progress;
    }

    // Prefer bins with residual close to item size in general (best-fit core).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += tightness * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits: minimize wasted space quadratically.
    let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score += tightness * tightness * 40.0;

    // Last-chance bonus: if this is the only bin that fits, heavily favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: penalize opening a new bin unless the fit is very tight
    // or the item would leave a large unusable gap in existing bins.
    if bin_residual == bin_capacity {
        let gap_penalty = if post_residual > 0 && post_residual < 10 { 0.0 } else { 25.0 };
        score += 30.0 + gap_penalty - (post_residual as f64) * 0.1;
        // Early in stream, opening bins is cheaper (build flexibility).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 15.0;
        // Many open bins with slack: discourage yet another bin.
        score += open_bins_count as f64 * 2.0;
    }

    // Lookahead: if the next item fits perfectly into the post-residual, reward this placement.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual > next_item_size {
            score -= 8.0;
        } else if post_residual > 0 {
            // Next item cannot use the leftover: penalize dead space.
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Prefer bins with residual below the mean (consolidate small leftovers),
    // but avoid dumping into near-empty bins when tighter options exist.
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // Late in stream: be greedier, minimize post residual more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.5;

    // Perfect fit gets an extra bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let r = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_r = r / cap;

    // Base: minimize post residual, with non-linear shaping
    let mut score = r * (1.0 + 0.5 * norm_r * norm_r);

    // Smooth polynomial coupling with stream progress: early on tolerate larger residuals,
    // later tighten the penalty on leftover space.
    let tightness = 1.0 + 1.5 * progress * progress;
    score *= tightness;

    // Penalize residuals that are too small to be useful (dead space), smoothly:
    // a quadratic bowl peaking near zero residual.
    let dead = (cap - r) / cap; // fraction used
    score -= 8.0 * dead * dead * (1.0 - dead);

    // Reward tight fits strongly (post_residual near zero)
    let tight = 1.0 - norm_r;
    score -= 10.0 * tight * tight * tight;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 6.0;
    }

    // Lookahead: if next item fits in post residual, reward this placement
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        let fit_q = next_item_size as f64 / (post_residual as f64 + 1.0);
        score -= 4.0 * fit_q * (1.0 - fit_q);
    }

    // Mild penalty for spreading across many open bins relative to mean residual
    let dev = (r - mean_residual) / cap;
    score += 2.0 * dev * dev;

    // New-bin candidate: penalize slightly unless current bin would leave very small residual
    if bin_residual == bin_capacity {
        score += 3.0 - 6.0 * (1.0 - norm_r) * (1.0 - norm_r);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the post-fit residual (dead-space quality) ---
    // Residuals are bucketed by how "reusable" they are for typical items.
    // Small residuals (<=10) are near-perfect fits; mid residuals are dead space.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect closure
    } else if pr <= 10 {
        score -= 25.0; // excellent: almost nothing wasted
    } else if pr <= 25 {
        score -= 6.0; // decent, still usable for small items
    } else if pr <= 50 {
        score += 8.0; // dead-space risk zone
    } else {
        score += 18.0; // large leftover: bin was underfilled
    }

    // --- Modulo / divisibility harmony with capacity ---
    // Residuals that are multiples of common item classes (10, 20, 25) are reusable.
    if pr % 10 == 0 && pr > 0 {
        score -= 5.0;
    }
    if pr % 25 == 0 && pr > 0 {
        score -= 3.0;
    }

    // --- Lookahead coupling: does the next item fit the leftover? ---
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0; // exact chaining: perfect follow-up
        } else if next_item_size <= pr {
            let slack = pr - next_item_size;
            score -= 18.0 - (slack as f64) * 0.15; // tighter follow-up is better
            // harmonic class match between next item and residual
            if slack % 10 == 0 {
                score -= 4.0;
            }
        } else {
            // next item won't fit here; penalize less if residual is tiny anyway
            score += 4.0;
        }
    }

    // --- Last-chance dynamics ---
    if fitting_bins_count == 1 && bin_residual >= item_size {
        // this is the only open bin that fits: strongly prefer using it
        // over opening a new bin (unless post_residual is terrible dead space)
        score -= 30.0 + (item_size as f64) * 0.1;
    } else if fitting_bins_count > 1 {
        // competition exists: mild preference for tighter fits among rivals
        score += 2.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // A fresh bin has residual 100; base score is item_size.
        // Penalize opening a new bin when healthy open bins exist,
        // but reward it when the item is huge (little room anywhere).
        if open_bins_count > 0 {
            score += 22.0 + 0.25 * (open_bins_count as f64);
        }
        if item_size >= 70 {
            score -= 20.0; // huge items justify fresh bins
        }
        if next_item_size > 0 && next_item_size + item_size > bin_capacity {
            score += 6.0; // lookahead can't share a bin anyway
        }
    }

    // --- Stream progression: tighten packing discipline over time ---
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 4.0;
    score += 0.03 * (mean_residual - post_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for the smallest item (1) are fine,
    // but small gaps that likely cannot fit typical future items are waste.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let dead_threshold = 10.0 + 20.0 * (1.0 - progress);
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += 3.0 * (dead_threshold - post_residual as f64);
    }

    // Perfect or near-perfect fit reward.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 2 {
        score -= 12.0;
    }

    // Open-bin pressure: discourage scattering across many bins unless fit is tight.
    score += (open_bins_count as f64) * 0.35;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // Lookahead: reward residual that can still host the next item.
    if next_item_size > 0 {
        if (post_residual as f64) >= next_item_size as f64 {
            score -= 6.0;
        } else if next_item_size as f64 > post_residual as f64 && post_residual > 0 {
            score += 2.0 * (next_item_size as f64 - post_residual as f64).min(30.0);
        }
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins first).
    score += 0.15 * (mean_residual - bin_residual as f64);

    // New-bin candidate: only attractive when current item barely fits anywhere
    // or open bins are very tight; otherwise penalize opening a fresh bin.
    if bin_residual == bin_capacity {
        let tight = (mean_residual / bin_capacity as f64) < 0.35;
        if fitting_bins_count >= 1 && !tight {
            score += 15.0;
        } else {
            score -= 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact/near match of next item into post_residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // Prefer placements where the next item fits with minimal slack.
            score -= 30.0 - slack * 0.4;
            if post_residual == next_item_size {
                score -= 25.0; // perfect 2-chain
            }
        } else {
            // Next item cannot follow into this bin: penalize proportionally to dead space.
            let dead = (post_residual as f64).min(next_item_size as f64 - post_residual as f64);
            score += dead * 0.3;
        }
    }

    // Compare residual to mean residual: bins with unusually small residual are "tight" fits,
    // reward using them; bins far above mean waste space.
    let res = post_residual as f64;
    if mean_residual > 0.0 {
        score += (res - mean_residual) * 0.15;
    }

    // Last-chance bin: strongly favor filling it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0 + item_size as f64 * 0.2;
    }

    // Penalize creating tiny unusable residuals (dead space < typical min item size 10).
    if post_residual < 10 {
        score += 15.0;
    }

    // Slight preference for using existing bins vs opening new ones early in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open or early on.
        score += 10.0 + (1.0 - progress) * 10.0 + open_bins_count as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;

    // Reward tight fits: small post_residual relative to item size.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= 30.0 * (1.0 - fit_ratio) * (1.0 - fit_ratio);

    // Penalize leaving dead space that the next item cannot use.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Post residual is reusable by lookahead item -> reward.
            score -= 12.0 * (post_residual as f64 - next_item_size as f64).abs() / bin_capacity as f64;
        } else {
            // Dead space below next item size -> penalize proportionally.
            score += 18.0 * (1.0 - post_residual as f64 / next_item_size.max(1) as f64);
        }
    }

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 25.0;
    }

    // New-bin candidate handling.
    if is_new_bin {
        // Opening a new bin is costly; penalize it, more so early when few bins exist.
        score += 40.0 + 3.0 * open_bins_count as f64 * (1.0 - progress);
        // But if the item fits poorly in existing bins (large post_residual there),
        // the new-bin penalty is effectively reduced via the base post_residual term
        // (post_residual = capacity here, which is large), so add coupling:
        if fitting_bins_count > 0 && (post_residual as f64) < mean_residual {
            score += 20.0;
        }
    }

    // Global fragmentation pressure: many open bins with high mean residual
    // suggests consolidation is preferable to spreading.
    if !is_new_bin {
        score += 0.15 * mean_residual * (1.0 - progress);
        score -= 0.1 * (bin_residual as f64 - mean_residual);
    }

    // Late stream: prefer closing bins tightly, discourage opening new ones.
    if progress > 0.8 && !is_new_bin {
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let mut score = pr * (1.0 + 0.8 * progress + 0.6 * progress * progress);

    // Penalize large dead space super-linearly, stronger late in the stream.
    score += 40.0 * norm_pr * norm_pr * (0.5 + progress);

    // Reward tight fits: small post_residual gets a discount.
    score -= 25.0 * (-norm_pr * 6.0).exp();

    // Exact-fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 * (1.0 - progress * 0.5);
    }

    // Lookahead: if the next item fits exactly into post_residual, reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (pr - nxt).abs() < 1.0 {
            score -= 20.0;
        } else if nxt <= pr {
            score -= 10.0 * (1.0 - nxt / pr.max(1.0));
        } else {
            score += 5.0;
        }
    }

    // Mild penalty when this bin is much fuller than the average open bin
    // (encourages balanced residual usage), scaled by number of open bins.
    let dev = (mean_residual - pr) / cap;
    score += 8.0 * dev * dev * (open_bins_count as f64).ln().max(1.0);

    // New-bin candidate: make it moderately attractive only when progress is
    // low or all fits are poor, otherwise discourage.
    if bin_residual == bin_capacity {
        score += 15.0 * progress - 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of post_residual: reward residuals that are "composable" ---
    // Residuals divisible by small item sizes (10, 20, 25) are easier to fill later.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit is always best
    } else {
        if pr % 10 == 0 { score -= 8.0; }
        if pr % 20 == 0 { score -= 6.0; }
        if pr % 25 == 0 { score -= 6.0; }
        // Dead-space classes: small odd residuals are hard to fill
        if pr < 10 { score += 25.0; }
        else if pr < 20 { score += 12.0; }
        // Quadratic penalty on wasted space, scaled by stream progress
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 0.05 * (pr as f64) * (pr as f64) / (bin_capacity as f64) * (0.5 + progress);
    }

    // --- Lookahead coupling: does next_item_size fit harmonically into post_residual? ---
    if next_item_size > 0 && post_residual >= next_item_size {
        // exact or near-exact chain fit is very desirable
        let chain = post_residual - next_item_size;
        if chain == 0 { score -= 30.0; }
        else if chain < 10 { score -= 15.0; }
        else if chain % 10 == 0 { score -= 10.0; }
        score -= 5.0; // mild general reward for keeping a future option alive
    } else if next_item_size > 0 {
        // next item cannot follow into this bin: penalize proportionally
        score += 10.0 + 0.2 * (next_item_size as f64);
    }

    // --- Last-chance bin: strongly prefer using the only fitting bin ---
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when existing bins are crowded
        // or mean residual is small relative to the item.
        let pressure = (mean_residual / bin_capacity as f64) - (item_size as f64 / bin_capacity as f64);
        if pressure < 0.05 && open_bins_count > 0 {
            score -= 15.0; // open fresh bin when nothing fits well
        } else {
            score += 40.0 + 3.0 * open_bins_count as f64; // discourage wasting open capacity
        }
    }

    // --- Tightness bonus: prefer bins where the item fills a large fraction ---
    let fill_fraction = item_size as f64 / bin_residual as f64;
    score -= 10.0 * fill_fraction;

    // Small tie-breaker toward fuller (lower-residual) bins
    score -= 0.05 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongly reward (post_residual == 0).
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space penalty: small unusable gaps (1..10) are almost certainly wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Reward tight fits relative to capacity.
    let tightness = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 30.0 * tightness;

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // Open-bin pressure: discourage opening new bins when many are open.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to open bins count,
        // but allow it if the current item leaves a very bad gap elsewhere.
        score += 40.0 + 15.0 * open_bins_count as f64;
        // If next item is large and this item is small, a fresh bin is attractive.
        if next_item_size > 60 && item_size < 30 {
            score -= 70.0;
        }
    } else {
        // Slight reward for using existing bins as they fill up.
        score -= 5.0 * (1.0 - (post_residual as f64 / bin_capacity as f64));
    }

    // Lookahead: if next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    }
    // If next item would leave the post residual as dead space, penalize.
    if next_item_size > 0 && post_residual >= next_item_size && (post_residual - next_item_size) < 10 && (post_residual - next_item_size) > 0 {
        score += 25.0;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter than average).
    if (bin_residual as f64) < mean_residual {
        score -= 10.0;
    } else {
        score += 5.0;
    }

    // Stream progression: late in the stream, consolidate more aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 20.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 50.0;
    }

    // Post-residual slightly below next item size is dead space for the lookahead.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 0.5 * (next_item_size - post_residual) as f64;
    }

    // Post-residual slightly above next item size is a near-perfect match.
    if next_item_size > 0 && post_residual > next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 10.0 * (-gap / 15.0).exp();
    }

    // Penalize post_residual far above mean residual (wasteful leftover).
    score += 0.3 * ((post_residual as f64 - mean_residual).abs());

    // Last-chance bin before opening a new one: strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Prefer opening a new bin when current fit is very poor (large dead space).
    if post_residual > 0 && post_residual < 10 {
        score -= 5.0; // tiny leftovers are near-useless anyway, slight reward
    }
    if post_residual > 0 && post_residual < item_size.min(next_item_size.max(1)) {
        score += 8.0; // unusable for next item
    }

    // Early in stream: encourage compact packing (keep bins tight).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.2 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress ratio of the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward bins whose post-residual can host the lookahead item (perfect pairing).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.25 * next_item_size as f64;
    } else if next_item_size > 0 {
        // Penalize dead space the known next item cannot use.
        score += 0.15 * (next_item_size as f64 - post_residual as f64).max(0.0);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Reward tight fits: small post residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 8.0 * tightness * tightness;

    // Slightly discourage spreading across many open bins when residuals are large.
    score += 0.05 * open_bins_count as f64 * (mean_residual / bin_capacity as f64);

    // Early in the stream, be a bit more willing to pack into existing bins;
    // late in the stream, prioritize minimizing leftover dead space harder.
    score += (1.0 - progress) * 3.0 * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: add a calibrated opening penalty so a new bin is only
    // chosen when existing bins would leave clearly worse dead space.
    if bin_residual == bin_capacity {
        score += 18.0 - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Base: post-residual (tighter fit preferred), smoothly warped by progress.
    let mut score = post;

    // Non-linear polynomial coupling: post_residual^2 normalized, weighted by progress.
    let post_norm = post / cap;
    score += 20.0 * post_norm * post_norm * (0.5 + progress);

    // Cubic interaction between item size and progress: penalize small items early less,
    // discourage wasting large bins late.
    score -= 0.15 * item * item * progress * (1.0 - progress) * 4.0;

    // Reward placements that leave room for the lookahead item (smooth quadratic).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = post - nxt;
        let gap_norm = gap / cap;
        score += 12.0 * gap_norm * gap_norm;
        score -= 6.0 * gap_norm.max(0.0);
    }

    // Mean-residual coupling: prefer bins close to the mean residual (smooth deviation penalty).
    let dev = post - mean_residual;
    score += 0.08 * dev * dev / cap;

    // Last-chance bonus: strongly favor the only fitting bin (smoothly scaled by progress).
    if fitting_bins_count == 1 {
        score -= 30.0 + 20.0 * progress;
    }

    // Mild preference for reusing bins over opening new ones, decaying with progress.
    score += 5.0 * (1.0 - progress) * (post_norm);

    // Slight penalty when many bins are open (consolidation pressure), smooth in progress.
    score += 0.5 * (open_bins_count as f64).ln().max(0.0) * post_norm * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo arithmetic on capacity fractions.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / cap;

    // Dead-space penalty grows super-linearly for residuals that are hard to fill.
    // Classes: post_residual mod 10 -> "awkward" remainders (1..=9) get extra penalty,
    // multiples of 10 are "harmonic" and fillable by common item sizes.
    let class = post_residual % 10;
    let class_penalty = match class {
        0 => 0.0,
        5 => 1.5,
        c if c <= 3 => 3.0 + c as f64,
        _ => 2.0,
    };
    score += class_penalty * (1.0 + frac);

    // Perfect-fit reward: harmonic closure (post_residual == 0) strongly favored.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            // next item fits but leaves another residue: mild reward scaled by fit tightness
            let gap = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - gap / cap);
        } else {
            // next item cannot use this residue: penalize large unusable residue
            score += 0.05 * (post - next_item_size as f64).max(0.0);
        }
    }

    // Last-chance logic: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin gets a base cost so we only open
    // when existing fits are bad; but reward opening when item is large.
    if bin_residual == bin_capacity {
        let base = 10.0 + 0.5 * open_bins_count as f64;
        score += base;
        if item_size >= bin_capacity / 2 {
            score -= 6.0;
        }
    }

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it is a "tight" bin — prefer packing into tight bins to consolidate.
    let tightness = mean_residual - post;
    score += 0.1 * tightness;

    // Stream progression: early on, be conservative about opening bins;
    // late in the stream, allow tighter packing aggression.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 4.0 * progress * frac; // late stream: large residues slightly more acceptable

    // Integer-division threshold: residues in (0, 10] are near-dead space.
    if post_residual > 0 && post_residual <= 10 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 45.0 - 3.0 * post_residual as f64;
    }
    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward bins whose residual can still fit the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            score += 8.0; // dead space relative to lookahead
        }
        // Bonus if this bin can take both current and next item.
        if bin_residual >= item_size + next_item_size {
            score -= 10.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is good.
    score += (open_bins_count as f64) * 0.8;

    // Penalize wasting a large residual on a small item when mean residual is high.
    if (post_residual as f64) > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.3;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // Default mild penalty; waived when item is large relative to capacity.
        let large_item = item_size as f64 > 0.6 * bin_capacity as f64;
        if large_item {
            score -= 15.0;
        } else {
            score += 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual equals next item size exactly -> strong reward.
    if next_item_size > 0 {
        let pr = post_residual as f64;
        let ni = next_item_size as f64;

        if post_residual == next_item_size {
            score -= 60.0; // exact chaining of the next item
        } else if post_residual > next_item_size {
            // next item fits: reward closeness of the resulting second residual
            let second_residual = pr - ni;
            score -= 25.0 / (1.0 + second_residual / 10.0);
        } else {
            // next item will NOT fit here: penalize dead space that blocks the chain
            let gap = ni - pr;
            score += 8.0 + gap / 4.0;
        }

        // lookahead strength grows as stream progresses
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 6.0 * progress;
    }

    // Penalize large post_residual waste relative to mean residual of open bins.
    if post_residual as f64 > mean_residual {
        score += 0.35 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.15 * (mean_residual - post_residual as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when residual is tiny (unusable dead space)
    // or no open bin chains well; otherwise discourage opening new bins.
    if bin_residual == bin_capacity {
        let tiny_waste = post_residual < 10;
        if tiny_waste || (next_item_size > 0 && post_residual < next_item_size) {
            score -= 20.0;
        } else {
            score += 45.0 + open_bins_count as f64;
        }
    }

    // Mild preference for tighter fits overall (small item-to-residual ratio).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * fill_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual already favored by base term).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // Penalize dead space: residuals that are small but unusable (below min item size).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Time horizon: early in stream, be more willing to open new bins (mild);
    // late in stream, prefer filling existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 8.0 * (1.0 - progress);

    // Penalize spreading across many open bins slightly; encourage consolidation.
    score += 0.05 * open_bins_count as f64;

    // Prefer bins with residual close to mean (balanced packing) mildly.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // New-bin candidate: only attractive when item is large relative to residual space
    // available in fitting bins or when no good fit exists.
    if bin_residual == bin_capacity {
        // Base penalty: opening new bin costs one bin.
        score += 55.0;
        // Reward opening a fresh bin for large items or when few bins fit the item.
        if item_size >= 50 {
            score -= 20.0;
        }
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
        // If open bins are already fragmented (high mean residual), opening new bin is fine.
        if mean_residual > 40.0 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
