pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: how "reusable" is the gap?
    // Residuals divisible by common item sizes (or small) are valuable.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit is golden
    } else {
        // dead-space class: small unusable gaps are worse than larger usable ones
        if pr < 10 {
            score += 45.0; // tiny dead space, nearly useless
        } else if pr <= 20 {
            score += 10.0;
        }
        // modulo arithmetic: gaps that are multiples of common sizes remain usable
        if pr % 10 == 0 { score -= 12.0; }
        if pr % 25 == 0 { score -= 8.0; }
        if pr % 50 == 0 { score -= 6.0; }
        // harmonic fraction of capacity
        let frac = pr as f64 / cap;
        if (frac - 0.5).abs() < 0.01 { score -= 5.0; }
        if (frac - 0.25).abs() < 0.01 { score -= 3.0; }
    }

    // Lookahead coupling: can next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 18.0; // keeps a chain going
            // bonus if next item exactly fills it
            if next_item_size == pr { score -= 15.0; }
        } else {
            // next item won't fit here: gap likely becomes dead space
            let gap = (pr as i64 - next_item_size as i64).unsigned_abs() as f64;
            score += 6.0 + 0.15 * gap;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive
    // when the item is large or fits would leave terrible gaps elsewhere.
    if bin_residual == bin_capacity {
        // neutral base for fresh bin
        score += 20.0;
        let progress = step_index as f64 / total_items.max(1) as f64;
        // late in the stream, prefer consolidating into open bins
        score += 25.0 * progress;
        // many open bins -> discourage more
        score += 2.0 * open_bins_count as f64;
        // large items pack cleanly in fresh bins
        if item_size > bin_capacity / 2 { score -= 25.0; }
        // if item would leave an awkward remainder in a fresh bin, discourage
        let fresh_post = bin_capacity - item_size;
        if fresh_post > 0 && fresh_post < 10 { score += 20.0; }
        // if next item pairs perfectly with fresh-bin leftover, encourage
        if next_item_size > 0 && fresh_post >= next_item_size && fresh_post - next_item_size < 10 {
            score -= 10.0;
        }
    }

    // mild preference for tighter (smaller-residual) bins overall
    score += 0.05 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harder than large ones.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0; // dead space below minimum item size
        } else if post_residual < 20 {
            score += 25.0;
        } else if post_residual < 35 {
            score += 10.0;
        }
    } else {
        score -= 40.0; // perfect fit strongly rewarded
    }

    // Reward bins whose residual exactly accommodates a plausible next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading to new bins.
    let pressure = (open_bins_count as f64 / 8.0).min(3.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are already open.
        score += 20.0 + 15.0 * pressure;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // pairing a big item now with a big next item justifies a fresh bin
        }
    } else {
        // Favor tighter bins slightly.
        score -= (bin_capacity - bin_residual) as f64 * 0.05;
    }

    // Mean-residual coupling: if this bin is far below average residual, it's a good filler.
    score -= (mean_residual - bin_residual as f64) * 0.1;

    // Late-stream urgency: consolidate more aggressively toward the end.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post-residual) more aggressively than linear.
    if post_residual == 0 {
        score -= 60.0; // perfect fit
    } else {
        let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= 25.0 * tightness * tightness;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if post_residual as f64 >= next {
            let diff = post_residual as f64 - next;
            if diff == 0.0 {
                score -= 40.0; // next item fits perfectly in this bin
            } else {
                // penalize large leftover after hypothetical next placement
                score += 0.35 * diff;
                score -= 15.0 * (1.0 - diff / bin_capacity as f64);
            }
        } else {
            // next item cannot follow here; penalize proportionally to waste
            score += 0.5 * (next - post_residual as f64);
        }
    }

    // Compare post_residual relative to mean residual: prefer bins that reduce dispersion
    // (leaving post_residual close to mean_residual keeps other bins usable).
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.2 * dev;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + 0.4 * item_size as f64;
    }

    // Penalize opening a new bin when existing bins fit reasonably well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let good_fit_exists = fitting_bins_count > 0 && (bin_residual as f64 - item_size as f64) <= 30.0;
        if good_fit_exists {
            score += 80.0; // strong penalty: don't open new bin when a decent fit exists
        } else {
            score += 10.0 + 10.0 * progress;
        }
        // New-bin baseline: slightly prefer new bin early when open bins are fragmented
        score -= 0.15 * mean_residual.min(50.0);
    }

    // Mild preference to fill larger items into emptier bins early on.
    score += 0.05 * (open_bins_count as f64).ln().max(0.0) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 8.0 * tightness * tightness;

    // Penalize dead space that is too small for typical items (1..100 unknown,
    // so use item_size as a proxy for the local scale).
    if post_residual > 0 && post_residual < item_size {
        score += 6.0 * (1.0 - post_residual as f64 / item_size as f64);
    }

    // Lookahead: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
        // Extra reward if the pair nearly fills the bin.
        if post_residual - next_item_size <= 5 {
            score -= 6.0;
        }
    } else if next_item_size > 0 {
        // Next item won't fit here; penalize proportionally to the gap.
        let gap = next_item_size as f64 - post_residual as f64;
        score += 0.15 * gap;
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Many open bins: prefer consolidating into existing bins over opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let crowding = (open_bins_count as f64 / (1.0 + progress * 10.0)).min(5.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open or early crowding.
        score += 12.0 + 3.0 * crowding;
        // Allow new bin if current bin would leave a large awkward residual.
        if post_residual > bin_capacity / 3 {
            score -= 10.0;
        }
    } else {
        // Existing bin: mild reward for using it, scaled by how full the fleet is.
        score -= 2.0 * (mean_residual / bin_capacity as f64);
    }

    // Time horizon: late in the stream, avoid opening new bins at all costs.
    if progress > 0.8 && bin_residual != bin_capacity {
        score -= 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let c = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = (step_index as f64) / (total_items.max(1) as f64);
    let norm_pr = pr / c;

    // Base: minimize waste, quadratically penalized
    let mut score = norm_pr * norm_pr * 60.0 + pr * 0.6;

    // Smooth coupling with stream progress: early stream tolerates larger residuals,
    // late stream demands tight fits.
    let progress_coupling = norm_pr * (0.5 + 3.0 * progress * progress);
    score += progress_coupling * 40.0;

    // Reward near-perfect fits (small post_residual) with smooth exponential bonus
    score -= 25.0 * (-norm_pr * 8.0).exp();

    // Penalize dead space that cannot fit the next item (smooth interaction)
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if pr < ns {
            let gap = (ns - pr) / c;
            score += gap * gap * 90.0 * (1.0 - progress * 0.5);
        } else {
            // Reward leaving room exactly for the next item (smooth window)
            let diff = (pr - ns) / c;
            score -= 15.0 * (-diff * diff * 40.0).exp();
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 30.0 + 20.0 * (1.0 - progress);
    }

    // Mild penalty for proliferating open bins, scaled by residual imbalance
    let imbalance = (mean_residual - pr) / c;
    score += open_bins_count as f64 * 0.05 + imbalance.abs() * 8.0;

    // New-bin candidate: neutral baseline; opening preferred only when all fits are poor
    if bin_residual == bin_capacity {
        score = 45.0 + 35.0 * (1.0 - progress) + pr * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    score += (post_residual as f64 / bin_capacity as f64) * 30.0;

    // Harmonic class of the item: classify by capacity fractions.
    let cap = bin_capacity as u32;
    let item_class = item_size / (cap / 4); // coarse class 0..=4
    let next_class = next_item_size / (cap / 4);

    // Reward pairings whose classes complement each other (sum near capacity).
    if next_item_size > 0 && item_class + next_class >= 3 {
        score -= 12.0;
    }
    if next_item_size > 0 && next_item_size <= post_residual {
        // Next item still fits after this placement: good chaining.
        score -= 8.0;
        // Extra reward when next item exactly harmonizes with post_residual.
        if post_residual % next_item_size == 0 {
            score -= 6.0;
        }
    } else if next_item_size > post_residual && next_item_size > 0 {
        // Next item won't fit here; penalize dead space creation.
        score += 10.0;
        if post_residual < 10 {
            score += 5.0; // tiny unusable residue
        }
    }

    // Integer-division thresholds on post_residual: dead zones.
    if post_residual > 0 && post_residual <= 9 {
        score += 15.0; // unusable sliver
    }
    if post_residual >= 50 && post_residual <= 60 {
        score -= 4.0; // half-cap zone still very usable
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate: penalize mildly so it's chosen only when fits are bad,
    // but keep it competitive when open bins are fragmented.
    if bin_residual == bin_capacity {
        score += 25.0 - 0.5 * (post_residual as f64);
        if fitting_bins_count > 0 && mean_residual > 40.0 {
            score -= 10.0; // open bins are roomy; opening new bin is fine
        }
    }

    // Stream progression: late in stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;
    score += (open_bins_count as f64) * 0.3;
    score += (mean_residual - post_residual as f64).abs() * 0.05;

    // Modulo harmonic bonus: post_residual divisible by common small sizes.
    for m in [10u32, 20, 25, 50].iter() {
        if post_residual > 0 && post_residual % m == 0 {
            score -= 3.0;
            break;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that no realistic item can use are heavily penalized.
    // Minimum plausible item size is 1, but "usable" gaps should still accommodate a
    // meaningful item; treat gaps below a dead-zone threshold as wasted space.
    let dead_zone = 15.0f64;
    if (post_residual as f64) < dead_zone {
        score += (dead_zone - post_residual as f64) * 6.0;
    }

    // Perfect fits are excellent.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward tight fits relative to the bin's current slack.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= fill_ratio * 20.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: penalize spreading across many bins, encouraging
    // consolidation into existing bins rather than opening new ones.
    score += open_bins_count as f64 * 1.5;

    // New-bin candidate handling: an empty bin should only win when the current
    // bin would be left with awkward dead space or the fit is poor.
    if bin_residual == bin_capacity {
        // Baseline attractiveness of a fresh bin: proportional to item size,
        // since big items leave little residual either way.
        score = (bin_capacity - item_size) as f64 + 5.0;
        // If the current placement would leave a usable gap for the next item,
        // make the fresh bin less attractive.
        if post_residual >= next_item_size && next_item_size > 0 {
            score += 15.0;
        }
        // If opening a new bin is nearly inevitable (few fitting alternatives),
        // make it more attractive.
        if fitting_bins_count <= 2 {
            score -= 10.0;
        }
    } else {
        // Reward leaving a residual that exactly fits the lookahead item.
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 30.0;
        } else if next_item_size > 0 && post_residual >= next_item_size {
            // Small bonus for leaving a gap usable by the next item.
            score -= (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64) * 5.0;
        }
    }

    // Late in the stream, waste matters less than bin count; tighten consolidation.
    let progress = step_index as f64 / total_items as f64;
    score += progress * (dead_zone - post_residual as f64).max(0.0) * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
