        } else {
            score += (next_item_size - post_residual) as f64 * 0.3; // next item won't fit here
        }
    }

    // Penalize large dead space relative to mean residual
    score += (post_residual as f64 - mean_residual).max(0.0) * 0.4;

    // Last-chance bonus: avoid wasting the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate: penalize mildly so we only open when open bins fit poorly
    if bin_residual == bin_capacity {
        score += 15.0 + mean_residual * 0.1;
    }

    // Prefer filling bins tighter as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * (0.1 + 0.2 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
