        let nxt_fit = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - nxt_fit / (bin_capacity as f64));
    } else if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual {
        // Dead space that next item cannot use: penalize proportionally.
        score += 0.4 * (post_residual as f64);
    }

    // Time horizon: late in the stream, avoid opening new bins (favor filling existing ones).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses and as many bins are open.
        score += 30.0 + 60.0 * progress + 2.0 * (open_bins_count as f64);
        // But if no open bin fits well, allow new bin when item is large.
        if item_size > bin_capacity / 2 {
            score -= 15.0;
        }
    } else {
        // Reward using existing bins more aggressively late in the stream.
        score -= 10.0 * progress;
    }

    // Mild penalty for creating very small unusable residuals (dead space < typical min item).
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = (1.0 + progress * progress) * (norm_pr * norm_pr) + 2.0 * progress * norm_pr * (1.0 - norm_pr);
    score += 18.0 * poly;

    // Reward tight fits more strongly as the stream progresses
    score -= 30.0 * progress * (1.0 - norm_pr) * (1.0 - norm_pr);

    // Penalize dead space that cannot fit the next item (smooth interaction)
    let next_fits = if norm_next > 0.0 { ((norm_pr - norm_next) / (1.0 + norm_next)).max(0.0) } else { 1.0 };
    score -= 12.0 * next_fits * (1.0 - progress);

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - norm_pr);
    }

    // Mild penalty for proliferating bins relative to mean residual
    score += 0.05 * (open_bins_count as f64) * (mean_residual - pr).abs() / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: classify post_residual by
    // integer division into coarse capacity-fraction buckets.
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;
    let post = post_residual;

    // Dead-space penalty: leftovers below the smallest plausible item are wasted.
    if post < 10 {
        score += 40.0 * (1.0 - post as f64 / 10.0);
    }

    // Perfect or near-perfect fits are heavily rewarded.
    if post == 0 {
        score -= 60.0;
    } else if post <= eighth {
        score -= 25.0;
    } else if post <= quarter {
        score -= 10.0;
    }

    // Harmonic modulo structure: leftover in classes that small future items
    // (sizes 1..100) can still fill get a bonus.
    let fillable = if post >= next_item_size && next_item_size > 0 { 1.0 } else { 0.0 };
    score -= 15.0 * fillable;

    // Modulo arithmetic on post_residual: residues divisible by common item
    // sizes (10, 20, 25, 50) are easier to fill later.
    let residue_bonus = ((post % 10 == 0) as i32
        + (post % 20 == 0) as i32
        + (post % 25 == 0) as i32
        + (post % 50 == 0) as i32) as f64;
    score -= 4.0 * residue_bonus;

    // Integer-division threshold: if leftover falls in a "dead zone"
    // (too big to waste, too small for the next item), penalize.
    if next_item_size > 0 && post > 0 && post < next_item_size {
        score += 12.0;
    }

    // Last-chance bin: strongly prefer using the only bin that fits,
    // avoiding opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Lookahead pairing: if the next item exactly matches the post_residual,
    // this is an ideal chain placement.
    if next_item_size > 0 && post == next_item_size {
        score -= 35.0;
    }

    // Prefer tighter bins overall: compare against mean residual.
    score += 0.15 * ((bin_residual as f64) - mean_residual);

    // New-bin candidate handling: an empty bin is a fresh start; make it
    // attractive when current bins fit poorly, unattractive when they fit well.
    if bin_residual == bin_capacity {
        // Neutral baseline slightly above a good fit but below a bad one.
        score = 45.0
            - 10.0 * fillable
            + 20.0 * (open_bins_count as f64).ln().max(0.0)
            - 0.05 * (mean_residual);
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A gap is "dead" if it is smaller than the smallest plausible item (1),
    // but practically we treat gaps below a threshold band as increasingly costly.
    let gap = post_residual as f64;
    if gap > 0.0 {
        if gap < 10.0 {
            // tiny sliver: near-wasted space
            score += 60.0 * (10.0 - gap) / 10.0;
        } else if gap < 25.0 {
            // awkward zone: only fits very small items
            score += 25.0 * (25.0 - gap) / 15.0;
        }
    }

    // Reward perfect / near-perfect fits strongly.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // Coupling with mean residual: prefer bins whose residual deviates
    // favorably from the mean (tighter than average bins get priority).
    score -= (mean_residual - bin_residual as f64) * 0.5;

    // Open-bin pressure: when many bins are open, discourage opening new ones;
    // when few bins are open, be more permissive.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // new-bin candidate: penalize proportionally to open-bin pressure
        score += 20.0 + 15.0 * pressure;
    } else {
        // existing bin: small reward that grows with pressure to consolidate
        score -= 2.0 * pressure;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (avoid waste).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // this placement is part of a good chain; reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < 10.0 {
            score -= 15.0 * (10.0 - slack) / 10.0;
        }
    }
    // If next item would be blocked by the post residual, mild penalty.
    if next_item_size > post_residual && next_item_size > 0 && post_residual > 0 {
        score += 5.0;
    }

    // Late-stream consolidation: as the stream progresses, favor filling
    // existing bins harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 10.0 * progress;
    } else {
        score += 10.0 * progress;
    }

    // Exact-fit-to-residual ratio reward (tight packing).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong 2-step lookahead: reward exact/near-exact match of post_residual to next item
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 25.0 * (1.0 - diff / bin_capacity as f64).max(0.0);
        // Perfect chain: next item exactly fills the bin
        if post_residual == next_item_size {
            score -= 40.0;
        }
    } else {
        // Last item: prefer minimal waste
        score += 5.0;
    }

    // Relative-to-mean residual: prefer bins tighter than average
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Penalize large dead space that next item cannot use
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += (post_residual as f64) * 0.5;
    }

    // Last-chance bonus: avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Prefer filling existing bins over opening new ones, more so early in stream
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize moderately, less as stream progresses
        score += 35.0 - 15.0 * progress;
    }

    // Slight penalty for item barely fitting (tight fit creates tiny residual)
    if post_residual > 0 && post_residual < 10 {
        score -= 8.0; // small residuals are fine (near-perfect fill)
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual gets strong discount.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize post-residuals that are small but unusable (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // or no good fit exists.
    if bin_residual == bin_capacity {
        let mut new_bin_penalty = 18.0;
        // Large items start bins well.
        if item_size >= bin_capacity / 2 {
            new_bin_penalty -= 10.0;
        }
        // If the current bin would leave a tiny awkward remainder, opening a
        // fresh bin becomes more attractive.
        if post_residual > 0 && post_residual < 15 {
            new_bin_penalty -= 12.0;
        }
        // Late in the stream, avoid spawning extra bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        new_bin_penalty += 10.0 * progress;
        // Many open bins with high mean residual: reuse is cheap.
        if open_bins_count > 2 && mean_residual > item_size as f64 {
            new_bin_penalty += 8.0;
        }
        score += new_bin_penalty;
    }

    // Lookahead: favor bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
            // Perfect pairing: residual exactly matches next item.
            if post_residual == next_item_size {
                score -= 12.0;
            }
        } else if post_residual > 0 {
            // Post-residual too small for the next item: mild penalty scaled
            // by how badly it misses.
            let miss = (next_item_size - post_residual) as f64;
            score += 0.15 * miss;
        }
    }

    // Prefer filling bins that are already below-average residual (consolidate
    // waste into few bins).
    if bin_residual < bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        score += 0.08 * diff;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post-residual cost, scaled by a non-linear function of stream progress.
    // Early in the stream, tight fits matter less; late, wasted space is expensive.
    let progress_weight = 0.5 + 1.5 * progress * progress;
    let mut score = pr * progress_weight;

    // Non-linear penalty on very small residuals (dead space) that grows with progress.
    let dead = (1.0 - norm_pr).clamp(0.0, 1.0);
    score += 12.0 * (1.0 - dead).powi(3) * (0.5 + progress);

    // Reward tight fits (small post_residual relative to item) with smooth coupling.
    let tightness = 1.0 - (pr as f64 / (item_size.max(1) as f64 + 1.0)).min(1.0);
    score -= 8.0 * tightness * tightness * (1.0 + progress);

    // Penalize when this is the only fitting bin but the fit is poor (last-chance trade-off).
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - norm_pr) * (1.0 - norm_pr);
    }

    // Coupling with mean residual: prefer bins whose residual deviates favorably.
    let dev = (pr - mean_residual) / cap;
    score += 6.0 * dev * dev - 4.0 * dev;

    // Lookahead: reward if next item could fit into the post-residual.
    if next_item_size > 0 {
        let fits_next = (next_item_size as f64 <= pr) as i32 as f64;
        score -= 10.0 * fits_next * (1.0 - norm_pr);
        // Penalize leaving residual that is awkwardly close to next item size.
        let gap = (pr - next_item_size as f64).abs();
        score += 0.15 * gap;
    }

    // Mild penalty for spreading across many open bins early on.
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo 10 (capacity fractions of C=100)
    let post_mod = post_residual % 10;
    // Penalize "dead" residues that are hard to fill (small non-zero leftovers)
    if post_residual > 0 {
        score += match post_mod {
            0 => -8.0,          // perfectly harmonic leftover (e.g. 10,20,30...) -> reward
            1..=4 => 6.0,       // awkward sliver
            5 => -2.0,          // half-class: fillable by mid-size items
            _ => 2.0,           // 6..=9 moderately awkward
        };
    }

    // Integer-division threshold: post_residual / item_size packing ratio
    if item_size > 0 {
        let ratio = post_residual / item_size;
        score -= ratio as f64 * 3.0; // more potential same-size refills -> better bin
    }

    // Lookahead harmonic coupling: does next item fit a harmonic class of post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0;
            // exact harmonic match: post_residual % next_item_size small or zero
            let m = post_residual % next_item_size;
            if m == 0 {
                score -= 8.0;
            } else if m <= 5 {
                score += 3.0;
            }
        } else {
            score += 5.0; // next item cannot use this bin's leftover
        }
    } else {
        // last item: just minimize waste
        score += 0.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin before opening a new one
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: only prefer fresh bin if all open residuals are badly fragmented
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        // open new bin when existing mean residual is small (poor fits everywhere)
        score += 30.0 * pressure - 10.0;
        // late in stream, slightly prefer reusing open bins
        if total_items > 0 {
            let progress = step_index as f64 / total_items as f64;
            score += 8.0 * progress;
        }
    }

    // Encourage consolidation when many bins are open
    if open_bins_count > 4 && bin_residual < bin_capacity {
        score -= 2.0;
    }

    // Mild preference for tighter fits overall
    score += (bin_residual - item_size) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small unusable gaps are worthless.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 12.0;
    }

    // Reward tight fits (small post_residual relative to item).
    score -= (item_size as f64) * (1.0 - (post_residual as f64 / bin_capacity as f64)) * 0.5;

    // Pressure: fewer open bins -> prefer reusing bins over opening new ones.
    score += open_bins_count as f64 * 0.8;

    // Last-chance bonus: only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is bad.
    if bin_residual == bin_capacity {
        score += 30.0;
        // If next item is large, opening fresh bin may be good.
        if next_item_size > item_size {
            score -= (next_item_size - item_size) as f64 * 0.4;
        }
    }

    // Lookahead: if next item fits exactly in post_residual, reward strongly.
    if next_item_size > 0 && next_item_size as f64 == post_residual as f64 {
        score -= 20.0;
    } else if next_item_size > 0 && (next_item_size as u32) > post_residual {
        // next item won't fit here anyway; mild penalty for stranding space
        score += post_residual as f64 * 0.3;
    }

    // Mean residual coupling: penalize bins far below mean residual (fragmented).
    score -= (mean_residual - post_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

