    // Early on: prefer tight fits (low post_residual) mildly.
    // Late: penalize wasted residual more strongly via smooth ramp.
    let tightness = 1.0 - (pr / cap);
    let progress_term = progress * progress * (1.0 - progress * 0.5);
    score -= tightness * tightness * 8.0 * (0.5 + progress_term);

    // Smooth penalty for leaving residual that can't fit the next item.
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if pr >= ns {
            // next item fits: reward slightly, scaled by how well it fills
            let fill = ns / cap;
            score -= 3.0 * fill * (1.0 - progress);
        } else {
            // dead space relative to next item: smooth quadratic penalty
            let gap = (ns - pr) / cap;
            score += 10.0 * gap * gap;
        }
