    // Many open bins with high mean residual: discourage fragmenting further.
    let mean_norm = mean_residual / cap;
    score += 2.0 * (open_bins_count as f64).sqrt() * mean_norm * mean_norm * (1.0 - progress);

    // Slight penalty for using a fresh bin when open bins exist.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 5.0 - 3.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small residue classes" (hard to fill later) get penalized.
    let pr = post_residual;
    let class = pr % 10; // residue class mod 10
    score += (class as f64) * 0.35;

    // Integer-division thresholds: leftover in [1..=9] is nearly dead space.
    if pr > 0 && pr <= 9 {
        score += 25.0;
    }
    // Perfect fit: reward strongly.
    if pr == 0 {
        score -= 60.0;
    }

    // Small leftover that exactly accommodates a harmonic class of future items
    // (multiples of 10): leftover divisible by 10 is reusable.
    if pr >= 10 && pr % 10 == 0 {
        score -= 12.0;
    }

    // Lookahead coupling: if next item fits the post residual exactly, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0;
        } else if next_item_size <= pr {
            // next item fits: reward proportional to how much would remain
            let next_post = pr - next_item_size;
            score -= 15.0 + 0.3 * (next_post as f64);
        } else {
            // next item won't fit here: mild penalty scaled by overflow amount
            score += 0.25 * ((next_item_size - pr) as f64);
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowded = mean_residual < 0.5 * cap;
        if fitting_bins_count == 0 || (crowded && progress > 0.2) {
            score -= 20.0;
        } else {
            score += 15.0 + 0.1 * (open_bins_count as f64);
        }
    }

    // Prefer tighter bins: relative fill fraction of this bin.
    let fill = (bin_residual as f64) / cap;
    score += 10.0 * fill;

    // Mean-residual divergence: bins far below mean residual are "loose" fits.
    score += 0.05 * ((mean_residual - bin_residual as f64).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space penalty: small unusable gaps are the enemy.
    // Define "unusable" as a gap smaller than the smallest plausible item (10),
    // with a graded penalty for gaps in the danger zone [1, 20].
    let pr = post_residual as f64;
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - pr) / 10.0; // dead space: nothing can ever use it
    } else if post_residual >= 10 && post_residual < 20 {
        // narrow window: only tiny items fit, likely wasteful
        score += 25.0 * (20.0 - pr) / 10.0;
    }

    // Reward exact fits / large post_residual that remain useful.
    if post_residual >= 40 {
        score -= 8.0;
    } else if post_residual == 0 {
        score -= 20.0; // perfect closure is ideal
    }

    // Pressure from number of open bins: prefer consolidating when many bins open.
    score += (open_bins_count as f64) * 1.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits in the post residual, reward this placement.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 10.0;
    } else if next_item_size > 0 && (next_item_size as u32) > post_residual && post_residual > 0 {
        score += 6.0; // placement strands the next item
    }

    // New-bin candidate: only attractive when open bins have poor residuals.
    if bin_residual == bin_capacity {
        let pressure = (mean_residual / bin_capacity as f64).max(0.0);
        score += 35.0 - 40.0 * pressure;
        // early stream: new bins are cheap to open
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * (1.0 - progress);
    }

    // Mean residual coupling: if this bin's residual is far below mean, it's a tight fit — prefer it.
    score -= (bin_residual as f64 - mean_residual) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit reward (post_residual == 0 is perfect).
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: strongly reward leaving exactly next_item_size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs();
        score -= 60.0 / (1.0 + diff as f64);
        // Perfect 2-chain: item + next item exactly fills the bin.
        if post_residual as i64 == next_item_size as i64 {
            score -= 400.0;
        }
        // Penalize leaving space that next item cannot use but is still "wasted".
        if post_residual < next_item_size && post_residual > 0 {
            score += 15.0;
        }
    }

    // Penalize dead space: residual too small for any plausible item (assume min size 1..=10).
    if post_residual > 0 && post_residual < 10 {
        score += 80.0;
    }

    // Last-chance bonus: this is the only bin that fits; avoid opening a new bin for marginal cases.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate logic: empty bin should only win when current fit is poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 150.0;
        // If lookahead chains perfectly into an empty bin, allow it.
        if next_item_size > 0 && (bin_capacity as i64 - item_size as i64 - next_item_size as i64) == 0 {
            score -= 500.0;
        }
        // Late in the stream, opening new bins is less attractive (leftover waste).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 200.0 * progress;
    }

    // Prefer bins tighter than the mean residual (best-fit flavor).
    score += (mean_residual - bin_residual as f64) * 0.5;

    // Mild preference for filling fuller bins.
    score -= (bin_capacity - bin_residual) as f64 * 0.3;

    // Slight penalty when many bins are open (encourage consolidation).
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: reward tight fits (small post_residual) non-linearly.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let tightness = 1.0 - (pr / cap);
    score -= 30.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 20.0;
    }

    // Dead-space penalty: post_residual too small for any plausible item (min size 1, but
    // realistically small slivers waste capacity). Penalize residuals in (0, 12).
    if post_residual > 0 && post_residual < 12 {
        score += 8.0 * (12.0 - pr);
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Lookahead: check if next item can co-fit into post_residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 15.0; // leaves room for the next item: good chaining
            // Extra reward if next item exactly fills the remainder.
            if (pr - nxt).abs() < 1.0 {
                score -= 15.0;
            }
        } else if pr > 0.0 && pr < nxt {
            // remainder can't host next item; penalize proportionally to how close it is
            score += 6.0 * (1.0 - pr / nxt.max(1.0));
        }
        // If this bin currently can't fit the next item either way, mild indifference.
    }

    // New-bin candidate handling: empty bin has bin_residual == bin_capacity.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Opening a new bin wastes the residual of the current bin stream; penalize
        // unless the current item would leave a very awkward remainder everywhere.
        // Base penalty grows with number of open bins (fragmentation cost).
        score += 35.0 + 3.0 * open_bins_count as f64;
        // But if item is large relative to capacity, a fresh bin is natural.
        let frac = item_size as f64 / cap;
        if frac > 0.6 {
            score -= 20.0 * (frac - 0.6) / 0.4;
        }
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
        // If the new bin would be nearly filled by the item, it's a fine choice.
        if frac > 0.85 {
            score -= 25.0;
        }
    }

    // Global state coupling: prefer filling bins whose residual is far below the mean
    // (drain outlier bins with large residuals? No — prefer bins with residual close to
    // mean to keep residuals homogeneous, making future fits predictable).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Mild preference for bins with larger residual when item is large (avoid stranding).
    if item_size as f64 > 0.5 * cap {
        score += 0.1 * (bin_residual as f64 - item_size as f64).max(0.0);
    }

    // Time horizon: early on, allow slight exploration of new bins; late, consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let res = bin_residual as f64;

    // Base: prefer small post_residual (tight packing).
    let mut score = pr;

    // Non-linear coupling: post_residual normalized, polynomial shaping.
    let x = pr / cap; // in [0,1]
    let poly = x * x * (3.0 - 2.0 * x); // smoothstep-like: penalizes mid-range waste
    score += 8.0 * poly * (1.0 + progress);

    // Reward high fill ratio (item_size / bin_residual) with non-linear boost.
    let fill = it / res.max(1.0);
    score -= 6.0 * fill * fill * (1.0 - progress);

    // Last-chance bonus: only one fitting bin -> strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    } else if fitting_bins_count > 1 {
        // mild preference proportional to scarcity
        score -= 2.0 / fitting_bins_count as f64;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let slack = (pr - nx) / cap;
            score -= 10.0 * (1.0 - slack) * (1.0 - progress);
        } else {
            // next item won't fit here; penalize leaving residual that is too small for typical items
            score += 3.0 * (1.0 - pr / cap) * (1.0 - progress);
        }
    }

    // Deviation from mean residual: prefer bins below mean (consolidate emptier bins usage).
    let dev = (pr - mean_residual) / cap;
    score += 4.0 * dev * dev.abs();

    // Many open bins: encourage closing bins (small post_residual) to reduce bin count.
    score += (open_bins_count as f64).ln().max(0.0) * 0.5 * x;

    // New-bin candidate: make it unattractive unless current bins would leave tiny dead space.
    if bin_residual == bin_capacity {
        score += 12.0 + 8.0 * progress;
        // allow opening a new bin if the item is large relative to capacity
        score -= 14.0 * (it / cap) * (it / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify by integer division into
    // dead-space bands (capacity 100 -> classes of width 10).
    let class = post_residual / 10;
    let frac = (post_residual % 10) as f64 / 10.0;

    // Reward small post_residual (tight fit) super-linearly.
    score -= (bin_capacity - post_residual) as f64 * (bin_capacity - post_residual) as f64 / (bin_capacity as f64 * bin_capacity as f64) * 30.0;

    // Penalize post_residuals in "awkward" harmonic classes: residues that
    // few item sizes can fill (e.g. 1..=9 leftover is nearly dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    if class == 3 && frac < 0.5 {
        score += 6.0; // 30..34 residual: awkward zone
    }
    if class == 5 {
        score -= 4.0; // 50..59 residual: half-full bins stay flexible
    }

    // Perfect fit is golden.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead coupling: if next item fits the post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size < post_residual {
            let slack = post_residual - next_item_size;
            score -= 20.0 * (1.0 - slack as f64 / bin_capacity as f64);
        } else {
            // next item cannot use this bin's residue: mild penalty scaled by dead space
            score += 5.0 + (post_residual % next_item_size.max(1)) as f64 * 0.3;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: only attractive late in the stream or when open bins
    // are nearly full on average; otherwise penalize opening new bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let avg_pressure = 1.0 - mean_residual / bin_capacity as f64;
        score += 40.0 - 30.0 * progress - 25.0 * avg_pressure;
        if fitting_bins_count > 0 {
            score += 12.0; // extra nudge to reuse existing bins
        }
    }

    // Mild diversity bonus: prefer bins whose residual differs from the mean
    // residual (keeps a spread of usable hole sizes across bins).
    score += 0.05 * ((bin_residual as f64 - mean_residual).abs());

    // Small penalty proportional to number of open bins to encourage consolidation.
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: any leftover gap that is too small to be
    // useful later is heavily penalized. Gaps of exactly 0 (perfect fit) are
    // rewarded; gaps in the "dead zone" (1..=12) are punished hard.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 12 {
        score += (13.0 - post_residual as f64) * 6.0;
    } else if post_residual < 10 {
        score += 10.0;
    }

    // Prefer bins whose residual is being consumed by a large fraction,
    // i.e., tight packing relative to current fill.
    let fill_frac = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 8.0 * fill_frac;

    // Open-bin pressure: discourage scattering across many bins; add a
    // mild penalty proportional to the number of currently open bins so
    // the heuristic prefers consolidating into existing bins when fits
    // are comparable.
    score += (open_bins_count as f64) * 0.35;

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: an empty bin has large post_residual,
    // which is naturally attractive. But if the item fits reasonably well
    // in an existing bin (post_residual not tiny), penalize the fresh bin
    // so we don't waste open capacity.
    if bin_residual == bin_capacity {
        // Reward a new bin when the item is large relative to capacity
        // (poor maneuverability later) or when existing fits are bad.
        score -= (item_size as f64 / bin_capacity as f64) * 10.0;
        if post_residual <= 12 && post_residual > 0 {
            // opening a bin that immediately creates a dead gap is bad
            score += 15.0;
        }
    }

    // Lookahead coupling: if the next item could use the post_residual
    // gap, mildly reward leaving exactly that much space.
    if next_item_size > 0 {
        let gap = post_residual as f64;
        if gap >= next_item_size as f64 {
            score -= 3.0;
        } else if gap > 0.0 && gap < 10.0 {
            score += 4.0; // gap likely unusable for next item too
        }
    }

    // Late-stream consolidation: as the stream progresses, tighten up and
    // avoid opening extra bins unless necessary.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 2.0 * (open_bins_count as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual) — already captured by starting score.

    // Aggressive 2-step lookahead: strongly reward when the NEXT item fits
    // exactly into the post_residual of this bin (perfect chain).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect 2-item completion
        } else if next_item_size <= post_residual {
            // next item fits: reward proportionally to how well it fills leftover
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 40.0 * fill;
        } else {
            // next item does NOT fit here: penalize dead space left behind,
            // scaled by how badly the next item misses
            let miss = (next_item_size - post_residual) as f64;
            score += 0.5 * miss.min(60.0);
        }
    } else {
        // Last item: just close out tightly
        score -= 10.0;
    }

    // Relative-to-mean coupling: bins with residual far below the mean are
    // "almost full" — placing here consolidates waste; reward that.
    let rel = post_residual as f64 - mean_residual;
    score += 0.15 * rel;

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is huge
    // relative to it or no good fit exists (handled by last-chance above).
    if bin_residual == bin_capacity {
        score += 30.0;
        // but if the next item is small, a fresh bin is more flexible
        if next_item_size > 0 && next_item_size <= 30 {
            score -= 15.0;
        }
    }

    // Mild early-stream exploration: early on, keep bins balanced.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 0.05 * (post_residual as f64 - bin_capacity as f64 / 2.0).abs();

    // Slight preference for using fewer open bins when many are open.
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: normalized fill ratio bonus.
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill * fill;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits exactly in post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item won't fit here; mild penalty if this bin becomes very fragmented.
            score += 5.0 * (1.0 - (post_residual as f64 / bin_capacity as f64));
        }
    } else {
        // Last item: prefer perfect closure.
        if post_residual == 0 {
            score -= 50.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 + 0.1 * (post_residual as f64);
    }

    // New-bin candidate handling: opening a new bin is wasteful early and when
    // mean residual across open bins is high; encourage reuse when mean_residual is large.
    if bin_residual == bin_capacity {
        // New bin: base score is capacity; penalize when open bins already hold lots of space.
        score += (mean_residual / open_bins_count.max(1) as f64).max(0.0) * 1.5;
        // Early stream: discourage proliferation; late stream: allow fresh bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * (1.0 - progress);
        // If many bins fit the item, opening a new one is rarely needed.
        if fitting_bins_count > 2 {
            score += 20.0;
        }
    }

    // Global pressure: many open bins -> prefer consolidating into fuller bins.
    if open_bins_count > 4 {
        score -= (bin_residual as f64 - post_residual as f64) * 0.05;
    }

    // Mild coupling with mean residual: prefer bins below mean residual (fuller bins).
    score += 0.05 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post-residual, smoothed by a quadratic shaping of normalized residual.
    let mut score = pr * (1.0 + 0.6 * norm_pr * (1.0 - norm_pr));

    // Non-linear coupling of post-residual with stream progress:
    // late in the stream, compact residual space more aggressively.
    score += 12.0 * norm_pr * norm_pr * progress;

    // Reward tight fits with a cubic term of (1 - norm_pr).
    let tight = 1.0 - norm_pr;
    score -= 8.0 * tight * tight * tight;

    // Penalize creating dead space unusable by the next item (smooth interaction).
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (nx - pr).max(0.0) / cap;
        score += 15.0 * gap * gap * (1.0 - progress);
        // Reward if next item fits the post-residual exactly-ish (smooth).
        let fit_frac = if pr > 0.0 { 1.0 - (nx - pr).abs() / cap } else { 0.0 };
        score -= 5.0 * fit_frac.max(0.0) * fit_frac;
    } else {
        // Last item: strongly prefer smallest post-residual.
        score += 20.0 * norm_pr;
    }

    // Last-chance bin bonus (smooth in fitting_bins_count).
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 6.0;
    }

    // Slight preference toward filling bins with larger mean residual (consolidation).
    score -= 0.05 * mean_residual * progress;

    // New-bin candidate: mild penalty so it's chosen only when placements are bad.
    if bin_residual == bin_capacity {
        score += 3.0 + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small" residue classes (likely dead space) are penalized.
    let pr = post_residual;
    let residue_class = pr % 10;
    if pr > 0 {
        // Dead-space penalty grows when leftover is awkward (1..9 mod 10 with small value)
        let awkward = if residue_class >= 1 && residue_class <= 9 && pr < 20 { 1.0 } else { 0.0 };
        score += awkward * 12.0;
    }

    // Perfect fit reward
    if pr == 0 {
        score -= 60.0;
    }

    // Harmonic capacity fractions: reward leaving multiples of common item sizes
    let harmony = |r: u32| -> f64 {
        let mut h = 0.0;
        for m in [10u32, 20, 25, 50] {
            if m > 0 && r % m == 0 && r > 0 {
                h += 8.0;
            }
        }
        h
    };
    score -= harmony(pr);

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0;
        } else if next_item_size <= pr {
            // next item fits: reward proportional to how snugly
            let slack = (pr - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here: mild penalty for leaving large residual
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Penalize opening new bins when open bins have plenty of room
    if bin_residual == bin_capacity {
        // new-bin candidate: base cost plus pressure from open bins' waste
        score += 25.0 + 0.35 * mean_residual;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * (1.0 - progress);
    }

    // Prefer filling fuller bins: tie-break by fraction of bin consumed
    let fill_frac = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fill_frac;

    // Integer-division threshold on post_residual: residuals < 10 are near-dead
    if pr > 0 && pr / 10 == 0 {
        score += 18.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harder than large ones.
    // A residual below the minimum item size (1) can't happen, but small residuals
    // (< ~20) are unlikely to be filled by future items -> quadratic penalty.
    if post_residual > 0 {
        let pr = post_residual as f64;
        if pr < 20.0 {
            score += (20.0 - pr) * (20.0 - pr) * 0.5;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 30.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / (bin_residual as f64).max(1.0);
    score -= tightness * 5.0;

    // Lookahead: if the next item fits exactly in the post_residual, reward heavily.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if nxt <= pr && pr - nxt < 10.0 {
            score -= 12.0;
        } else if pr > 0.0 && nxt > pr {
            // next item won't fit here: mild penalty for leaving a gap that blocks lookahead
            score += 3.0;
        }
    }

    // Open-bin pressure: when many bins are open, discourage opening new bins
    // and encourage consolidating into existing ones.
    let obp = open_bins_count as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are already open.
        score += obp * 2.0;
        // But if no existing bin fits well (post_residual large), new bin is OK.
    } else {
        // Existing bin: reward using it, scaled by open-bin pressure.
        score -= obp * 0.5;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Mean-residual coupling: prefer bins whose residual is below average
    // (fill the fullest bins first, keep large gaps available).
    let res = bin_residual as f64;
    if res < mean_residual {
        score -= (mean_residual - res) * 0.3;
    } else {
        score += (res - mean_residual) * 0.3;
    }

    // Stream progression: early on, allow more new bins (exploration);
    // late in the stream, be conservative and fill existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += progress * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fills: small post_residual is good, but
    // an exact match (post_residual == 0) is best.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    } else if post_residual > 60 {
        // Large dead space penalty: leaving a huge unusable gap.
        score += (post_residual as f64 - 60.0) * 1.5;
    }

    // Aggressive 2-step lookahead: if the next item fits exactly into
    // the post-residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size < post_residual {
            let next_post = post_residual - next_item_size;
            // Prefer chains that keep residual small after two placements.
            score -= 10.0 - (next_post as f64).min(10.0);
            if next_post == 0 {
                score -= 35.0;
            }
        } else {
            // Next item won't fit here; slight penalty proportional to waste.
            score += ((next_item_size - post_residual) as f64) * 0.3;
        }
    }

    // Coupling with mean residual: bins tighter than the mean are
    // preferable targets (compact the packing).
    let diff = mean_residual - bin_residual as f64;
    if diff > 0.0 {
        score -= diff * 0.4;
    } else {
        score += (-diff) * 0.2;
    }

    // Last-chance bin: if this is the only bin that fits the item,
    // using it avoids opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless the item
    // is large and few bins are open (amortization of the new bin).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let large_item = item_size >= 70;
        let few_bins = open_bins_count <= 2;
        if !(large_item && few_bins) {
            score += 25.0 + 30.0 * (1.0 - progress);
        } else {
            score += 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let mut score = post;

    // Tight-fit reward: quadratic bonus for small post-residual.
    let tight = 1.0 - post / cap;
    score -= 18.0 * tight * tight;

    // Penalize dead space that no future item (>=10) can ever use.
    if post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as u32) >= next_item_size {
            let slack = post_residual - next_item_size;
            score -= 12.0 * (1.0 - slack as f64 / cap);
        } else {
            // Next item cannot follow here; slight penalty if post residual is stranded.
            score += 3.0 * (post / cap);
        }
        // Perfect chain: item + next fill the bin exactly.
        if next_item_size == post_residual {
            score -= 30.0;
        }
        let _ = nxt;
    }

    // Last-chance bin: if this is the only fitting bin, prefer it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        // Many options: mild penalty to encourage diversity of remaining residuals.
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate handling: opening a new bin is only attractive when the item
    // is large relative to capacity (poor fit anywhere) or late in the stream.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fill_ratio = item / cap;
        // Penalize new bin by default; discount when item is big or stream is ending.
        score += 10.0 - 20.0 * fill_ratio * fill_ratio - 8.0 * progress;
        if post_residual > 50 {
            score += 6.0; // wasteful new bin with a huge hole
        }
    }

    // Global state coupling: spread of residuals vs mean; prefer bins near the mean
    // to keep residuals uniform and predictable for future items.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 1.5 * (dev / cap);

    // Early stream: encourage keeping residuals large and flexible.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * (post / cap) * 4.0;

    // Mild penalty for opening many bins.
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: quadratic in normalized post residual
    let mut score = norm_pr * norm_pr * cap;

    // Smooth progress coupling: penalize waste more as stream progresses
    score += norm_pr * (0.5 + 2.0 * progress) * cap;

    // Interaction of post residual with mean residual (relative waste)
    score += (pr - mean_residual).abs() * (0.2 + progress);

    // Reward tight fits smoothly via cubic decay of post residual
    score -= (1.0 - norm_pr).powi(3) * item_size as f64 * (0.3 + 0.7 * progress);

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 10.0 * (1.0 - norm_pr);
    }

    // Lookahead: penalize if next item cannot use the post residual
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).max(0.0);
        score += gap * (0.1 + 0.4 * progress);
        // Reward if next item fits exactly into the resulting space
        if next_item_size as f64 <= pr {
            score -= 2.0 * (pr - next_item_size as f64) / cap;
        }
    }

    // Mild pressure to consolidate when many bins are open
    score += open_bins_count as f64 * norm_pr * 0.05;

    // New-bin candidate: neutral-ish baseline, penalized when a good fit exists
    if bin_residual == bin_capacity {
        score = cap * (0.35 + 0.4 * progress) + open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls on a
    // "usable" residue class are rewarded, awkward classes are penalized.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Fraction of capacity left after placement.
    let frac = pr / cap;

    // Class 1: near-perfect fit (residual in [0,10]) -> strong reward.
    if post_residual <= 10 {
        score -= 40.0 + 2.0 * (10 - post_residual) as f64;
    }

    // Class 2: residual divisible by 4 (aligns with common item granularities) -> reward.
    if post_residual % 4 == 0 && post_residual > 0 {
        score -= 8.0;
    }
    if post_residual % 8 == 0 && post_residual > 0 {
        score -= 4.0;
    }

    // Class 3: dead-zone residuals (just above small-item sizes 10..30) -> penalize.
    let dead = |r: u32| -> bool {
        (r > 10 && r < 15) || (r > 20 && r < 25) || (r > 30 && r < 34) || (r > 40 && r < 45)
    };
    if dead(post_residual) {
        score += 12.0;
    }

    // Lookahead coupling: harmonic compatibility between post_residual and next item.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item fits exactly or with small slack -> reward.
            let slack = post_residual - next_item_size;
            score -= 10.0 + (slack as f64).recip().min(5.0);
            if slack == 0 {
                score -= 30.0;
            }
        } else {
            // Next item cannot use this bin's leftover -> penalize proportionally.
            score += 6.0 + (next_item_size as f64 - pr).min(20.0);
        }
        // Modulo harmony: if next item and residual share a residue class mod 10.
        if post_residual % 10 == next_item_size % 10 && next_item_size <= post_residual {
            score -= 6.0;
        }
    }

    // Integer-division threshold on residual: quarter classes of capacity.
    let quarter = post_residual / (bin_capacity / 4);
    score += match quarter {
        0 => -6.0,          // <=25 left: fairly committed bin
        1 => 0.0,
        2 => 2.0,
        3 => 4.0,           // mostly empty: prefer filling it, mild penalty
        _ => 0.0,
    };

    // Last-chance bin: only one fitting bin -> strong reward to avoid opening new bins.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when residual classes of open bins are bad
    // or stream is early with few open bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let bad_open = (mean_residual / cap) < 0.15;
        if open_bins_count == 0 || bad_open || (progress < 0.2 && open_bins_count < 3) {
            score -= 20.0;
        } else {
            score += 25.0;
        }
    }

    // Mild preference for bins below mean residual (fill emptier-of-space bins first).
    score += 0.05 * (pr - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 25.0;
    }
    if post_residual > 0 && post_residual < item_size.min(30) {
        // gap too small for typical future items -> dead space
        score += 15.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward filling a bin that was already fairly empty-relative (good consolidation).
    let fill_ratio = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * 20.0;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 1.5;

    // New-bin candidate: only attractive when no open bin fits well
    // (item is large relative to mean residual) or stream is early.
    if bin_residual == bin_capacity {
        let tightness = (item_size as f64) / (mean_residual.max(1.0));
        score += 45.0;                       // base cost of opening a bin
        score -= tightness * 20.0;           // attractive when item barely fits open bins
        if next_item_size > 0 && (next_item_size as f64) > mean_residual {
            score -= 10.0;                   // next item also won't fit open bins
        }
        if step_index as f64 / total_items as f64 > 0.5 {
            score += 10.0;                   // late stream: prefer consolidating
        }
    }

    // Lookahead: if next item exactly fits the post residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        score += 8.0; // next item can't use this bin's leftover
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect fill
    if post_residual == 0 {
        score -= 500.0;
    }

    // 2-step lookahead: reward residual that exactly matches next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 300.0;
        } else if post_residual > next_item_size {
            // next item still fits after this placement
            score -= 40.0;
        } else {
            // dead space smaller than next item: penalize proportionally
            let dead = (next_item_size - post_residual) as f64;
            score += dead * 1.5;
        }
    }

    // Compare against mean residual: prefer bins tighter than average
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 200.0;
    }

    // New-bin candidate: make it less attractive unless it's an excellent move
    if bin_residual == bin_capacity {
        score += 150.0;
        // opening new bin is OK late in stream when many bins open anyway
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 50.0;
        if open_bins_count == 0 {
            score -= 1000.0;
        }
    }

    // Slight preference for fuller bins overall
    score -= (item_size as f64 / bin_capacity as f64) * 30.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: scale down score when the item fills a large fraction of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * (bin_capacity as f64) * 0.6;

    // Penalize very small post-residuals only when they are likely unusable dead space
    // relative to the expected next item size.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if (post_residual as f64) < nx {
            // dead space for the next item: penalize proportionally to the gap
            score += (nx - post_residual as f64) * 0.8;
        } else {
            // residual can host the next item: reward
            score -= 6.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits, to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Many open bins with slack: discourage spreading; prefer consolidation into fuller bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let openness = open_bins_count as f64 / (mean_residual / 10.0 + 1.0);
    score += openness * 0.05 * (0.5 + progress);

    // Prefer bins whose residual is below the mean residual (i.e., fuller bins).
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    } else {
        score += 2.0;
    }

    // New-bin candidate handling: make an empty bin attractive only when no good fit exists
    // (i.e., post_residual would be tiny/dead or item barely fits elsewhere).
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        let mut new_bin_cost = 18.0;
        // cheaper to open a new bin early (plenty of stream left to fill it)
        new_bin_cost *= 1.0 - 0.5 * progress;
        // if the item is large relative to capacity, a fresh bin is more appealing
        new_bin_cost -= (item_size as f64 / bin_capacity as f64) * 8.0;
        // if many bins already fit the item, opening a new bin is wasteful
        if fitting_bins_count > 2 {
            new_bin_cost += 12.0;
        }
        score = post_residual as f64 + new_bin_cost;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with non-linear shaping
    let mut score = pr * (1.0 + 0.5 * norm_pr * norm_pr);

    // Smooth polynomial coupling of post-residual with stream progress:
    // late in the stream, tighter packing matters more
    let coupling = progress * (1.0 - progress);
    score += 8.0 * pr * (norm_pr - coupling) * (norm_pr - coupling);

    // Penalize dead space that cannot fit the lookahead item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            score += (nxt - pr) * (1.0 + 2.0 * progress);
        } else {
            score -= 2.0 * (1.0 - (pr - nxt) / cap);
        }
    }

    // Last-chance bonus: only one bin can fit this item
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0 * (1.0 - progress);
    }

    // Mild penalty for spreading across many open bins
    score += open_bins_count as f64 * 0.05;

    // Prefer bins below mean residual (filling emptier bins)
    score += 0.3 * (mean_residual - pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo classes over capacity
    let post = post_residual;
    let class_small = (post % 10) as f64;          // fine-grained remainder
    let class_coarse = (post / 10) as f64;         // decade class 0..10

    // Reward small post_residual (tight fit) with non-linear decay
    score -= 40.0 * (-post as f64 / 25.0).exp();

    // Dead-space penalty: post_residual too small for any plausible item (1..100)
    if post > 0 && post < 10 {
        score += 45.0; // unusable sliver
    } else if post >= 10 && post < 20 {
        score += 12.0; // marginal zone
    }

    // Harmonic coupling: if next item exactly divides into post_residual, big reward
    if next_item_size > 0 && post > 0 {
        if next_item_size == post {
            score -= 55.0; // perfect next fit
        } else if post % next_item_size == 0 && post >= next_item_size {
            score -= 20.0; // exact harmonic division
        } else if next_item_size > post {
            score += 18.0; // next item cannot follow here
        } else {
            let frac = next_item_size as f64 / post as f64;
            score -= 25.0 * frac * frac; // smoother next-fit quality
        }
    }

    // Coarse class bonus: residuals near half-capacity or multiples of 25 are versatile
    let half = bin_capacity / 2;
    if post.abs_diff(half) <= 5 {
        score -= 15.0;
    }
    if post % 25 == 0 && post > 0 {
        score -= 8.0;
    }

    // Fine remainder harmonics: multiples of 5 pack better with typical sizes
    score -= 4.0 * ((class_small / 5.0).round() * 5.0 - class_small).abs() / 5.0;

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize mildly so it only wins when fits are terrible,
    // but boost it late in the stream or when many bins are open (load spreading)
    if bin_residual == bin_capacity {
        score += 70.0;
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 30.0 * progress;
        if open_bins_count > 4 { score -= 10.0; }
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 { score -= 25.0; }
    }

    // Prefer filling bins below mean residual (consolidation)
    score -= 0.15 * (mean_residual - bin_residual as f64);

    // Tie-break by tightness of the item itself
    score -= 0.05 * item_size as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 12.0;
    } else if post_residual > 50 {
        score -= 6.0; // roomy leftover is reusable
    }

    // Perfect fit strongly rewarded.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Last-chance bin: strong bonus to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: penalize adding to many open bins lightly,
    // encourage closing bins out (large fill fraction).
    score += 0.15 * open_bins_count as f64;

    // Lookahead: if next item fits the post residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 4.0; // dead space for the known next item
    }

    // New-bin candidate: prefer it only late in the stream or when open bins are many.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 - 10.0 * progress + 0.3 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near-match: next item fits with small slack
    else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
    }
    // Next item cannot use the leftover: dead-space penalty scaled by dead fraction
    else if next_item_size > 0 && post_residual < next_item_size {
        score += 15.0 * (post_residual as f64 / next_item_size as f64);
    }

    // Last-chance bin: strong bonus to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Penalize bins whose residual deviates above the mean (hoarded space)
    score += 0.3 * (bin_residual as f64 - mean_residual).max(0.0);

    // New-bin candidate (empty bin): only attractive when nothing fits well
    if bin_residual == bin_capacity {
        score += 25.0 + 0.5 * mean_residual;
    }

    // Early stream: be slightly conservative, keep bins flexible
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to item size.
    let tight = (post_residual as f64) / (item_size as f64).max(1.0);
    score -= tight * 30.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual < 10 {
        score -= 60.0;
    }

    // Penalize dead space that is too small for typical items (1..100 range).
    if post_residual > 0 && post_residual < 25 {
        score += 40.0;
    }

    // Lookahead: if the next item fits into the post residual, reward; else penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 35.0;
        } else {
            score += 15.0;
        }
        // Chain fit: next item leaves a reasonable remainder too.
        if next_item_size > 0 && next_item_size <= post_residual {
            let chain_post = post_residual - next_item_size;
            if chain_post < 10 {
                score -= 25.0;
            }
        }
    }

    // Last chance: this is the only bin that fits; strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 80.0;
    } else if fitting_bins_count > 3 {
        score += 5.0 * (fitting_bins_count as f64 - 3.0).min(5.0);
    }

    // Global state coupling: prefer filling bins when many bins are open.
    score -= (open_bins_count as f64).ln().max(0.0) * 8.0;

    // Prefer bins whose residual is below the mean residual (consolidate fuller bins).
    score += (mean_residual - bin_residual as f64) * 0.5;

    // Time horizon: early in the stream, be more open to spreading items (favor new bins
    // slightly); late in the stream, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 20.0;

    // New-bin candidate handling: empty bin gets a moderate baseline; opening a new bin
    // is only attractive when current bin fits are poor (post_residual high) or when
    // the item barely fits anywhere.
    if bin_residual == bin_capacity {
        // New bin: penalize if many open bins exist and progress is high (consolidate),
        // but reward slightly when item is large relative to capacity.
        score = post_residual as f64 + 30.0
            - (item_size as f64 / bin_capacity as f64) * 40.0
            + (1.0 - progress) * 10.0
            + (open_bins_count as f64) * 3.0;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 20.0; // a fresh bin can host the lookahead item too
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Base: post_residual (bigger leftover => higher score => less preferred)
    let mut score = post;

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, prefer filling bins tightly (low post_residual matters more);
    // later, tolerate residual since bins close out anyway.
    let norm_post = post / cap;
    let coupling = norm_post * norm_post * (1.0 - progress) * 40.0
                 - norm_post * progress * 12.0;
    score += coupling;

    // Reward near-perfect fits with a smooth quadratic dip.
    let fit_quality = 1.0 - (item / bin_residual.max(1) as f64);
    score -= (1.0 - fit_quality) * (1.0 - fit_quality) * 15.0;

    // Penalize dead space relative to mean residual (smooth quadratic).
    let dead = (post - mean_residual) / cap;
    score += dead * dead * 10.0;

    // Last-chance bin: strongly favor using it (subtract smoothly).
    if fitting_bins_count == 1 {
        score -= 25.0 + 10.0 * (1.0 - progress);
    }

    // Lookahead: if next item fits exactly in post_residual, reward heavily.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= (1.0 - diff / cap).max(0.0) * 20.0;
    }

    // New-bin candidate: make it moderately attractive only when open bins
    // are fragmented (mean residual low) or late in the stream.
    if bin_residual == bin_capacity {
        score = post + 5.0 + mean_residual * 0.3 - 15.0 * progress;
    }

    // Mild penalty for proliferating bins early.
    score += (open_bins_count as f64).ln() * 2.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues mod common item-size divisors.
    // Post-residuals that are "friendly" (divisible by common sizes) are worth keeping.
    let pr = post_residual;
    if pr > 0 {
        let mut friendliness = 0.0f64;
        for m in [10u32, 20, 25, 50].iter() {
            if pr % m == 0 { friendliness += 3.0; }
        }
        if pr % 5 == 0 { friendliness += 1.0; }
        score -= friendliness;

        // Penalize dead space: residuals too small for the smallest plausible item.
        if pr < 10 {
            score += 40.0;
        } else if pr < 20 {
            score += 12.0;
        }

        // Integer-division thresholds: how many "average chunks" fit afterwards.
        let chunks = pr / 25;
        score -= chunks as f64 * 2.0;
    } else {
        // Perfect fit is ideal.
        score -= 60.0;
    }

    // Lookahead: does post_residual fit the next item exactly or well?
    if next_item_size > 0 {
        if next_item_size <= pr {
            let nr = pr - next_item_size;
            if nr == 0 { score -= 25.0; }
            else if nr < 10 { score += 8.0; } else { score -= 6.0; }
        } else {
            // Next item can't use this residue: penalize proportionally.
            score += 5.0 + (next_item_size - pr) as f64 * 0.3;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when existing bins are fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score += 25.0 - fragmentation * 0.5 - progress * 10.0;
        if open_bins_count == 0 { score -= 100.0; }
        // Prefer new bin when item is large and would leave bad residue elsewhere.
        if item_size > bin_capacity / 2 { score -= 8.0; }
    } else {
        // Tight fits rewarded.
        score -= (item_size as f64 / bin_capacity as f64) * 10.0;
    }

    // Mild preference to balance bin count over the stream.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A gap is "dead" if the next item cannot fit into it.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0 + (next_item_size - post_residual) as f64 * 0.5;
    }
    // Gaps too small for the smallest conceivable item (<= 1) are pure waste.
    if post_residual == 0 {
        score -= 15.0; // perfect fit reward
    } else if post_residual < 10 {
        score += 40.0; // tiny dead space is the worst outcome
    }

    // Reward tight fits relative to bin capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 10.0;

    // Last-chance pressure: if this is the only bin that fits, prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 {
        score -= 8.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones
    // (the empty-bin candidate has bin_residual == bin_capacity, so its
    // post_residual is large; tighten the competition here).
    if bin_residual == bin_capacity {
        score += 5.0 + (open_bins_count as f64).sqrt() * 3.0;
    }

    // Coupling with mean residual: placing into a bin whose residual is far
    // below average consolidates space, leaving big gaps elsewhere usable.
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score -= dev * 0.3;
    } else {
        score += (-dev) * 0.15;
    }

    // Early in the stream, allow slightly more freedom to open bins for
    // diversity; late in the stream, be conservative.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= (1.0 - progress) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> strong reward
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 50.0;
    }
    // Near-perfect match: next item fits with small slack
    else if next_item_size > 0 && post_residual > next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= (30.0 * (1.0 - slack / bin_capacity as f64)).max(0.0);
    }
    // Next item does NOT fit in this bin's post residual: penalize wasted potential
    else if next_item_size > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Dead-space penalty for very small unusable residuals
    if post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bonus: only bin that fits, avoid opening new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Compare against mean residual: prefer bins tighter than average
    score -= 0.3 * (mean_residual - post_residual as f64);

    // New-bin candidate: mild penalty so we prefer reusing open bins unless they fit poorly
    if bin_residual == bin_capacity {
        score += 25.0;
        // But if next item matches a fresh bin perfectly, allow opening
        if next_item_size > 0 && bin_capacity - item_size == next_item_size {
            score -= 40.0;
        }
    }

    // Late in stream: prefer compacting into existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic penalty on leftover space
    score += 0.05 * (post_residual as f64).powi(2);

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: reward leaving space exactly matching the next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual > next_item_size {
            // leaving usable space for next item is good
            score -= 0.3 * (next_item_size as f64).min(post_residual as f64) * 0.1;
        } else {
            // dead space smaller than next item is bad
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // New-bin candidate: penalize opening a new bin unless current fit is poor
    if bin_residual == bin_capacity {
        // baseline cost of a fresh bin; make it competitive only against bad fits
        score += 40.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 20.0; // fresh bin can host the next large item
        }
    }

    // Fragmentation pressure: penalize bins whose residual becomes small & unusable
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Time horizon: late in the stream, consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Prefer filling bins with larger residuals when many bins are open
    score += 0.02 * open_bins_count as f64 * (bin_residual as f64 / bin_capacity as f64);

    // Mean-residual coupling: bins far from mean residual get slight normalization
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.01 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with non-linear tightening over time.
    let mut score = pr * (1.0 + 0.6 * progress) + 40.0 * norm_pr * norm_pr;

    // Reward tight fits (small dead space) with a smooth cubic coupling.
    score -= 60.0 * (1.0 - norm_pr).powi(3) * (1.0 + 0.5 * progress);

    // Penalize leaving residuals that no typical next item could use (dead space).
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr < nx {
            score += 25.0 * (nx - pr) / cap * (1.0 + progress);
        } else {
            // Reward residuals that exactly accommodate the lookahead item.
            score -= 20.0 * (1.0 - ((pr - nx) / cap).powi(2));
        }
    }

    // Last-chance bonus: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0 * (1.0 + 0.5 * progress);
    }

    // Mild penalty for spreading across many open bins vs. mean residual.
    let mean_gap = (mean_residual - pr) / cap;
    score += 10.0 * mean_gap * mean_gap;

    // Smooth new-bin handling: prefer new bin early or when residual would be tiny/wasteful.
    if bin_residual == bin_capacity {
        let waste = pr / cap;
        score -= 15.0 * (1.0 - progress) - 25.0 * waste * waste;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space quantization.
    // Residuals that are "useful" (multiples of small sizes) get rewarded.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit
    } else if pr % 10 == 0 {
        score -= 12.0; // decile-aligned residual is reusable
    } else if pr % 5 == 0 {
        score -= 5.0;
    } else if pr < 10 {
        score += 8.0; // tiny unusable dead space
    } else {
        score += ((pr % 10) as f64) * 0.6; // penalty grows with misalignment
    }

    // Integer-division threshold classes on post_residual vs next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // can host the lookahead item: strong reward, scaled by slack
            score -= 15.0 + 0.25 * (post_residual - next_item_size) as f64;
        } else {
            score += 10.0; // cannot host lookahead
        }
        // Harmonic pair: item + next fits exactly into capacity
        if item_size + next_item_size as u32 == bin_capacity && post_residual == 0 {
            score -= 40.0;
        }
    } else {
        // last item: prefer tightest fill anywhere
        score -= 5.0;
    }

    // Last-chance bin bonus: if this is the only fitting bin, avoid opening new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    // or the item is huge relative to mean residual.
    if bin_residual == bin_capacity {
        let crowded = mean_residual < item_size as f64 * 1.2;
        if crowded {
            score -= 25.0; // opening fresh bin is good
        } else {
            score += 30.0 + 0.1 * open_bins_count as f64; // prefer existing bins
        }
    }

    // Fraction-of-capacity coupling: reward bins whose fill ratio lands in
    // "harmonic" fractions (1/2, 2/3, 3/4) of capacity after placement.
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    for frac in [0.5f64, 2.0 / 3.0, 0.75, 0.9] {
        let d = (fill - frac).abs();
        if d < 0.02 {
            score -= 10.0;
        }
    }

    // Early stream: keep bins balanced (mild penalty for deviating from mean residual)
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        if progress < 0.5 {
            score += (score * 0.0) + 0.15 * (post_residual as f64 - mean_residual).abs();
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10.0 - post_residual as f64);
    }
    // Medium dead space (10..=20) mildly penalized; it may still fit small items.
    if post_residual >= 10 && post_residual <= 20 {
        score += 3.0;
    }

    // Reward tight fits (small waste) super-linearly.
    let waste = post_residual as f64;
    score += 0.02 * waste * waste;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: with many open bins, prefer packing into existing bins.
    let pressure = open_bins_count as f64 / 8.0;
    if bin_residual != bin_capacity {
        score -= pressure;
    } else {
        // New-bin candidate: penalize unless it would create a good future fit.
        score += pressure;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 8.0;
        }
    }

    // Lookahead: reward bins whose post_residual fits the next item exactly-ish.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 10 {
        score -= 6.0;
    }
    // Penalize leaving a gap that the next item just barely misses.
    if next_item_size > post_residual && next_item_size - post_residual < 10 && post_residual > 0 {
        score += 5.0;
    }

    // Early in stream: be slightly more willing to open fresh bins for large items.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity && item_size > 60 {
        score -= 4.0 * (1.0 - progress);
    }

    // Mild tie-break toward fuller bins relative to fleet mean residual.
    score -= (mean_residual - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual with next item.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let diff = (post_residual as f64 - next).abs();
        if post_residual as f64 == next {
            score -= 50.0; // perfect chain: item + next item fills bin exactly
        } else if post_residual >= next_item_size {
            score -= 15.0 * (1.0 - diff / bin_capacity as f64); // next item still fits
        } else {
            // dead space relative to lookahead item
            score += 10.0 + (next - post_residual as f64) * 0.5;
        }
    }

    // Penalize small unusable residuals (dead space) nonlinearly.
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Prefer bins tighter than the mean residual (good fits), discourage very loose bins.
    let res = post_residual as f64;
    if res < mean_residual {
        score -= (mean_residual - res) * 0.3;
    } else {
        score += (res - mean_residual) * 0.3;
    }

    // Slight preference for using open bins over opening new ones as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * progress; // new-bin candidate penalty grows over time
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong penalty for leaving dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 25 {
        score += (25.0 - post_residual as f64) * 0.8;
    }

    // Reward tight fits: post_residual near zero is ideal.
    score -= (item_size as f64 / bin_capacity as f64) * 15.0;

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 + (post_residual as f64 - next_item_size as f64).abs() * 0.3;
        } else {
            // Next item cannot follow here; slight penalty proportional to waste.
            score += (next_item_size as f64 - post_residual as f64).min(30.0) * 0.4;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Many open bins: discourage fragmenting space further; prefer best fit.
    let openness = open_bins_count as f64;
    score += openness * 0.5;

    // Deviation from mean residual: prefer bins tighter than average.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Time horizon: early in stream, be flexible (keep residuals large); later, pack tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * (1.0 - progress) * 0.2;

    // New-bin candidate: penalize opening a new bin unless current fits are poor.
    if bin_residual == bin_capacity {
        score += 25.0 + progress * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let p2 = progress * progress;
    let p3 = p2 * progress;
    let coupling = norm_pr * norm_pr * (1.0 + 2.0 * p2 + 3.0 * p3);
    score += 40.0 * coupling;

    // Reward tight fits more strongly as the stream progresses
    let tightness = 1.0 - norm_pr;
    score -= 25.0 * tightness * tightness * (0.5 + progress);

    // Penalize dead space that cannot fit the lookahead item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            let gap = (nxt - pr) / cap;
            score += 30.0 * gap * (1.0 + progress);
        } else {
            score -= 10.0 * (pr / nxt).min(2.0) * (0.3 + 0.7 * progress);
        }
    } else {
        // Last item: strongly prefer minimal post residual
        score -= 50.0 * (1.0 - norm_pr);
    }

    // Last-chance bin bonus (only fitting bin)
    if fitting_bins_count == 1 {
        score -= 20.0 * (1.0 - norm_pr) * (0.5 + progress);
    }

    // Mild penalty when many bins are open and residual is large (fragmentation)
    let ob = open_bins_count as f64;
    score += (ob / (ob + 5.0)) * 8.0 * norm_pr * (0.5 + p2);

    // Pull toward mean residual: prefer bins whose residual is near the mean (balanced packing)
    let dev = (pr - mean_residual) / cap;
    score += 6.0 * dev * dev * (0.5 + progress);

    // New-bin candidate: penalize opening a new bin unless residual is large relative to item
    if bin_residual == bin_capacity {
        let waste = 1.0 - (item_size as f64 / cap);
        score += 15.0 + 20.0 * waste * (1.0 - progress);
        if next_item_size > 0 && (next_item_size as f64) <= cap - item_size as f64 {
            score -= 12.0 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small dead space" classes (0..=10) are excellent; mid classes are poor.
    let pr = post_residual;
    if pr == 0 {
        score -= 40.0; // perfect closure
    } else if pr <= 5 {
        score -= 25.0;
    } else if pr <= 10 {
        score -= 15.0;
    } else if pr <= 20 {
        score -= 5.0;
    } else if pr <= 30 {
        score += 4.0; // awkward mid-class dead space
    } else if pr <= 45 {
        score += 8.0;
    }

    // Harmonic compatibility: does next_item_size fit exactly or nearly into post_residual?
    if next_item_size > 0 && (pr as f64) >= next_item_size as f64 {
        let slack = pr - next_item_size;
        if slack == 0 {
            score -= 20.0; // next item closes this bin perfectly
        } else if slack <= 10 {
            score -= 10.0;
        } else {
            score += (slack as f64) * 0.15; // big slack after next item = waste
        }
    } else if next_item_size > 0 {
        // next item cannot fit here; residual becomes pure dead space
        score += (pr as f64) * 0.10;
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless it truly helps.
    if bin_residual == bin_capacity {
        // Base penalty grows with number of open bins and mean residual.
        score += 55.0 + 2.0 * open_bins_count as f64;
        // A fresh bin is attractive only if the item is large and no open bin
        // offers a tight fit (post_residual here is cap - item_size).
        let fresh_post = pr as f64;
        if fresh_post <= 10.0 {
            score -= 45.0; // large item, fresh bin is nearly tight
        }
        // If mean residual across open bins is small, open bins are crowded:
        // opening a new bin may be justified.
        if mean_residual < 15.0 && fitting_bins_count <= 1 {
            score -= 25.0;
        }
        // Late in the stream, avoid bin proliferation slightly less.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 5.0 * progress;
    }

    // Mild preference for tighter existing bins relative to mean residual.
    score -= (mean_residual - post_residual as f64) * 0.05;

    // Tie-break: prefer bins with larger residual when residuals are harmonic
    // (multiples of 10 tend to pair well with 10..80 items).
    if pr % 10 == 0 && pr > 0 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (< smallest possible item) are pure waste.
    if post_residual < 10 && post_residual > 0 {
        score += 40.0;
    }
    // Penalize very tight fits that leave tiny gaps relative to capacity.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    if post_residual > 0 && fill_ratio > 0.6 {
        score += 8.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 15 {
        score -= 20.0 * (15.0 - post_residual as f64) / 15.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins.
    let pressure = (open_bins_count as f64).ln().max(1.0);
    score += 6.0 * pressure;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize opening a new bin unless item is large and would
    // leave a well-shaped residual, or existing residuals are too fragmented.
    if bin_residual == bin_capacity {
        score += 30.0 + 0.5 * open_bins_count as f64;
        // Large items fit better in fresh bins.
        if item_size > bin_capacity / 2 {
            score -= 25.0;
        }
        // If mean residual across open bins is small, existing bins are nearly full anyway.
        if mean_residual < item_size as f64 * 1.2 {
            score -= 20.0;
        }
    }

    // Lookahead coupling: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If next item would be blocked by the resulting residual, mild penalty.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 10.0;
    }

    // Late in the stream, be more conservative with new bins (fewer future chances to fill them).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // 2-step lookahead: reward residuals that can host the next item well.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 55.0; // perfect chain placement
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 - 0.25 * slack.min(40.0); // good but decaying with slack
        } else {
            // next item cannot fit here: penalize dead space
            let gap = (next_item_size - post_residual) as f64;
            score += 0.5 * gap;
        }
    }

    // Penalize residuals that become unusable (below minimum item size 1..10 typical).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Compare against mean residual: prefer bins tighter than average.
    score += 0.35 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when no good fit exists elsewhere.
    if bin_residual == bin_capacity {
        score += 20.0 + 0.1 * open_bins_count as f64;
    }

    // Late in stream, tighten packing (avoid spreading).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 8.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual relative to capacity).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * 40.0;

    // Penalize leaving dead space that likely cannot be filled by next item.
    if next_item_size > 0 && post_residual > 0 {
        if (post_residual as u32) < next_item_size {
            score += 12.0 + (next_item_size - post_residual) as f64 * 0.3;
        } else {
            // Good: next item could still fit here; reward proportionally.
            score -= ((post_residual as u32 - next_item_size).min(30)) as f64 * 0.15;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        let fit_quality = item_size as f64 / bin_residual as f64;
        if fit_quality > 0.5 {
            score -= 25.0 * fit_quality;
        }
    }

    // New-bin candidate handling: make an empty bin attractive only when the item
    // is large relative to capacity or open bins are already fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = open_bins_count as f64 / 10.0;
        let large_item_bonus = if item_size > bin_capacity / 2 { 8.0 } else { 0.0 };
        // Slight penalty so it's only chosen when open bins score badly.
        score += 6.0 + fragmentation * 0.5 - progress * 2.0 - large_item_bonus;
        // Empty bin leaves max residual for future flexibility; mild reward.
        score -= 3.0;
    }

    // Global pressure: when mean residual is low, prefer bins above mean (keep
    // high-residual bins flexible for big future items).
    if bin_residual as f64 > mean_residual {
        score -= 1.5;
    } else {
        score += 1.5;
    }

    // Slight preference for bins whose residual is "well-shaped" (multiples near
    // common item sizes) — reward residuals close to 10..80 range edges.
    let pr = post_residual as f64;
    if pr >= 10.0 && pr <= 80.0 {
        score -= 2.0;
    } else if pr > 0.0 {
        score += 2.0;
    }

    // Time horizon: early in the stream, be conservative (keep bins open and
    // flexible); late, pack aggressively to close bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let t = step_index as f64 / total_items.max(1) as f64;
    let fit = item_size as f64 / cap;
    let nxt = next_item_size as f64 / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let base = post / cap;
    let poly = base * base * (1.0 + 2.0 * t) - base * base * base * (1.0 + 3.0 * t);

    // Reward tight fits (small post residual) more strongly as stream progresses.
    let mut score = post * (0.5 + t * t);

    // Smooth interaction: dead space penalty scaled by fit ratio and progress.
    score += poly * cap * (0.3 + 0.7 * fit);

    // Penalize wasting a nearly-full bin if the next item could still use it.
    if next_item_size > 0 {
        let waste = (post - nxt).max(0.0);
        score += waste * (0.4 + 0.6 * t) * (1.0 - fit);
    }

    // Reward using the last fitting bin (avoid opening a new bin).
    if fitting_bins_count == 1 {
        score -= 15.0 * (0.5 + t);
    }

    // Slight preference toward balancing residuals across open bins.
    score += 0.2 * (post - mean_residual).abs();

    // New-bin candidate: mildly penalize opening bins early, allow later.
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - t) - 5.0 * t;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which quarter of the bin it lands in.
    let quarter = bin_capacity / 4;
    let class = post_residual / quarter; // 0..=4

    // Penalize dead space in the "unusable" low classes (tiny leftovers).
    match class {
        0 => score += 18.0,                       // residual < 25: nearly dead
        1 => score += 6.0,                        // 25..49: fits only small items
        2 => score -= 2.0,                        // 50..74: decent
        3 => score -= 8.0,                        // 75..99: very reusable
        _ => {}                                   // perfect fill (0 residual)
    }

    // Exact-fill bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Modulo coupling: does the leftover pair well with typical item granularity?
    let gran = 10u32;
    let aligned = post_residual % gran == 0;
    if aligned {
        score -= 5.0;
    } else {
        score += (post_residual % gran) as f64 * 0.4;
    }

    // Lookahead: if next item fits the post residual exactly, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.25;
        } else {
            // next item cannot use this leftover: penalize proportionally
            score += (next_item_size - post_residual).min(bin_capacity) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when nothing fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // New bin baseline: slightly worse than a good fit, better than dead space.
        score = cap * 0.55 + mean_residual * 0.2 - progress * 5.0;
        if fitting_bins_count == 0 {
            score -= 60.0; // nothing else fits: must open new bin
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 8.0; // pairing large items into fresh bins can help
        }
    }

    // Mild preference for tighter bins when many are open (consolidation).
    if !is_new_bin {
        score += (open_bins_count as f64).ln().max(0.0) * (post_residual as f64 / cap) * 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable gaps (dead space) super-linearly.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 25.0;
    }

    // Reward tight fits (post_residual near zero).
    if post_residual == 0 {
        score -= 60.0;
    }

    // Penalize opening a new bin when existing bins can fit, scaled by open-bin pressure.
    if bin_residual == bin_capacity && open_bins_count > 0 && fitting_bins_count > 0 {
        score += 30.0 + 5.0 * open_bins_count as f64;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Prefer bins whose residual is already small relative to mean residual.
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Lookahead: if next item could fill this bin's post-residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 50.0;
    }

    // Mild pressure against accumulating many open bins.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: strongly favor bins whose post residual is tiny.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: reward when the next item fits exactly into post_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
            // Next item fits; reward proportionally to how snug the second fit is.
            let second_fit = post_residual - next_item_size;
            if second_fit == 0 {
                score -= 400.0;
            } else if second_fit <= 10 {
                score -= 150.0;
            } else {
                score -= (10.0 * (1.0 - second_fit as f64 / bin_capacity as f64)).max(0.0);
            }
        } else {
            // Next item cannot fit here: penalize slightly, worse for small leftovers.
            let gap = next_item_size - post_residual;
            score += 20.0 + (gap as f64).min(50.0);
        }
    }

    // Penalize large dead space relative to mean residual across open bins.
    if post_residual as f64 > mean_residual + 20.0 {
        score += 0.5 * (post_residual as f64 - mean_residual);
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 300.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless the item
    // leaves a very large residual (poor fit everywhere) late in the stream.
    if bin_residual == bin_capacity {
        if next_item_size > 0 && post_residual >= next_item_size {
            score += 250.0; // keep using open bins when possible
        } else if fitting_bins_count > 0 {
            score += 400.0; // never open a new bin if one open bin fits reasonably
        } else {
            score -= 100.0; // no open bin fits: open a new one
        }
    }

    // Late in the stream, prefer tighter packing to close bins out.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * post_residual as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor placements leaving small post residual.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * tightness * 40.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bin: penalize skipping it (opening a new bin is costly).
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual >= next_item_size {
            score -= 10.0;
        } else {
            // Dead space relative to next item: penalize.
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Prefer bins with residual below mean residual (denser bins).
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // New-bin candidate: only attractive when the item is large relative to capacity
    // or all existing fits are poor.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / bin_capacity as f64;
        score += 20.0 - 25.0 * large_item;
        // Late in the stream, opening new bins is cheaper (fewer future items to fill them).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 10.0;
        // If many bins are open and none fit well, allow new bin.
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    // Mild penalty for many open bins when residual is fragmented.
    if open_bins_count > 0 {
        score += (open_bins_count as f64).ln() * 2.0 * tightness;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;
    let norm_pr = pr / cap;

    // Base: post residual, mildly non-linear (dead space penalty grows quadratically for small residuals)
    let mut score = norm_pr + 0.9 * norm_pr * norm_pr;

    // Reward tight fits: subtract a smooth bell around small post_residual
    let tightness = (-norm_pr * 4.0).exp();
    score -= 0.8 * tightness * (0.4 + 0.6 * progress);

    // Stream progress coupling: later in stream, prefer fuller packing (quadratic interaction)
    score -= 0.5 * progress * fit_ratio * (1.0 - norm_pr);

    // Lookahead: if next item fits exactly in post_residual, big reward (smooth coupling)
    if next_item_size > 0 {
        let next_fit = (post_residual as i64 - next_item_size as i64) as f64;
        if next_fit >= 0.0 {
            let nf = next_fit / cap;
            score -= 0.6 * (-nf * 8.0).exp() * (1.0 - progress);
        } else {
            score += 0.25 * (-next_fit / cap);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 1.5 * (0.5 + 0.5 * progress);
    }

    // Mean residual coupling: penalize bins far from the mean residual (smooth quadratic)
    let dev = (pr - mean_residual) / cap;
    score += 0.15 * dev * dev;

    // Mild penalty for too many open bins relative to stream length
    score += 0.05 * (open_bins_count as f64 / total_items.max(1) as f64);

    // New-bin candidate: make it moderately unattractive unless residuals are all large
    if bin_residual == bin_capacity {
        let scarcity = (fitting_bins_count as f64).max(1.0).recip();
        score = 0.6 + 0.5 * (1.0 - progress) - 0.8 * scarcity * (mean_residual / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: bucket sizes by quarters of capacity
    let item_class = (item_size * 4 / bin_capacity) as f64;
    let next_class = if next_item_size > 0 { (next_item_size * 4 / bin_capacity) as f64 } else { 0.0 };

    // Reward tight fits: small post_residual is good
    let tight_bonus = if post_residual == 0 {
        -30.0
    } else if post_residual <= 10 {
        -15.0
    } else {
        0.0
    };
    score += tight_bonus;

    // Penalize post_residual that cannot fit any plausible future item (dead space)
    let dead_threshold = 9.0;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += 25.0;
    }

    // Harmonic pairing: reward when post_residual can exactly fit the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        let pair_quality = if post_residual == next_item_size { -20.0 } else { -8.0 };
        score += pair_quality;
    } else if next_item_size > 0 {
        // Next item won't fit here; penalize more if next item is large (hard to place)
        score += 5.0 + next_class * 4.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Modulo harmonic: bins whose residual is a multiple of 5 are more reusable
    if post_residual % 5 == 0 {
        score -= 6.0;
    } else {
        score += 3.0;
    }

    // Integer division threshold on post_residual classes
    let residual_class = post_residual / 20; // 0..=5
    score += residual_class as f64 * 4.0;

    // New-bin candidate logic: only prefer a fresh bin if current open bins are crowded
    // and the item is large (would leave a good residual in a fresh bin)
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowded = (open_bins_count as f64) > 2.0 + progress * 4.0;
        let large_item = item_class >= 2.5;
        if crowded && large_item {
            score -= 10.0;
        } else {
            score += 15.0 + mean_residual * 0.05;
        }
    }

    // Mild preference for fuller bins (smaller residual) overall
    score -= (bin_capacity - bin_residual) as f64 * 0.05;

    // Penalize creating residual that is smaller than mean residual (fragmenting)
    if (post_residual as f64) < mean_residual && post_residual > 0 {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny nonzero gaps are heavily penalized.
    if post_residual > 0 {
        let dead = post_residual as f64;
        if dead < 10.0 {
            score += (10.0 - dead) * 12.0; // unusable micro-gap
        } else if dead < 20.0 {
            score += (20.0 - dead) * 3.0;  // near-dead gap
        }
        // Smooth extra penalty proportional to wasted fraction of capacity
        score += (dead / bin_capacity as f64) * 8.0;
    } else {
        score -= 25.0; // perfect fit: strongly rewarded
    }

    // Reward using a bin that is the last chance before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // Open-bins pressure: prefer consolidating into fewer bins
    score += open_bins_count as f64 * 0.6;

    // Prefer bins tighter than the mean residual (good packing)
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Lookahead: if next item fits the post-residual exactly-ish, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 10.0 * (1.0 - slack / bin_capacity as f64);
    }

    // New-bin candidate handling: only attractive when nothing packs well
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64 / (total_items.max(1) as f64).sqrt()) * 4.0;
        let last_chance_elsewhere = fitting_bins_count == 1;
        if last_chance_elsewhere {
            score += 30.0; // avoid wasting a full bin when an open bin is last chance
        } else {
            score -= pressure.min(6.0);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with a mild convex penalty
    let pr = post_residual as f64;
    score += 0.05 * pr * pr / bin_capacity as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post_residual >= next_item_size {
            let diff = (post_residual - next_item_size) as f64;
            // Perfect chain (next item fills exactly) is heavily rewarded
            score -= 30.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // Next item cannot chain into this bin: penalize proportionally to waste
            score += 8.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        }
        // If next item exactly fills the bin after this placement, big bonus
        if post_residual == next_item_size {
            score -= 25.0;
        }
    } else {
        // Last item: just minimize leftover
        score -= 20.0;
    }

    // Relative-to-mean coupling: bins tighter than average are more valuable to fill
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when nothing fits well
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 1.0 };
        score += 40.0 * pressure;
        // Late in the stream, opening new bins is more wasteful
        score += 20.0 * (step_index as f64 / total_items.max(1) as f64);
    }

    // Prefer reusing bins among many open bins (consolidation)
    score -= 0.05 * open_bins_count as f64 * (bin_capacity - bin_residual) as f64 / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squared penalty on wasted space.
    score += 0.05 * (post_residual as f64).powi(2) / bin_capacity as f64;

    // Penalize very small dead space that is hard to reuse later (awkward residual band).
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 12.0 {
        score += 18.0 * (12.0 - pr) / 12.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Lookahead: reward bins whose post-residual can still fit the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            score += 6.0; // creating residual that kills the next item's fit
        }
        // Chain fit: residual after placing next item too
        let chain = post_residual as i64 - next_item_size as i64;
        if chain >= 0 {
            score -= (chain as f64).min(20.0) * 0.15;
        }
    }

    // Time horizon: late in the stream, prefer consolidating into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress > 0.7 {
        score -= 5.0 * progress;
    }

    // Global state: many open bins with large mean residual -> discourage opening new bins,
    // encourage packing into bins with above-average residual.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize when existing bins are roomy or plentiful.
        score += 10.0 + 0.3 * open_bins_count as f64 + 0.2 * mean_residual;
        if fitting_bins_count == 0 {
            score -= 60.0; // no alternative: new bin is fine
        }
    } else if (bin_residual as f64) >= mean_residual {
        score -= 3.0;
    } else {
        score += 2.0;
    }

    // Prefer filling bins that are already fairly full (low residual) to close them out.
    score -= 0.1 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let poly = norm_pr * (1.0 + 0.8 * progress * norm_pr - 0.4 * (1.0 - progress) * norm_pr);
    let mut score = poly * cap;

    // Penalize near-full leftovers slightly less as stream ends (dead space matters less)
    let dead = (norm_pr - 0.1).max(0.0);
    score += dead * cap * (0.3 * (1.0 - progress));

    // Last-chance bin bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 15.0 * progress;
    }

    // New-bin candidate: penalize opening fresh bins unless residual would be very tight
    if bin_residual == bin_capacity {
        score += 30.0 - 20.0 * progress;
    }

    // Lookahead: reward leaving space for the next item
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 8.0 + 6.0 * progress;
    } else if next_item_size > 0 {
        score += 5.0;
    }

    // Mild preference for bins tighter than average
    score += 0.15 * (pr as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: which capacity fraction band does it land in?
    // Classes: 0 (perfect fit), 1..4 (fine slivers), 5..9 (usable mid), >=10 (roomy).
    let class = match post_residual {
        0 => 0,
        1..=4 => 1,
        5..=9 => 2,
        10..=19 => 3,
        20..=34 => 4,
        _ => 5,
    };

    // Reward tight fits strongly, with a bonus for the perfect fit.
    match class {
        0 => score -= 60.0,
        1 => score -= 25.0,
        2 => score -= 10.0,
        3 => {}
        4 => score += 8.0,
        _ => score += 15.0,
    }

    // Modulo-10 harmony: residuals that are multiples of 10 pair well with
    // common item sizes (multiples of 5/10 dominate most streams).
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    }
    if post_residual % 5 == 0 && post_residual > 0 {
        score -= 2.0;
    }

    // Lookahead coupling: does the leftover leave room for the next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Harmonic pair: post_residual - next_item_size determines future quality.
            let future = post_residual - next_item_size;
            if future == 0 {
                score -= 30.0;
            } else if future <= 10 {
                score -= 12.0;
            } else if future <= 25 {
                score -= 4.0;
            }
        } else {
            // Leftover too small for next item: penalize proportionally to wasted fraction.
            let waste = post_residual as f64;
            score += waste * 0.6;
            // But a tiny leftover (<5) is near-perfect packing anyway.
            if post_residual < 5 {
                score -= 18.0;
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit would be terrible.
    if fitting_bins_count == 1 && post_residual <= 40 {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless current fit is bad
    // or the bin is nearly full elsewhere. Empty bin has post_residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is discouraged when the item fits reasonably somewhere.
        score += 35.0;
        // But if the item is large relative to capacity and next item is also large,
        // a fresh bin may be better (avoid fragmenting).
        if item_size >= 60 && next_item_size >= 50 {
            score -= 45.0;
        }
        // Late in the stream, prefer closing out tight bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if progress > 0.8 {
            score += 10.0 * progress;
        }
    }

    // Mild preference for fuller bins overall (balance against mean residual).
    let fullness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= fullness * 10.0;

    // Slight penalty when many bins are open and this one would be left very empty.
    if open_bins_count > 3 && post_residual as f64 > mean_residual + 30.0 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residual gaps that no future item (min size 1,
    // but practically small) can use are pure waste. Penalize tiny unusable gaps
    // superlinearly, but reward a *perfect* fit (post_residual == 0).
    if post_residual == 0 {
        score -= 1000.0; // perfect fit: always take it
    } else if post_residual <= 10 {
        // dead space zone: gap too small for typical items
        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    } else if post_residual <= 25 {
        // marginal zone: mildly penalize
        score += (25 - post_residual) as f64 * 1.5;
    }

    // Reward leaving room for the lookahead item (k=2) when possible.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + next_item_size as f64 * 0.2;
    } else if next_item_size > 0 && post_residual > 0 {
        // placing here strands the next item relative to this bin
        score += 5.0;
    }

    // Last-chance pressure: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: opening a new bin is justified only when the
    // item fits badly everywhere else. Penalize the fresh bin when decent
    // alternatives exist; reward it when fitting options are scarce.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 30.0; // no open bin fits: new bin is the right call
        } else if fitting_bins_count == 1 {
            score += 20.0; // one last-chance bin exists: prefer it
        } else {
            score += 25.0 + open_bins_count as f64 * 0.5;
        }
    }

    // Open-bins pressure: mildly discourage scattering across many bins;
    // prefer tighter bins (low residual) when several fit equally.
    score += open_bins_count as f64 * 0.3;
    score += (bin_residual as f64 - mean_residual) * 0.4;

    // Late-stream tightening: as the stream progresses, favor compact placements.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * progress * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item fits the post-residual exactly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // perfect 2-chain
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot fit here: penalize dead space growth
            score += 6.0;
        }
    }

    // Relative to mean residual: prefer bins with residual already below average
    // (tighter bins get filled), penalize dipping far below mean (fragmentation).
    let res = post_residual as f64;
    let dev = res - mean_residual;
    score += 0.35 * dev;

    // Last-chance bonus: only one fitting bin -> avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 18.0;
    }

    // Penalize tiny unusable post-residuals (dead space < min item size 1..10 threshold)
    if post_residual < 10 && post_residual > 0 {
        score += 12.0;
    }

    // New-bin candidate: neutral-ish baseline; only attractive when open bins are fragmented.
    if bin_residual == bin_capacity {
        let frag = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score = 55.0 - 45.0 * frag;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0;
        }
    }

    // Late-stream consolidation: prefer filling existing bins near the end.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 8.0 * progress * (1.0 - res / bin_capacity as f64);

    // Mild penalty for too many open bins
    score += 0.4 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is already low, amplify exact/near-exact fits.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 12.0;
    } else if post_residual <= 15 {
        score -= 4.0;
    }

    // Penalize dead space that can't fit typical future items (below min item size 10).
    if post_residual < 10 && post_residual > 0 {
        score += 6.0;
    }

    // Last-chance bin bonus: if this is the only fitting bin, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly into the post_residual, reward heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size <= 10 {
            score -= 10.0;
        } else if post_residual > 0 && (post_residual as f64) < (next_item_size as f64) * 0.6 {
            // post residual too small for next item -> dead space risk
            score += 5.0;
        }
    }

    // Time horizon: early in the stream, be more conservative about filling bins
    // poorly (long horizon ahead); late in stream, accept mediocre fits.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 3.0 * (post_residual as f64 / bin_capacity as f64);

    // Global state coupling: many open bins with high mean residual -> prefer
    // consolidating into existing bins rather than opening new ones.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportional to open bins' idle capacity.
        score += 10.0 + 0.5 * open_bins_count as f64;
        if mean_residual > item_size as f64 {
            score += 8.0; // an open bin could absorb this item
        }
    } else {
        // Reward using bins whose residual deviates from mean (balance consolidation).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score -= 0.15 * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit_norm = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early stream: quadratic waste penalty grows with post_residual (save space).
    // Late stream: cubic term favors tight fits (small post_residual) more aggressively.
    let quad = fit_norm * fit_norm;
    let cube = quad * fit_norm;
    score += progress * 8.0 * cube - (1.0 - progress) * 3.0 * quad;

    // Penalize dead space that cannot fit the lookahead item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr < nx {
            score += 0.5 * (nx - pr) * (0.5 + progress);
        } else {
            // Reward bins whose leftover still accommodates the next item.
            score -= 0.35 * (1.0 - (pr - nx) / cap);
        }
    }

    // Last-chance bonus: prefer this bin when it is the only fitting one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 2.5;
    }

    // Mild pressure toward consolidating many open bins.
    score += 0.01 * (open_bins_count as f64 - mean_residual / 10.0);

    // Tightness reward: near-perfect fits get strong discount.
    if post_residual == 0 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: residuals divisible by common item
    // granularities are more reusable than "odd" dead space.
    let pr = post_residual;
    let class_bonus = if pr == 0 { -40.0 }
        else if pr % 10 == 0 { -12.0 }
        else if pr % 5 == 0 { -6.0 }
        else if pr % 2 == 0 { -2.0 }
        else { 4.0 };
    score += class_bonus;

    // Fractional capacity bands: prefer leaving either a large usable remainder
    // (> 50% of capacity) or an exact fit; penalize mid-range dead space.
    let frac = post_residual as f64 / cap;
    if frac > 0.5 { score -= 8.0; }
    else if frac > 0.25 { score += 6.0; }
    else if frac > 0.0 { score += 12.0; }

    // Integer-division threshold: can the lookahead item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Harmonic pairing: post_residual / next_item_size integer division
            let pairing = (post_residual / next_item_size.max(1)) as f64;
            score -= 10.0 + 4.0 * pairing.min(3.0);
            // Exact modulo match is a perfect harmonic pair
            if post_residual % next_item_size == 0 { score -= 15.0; }
        } else {
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when current item leaves awkward waste
    // and open bins are already fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap).clamp(0.0, 1.0);
        score += 20.0 - 15.0 * fragmentation;
        if post_residual >= 20 && post_residual % 10 == 0 { score -= 10.0; }
        if next_item_size > 0 && next_item_size > item_size { score -= 12.0; }
    }

    // Late in the stream, tighten packing (waste matters more).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that can never be used again are very costly.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item {
        score += 1000.0;
    }
    // Gap too small for the lookahead item AND below typical small-item size -> dead space risk
    if next_item_size > 0 && post_residual < next_item_size {
        score += 40.0 + (next_item_size - post_residual) as f64 * 0.8;
    }

    // Reward tight fits (small post_residual) super-linearly.
    if post_residual <= item_size / 2 {
        score -= 15.0;
    }
    if post_residual == 0 {
        score -= 60.0; // perfect fill
    }

    // Last chance before opening a new bin: strongly favor using this bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Open-bins pressure: discourage spreading across many bins unless fit is tight.
    let pressure = open_bins_count as f64 * 1.5;
    score += pressure * (post_residual as f64 / bin_capacity as f64);

    // Prefer bins with residual below the mean (consolidating fuller bins).
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // New-bin candidate: only attractive when current bin fits are poor.
    if bin_residual == bin_capacity {
        let poor_fits = (post_residual as f64) > 0.0
            && (next_item_size > 0 && post_residual < next_item_size);
        if poor_fits || open_bins_count == 0 {
            score -= 30.0;
        } else {
            score += 35.0 + open_bins_count as f64 * 2.0;
        }
    }

    // Slight early-stream bias toward filling existing bins aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - progress) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step chain: post_residual exactly matches next item -> strongly reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        let diff = (post - nxt).abs();
        if diff == 0.0 {
            score -= 60.0;
        } else if diff <= 5.0 {
            score -= 25.0 - diff * 3.0;
        } else {
            // Penalize dead space that next item cannot use
            score += diff * 0.35;
        }
        // If post_residual is too small for next item, it's dead space: penalize
        if post < nxt && post > 0.0 {
            score += post * 0.6;
        }
    } else {
        // Last item: just minimize leftover
        score += 5.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Prefer bins tighter than the mean residual (good fits)
    score += (bin_residual as f64 - mean_residual) * 0.25;

    // Penalize opening a new bin when open bins exist, unless item is large
    if bin_residual == bin_capacity && open_bins_count > 0 {
        let waste = bin_capacity as f64 - item_size as f64;
        score += 15.0 + waste * 0.5;
        // If no open bin fits well (many fitting bins is fine), allow new bin
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    // Slight preference for filling bins more completely as stream progresses
    score += (1.0 - (post_residual as f64) / bin_capacity as f64) * 10.0
        - (step_index as f64 / total_items.max(1) as f64) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 20.0 * fit_ratio * fit_ratio;

    // Penalize leaving dead space that few future items can use.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead: reward if the next item exactly fits the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item won't fit here; penalize wasting space it could have used elsewhere.
            score += 5.0 * (post_residual as f64 / next_item_size as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
        // Extra bonus if this is a decent fit.
        if post_residual < 20 {
            score -= 15.0;
        }
    }

    // New-bin candidate handling: only attractive when existing fits are poor.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin.
        score += 30.0;
        // If many bins already fit this item, opening new is wasteful.
        if fitting_bins_count > 0 {
            score += 20.0 * fitting_bins_count as f64;
        }
        // Early in stream, new bins are cheaper (future items unknown).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * (1.0 - progress);
        // If mean residual is large, open bins have room; discourage new bin.
        score += 0.3 * mean_residual;
    }

    // Mild preference for filling fuller bins as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - bin_residual as f64 / bin_capacity as f64);

    // Prefer consolidating into fewer bins when many are open.
    score += 0.05 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: reward tight fits via non-linear polynomial in post_residual (normalized).
    let x = pr / cap;
    let mut score = x * x * (3.0 - 2.0 * x); // smoothstep: small post_residual -> low score

    // Polynomial coupling with stream progress: later in stream, penalize larger residuals more strongly.
    let coupling = pr * (progress * progress) / cap;
    score += 0.5 * coupling;

    // Dead-space penalty: residual too small for any plausible item (min size 1..100 unknown; use item_size as scale proxy).
    let dead = (pr < item_size as f64 * 0.25) as f64;
    score += dead * (1.0 + progress) * 5.0;

    // Last-chance bonus: only one fitting bin -> strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // Lookahead: if next item fits exactly in post_residual, reward.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let fit_quality = 1.0 - ((pr - next_item_size as f64) / cap);
        score -= 2.0 * fit_quality * fit_quality;
    } else if next_item_size > 0 {
        score += 1.0;
    }

    // Mild preference for filling bins with low mean residual (consolidation).
    score += 0.1 * (mean_residual / cap);

    // New-bin candidate: neutral-ish baseline; only attractive when open bins are crowded.
    if bin_residual == bin_capacity {
        score = 8.0 + 4.0 * (1.0 - progress) - 0.05 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }
    // Perfect fit is strongly rewarded.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: reward bins whose leftover can host the next item.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0;
    }

    // Open-bins pressure: with many bins open, prefer consolidating into
    // existing bins rather than spreading items.
    let is_new_bin = bin_residual == bin_capacity;
    if !is_new_bin {
        score -= 2.5 * open_bins_count as f64;
        // Last-chance bin: this is the only bin that fits; avoid opening a new bin.
        if fitting_bins_count == 1 {
            score -= 20.0;
        }
    } else {
        // New-bin candidate: only attractive when the fit would leave a bad gap.
        if post_residual > 0 && post_residual < 10 {
            score -= 35.0; // opening a fresh bin beats creating dead space
        } else {
            score += 15.0; // otherwise prefer existing bins
        }
    }

    // Mild bias toward bins tighter than the average residual.
    score -= 0.3 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near-perfect match: next item fits leaving minimal waste.
    else if next_item_size > 0 && next_item_size <= post_residual {
        let leftover = (post_residual - next_item_size) as f64;
        score -= 30.0 - leftover.min(30.0);
    }
    // Next item does NOT fit in this bin after placement: penalize slightly
    // less if post_residual is large enough to be reusable anyway.
    else if next_item_size > post_residual {
        score += 5.0;
    }

    // Penalize small unusable dead space (hard to fill later).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Reward tight fits relative to current item size.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill_ratio;

    // Compare against mean residual: prefer bins tighter than average.
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin, unless the current item
    // is huge and many bins are already open (fragmentation risk).
    if bin_residual == bin_capacity {
        score += 15.0;
        if item_size > 70 && open_bins_count > 3 {
            score -= 30.0;
        }
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
    }

    // Early in the stream: be more willing to open bins to build diversity.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress < 0.2 && bin_residual == bin_capacity {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: penalize post_residual quadratically relative to capacity.
    score += 0.35 * (post_residual as f64 / cap) * (post_residual as f64 / cap) * cap * 0.1;

    // Exact fill is ideal.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: strongly reward bins whose post_residual exactly matches next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score += slack * 0.25;
        } else {
            // next item can't use leftover; dead-space penalty grows with gap
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.12;
        }
    }

    // Last chance: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        let waste = post_residual as f64;
        let bonus = 70.0 - 0.35 * waste;
        score -= bonus.max(0.0);
    }

    // New-bin candidate: penalize opening a new bin unless current item is large
    // and stream is early (leaves a versatile big residual).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let item_frac = item_size as f64 / cap;
        let mut new_bin_score = 55.0 + 40.0 * progress; // later => more costly to open
        new_bin_score -= 30.0 * item_frac;             // big items justify fresh bins
        if next_item_size > 0 && next_item_size >= post_residual.max(1) {
            new_bin_score -= 10.0; // fresh bin can host next item too
        }
        score = score.max(0.0) + new_bin_score;
    }

    // Global pressure: many open bins with high mean residual => prefer reusing
    // bins with below-average residual (consolidate).
    if bin_residual != bin_capacity {
        let dev = bin_residual as f64 - mean_residual;
        score += 0.08 * dev;
        if open_bins_count > 8 {
            score += 0.05 * dev;
        }
    }

    // Late in stream: be greedy, minimize post residual harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.25 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_pr = pr / cap;

    // Base: minimize post residual (tight packing)
    let mut score = pr as f64;

    // Non-linear penalty for residual that is too small to be useful later:
    // dead-space term grows quadratically as residual shrinks below typical item size
    let dead = if pr > 0 { (1.0 - norm_pr) * norm_pr } else { 0.0 };
    score += 8.0 * dead * dead;

    // Reward tight fits more aggressively via cubic coupling with stream progress:
    // later in the stream, tight fits matter more
    score -= (1.0 - norm_pr).powi(3) * (10.0 + 20.0 * progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Lookahead coupling: if next item fits in post residual, reward
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 6.0 * (1.0 - (next_item_size as f64) / cap);
    } else if next_item_size > 0 {
        // penalize leaving residual that blocks the next item
        score += 3.0 * (next_item_size as f64 - pr) / cap;
    }

    // Mild penalty when bin is far below mean residual (keeps spread balanced)
    score += 0.05 * ((mean_residual - pr).abs() / cap);

    // New-bin candidate (empty bin): neutral-ish but slightly penalized so it
    // only wins when open bins are genuinely poor fits
    if bin_residual == bin_capacity {
        score += 12.0 - 8.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how "wasted" is the leftover?
    // Residuals that are exact capacity fractions (e.g. 0, 25, 50, 75) are more reusable.
    let pr = post_residual;
    let harmonic_bonus: f64 = if pr == 0 {
        -60.0 // perfect fit, huge reward
    } else if pr % 10 == 0 {
        -12.0 // multiple of 10: likely reusable by future items
    } else if pr % 5 == 0 {
        -5.0
    } else {
        8.0 // awkward residual, penalize
    };
    score += harmonic_bonus;

    // Dead space: small post_residual but nonzero is nearly unusable
    if pr > 0 && pr < 10 {
        score += 25.0;
    }

    // Lookahead coupling: does next item fit in post_residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // next item chains perfectly into this bin
            let tightness = (pr - next_item_size) as f64;
            score -= 20.0 - 0.2 * tightness; // reward chain, more if tight
            if pr == next_item_size {
                score -= 30.0; // exact two-item fill
            }
        } else {
            // next item cannot use this residual: penalize proportional to gap
            score += 0.3 * (next_item_size - pr) as f64;
            // harmonic class mismatch: next_item_size % 10 vs pr % 10
            if pr % 10 != 0 && (next_item_size % 10) > (pr % 10) {
                score += 6.0;
            }
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Tightness of current fit: reward small waste relative to item
    let waste_ratio = post_residual as f64 / cap;
    score += 15.0 * waste_ratio;

    // Prefer filling nearly-full bins over fresh ones when many bins are open
    if open_bins_count > 3 {
        let fill_frac = (bin_capacity - bin_residual) as f64 / cap;
        score -= 10.0 * fill_frac;
    }

    // New-bin candidate: make it moderately attractive only when residuals are bad
    if bin_residual == bin_capacity {
        let mean_badness = (mean_residual - cap * 0.5).max(0.0);
        score = 40.0 + mean_badness * 0.5;
        if fitting_bins_count == 0 {
            score -= 50.0; // nothing else fits: new bin is right
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // big items coming: fresh capacity useful
        }
    }

    // Mild stream-phase modulation: later in stream, consolidate harder
    let phase = step_index as f64 / (total_items.max(1) as f64);
    score -= 8.0 * phase * (1.0 - waste_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small gaps (< 10, or below min item size) are unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 30.0;
    }

    // Penalize medium dead space that is unlikely to be filled by typical items.
    if post_residual > 0 && post_residual < 20 {
        score += (20 - post_residual) as f64 * 1.5;
    }

    // Tight-fit reward: fraction of bin consumed by this placement.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= fill * 10.0;

    // Lookahead: if next item fits into post_residual, reward leaving that space.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }
    // If next item almost fits (small shortfall), slight penalty for wasting space.
    if next_item_size > post_residual && next_item_size - post_residual <= 5 && post_residual > 0 {
        score += 6.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage opening new bins when many are open and healthy.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure from open bins.
        score += 15.0 + open_bins_count as f64 * 2.0;
        // If mean residual across open bins is large, opening new bin is wasteful.
        score += mean_residual * 0.3;
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    } else {
        // Favor filling existing bins more as they accumulate.
        score -= open_bins_count as f64 * 0.5;
    }

    // Slight preference for bins with lower residual among comparable options.
    score += (bin_residual as f64 - post_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact 2-step match: post_residual equals next item size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 * (1.0 - diff / (bin_capacity as f64)) * (diff / (bin_capacity as f64)).exp();
    }

    // Penalize large dead space relative to mean residual (wasteful fit).
    let mean_r = if mean_residual > 0.0 { mean_residual } else { bin_capacity as f64 };
    if (post_residual as f64) > mean_r * 0.5 {
        score += 0.4 * (post_residual as f64 - mean_r * 0.5);
    }

    // Reward tight fits (small post residual) with mild nonlinearity.
    score -= 20.0 * (-post_residual as f64 / 20.0).exp();

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fits are all poor.
    if bin_residual == bin_capacity {
        let poor_fit = (post_residual as f64) > bin_capacity as f64 * 0.45;
        if poor_fit {
            score -= 5.0; // allow new bin when fit would leave big dead space
        } else {
            score += 15.0; // discourage opening new bin when a decent fit exists
        }
    }

    // Mild progression-aware tightening: later in stream, favor tighter packing.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize dead space non-linearly: small residuals are hard to fill later.
    if post_residual > 0 {
        score += 40.0 / (post_residual as f64).powf(1.3);
    } else {
        score -= 15.0; // perfect fit reward
    }

    // Tight-fill reward: item occupies most of the bin.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 12.0 * fill_ratio * fill_ratio;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // Mild competition normalization: prefer bins only this item fits well.
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 * (next_item_size as f64 / bin_capacity as f64);
        } else {
            score += 5.0; // creates likely dead space for the known next item
        }
    }

    // Time horizon: early in the stream, keep bins flexible; late, pack greedily.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Global state: many open bins -> encourage consolidation into existing bins.
    score += 1.5 * (open_bins_count as f64).ln().max(0.0);

    // Prefer bins with residuals near mean (keeps bin states balanced) unless last chance.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // New-bin candidate: make empty bins moderately attractive only when nothing fits well.
    if bin_residual == bin_capacity {
        let waste_threshold = bin_capacity as f64 * 0.35;
        if item_size as f64 > waste_threshold || (next_item_size > 0 && next_item_size as f64 + item_size as f64 > bin_capacity as f64) {
            score -= 20.0; // opening fresh is fine for big items
        } else {
            score += 30.0; // discourage wasteful new bins for small items
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits, with non-linear (quadratic) coupling to progress.
    let mut score = pr * (1.0 + 0.8 * progress * norm_pr);

    // Late in stream, dead space matters more: cubic-ish penalty on large residuals.
    score += 12.0 * progress * norm_pr * norm_pr;

    // Last-chance bonus: strongly favor the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    }

    // Reward bins whose residual is below the mean (already well-utilized).
    score -= 4.0 * (mean_residual - pr) / cap;

    // Lookahead: if next item would fit the post-residual, reward this placement.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 8.0 * (1.0 - progress);
    } else if next_item_size > 0 {
        score += 3.0 * progress;
    }

    // Mild penalty for opening new bins when many bins are open late in the stream.
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * progress * (open_bins_count as f64).ln().max(0.0);
        // But allow new bin if residual would be very small elsewhere anyway.
        score -= 6.0 * (1.0 - norm_pr);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is ideal
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: prefer residuals that are "useful" for
    // future items. Classify via modulo against common size divisors.
    let pr = post_residual;
    let useful = |r: u32| -> f64 {
        let mut v = 0.0;
        // residuals divisible by 10/20/25/50 are easier to fill exactly
        if r % 10 == 0 { v -= 6.0; }
        if r % 20 == 0 { v -= 4.0; }
        if r % 25 == 0 { v -= 3.0; }
        if r % 50 == 0 { v -= 4.0; }
        // small residuals are near-dead space unless zero
        if r > 0 && r < 10 { v += 25.0; }
        if r >= 10 && r < 20 { v += 8.0; }
        v
    };
    score += useful(pr);

    // Lookahead coupling: reward residuals that can host the next item exactly
    if next_item_size > 0 {
        if pr >= next_item_size {
            let slack = pr - next_item_size;
            if slack == 0 {
                score -= 120.0; // chains a perfect fit for the next item
            } else {
                score -= 15.0 * (1.0 - slack as f64 / bin_capacity as f64);
                score += useful(slack) * 0.5;
            }
        } else {
            // next item cannot fit here; penalize slightly less if residual small
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: penalize opening a bin unless current bin would leave bad space
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        // open new bin when existing residuals are large (fragmented) or few bins fit
        score += 40.0;
        if pressure > 0.4 { score -= 20.0 * (pressure - 0.4); }
        if fitting_bins_count <= 1 { score -= 30.0; }
        if next_item_size > 0 && next_item_size >= item_size && next_item_size <= bin_capacity {
            score -= 5.0;
        }
    }

    // Mild preference to consolidate into fewer bins as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 3.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Tie-break: prefer bins with larger current residual (tighter fill)
    score -= 0.01 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual gap is "dead" if it's smaller than the smallest plausible item (<=10)
    // or too small to be useful for the lookahead item.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // dead space penalty
    }

    // Reward near-perfect fits (post_residual close to 0 but usable).
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly reward this placement (chained fit).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 15.0 * (1.0 - slack / bin_capacity as f64);
    }
    // If next item cannot fit into post_residual, the gap may become dead space
    // unless it is large enough for other future items; mildly penalize small gaps.
    if next_item_size > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new bins
    // (make empty-bin candidate less attractive) and encourage consolidation.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to open bins and progress.
        score += 20.0 + 3.0 * open_bins_count as f64 + 30.0 * progress;
        // But if no open bin fits well (large post_residual elsewhere), allow new bin:
        // handled implicitly since fitting bins with bad gaps get penalized above.
        if open_bins_count == 0 {
            score -= 100.0; // must open a bin
        }
    } else {
        // Consolidation reward: prefer bins with below-mean residual (tighter bins),
        // keeping high-residual bins flexible.
        let dev = mean_residual - bin_residual as f64;
        score -= 0.3 * dev;
        // Mild pressure to use existing bins when many are open.
        score -= 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose leftover can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let tightness = (post_residual - next_item_size) as f64;
        score -= 30.0 + 0.5 * tightness;
        if tightness == 0.0 {
            score -= 25.0; // perfect 2-step match
        }
    } else if next_item_size > 0 {
        // Dead space relative to the upcoming item
        score += 0.3 * (next_item_size - post_residual) as f64;
    }

    // Reward tight fits now
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 20.0 * fit_ratio;

    // Penalize large leftovers that likely become dead space
    if post_residual > 50 {
        score += 0.4 * (post_residual - 50) as f64;
    }

    // Last-chance bin before opening a new one
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate: prefer it only when it enables the next item too
    if bin_residual == bin_capacity {
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 35.0;
        } else {
            score += 12.0 + 0.2 * mean_residual;
        }
    }

    // Context coupling: late in stream, consolidate into existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 8.0 * progress * (open_bins_count as f64 / (mean_residual.max(1.0) / 10.0).max(1.0)).min(5.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Primary fit term: squared post-residual to strongly prefer tight fits.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64 * 2.0);

    // Lookahead: penalize dead space that cannot host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward residuals that remain usable for the lookahead item.
            score -= ((post_residual - next_item_size) as f64).min(30.0) * 0.3;
        } else {
            // Dead space for next item: penalize proportionally to waste.
            let waste = post_residual as f64;
            score += waste * 0.8;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 40.0;
    } else if fitting_bins_count > 1 {
        // Mild tie-breaking among several fitting bins via residual tightness.
        score += (fitting_bins_count as f64 - 1.0) * 1.5;
    }

    // Global state coupling: when mean residual across open bins is low,
    // packing tightly matters more; when it's high, prefer spreading load.
    let tightness = 1.0 - (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
    score += tightness * (post_residual as f64) * 0.5;

    // Time horizon: early in the stream, be more willing to open new bins
    // (keep bins flexible); late in the stream, fill existing bins aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 8.0 * (bin_residual as f64 / bin_capacity as f64);

    // New-bin candidate: penalize opening a fresh bin unless the item fits poorly
    // everywhere (handled by last-chance bonus and dead-space penalties).
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 > 40.0 && fitting_bins_count >= 1;
        score += if poor_fit { 60.0 } else { 25.0 };
        // Late stream: opening new bins is less attractive.
        score += progress * 15.0;
    }

    // Small penalty for many open bins to encourage consolidation.
    score += open_bins_count as f64 * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let post_norm = post / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on: prefer tight fills (low post_residual). Later: tolerate slack.
    let t = progress;
    let poly = 1.0 - 1.4 * t + 0.6 * t * t; // smooth decay in [~0.2, 1.0]

    let mut score = post * poly;

    // Quadratic penalty on very small residuals (dead space), smoothed by progress.
    let dead = (cap * 0.15 - post).max(0.0);
    score += dead * dead / (cap * 0.05) * (1.0 - 0.5 * t);

    // Last-chance bonus: only fitting bin -> strong reward.
    if fitting_bins_count == 1 {
        score -= 30.0 + 20.0 * t;
    }

    // Reward bins below mean residual (tighter bins), smooth coupling.
    score -= 0.3 * (mean_residual - post) * (1.0 - t);

    // Lookahead: if next item fits exactly into post_residual, reward.
    if next_item_size > 0 && (post_residual as u32) == next_item_size {
        score -= 25.0;
    } else if next_item_size > 0 && (next_item_size as f64) <= post {
        score -= 8.0 * (post - next_item_size as f64) / cap;
    }

    // Mild pressure to consolidate when many bins are open.
    score += 0.05 * open_bins_count as f64 * post_norm * (1.0 - t);

    // New-bin candidate: penalize opening fresh bin unless residuals are all tiny.
    if bin_residual == bin_capacity {
        let tight = (mean_residual / cap).max(0.0);
        score += 12.0 * (1.0 - tight) + 10.0 * (1.0 - t);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: capacity divided into 5 classes of 20 units.
    let class = post_residual / 20; // 0..=5 for capacity 100
    // Dead-space penalty: leftover in the lowest class (1..=19) is nearly unusable.
    if post_residual > 0 && post_residual < 20 {
        score += 25.0;
    } else {
        // Reward leftovers that are multiples of 10 (align with common item sizes).
        if post_residual % 10 == 0 && post_residual > 0 {
            score -= 6.0;
        }
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead harmony: does the leftover match the next item's size class?
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 18.0;
        } else if post_residual >= next_item_size {
            // leftover can host next item: mild reward scaled by leftover quality
            score -= 4.0 + (20 - (post_residual - next_item_size).min(20)) as f64 * 0.15;
        } else {
            // leftover cannot host next item: penalize more if gap is small (wasted)
            let gap = next_item_size - post_residual;
            score += (gap as f64) * 0.5;
        }
        // Modulo coupling: leftover and next item sharing a harmonic class (same /20 bucket)
        if post_residual / 20 == (next_item_size as u32) / 20 {
            score -= 3.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: only attractive when current bins are crowded or fit is bad.
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64) * (mean_residual / bin_capacity as f64);
        score = 55.0 + score * 0.5 - pressure * 4.0;
        // discourage opening new bin early in the stream
        score += (step_index as f64 / (total_items.max(1) as f64)) * 10.0;
    }

    // Tightness coupling: prefer bins where item fills a large fraction of residual.
    let fill_frac = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_frac * 8.0;

    // Small global regularization toward bins with low residual (best-fit bias).
    score += (bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64) / 10.0;
    }
    if post_residual >= 10 && post_residual < 20 {
        score += 8.0; // medium-risk gap
    }

    // Reward tight fits (exact fill is ideal).
    if post_residual == 0 {
        score -= 40.0;
    } else {
        let fit_ratio = item_size as f64 / bin_residual as f64;
        score -= 20.0 * fit_ratio; // prefer bins where item fills most of the residual
    }

    // Dead space is worse if the next item can't use it.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0;
    }
    // Bonus if post residual exactly accommodates the lookahead item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 15.0;
    }

    // Last-chance bin: strong preference to use it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: discourage opening new bins when many are open,
    // encourage consolidation when few bins are open.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportional to open bins and stream progress.
        score += 15.0 + 2.0 * open_bins_count as f64 + 10.0 * (step_index as f64 / total_items.max(1) as f64);
    } else {
        score -= 1.5 * open_bins_count as f64;
        // Prefer bins with residual below the mean (consolidate fuller bins).
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        } else {
            score += 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item exactly
    if next_item_size > 0 {
        let nr = next_item_size as f64;
        let pr = post_residual as f64;
        let diff = (pr - nr).abs();
        if diff == 0.0 {
            score -= 500.0; // next item fills this bin perfectly
        } else if pr >= nr {
            score -= 150.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // next item cannot fit: dead space penalty scaled by wasted amount
            score += 0.5 * diff;
        }

        // Chain fit: item + next item together
        if (item_size + next_item_size) == bin_capacity && bin_residual == bin_capacity {
            score -= 400.0;
        }
    } else {
        // Last item: prefer minimal residual
        score += 0.2 * post_residual as f64;
    }

    // Relative-to-mean coupling: bins with residual below mean are "tighter" fits
    let residual_f = bin_residual as f64;
    let mean_gap = residual_f - mean_residual;
    score += 0.3 * mean_gap;

    // Penalize wasting large residuals on small items (dead space creation)
    let fill_ratio = item_size as f64 / residual_f.max(1.0);
    if fill_ratio < 0.35 {
        score += 40.0 * (0.35 - fill_ratio);
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: penalize opening a new bin unless current item is large
    // and no open bin is a good fit
    if bin_residual == bin_capacity {
        let base_penalty = 60.0;
        let lookahead_bonus = if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            80.0 // pair packing in fresh bin is attractive
        } else {
            0.0
        };
        let scarcity_bonus = if fitting_bins_count == 0 { 200.0 } else { 0.0 };
        score += base_penalty + lookahead_bonus + scarcity_bonus;
    }

    // Mild late-stream consolidation: as stream ends, avoid leaving many tiny residuals
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 0.1 * post_residual as f64;

    // Encourage spreading when many open bins have high mean residual (fragmentation control)
    if open_bins_count > 4 && mean_residual > 50.0 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) more aggressively than linear.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness * (item_size as f64 / 100.0);

    // Penalize dead space: residuals too small for any plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Lookahead: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size {
            score -= 6.0 * (next_item_size as f64 / 100.0);
        } else {
            // next item won't fit here; slight penalty for blocking
            score += 2.0;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Time horizon: early in the stream, be more willing to open new bins
    // (keep flexibility); late in the stream, pack tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * tightness;

    // Global state: many open bins with high mean residual -> prefer
    // consolidating into existing bins rather than opening new ones.
    let pressure = mean_residual / (bin_capacity as f64);
    score -= 6.0 * pressure * (open_bins_count as f64).ln().max(1.0);

    // New-bin candidate handling: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        let openness = 1.0 - progress;
        // Favor new bin when existing bins are fragmented (low mean residual)
        // or when item barely fits anywhere.
        let poor_fits = if fitting_bins_count == 0 { 0.0 } else {
            (mean_residual - item_size as f64).max(0.0) / 100.0
        };
        score = 30.0 + 40.0 * openness - 15.0 * poor_fits - 10.0 * pressure;
        if fitting_bins_count == 1 {
            // last chance: discourage opening a new bin
            score += 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let mut score = post_residual as f64;

    // Smooth polynomial coupling: post_residual weighted by stream progress
    let pr = post_residual as f64;
    let pr_norm = pr / bin_capacity as f64;
    score += progress * pr * pr_norm * 2.0;

    // Penalize large dead space more as stream progresses (quadratic coupling)
    let dead = pr_norm * pr_norm;
    score += 30.0 * progress * dead;

    // Reward tight fits: subtract when post_residual is small, more so early
    let tight = 1.0 - pr_norm;
    score -= 20.0 * (1.0 - progress) * tight * tight;

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: penalize mildly, more when many bins are open and residual is usable
    if bin_residual == bin_capacity {
        let usable = if next_item_size > 0 { (next_item_size as f64 / bin_capacity as f64).min(1.0) } else { 0.5 };
        score += 15.0 + 5.0 * (open_bins_count as f64).ln() - 10.0 * usable * (1.0 - progress);
    }

    // Lookahead: reward bins whose post_residual could fit the next item
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 8.0 * (post_residual as f64 - next_item_size as f64 + 1.0) / bin_capacity as f64;
    }

    // Mean-residual coupling: prefer bins deviating below mean residual (keeps diversity)
    score += 3.0 * ((post_residual as f64 - mean_residual) / bin_capacity as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward "nice" residuals that future items
    // (sizes 1..100, unknown distribution) are likely to fill exactly.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Fraction-of-capacity classes: residuals near multiples of small divisors
    // (cap/2, cap/3, cap/4) are highly reusable.
    for d in [2u32, 3, 4, 5] {
        let target = cap / d as f64;
        let dist = (pr - target).abs();
        if dist < 5.0 {
            score -= (5.0 - dist) * (6.0 / d as f64);
        }
    }

    // Integer-division dead-space penalty: residuals in awkward slivers
    // (e.g. 1..10 or 91..99 with typical items) are hard to fill.
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }
    let band = post_residual % 25;
    if band >= 20 {
        score += 3.0; // top-of-quarter sliver penalty
    }

    // Exact-fit harmony: post_residual divisible by common small sizes.
    if post_residual > 0 && (post_residual % 10 == 0) {
        score -= 6.0;
    }
    if post_residual > 0 && post_residual % 5 == 0 {
        score -= 2.0;
    }

    // Lookahead coupling: if next item fits the post residual exactly, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size < post_residual {
            score -= 4.0;
        } else {
            score += 8.0; // next item cannot use this bin's remainder
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when current item is huge and
    // no open bin is a good home; otherwise discourage opening bins.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 15.0 };
        score += pressure + (open_bins_count as f64) * 0.5;
        if item_size >= 70 {
            score -= 10.0;
        }
    }

    // Slight preference for fuller bins as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (cap - pr) * 0.05 * (0.5 + progress);

    // Tie-break toward bins below mean residual (fill laggards).
    score -= (mean_residual - pr) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest item
    // (size 1) are pure waste; residuals below the typical item scale are
    // near-waste. Penalize hard in the "unusable gap" zone.
    if post_residual == 0 {
        score -= 30.0; // perfect fit: ideal
    } else if post_residual < 10 {
        score += (10 - post_residual) as f64 * 6.0; // dead space: strongly penalize
    } else if post_residual < 20 {
        score += 8.0; // marginal gap
    }

    // Reward leaving room for the lookahead item (k=2 lookahead exploitation).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.25 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0; // blocks the next item: bad
    }

    // Last-chance bin: strongly prefer using the only bin that fits,
    // otherwise we must open a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless the
    // fit is genuinely tight.
    score += 0.6 * open_bins_count as f64;

    // Prefer bins tighter than the current mean residual (good packing).
    score += 0.4 * (mean_residual - bin_residual as f64);

    // New-bin candidate handling: only attractive when nothing fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let poor_fit = fitting_bins_count == 0
            || (post_residual < 10 && post_residual > 0)
            || (next_item_size > 0 && bin_residual >= item_size + next_item_size
                && fitting_bins_count > 0
                && mean_residual < item_size as f64);
        if poor_fit {
            score -= 20.0; // opening fresh is better than a bad fit
        } else {
            score += 15.0; // prefer existing bins when fit is decent
        }
    }

    // Slight late-stream tightening: as the stream progresses, favor
    // consolidating into near-full bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_capacity - bin_residual) as f64 * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: prefer tight fits (small post_residual already in base score).

    // Aggressive 2-step lookahead: strongly reward bins whose post_residual
    // can accommodate the next item exactly or well.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack_after_next = post_residual - next_item_size;
        // Exact match is golden.
        if slack_after_next == 0 {
            score -= 60.0;
        } else {
            // Reward proportional to how well next item fills the remainder.
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 40.0 * fill;
            // Penalize leaving a third-level dead space.
            if slack_after_next < 10 {
                score += 15.0;
            }
        }
    } else if next_item_size > 0 {
        // Next item won't fit here after placement: penalize more if the
        // leftover is small and unusable (dead space).
        let dead = post_residual as f64;
        if dead < next_item_size as f64 && dead < 20.0 {
            score += 0.5 * (20.0 - dead);
        }
    }

    // Relative to mean residual: prefer bins that are more filled than average
    // (small residual relative to mean) to consolidate packing.
    score -= 0.3 * (mean_residual - bin_residual as f64);

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 25.0;
        // But if it would strand a large dead space, soften the discount.
        if post_residual < 10 {
            score += 20.0;
        }
    }

    // New-bin candidate handling: an empty bin is only attractive when no open
    // bin offers a good fit. Make the empty bin moderately expensive so open
    // bins with reasonable fits win.
    if bin_residual == bin_capacity {
        score += 30.0;
        // Late in the stream, opening new bins is cheaper (less future waste).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * progress;
        // If next item is large, an empty bin gives flexibility.
        if next_item_size >= 50 {
            score -= 15.0;
        }
    }

    // Mild penalty for many open bins already (encourage consolidation).
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post residual (tightest fit).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score *= 1.0 + 0.5 * fit_ratio * fit_ratio;

    // Lookahead: if the next item fits exactly in the post residual, strongly reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_tightness = next_item_size as f64 / post_residual as f64;
        score -= 8.0 * next_tightness;
    }
    // Penalize leaving a dead space that the next item cannot use.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 3.0 + 0.1 * post_residual as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
    } else if fitting_bins_count > 2 {
        // Many alternatives: mild penalty so tightest alternatives win.
        score += 1.5 * (fitting_bins_count as f64 - 2.0).min(4.0);
    }

    // Time horizon: early in the stream, keep bins flexible (favor larger residuals);
    // late in the stream, fill aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 4.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Global state coupling: if open bins are mostly full (low mean residual),
    // discourage fragmenting the remaining capacity; if mean residual is high,
    // encourage consolidation into existing bins.
    if mean_residual > item_size as f64 {
        score -= 2.0 * (mean_residual - item_size as f64) / bin_capacity as f64;
    } else {
        score += 2.0 * (item_size as f64 - mean_residual) / bin_capacity as f64;
    }

    // New-bin candidate handling: only attractive when it enables a great lookahead
    // pairing or existing bins are very fragmented.
    if bin_residual == bin_capacity {
        let base_penalty = 18.0 + 0.5 * open_bins_count as f64;
        let lookahead_bonus = if next_item_size > 0 && post_residual >= next_item_size {
            6.0 * (next_item_size as f64 / bin_capacity as f64)
        } else {
            0.0
        };
        score = base_penalty - lookahead_bonus + (bin_capacity - post_residual) as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_pr = pr / cap;

    // Base: prefer small post residual (tight fit), with polynomial shaping
    let mut score = pr + 30.0 * norm_pr * norm_pr * cap;

    // Stream-progress coupling: early on, allow loose fits (favor large residuals less strictly);
    // later, penalize wasted space more aggressively via cubic interaction.
    let coupling = norm_pr * norm_pr * (1.0 - progress) * 50.0
                 - norm_pr * progress * progress * 20.0;
    score += coupling;

    // Penalize dead space that cannot fit the next item (lookahead), smooth quadratic
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - pr).max(0.0);
        score += 0.8 * gap * gap / cap;
    }

    // Reward using bins when few can fit (avoid opening new bins unnecessarily)
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else {
        score -= 5.0 * (fitting_bins_count as f64).ln().max(0.0) / (1.0 + open_bins_count as f64).ln();
    }

    // Mild deviation penalty from mean residual: prefer balanced bin usage
    score += 0.1 * (pr - mean_residual).abs();

    // New-bin candidate: penalize so it's chosen only when fits are poor
    if bin_residual == bin_capacity {
        score += 25.0 + 30.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
