pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residual gaps that are too small to be
    // useful (below the minimum plausible item size of 1..10) are heavily
    // penalized; perfect fits are strongly rewarded.
    if post_residual == 0 {
        score -= 60.0; // perfect fit
    } else if post_residual < 10 {
        score += 45.0; // tiny dead space, essentially unusable
    } else if post_residual < 20 {
        score += 15.0; // marginal dead space
    } else if post_residual >= next_item_size && next_item_size > 0 {
        // gap can hold the lookahead item: reward
        score -= 12.0;
    }

    // Reward tight fits relative to the bin residual (small waste ratio).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fit_ratio;

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // over spreading; with few open bins, allow opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).ln().max(0.0) * (0.5 + progress);
    score += pressure;

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Discourage drifting far from mean residual (avoid creating outliers).
    score += 0.15 * (post_residual as f64 - mean_residual).abs();

    // Slight bonus for using existing bins vs. the brand-new empty bin.
    if bin_residual != bin_capacity {
        score -= 5.0;
    } else {
        // New-bin candidate: penalize unless item is large and would leave
        // a big residual anyway.
        score += 8.0 * (1.0 - fit_ratio);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact match: item leaves residual equal to next item -> perfect 2-step chain
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Next item fits into the resulting residual -> good lookahead pairing
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 30.0 - slack * 0.25;
    }

    // Dead space: residual too small for anything (min item assumed ~1..100 unknown,
    // use item_size as a proxy for typical small sizes)
    if next_item_size > 0 && post_residual < next_item_size {
        let waste = post_residual as f64;
        score += (item_size as f64) * 0.3 - waste * 0.2;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Prefer bins tighter than the mean residual (best-fit flavor)
    score -= (mean_residual - bin_residual as f64) * 0.15;

    // Slight preference for filling large items into fuller bins
    score += (item_size as f64 / bin_capacity as f64) * 5.0;

    // Late in the stream, consolidate aggressively
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 8.0;

    // New-bin candidate: penalize mildly so it's chosen only when open bins fit poorly
    if bin_residual == bin_capacity {
        score += 20.0 + open_bins_count as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through stream: early on, prefer tighter fits (small post_residual);
    // later, tolerate some slack to keep bins usable.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Lookahead: if the next item fits into post_residual, reward this bin strongly.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        let combo_waste = post_residual as f64 - next_item_size as f64;
        score -= 18.0 - 0.35 * combo_waste;
    } else if next_item_size > 0 {
        // Next item won't fit here: penalize leaving awkward small residuals.
        let gap = next_item_size as f64 - post_residual as f64;
        if post_residual > 0 && gap < 20.0 {
            score += 6.0 + 0.5 * (20.0 - gap);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 12.0 + 0.15 * (post_residual as f64);
    }

    // Penalize creating dead space: residuals too small to be useful for typical items.
    if post_residual > 0 && post_residual < 10 {
