    // Perfect fit reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Global state coupling: when many bins are open with high mean residual,
    // discourage opening new bins (raise score for the empty-bin candidate).
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        score += 8.0 * pressure + 0.5 * open_bins_count as f64;
        // Early in the stream, new bins are cheaper; later, avoid proliferation.
        score += 10.0 * (1.0 - progress);
    }

    // Slight preference for bins with residual close to item size (snug fits).
    let snug = (bin_residual as f64 - item_size as f64).abs();
    score += 0.08 * snug;

    // Mild time-dependent scaling of overall waste sensitivity.
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: penalize post residual non-linearly
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, prefer filling bins fully (low post_residual); later, tolerate slack
    let coupling = 1.0 + 1.5 * (1.0 - progress) * (1.0 - progress);
    score *= coupling;

    // Reward tight fits via smooth term on item_size relative to residual
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize dead space that cannot fit the next item (smooth quadratic)
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).max(0) as f64;
        let gap_norm = gap / cap;
        score += 20.0 * gap_norm * gap_norm * (0.5 + progress);
    } else {
        // last item: strongly prefer minimal post residual
        score -= 5.0 * (1.0 - norm_pr);
    }

    // Last-chance bonus: only bin that fits -> encourage using it
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - progress);
    }

    // Mild penalty for opening new bins when many are already open and mean residual is high
    let new_bin = if bin_residual == bin_capacity { 1.0 } else { 0.0 };
    let mean_norm = mean_residual / cap;
    score += new_bin * (10.0 + 25.0 * mean_norm * (1.0 - progress));

    // Slight preference for bins with residuals near mean (balance)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 3.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo 10 measure "wasted dead space"
    let res_class = post_residual % 10;
    score += (res_class as f64) * 0.35;

    // Integer-division thresholds: post_residual in low classes is near-dead space
    if post_residual <= 10 {
        score -= 8.0; // perfect closure, excellent
    } else if post_residual <= 20 {
        score -= 4.0;
    } else if post_residual > 50 {
        score += 6.0; // large residual left behind: poor packing
    }

    // Lookahead coupling: can next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // harmonic compatibility: next item slots into leftover
            let compat = (post_residual - next_item_size) as f64;
            score -= 5.0 - compat * 0.05;
        } else {
            score += 2.0;
        }
    }

    // Last-chance bonus: only one bin fits the item
    if fitting_bins_count == 1 {
        score -= 7.0;
    }

    // New-bin candidate handling: empty bin should win only when fits are bad
    if bin_residual == bin_capacity {
        // base penalty so it loses to good fits
        score = 60.0;
        // open a new bin when existing residuals are small / unusable
        if mean_residual < 25.0 {
            score -= 30.0;
        }
        if post_residual <= 10 {
            score -= 10.0;
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score += 5.0; // big item coming, prefer fresh bin
        }
    }

    // Stream progression: late in stream, tighten up, avoid opening bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += progress * 10.0;
    } else {
        score -= progress * 2.0;
    }

    // Many open bins: discourage spreading, prefer filling
    score += (open_bins_count as f64) * 0.4;

    // Deviation from mean residual: prefer bins tighter than average
    score += (bin_residual as f64 - mean_residual) * 0.08;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in (0,10) are nearly unusable
    // for future items (min size 1..100 stream, but small gaps waste capacity).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // heavy penalty for creating tiny dead gaps
    }
    // Perfect fit is strongly rewarded.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward leaving a residual that exactly accommodates the lookahead item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }
    // Penalize residuals that are too small for the next item but nonzero.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    }

    // Open-bin pressure: discourage scattering items across many bins
    // unless the fit is genuinely good.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (2.0 + 3.0 * progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: an empty bin is a fallback; prefer it only
    // when the fit into open bins would be poor (large post_residual).
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, softened late in the stream.
        score = bin_capacity as f64 * 0.5 + open_bins_count as f64 * 2.0 - 20.0 * progress;
        // If it's a perfect fit for the next item too, opening is fine.
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 20.0;
        }
    }

    // Mild tie-breaker: prefer bins whose residual is already small
    // (best-fit flavor beyond raw post_residual).
    score += (mean_residual - bin_residual as f64).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: strongly reward leaving exactly next_item_size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs();
        if diff == 0 {
            score -= 60.0; // perfect chain: item + next item fill this bin
        } else if post_residual >= next_item_size {
            score -= 20.0 - (diff as f64).min(20.0); // next item still fits here
        } else {
