    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let tight_bias = 0.3 + 0.4 * progress;
    score -= (mean_residual - post_residual as f64) * tight_bias;

    // Last-chance bin: avoid opening a new bin if this is the only fitting one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make it unattractive unless current bins are all large-residual
    if bin_residual == bin_capacity {
        score += 45.0 - (mean_residual - item_size as f64).max(0.0) * 0.5;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0; // fresh bin can chain the next item too
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that no plausible future item can use.
    if post_residual > 0 {
        if post_residual < 10 {
