    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance bonus: only one fitting bin; avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Penalize bins far below mean residual (fragmented spread),
    // reward bins near the mean to keep residuals balanced.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Late in the stream, prefer packing existing bins tightly
    // rather than opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 20.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    // Many open bins: discourage new-bin-like behavior (large residual bin chosen less).
    score += 0.5 * (open_bins_count as f64).ln() * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate handling: empty bin gets a moderate default
    // score; only chosen if no open bin scores lower.
    if bin_residual == bin_capacity {
        score += 35.0 + 10.0 * (1.0 - progress);
        if next_item_size > 0 && next_item_size >= bin_capacity - item_size {
            score -= 20.0; // new bin leaves room for a large next item
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let pr = post / cap; // normalized post residual

    // Base: prefer minimal leftover space (best fit core)
    let mut score = post;

    // Smooth non-linear coupling: tight fits (small pr) get extra reward,
    // polynomial in normalized post residual modulated by stream progress.
    let tightness = (1.0 - pr).powi(3);
    score -= 30.0 * tightness * (0.5 + 0.5 * progress);

    // Penalize dead space: residuals too small to plausibly hold future items
    // (items are >= 1, but typical useful space ~ >= 10). Smooth logistic penalty.
    let dead = 1.0 / (1.0 + (post - 12.0).abs().exp().recip() * (post - 12.0).signum());
    score += 25.0 * dead * (1.0 - progress * 0.5);

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    // (mean residual low) or late in stream; smooth interaction.
    if bin_residual == bin_capacity {
        let crowding = 1.0 - (mean_residual / cap).min(1.0);
        score -= 35.0 * crowding * (0.3 + 0.7 * progress);
        score += 20.0 * (mean_residual / cap).min(1.0);
    }

    // Lookahead coupling: if next item fits the post residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= post {
        score -= 12.0 * (1.0 - post / cap);
    } else if next_item_size > 0 {
        score += 6.0 * (1.0 - (next_item_size as f64 - post) / cap).max(0.0);
    }

    // Mild penalty for spreading across many open bins early on
    score += (open_bins_count as f64).ln().max(0.0) * 2.0 * (1.0 - progress);

    // Quadratic smoothing term on post residual to break ties smoothly
    score += 0.05 * post * post / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Capacity fraction of the item relative to bin
    let frac = item_size as f64 / bin_capacity as f64;
