    // Harmonic classes: post_residual mod 10 -> dead-space penalty for awkward remainders
    let class = post_residual % 10;
    let class_penalty = match class {
        0 => -12.0,           // perfectly full: excellent
        1 | 9 => 8.0,         // 1-unit sliver: unusable dead space
        2 | 8 => 5.0,
        3 | 7 => 3.0,
        4 | 6 => 1.5,
        _ => 0.0,             // mod 5: friendly residue
    };
    score += class_penalty;

    // Harmonic subdivision thresholds on post_residual (integer division)
    let quarter = post_residual / (bin_capacity / 4);
    score += match quarter {
        0 => -10.0,  // post_residual < 25: bin nearly saturated, great
        1 => -4.0,
        2 => 2.0,
        3 => 6.0,
        _ => 10.0,   // large leftover
    } as f64;

    // Lookahead coupling: does next item fit harmonically into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let nfrac = next_item_size as f64 / bin_capacity as f64;
            score -= 15.0 * nfrac;
            // bonus if next item leaves a class-0 residue too
            if (post_residual - next_item_size) % 10 == 0 {
                score -= 8.0;
            }
