        score -= 5.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 18.0;
    }

    // Slight preference for bins tighter than the mean residual (best-fit flavor)
    score += 0.05 * (mean_residual - bin_residual as f64);

    // Early in stream: encourage consolidating into few bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * open_bins_count as f64 * 0.3;

    // New-bin candidate: only attractive when nothing fits well
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 25.0 + 10.0 * (fitting_bins_count as f64);
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 20.0; // big next item: fresh bin is valuable
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
