    // with a smooth threshold via sigmoid-like term around mean residual.
    let mean = if mean_residual.is_finite() { mean_residual } else { 0.0 };
    let useless = ((post - mean) / 25.0).tanh();
    score += 0.25 * useless * progress;

    // Lookahead: reward bins whose post_residual can still host the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            score -= 0.5 * (1.0 - (post - nxt) / cap);
        } else {
            score += 0.3 * (nxt - post) / cap;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin, unless post_residual is terrible.
    if fitting_bins_count <= 1 && bin_residual < bin_capacity {
        score -= 0.8;
    }

    // Mild preference for keeping few open bins early, more bins late.
    let openness = open_bins_count as f64;
    score += 0.02 * openness * (1.0 - progress) - 0.01 * openness * progress;

    // New-bin candidate: neutral baseline, slightly discouraged early.
    if bin_residual == bin_capacity {
        score += 0.15 + 0.4 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: prefer residuals that are "friendly"
    // (multiples of 10 or 20), penalize awkward dead space.
    let pr = post_residual;
    if pr > 0 {
        if pr % 20 == 0 {
            score -= 5.0;
        } else if pr % 10 == 0 {
            score -= 3.0;
        }
        // Penalize residuals in awkward bands (1..=9): nearly unusable
        if pr < 10 {
            score += 25.0;
        }
    }

    // Lookahead coupling: if next item fits into post_residual, big reward
    if next_item_size > 0 && next_item_size <= pr {
        score -= 40.0;
        // Harmonic match: next item exactly fills the residual
        if next_item_size == pr {
            score -= 100.0;
        } else if pr % next_item_size == 0 {
            score -= 15.0;
        }
    } else if next_item_size > pr {
        // Next item cannot follow here; slight penalty proportional to gap
        score += 5.0 + ((next_item_size - pr) as f64) * 0.2;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // New-bin candidate handling: only open a new bin when the fit here is bad
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin
        score += 120.0;
        // But if this bin would leave a tiny dead space while the current
        // alternative is terrible, opening is fine (score stays competitive)
        if item_size >= bin_capacity / 2 {
            score -= 40.0;
        }
        // Late in stream, prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * progress;
    }

    // Prefer tighter bins (small residual before placement) slightly
    score += (bin_residual as f64 - item_size as f64) * 0.1;

    // Mild preference for bins below mean residual (balance load)
    score += (mean_residual - post_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * 12.0; // dead space penalty up to ~120
    } else if post_residual == 0 {
        score -= 40.0; // perfect fit strongly rewarded
    }

    // Reward tight fits relative to capacity (waste ratio).
    score += (post_residual as f64 / bin_capacity as f64) * 30.0;

    // Open-bin pressure: discourage spreading across many bins, but
    // allow opening new bins when the stream is early / few bins open.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (2.0 + 6.0 * (1.0 - progress));

    // Mean residual coupling: prefer bins whose residual is near the mean
    // (balanced packing), penalize outliers.
    score += (bin_residual as f64 - mean_residual).abs() * 0.5;

    // Last chance: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits in the post residual, reward this bin;
    // otherwise penalize leaving a gap the next item cannot use.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0;
        } else if post_residual > 0 {
            score += (next_item_size as f64 - post_residual as f64).min(20.0) * 1.5;
        }
    }

    // New-bin candidate: only attractive when the item is large and no
    // open bin offers a good fit, or many bins are already strained.
    if bin_residual == bin_capacity {
        let poor_alternatives = (fitting_bins_count == 0) as i32 as f64
            + ((fitting_bins_count == 1) as i32 as f64) * 0.5;
        let large_item = item_size as f64 / bin_capacity as f64;
        score = bin_capacity as f64 - poor_alternatives * 55.0 - large_item * 20.0
            + open_bins_count as f64 * 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post_residual).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= 30.0 * (1.0 - fit_ratio).powi(3);

    // Aggressive 2-step lookahead: exact match of next item into post_residual is excellent.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0; // perfect chaining of two items
        } else if post_residual >= next_item_size {
            // how well the next item fits the remainder
            let next_fit = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - next_fit / bin_capacity as f64);
        } else {
            // next item cannot follow: dead space risk grows with gap
            let gap = (next_item_size - post_residual) as f64;
            score += 0.35 * gap;
        }
        // Bonus if the pair (item, next) nearly fills the bin exactly
        let pair = item_size as f64 + next_item_size as f64;
        if (pair - bin_capacity as f64).abs() <= 2.0 {
            score -= 20.0;
        }
    }

    // Penalize creating unusable slivers relative to smallest item scale.
    if post_residual > 0 && post_residual < 10 {
        score += 18.0;
    }

    // Relative-to-mean coupling: bins below mean residual are "tight" — prefer filling them.
    let dev = bin_residual as f64 - mean_residual;
    score -= 0.25 * dev;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: make it moderately attractive only when current bin would leave
    // large waste and lookahead doesn't chain well.
    if bin_residual == bin_capacity {
        score += 8.0; // slight default penalty; lookahead terms above can still win
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // opening fresh bin good when next item is large
        }
    }

    // Mild pressure against bin sprawl late in the stream.
    score += 0.05 * open_bins_count as f64 * (step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: residuals too small to be useful for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: if the next item fits into post_residual, reward this placement.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0;
        } else {
            // Penalize leaving space that the next item cannot use but is also too large to waste gracefully.
            let wasted_for_next = post_residual.min(next_item_size.saturating_sub(1)) as f64;
            score += 0.15 * wasted_for_next;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits, to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Global pressure: many open bins with low mean residual -> prefer filling existing bins.
    let pressure = mean_residual / (bin_capacity as f64);
    if open_bins_count > 2 {
        score += 10.0 * pressure;
    }

    // Time horizon: late in the stream, consolidate aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 20.0 * progress * tightness;

    // New-bin candidate: make an empty bin moderately attractive only when existing bins fit poorly.
    if bin_residual == bin_capacity {
        score += 18.0 + 8.0 * pressure;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0; // fresh bin can serve the upcoming item too
        }
    }

    // Mild penalty for very loose fits relative to mean residual (keeps bins balanced).
    if (post_residual as f64) > mean_residual + 0.5 * (bin_capacity as f64) {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Normalized stream progress
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let t2 = t * t;
    let t3 = t2 * t;

    // Normalized post-residual
    let r = post_residual as f64 / cap;
    let r2 = r * r;
    let r3 = r2 * r;

    // Non-linear coupling: dead space penalized more as stream progresses
    score += (1.0 + 2.0 * t + 3.0 * t2 + 1.5 * t3) * r2 * cap * 0.3;

    // Reward near-perfect fits with smooth decay
    score -= 12.0 * (-((r * 10.0 - 1.0) * (r * 10.0 - 1.0))).exp() * (1.0 + t);

    // Lookahead synergy: reward if next item fits the post-residual smoothly
    if next_item_size > 0 {
        let gap = (post_residual as f64 - next_item_size as f64).abs();
        score -= 6.0 * (-(gap * gap) / 900.0).exp() * (1.0 - 0.5 * t);
    }

    // Last-chance bonus: prefer using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + 2.0 * t);
    }

    // Slight preference for bins deviating from mean residual (diversity of gaps)
    score += 0.5 * ((post_residual as f64 - mean_residual) / cap).abs() * (1.0 - t);

    // Mild new-bin preference early when mean residual is high (fragmentation risk)
    score += (mean_residual / cap) * 3.0 * (1.0 - t2) * (1.0 - t2);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: capacity divided into octiles.
    let cap = bin_capacity as f64;
    let post_f = post_residual as f64;
    let octile = (post_f / cap * 8.0).floor() as i32; // 0..8

    // Reward residuals that land in "usable" harmonic classes (divisible by common item sizes).
    let usable: [u32; 8] = [0, 10, 20, 25, 33, 50, 66, 100];
    let mut best_align: f64 = 0.0;
    for &u in &usable {
        if u <= post_residual {
            let d = (post_residual - u) as f64;
            let a = 1.0 / (1.0 + d);
            if a > best_align { best_align = a; }
        }
    }
    score -= 6.0 * best_align;

    // Penalize dead space: residual below smallest plausible item (1..10 band).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0 * (1.0 - post_f / 10.0);
    }

    // Modulo coupling: if post_residual % 10 == 0, it's a clean slot for grid-like streams.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 4.0;
    }

    // Lookahead: reward when next item fits exactly into post_residual (perfect chain).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 15.0;
        } else if next_item_size < post_residual {
            let chain_waste = (post_residual - next_item_size) as f64;
            score += 0.3 * chain_waste;
        } else {
            // Next item cannot use this residual at all -> residual is likely dead.
            score += 2.0 + 0.05 * (next_item_size - post_residual) as f64;
        }
    }

    // Integer-division threshold on post_residual / capacity fraction.
    if octile <= 1 && post_residual > 0 {
        score += 5.0; // tiny slivers are nearly useless
    } else if octile >= 5 {
        score -= 3.0; // roomy residuals are valuable
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: penalize mildly so we only open when open bins are truly bad,
    // but relax as stream progresses and open bins crowd with high mean residual.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowding = (mean_residual / cap - 0.5).max(0.0);
        score += 8.0 - 6.0 * progress - 10.0 * crowding;
        if post_residual % 25 == 0 {
            score -= 3.0; // fresh full bin is a clean harmonic slate
        }
    }

    // Mild preference to fill fuller (tighter) bins among open ones.
    score -= 0.02 * (bin_capacity.saturating_sub(bin_residual)) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable dead space: small gaps below the minimum item size
    let dead = if post_residual > 0 && post_residual < 10 { 60.0 } else if post_residual == 0 { -40.0 } else { 0.0 };
    score += dead;

    // Exact fits are strongly rewarded
    if post_residual == 0 {
        score -= 25.0;
    }

    // Penalize gaps that cannot fit the lookahead item
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 18.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Pressure from number of open bins
    score += open_bins_count as f64 * 1.5;

    // Progression: late in the stream, prefer tighter packing
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 8.0;

    // Prefer bins with residuals close to item_size (tight fit)
    score += ((bin_residual as f64 - item_size as f64) / bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when the next item fits the post residual exactly.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let slack = (post_residual as f64 - next).abs();
        // Perfect match bonus (post residual exactly fits next item)
        if post_residual as f64 == next {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // next item fits after placement: mild reward proportional to tightness
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot use leftover: penalize dead space creation
            score += 15.0 + 0.3 * (post_residual as f64);
        }
        // Extra reward if post residual tightly matches next item relative to mean residual
        score -= 10.0 * (1.0 - slack / (mean_residual + 1.0));
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize creating very small unusable residuals (dead space < typical min item)
    if post_residual < 10 && post_residual > 0 {
        score += 20.0;
    }

    // Perfect fill reward
    if post_residual == 0 {
        score -= 30.0;
    }

    // New-bin candidate: keep it neutral-ish, only attractive when current bins are fragmented
    if bin_residual == bin_capacity {
        // discourage opening a new bin unless open bins are crowded
        score += 10.0 * (open_bins_count as f64).max(0.0).min(20.0);
        if fitting_bins_count > 0 {
            score += 25.0; // existing bins can fit: prefer them over new bin
        }
    }

    // Mild progression bias: later in stream, tighten packing (favor tight fits)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize large post-residuals more aggressively (dead space is superlinear bad)
    if post_residual > 0 {
        score += (post_residual as f64).powf(1.35) * 0.08;
    }

    // Reward tight fits: small post_residual relative to item size
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 12.0;

    // Lookahead coupling: if the next item fits exactly in the post residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            // reward proportional to how well next item uses the leftover
            score -= 10.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // next item won't fit here; penalize leaving awkward gaps
            score += 4.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: neutral-ish baseline, but discourage opening new bins
    // when existing bins fit reasonably well (fit_ratio > 0.7)
    if bin_residual == bin_capacity {
        score += 18.0;
        if fit_ratio <= 1.0 && item_size as f64 / bin_capacity as f64 > 0.7 {
            score -= 10.0; // big items are fine in a fresh bin
        }
        // late in stream, opening bins is less costly
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 6.0;
    }

    // Global state: many open bins with high mean residual -> prefer consolidating
    // into existing bins to avoid bin sprawl
    if open_bins_count > 2 {
        let sprawl = (open_bins_count as f64).ln() * (mean_residual / bin_capacity as f64);
        score += sprawl * 3.0;
        score -= 3.0; // net bias toward using existing bins when they exist
    }

    // Prefer bins whose residual is close to the mean (keep residuals balanced)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Time horizon: early in the stream, be more selective (penalize mediocre fits);
    // late in the stream, just fill anything available
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * fit_ratio * 5.0;

    // Small bonus for leaving residuals that are common "waste-friendly" sizes
    if post_residual <= 10 {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let p2 = progress * progress;
    let p3 = p2 * progress;
    score += 40.0 * norm_pr * norm_pr * (0.5 + p2);
    score -= 25.0 * norm_item * (1.0 - progress) * (1.0 + p3);

    // Penalize near-full waste growing with progress
    score += 60.0 * norm_pr * norm_pr * norm_pr * p2;

    // Lookahead: reward leaving room for the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let diff = norm_pr - nx;
        let diff2 = diff * diff;
        score -= 30.0 * (1.0 - diff2.min(1.0)) * (1.0 - progress);
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 20.0 * (1.0 - norm_pr * norm_pr);
    }

    // Mild pressure to prefer tighter bins when many bins are open
    score += 0.5 * (open_bins_count as f64) * norm_pr;
    score -= 10.0 * (mean_residual / cap - norm_pr).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues modulo small divisors
    // reveal "nice" leftover sizes that pair well with common item sizes.
    let pr = post_residual;
    let r4 = (pr % 4) as f64;
    let r5 = (pr % 5) as f64;
    let r10 = (pr % 10) as f64;
    let r20 = (pr % 20) as f64;

    // Penalize awkward residues (dead space unlikely to be filled exactly).
    score += 0.6 * r4 + 0.8 * r5 + 1.0 * r10 + 0.5 * r20;

    // Reward exact fits and near-perfect harmonic alignment.
    if pr == 0 {
        score -= 50.0;
    } else if pr % 10 == 0 {
        score -= 6.0;
    } else if pr % 5 == 0 {
        score -= 3.0;
    }

    // Integer-division thresholds: how many "next items" fit the leftover.
    if next_item_size > 0 {
        let fits_next = pr / next_item_size;
        if fits_next >= 1 {
            score -= 4.0 * fits_next as f64;
        }
        // Perfect pairing: leftover exactly matches next item size.
        if pr == next_item_size {
            score -= 12.0;
        }
        // Leftover slightly above next item: small dead space risk.
        if pr > next_item_size && pr - next_item_size < 5 {
            score -= 2.0;
        }
        // Leftover just below next item size: unusable sliver.
        if pr > 0 && pr < next_item_size && pr < 10 {
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when the current item is
    // large and open bins are fragmented (high mean residual spread).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score = (bin_capacity as f64) * 0.5
            + fragmentation * 0.3
            + item_size as f64 * 0.4
            - progress * 10.0
            - (open_bins_count as f64) * 0.5;
        // Large items early: fresh bin gives clean space.
        if item_size >= 60 {
            score -= 8.0;
        }
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 5.0; // fresh bin can host current + next item together
        }
    }

    // Mild preference for tighter bins overall (low residual = well-packed).
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // Small global pressure to prefer existing bins as stream progresses.
    score += progress * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 12.0;
    } else {
        // Larger leftovers are more reusable; mildly reward them.
        score -= 5.0;
    }

    // Reward tight fits (item fills most of the bin).
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 25.0 * fill_ratio * fill_ratio;

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage opening another;
    // make the new-bin candidate (bin_residual == bin_capacity) less attractive.
    if bin_residual == bin_capacity {
        score += 15.0 + 2.0 * open_bins_count as f64;
        // If the next item could use the fresh bin well, soften the penalty.
        if next_item_size > 0 && next_item_size as f64 >= 0.5 * bin_capacity as f64 {
            score -= 20.0;
        }
    }

    // Mean residual coupling: prefer bins whose residual is below the mean
    // (consolidate space into few bins, keep average slack large).
    score -= 0.3 * (mean_residual - bin_residual as f64);

    // Lookahead: if next item fits the post-residual exactly, reward it.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Dead space for the known next item: penalize proportionally.
        score += 0.2 * (next_item_size - post_residual) as f64;
    }

    // Early in the stream, allow slightly more freedom to open bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * (1.0 - progress) * (bin_residual == bin_capacity) as i32 as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: small post_residual is good (already implicit), amplify it.
    if post_residual == 0 {
        score -= 60.0; // perfect fit, best possible outcome
    } else if post_residual < 10 {
        score -= 30.0; // near-perfect fit, dead space is negligible
    } else if post_residual > 50 {
        score += 15.0; // creates large awkward gap; better to leave bin for small items
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item well.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0; // chain of perfect fits
        } else if next_item_size < post_residual {
            let next_post = post_residual - next_item_size;
            if next_post < 10 {
                score -= 25.0; // next item nearly fills this bin too
            } else {
                score -= 8.0; // next item fits, mild bonus
            }
        } else {
            // next item won't fit here; penalize proportionally to how wasteful the gap is
            let gap = post_residual as f64;
            let next = next_item_size as f64;
            score += 5.0 + 0.3 * (gap / (next + 1.0)) * gap.min(40.0) * 0.1;
        }
    }

    // Compare against mean residual: prefer bins that are already relatively full
    // (small residual) so we consolidate waste into few bins.
    score += 0.15 * ((bin_residual as f64) - mean_residual).max(-50.0).min(50.0);

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin should only win when the item
    // fits poorly everywhere else. Penalize new bins unless it's early in the
    // stream or item is large.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let large_item = (item_size as f64) > 0.7 * (bin_capacity as f64);
        score += 25.0 - 15.0 * progress;
        if large_item {
            score -= 20.0; // big items deserve fresh bins
        }
        if post_residual < 20 {
            score -= 10.0; // a fresh bin hosting a large item still leaves usable space
        }
        // If many bins are open, discourage spreading further.
        score += 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post-residual is good.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += fit_ratio * fit_ratio * 40.0;

    // Penalize leaving dead space that cannot fit typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0; // tiny unusable sliver
    }

    // Lookahead: if the next item fits exactly in the post-residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= (next_item_size as f64 / post_residual as f64) * 10.0;
        } else {
            // Next item won't fit here; mild penalty proportional to waste.
            score += (next_item_size as f64 - post_residual as f64) * 0.15;
        }
    }

    // Last chance: if this is the only bin that can fit the item, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // the current placement would waste a lot or the stream is early.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Waste of capacity by placing item in fresh bin.
        let waste = (bin_capacity - item_size) as f64;
        score += waste * 0.8;
        // Early in the stream, new bins are cheaper; later, prefer consolidation.
        score += (1.0 - progress) * 10.0 - progress * 15.0;
        // If many open bins already, discourage spreading.
        score += open_bins_count as f64 * 2.0;
        // If item is large, a fresh bin is natural.
        if item_size >= bin_capacity * 3 / 4 {
            score -= 20.0;
        }
    }

    // Prefer bins whose residual is below the mean residual (consolidating emptier space first
    // keeps fuller bins available for large items).
    let diff = mean_residual - bin_residual as f64;
    if diff > 0.0 {
        score -= diff * 0.3;
    } else {
        score += (-diff) * 0.1;
    }

    // Mild penalty for very full open bins count to encourage reuse over sprawl.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit = pr / cap;

    // Base: prefer tight fits, with a non-linear polynomial penalty on slack.
    let mut score = pr * (1.0 + 2.0 * fit * fit);

    // Smooth coupling of post-residual with stream progress:
    // early on, waste is cheaper; late, dead space is heavily penalized.
    let late = progress * progress * (3.0 - 2.0 * progress);
    score += 40.0 * late * fit * (1.0 - fit);

    // Penalize slack that cannot fit the next item (smooth interaction).
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - pr).max(0.0) / cap;
        score += 25.0 * gap * gap * (0.5 + late);
    } else {
        score += 10.0 * fit;
    }

    // Reward using the last fitting bin (avoid opening a new bin needlessly).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 * (1.0 - fit);
    }

    // Slight pressure to consolidate when many bins are open.
    score += 0.05 * open_bins_count as f64 * fit;

    // New-bin candidate: keep it neutral-ish, only attractive when current
    // bin residuals are poor (large mean residual spread vs item).
    if bin_residual == bin_capacity {
        score = 0.5 * cap + 0.3 * mean_residual - 10.0 * late;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues mod common divisors (10, 25, 50)
    let r = post_residual;
    let res10 = (r % 10) as f64;
    let res25 = (r % 25) as f64;
    let res50 = (r % 50) as f64;

    // Penalize "odd" residuals that are hard to fill by typical item sizes (multiples of 5/10)
    score += (res10 * 0.8) + (res25 * 0.4) + (res50 * 0.3);

    // Perfect-fit classes are gold: residual exactly 0 or a multiple of 10/25
    if r == 0 {
        score -= 40.0;
    } else if r % 10 == 0 {
        score -= 8.0;
    } else if r % 5 == 0 {
        score -= 3.0;
    }

    // Dead-space thresholds via integer division: residuals in (0,10) are near-unusable
    if r > 0 && r < 10 {
        score += 25.0;
    } else if r >= 10 && r < 20 {
        score += 6.0;
    }

    // Lookahead coupling: does post_residual class fit the next item's class?
    if next_item_size > 0 {
        if r >= next_item_size {
            // next item still fits: reward, especially when the pair nearly exhausts the bin
            let pair = item_size + next_item_size;
            if pair == bin_residual {
                score -= 30.0;
            } else {
                score -= 6.0;
            }
        } else {
            // next item won't fit here: penalize unless residual is tiny (already committed)
            if r >= 10 {
                score += (next_item_size as f64 - r as f64).max(0.0) * 0.5;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when current item is huge and no good fit exists,
    // or late in the stream where consolidation matters less
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let tight_fit_exists = fitting_bins_count > 0 && (bin_residual - item_size) < (bin_capacity / 4);
        if tight_fit_exists || next_item_size == 0 {
            score += 20.0;
        } else if item_size >= bin_capacity / 2 && progress > 0.3 {
            score -= 5.0;
        } else {
            score += 10.0;
        }
    }

    // Mean-residual pressure: when open bins are collectively full, discourage spreading
    if mean_residual < 15.0 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the minimum item (1..=10)
    // are pure waste. Penalize sharply when post_residual is a tiny unusable gap.
    if post_residual > 0 && post_residual < 10 {
        score += 120.0;
    }
    // Gaps in 10..=20 are usable but awkward: mild penalty proportional to waste.
    if post_residual >= 10 && post_residual < 20 {
        score += 0.35 * (post_residual as f64);
    }

    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward tight fits: score close to (residual - item) already favors this,
    // but add extra coupling for high fill ratio.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * fill;

    // Last chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += 0.6 * open_bins_count as f64;

    // New-bin candidate: penalize opening a new bin unless the fit there is
    // genuinely better. Make the new bin look unattractive by default.
    if bin_residual == bin_capacity {
        score += 55.0;
        // But if next item is large and would pair well, soften slightly.
        if next_item_size > 0 && (next_item_size as f64) <= 0.25 * bin_capacity as f64 {
            score -= 10.0;
        }
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size && bin_residual != bin_capacity {
        score -= 18.0;
    }
    // Penalize if post_residual cannot host the next item (likely dead space).
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 0.25 * post_residual as f64;
    }

    // Late in the stream, waste matters less than bin count; tighten pressure.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 8.0 * progress * (1.0 - fill);

    // Mild tie-break toward bins tighter than average.
    score -= 0.1 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Post residual slightly below next item size is dead space for the lookahead.
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.8;
    }
    // Post residual slightly above next item size: near-match reward.
    if next_item_size > 0 && post_residual > next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        if gap <= 10.0 {
            score -= (10.0 - gap) * 1.5;
        }
    }

    // Reward tight fits relative to mean residual.
    if (post_residual as f64) < mean_residual {
        score -= (mean_residual - post_residual as f64) * 0.3;
    } else {
        score += (post_residual as f64 - mean_residual) * 0.3;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New empty bin candidate: penalize unless current bin would leave large waste
    // or the item is huge relative to capacity.
    if bin_residual == bin_capacity {
        let waste = post_residual as f64;
        score += 25.0;
        if item_size > 60 {
            score -= 30.0;
        }
        if next_item_size > 0 && waste > 70.0 {
            score -= 10.0;
        }
    }

    // Penalize leaving tiny unusable residuals (< smallest item ~1..10).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Late in the stream, prefer closing bins tightly (fewer total bins).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core tightness reward: strongly favor small post_residual (good fit).
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score += 40.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Penalize dead space: residual too small to ever hold a typical item (min size 1..100 unknown,
    // use conservative threshold relative to observed item scale).
    let dead_threshold = 10u32.min(item_size);
    if post_residual > 0 && post_residual < dead_threshold {
        score += 50.0;
    }

    // Lookahead coupling: reward bins whose post_residual can host the next item (k=2 lookahead).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 18.0;
        } else {
            // Post residual cannot host next item: mild penalty scaled by wasted gap.
            let gap = (post_residual as f64) / (bin_capacity as f64);
            score += 12.0 * gap;
        }
        // Chain fit: residual can host both remainder and next item tightly.
        if post_residual >= next_item_size && post_residual - next_item_size < 10 {
            score -= 10.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the current item
    // fits poorly everywhere (large item, poor fit) or the fit here leaves large waste.
    let is_new_bin = bin_residual == bin_capacity && bin_capacity == 100;
    if is_new_bin {
        // Base penalty so we prefer existing bins when fit is decent.
        score += 30.0;
        // Reward new bin when item is large and would leave a big unusable remainder elsewhere.
        let frag = post_residual as f64;
        if frag > 0.0 && frag < 25.0 {
            score -= 20.0; // actually a decent fit even in new bin? no: new bin post_residual = 100-item
        }
        // In a new bin, post_residual = 100 - item_size; favor new bin for very large items
        // that would otherwise strand in a nearly-full bin leaving tiny dead space.
        if item_size >= 70 {
            score -= 25.0;
        }
        // Late in stream, consolidation matters more: penalize new bins less when many bins open.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 15.0 * progress * (open_bins_count as f64).ln().max(0.0);
    } else {
        // Existing bin: reward filling fuller bins (large residual used well).
        let fill_ratio = (item_size as f64) / (bin_residual as f64);
        score -= 10.0 * fill_ratio.min(1.0);
    }

    // Global state coupling: when mean residual is high, prefer bins below mean
    // (balance residuals), keeping some bins near-empty for future large items.
    let dev = (bin_residual as f64) - mean_residual;
    score += 0.05 * dev;

    // Slight preference for bins that fit among many (tie-breaking toward emptier bins
    // when several fit): normalize by fitting count.
    if fitting_bins_count > 1 {
        score -= 2.0 / fitting_bins_count as f64;
    }

    // Early-stream exploration: keep residuals flexible early on.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress < 0.2 {
        score += 5.0 * (1.0 - progress / 0.2) * tightness;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let mut score = pr;
    // smooth polynomial coupling of post_residual with stream progress
    score += 12.0 * (pr / cap) * (pr / cap) * (0.5 + progress);
    // reward tight fits, more strongly as stream progresses
    score -= (1.0 - pr / cap) * (1.0 - pr / cap) * (20.0 + 30.0 * progress);
    // penalize near-waste dead space that next item cannot use
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr < nx {
            score += (nx - pr) * (1.0 + progress);
        } else {
            score -= 2.0 * (1.0 - pr / nx).max(0.0);
        }
    }
    // last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 * (1.0 - progress);
    }
    // new-bin candidate: slight penalty early, neutral late
    if bin_residual == bin_capacity {
        score += 8.0 * (1.0 - progress) - 4.0 * progress;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: perfect fit classes get strong rewards
    let pr = post_residual;
    if pr == 0 {
        score -= 1000.0; // perfect fit
    } else if pr <= 5 {
        score -= 200.0;
    } else if pr <= 10 {
        score -= 80.0;
    } else if pr <= 20 {
        score -= 30.0;
    }

    // Modulo-10 dead-space classes: leftovers that are small multiples of 10
    // are more likely reusable by future items (sizes 1..100 often cluster).
    let m = pr % 10;
    if pr > 0 && m == 0 {
        score -= 25.0;
    } else if pr > 0 && m >= 1 && m <= 3 {
        score += 15.0; // awkward sliver
    }

    // Integer-division thresholds: classify post_residual into capacity eighths
    let eighth = (bin_capacity / 8).max(1);
    let tier = pr / eighth;
    score += tier as f64 * 10.0;

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 300.0;
        } else if next_item_size <= pr {
            score -= (pr - next_item_size) as f64 * 2.0;
        } else {
            // next item cannot use this leftover: penalize large leftovers less
            // if they are large enough to matter for many item classes
            score += (pr as f64) * 0.1;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // New-bin candidate handling: prefer existing bins unless this bin is bad
    if bin_residual == bin_capacity {
        // New bin baseline: neutral leftover, slight penalty so decent fits win
        score = cap * 0.5 + 40.0;
        if next_item_size > 0 && next_item_size <= item_size {
            score -= 10.0;
        }
        // Late in stream, opening new bins is less costly
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 20.0;
    }

    // Mild tie-break by mean residual: prefer bins tighter than average
    score -= (mean_residual - post_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Strict dead-space avoidance: gaps too small to hold the smallest
    // plausible item (<= 10) are pure waste -> heavy penalty.
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }
    // Gaps that can only fit tiny items (<= 20) are semi-dead.
    if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Reward tight fits: post_residual near zero is excellent.
    if post_residual == 0 {
        score -= 15.0;
    } else {
        // Fractional tightness reward: smaller relative gap -> more reward.
        score -= 10.0 * (1.0 - post / cap);
    }

    // Perfect-fit bonus when the bin is exactly consumed by a known-size item.
    if post_residual == 0 && item_size as f64 >= 0.5 * cap {
        score -= 10.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 12.0;
    }
    // Penalize if post-residual cannot fit the next item but is large enough
    // to have been useful (wasted opportunity).
    if next_item_size > 0 && post_residual < next_item_size && post_residual >= 20 {
        score += 5.0;
    }

    // Open-bin pressure: discourage scattering items across many bins,
    // but relax pressure late in the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 1.5 * (open_bins_count as f64) * (1.0 - 0.5 * progress);

    // Last-chance bin: strongly favor using the only bin that fits,
    // otherwise a new bin must be opened.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: an empty bin has full residual.
    // Only attractive when open bins are congested (high mean residual usage)
    // or the current fit would be terrible. Otherwise penalize so we reuse bins.
    if bin_residual == bin_capacity {
        let bad_fit = post > 0.45 * cap; // current placement leaves a big gap
        let congested = (mean_residual / cap) < 0.25 && open_bins_count > 0;
        if bad_fit || congested {
            score -= 18.0;
        } else {
            score += 30.0;
        }
        // Late stream: opening bins is fine since bins won't be reused much.
        if progress > 0.8 {
            score -= 10.0;
        }
    }

    // Mild preference for bins below mean residual (keeps balance,
    // preserves larger-gap bins for bigger future items).
    if (bin_residual as f64) > mean_residual && bin_residual < bin_capacity {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < 10 {
        score -= 300.0;
    }

    // 2-step lookahead: reward if next item exactly fills post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 900.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 200.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot fit here; penalize small post_residual dead space
            let dead = post_residual as f64;
            if dead < next_item_size as f64 {
                score += 0.5 * (next_item_size as f64 - dead);
            }
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score += 0.5 * (mean_residual - bin_residual as f64);

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // Penalize opening a new bin when decent fits exist
    if bin_residual == bin_capacity {
        score += 40.0 + 0.3 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size <= bin_residual {
            score -= 25.0; // fresh bin useful for the next item too
        }
    }

    // Late-stream consolidation: prefer filling existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize relative waste quadratically.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 6.0 * fit_ratio * fit_ratio * bin_residual as f64;

    // Perfect fit is highly desirable.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Penalize small dead space that no future item (min size 1..10) can use.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // Next item still fits: mild reward proportional to leftover usefulness.
            score -= 8.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item won't fit here: slight penalty for blocking chain packing.
            score += 4.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Discourage opening new bins when existing bins are reasonably empty.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let pressure = (mean_residual / bin_capacity as f64) * (open_bins_count as f64);
        score += 30.0 + 5.0 * pressure;
        // Late in the stream, avoid spawning bins with big residual capacity.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
    } else {
        // Mild bonus for filling bins that are already mostly consumed.
        let used = (bin_capacity - bin_residual) as f64;
        score -= 3.0 * (used / bin_capacity as f64);
    }

    // Global balance: prefer bins whose residual is below the mean residual
    // (targets bins that are closer to full than average).
    if !is_new_bin {
        let diff = mean_residual - bin_residual as f64;
        if diff > 0.0 {
            score -= 2.0 * diff.min(50.0);
        } else {
            score += 1.5 * (-diff).min(50.0);
        }
    }

    // Many open bins: consolidate to reduce fragmentation.
    score += 0.5 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // later in the stream, tight fits (small post_residual) are rewarded more aggressively.
    let norm_post = post / cap;
    let progress_weight = 0.5 + 2.0 * progress * progress;
    score -= progress_weight * (1.0 - norm_post) * (1.0 - norm_post) * cap * 0.35;

    // Penalize dead space quadratically: residual too small to matter is wasted.
    score += 0.6 * norm_post * norm_post * cap;

    // Reward using a nearly-full bin; smooth cubic saturation.
    let fill = 1.0 - norm_post;
    score -= 8.0 * fill * fill * fill;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0 + 10.0 * progress;
    }

    // New-bin candidate handling: empty bin gets a penalty so it is only chosen
    // when no open bin offers a decent fit; penalty eases late in the stream.
    if bin_residual == bin_capacity {
        score += 18.0 - 10.0 * progress + 2.0 * (open_bins_count as f64).sqrt();
    }

    // Lookahead coupling: if the next item fits the post-residual exactly-ish, reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            let slack = post - nxt;
            score -= 6.0 * (1.0 - slack / cap).max(0.0);
        } else {
            score += 3.0 * (nxt - post) / cap;
        }
    }

    // Mild penalty when this bin is far below mean residual (fragmentation avoidance).
    score += 0.05 * (mean_residual - post).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues near multiples of 10 are "usable"
    let r = post_residual % 10;
    let harmonic_bonus = match r {
        0 => -12.0,               // perfectly harmonic residual
        1 | 9 => -6.0,
        2 | 8 => -3.0,
        5 => 2.0,                 // half-slot residue, mildly awkward
        _ => 0.0,
    };
    score += harmonic_bonus;

    // Integer-division threshold: dead space penalty for tiny unusable slivers
    if post_residual < 10 {
        score += 25.0 * (10 - post_residual) as f64 / 10.0;
    }

    // Reward tight fits (small post_residual relative to item size)
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= tightness * 8.0;

    // Lookahead: if next item fits exactly in post_residual, strong reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            score -= 6.0;
        } else {
            // next item cannot use this residual: penalize proportionally
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: make it attractive only when open bins are crowded
    if bin_residual == bin_capacity {
        let crowding = mean_residual / bin_capacity as f64;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // penalty shrinks as bins fill up / stream progresses
        let new_bin_penalty = 30.0 * (1.0 - crowding.clamp(0.0, 1.0)) * (1.0 - 0.5 * progress);
        score += new_bin_penalty;
        // large items prefer fresh bins
        if item_size > bin_capacity / 2 {
            score -= 8.0;
        }
    }

    // Mild preference to spread load when many bins are open and mean residual is high
    if (bin_residual as f64) > mean_residual {
        score += 1.5;
    } else {
        score -= 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // plausible future item (<= 10) are wasted space -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Post-residuals that cannot fit the lookahead item are less useful.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 8.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // reward bins that can also swallow the next item
        score -= 6.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Tight fit bonus: fraction of bin consumed by this placement.
    let fill_frac = item_size as f64 / bin_residual as f64;
    score -= 15.0 * fill_frac;

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, prefer
    // filling existing bins; few open bins -> allow opening new ones.
    let pressure = (open_bins_count as f64).ln() * 5.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure; becomes attractive
        // only when item fits poorly everywhere else (score stays high there).
        score += 30.0 + pressure + item_size as f64 * 0.2;
    } else {
        score -= pressure * 0.5;
    }

    // Mild stream-progression term: later in the stream, prefer
    // consolidating into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 5.0 * progress;
    }

    // Prefer bins with residuals near the item (best-fit style) via mean
    // residual coupling: bins far below mean residual are precious.
    if (bin_residual as f64) < mean_residual {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item fits into post_residual
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0 + 0.5 * next_item_size as f64;
        // exact match of post_residual to next item is ideal
        let slack = (post_residual as i64 - next_item_size as i64) as f64;
        score -= 20.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // next item won't fit here; penalize wasted potential
        let miss = (next_item_size as f64 - post_residual as f64).min(bin_capacity as f64);
        score += 0.3 * miss;
    }

    // Penalize dead space relative to mean residual (keep residuals balanced)
    let dev = post_residual as f64 - mean_residual;
    score += 0.15 * dev * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: prefer it only when item fits poorly everywhere
    if bin_residual == bin_capacity {
        score += 30.0;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 10.0; // fresh bin allows a good pair
        }
    }

    // Late in stream: be greedy about filling bins tightly
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: reward tight fits (squash dead space nonlinearly).
    let fit_ratio = item_size as f64 / bin_residual as f64; // 0..1, 1 = perfect
    score -= 40.0 * fit_ratio * fit_ratio;

    // Strongly penalize large leftover slivers that likely become dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable gap
    } else if post_residual >= 10 && post_residual <= 20 {
        score += 8.0; // only fits smallest items
    }

    // Lookahead: if the next item fits exactly into the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chain
        } else if next_item_size <= post_residual {
            score -= 15.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item cannot use this bin's leftover; mild penalty for wasted space
            score += 6.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin should only win when fits are bad.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin; relax late in the stream or when
        // many bins are open with poor average residual (fragmented state).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let mut new_bin_penalty = 55.0;
        // If mean residual across open bins is low (fragmented), new bin is attractive.
        let frag = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        new_bin_penalty -= 30.0 * (1.0 - frag);
        // Slightly cheaper to open bins early (build reserve) when stream is long.
        new_bin_penalty -= 10.0 * (1.0 - progress) * if total_items > 200 { 1.0 } else { 0.0 };
        // Penalize opening new bins when item is small (easy to place anywhere).
        new_bin_penalty += (item_size as f64 - 50.0).max(0.0) * 0.3;
        score += new_bin_penalty;
    }

    // Mild preference for filling fuller bins among open bins (best-fit bias).
    let fullness = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 10.0 * fullness;

    // Discard spreading across too many open bins early; encourage consolidation.
    if open_bins_count > 4 && bin_residual > 0 {
        score += 2.0 * (open_bins_count as f64).ln();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Base: prefer small post residual (tight fit)
    let mut score = x;

    // Non-linear polynomial coupling with stream progress:
    // late in the stream, dead space becomes costlier -> penalize mid-range residuals more
    let mid = x * (1.0 - x); // peaks at x=0.5
    score += 2.0 * mid * (0.5 + progress);

    // Reward very tight fits increasingly with progress
    score -= (1.0 - x) * (1.0 - x) * (0.3 + 0.7 * progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 0.8 + 0.5 * progress;
    }

    // Penalty when many bins are open and residual is wasteful
    let open_norm = (open_bins_count as f64).ln1p();
    score += 0.05 * open_norm * mid;

    // Lookahead: if next item fits the post residual, reward this placement
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = (pr - nxt) as f64 / cap;
            score -= 0.5 * (1.0 - slack);
        } else {
            // next item won't fit; penalize leaving a gap next item can't use
            score += 0.3 * (nxt - pr) / cap;
        }
    }

    // Slight preference for bins below mean residual (balance load)
    score += 0.1 * (pr - mean_residual) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: classify post_residual by integer division into "dead space" buckets.
    // Small post_residual = tight fit (good). Buckets of width 10 (min item size).
    let tight_class = post_residual / 10;
    let tight_bonus = match tight_class {
        0 => 60.0,           // perfect/near-perfect fit
        1 => 30.0,           // very small gap, likely unusable anyway -> good
        2 => 10.0,           // moderate
        _ => 0.0,            // large residual, no bonus
    };
    score -= tight_bonus;

    // Penalize residual that next_item_size cannot use (wasted lookahead opportunity).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward leaving exactly enough room for the next item (chain packing).
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 - slack.min(25.0) * 0.4;
        } else {
            // Next item cannot follow into this bin: penalize proportionally.
            let gap = (next_item_size - post_residual) as f64;
            score += gap.min(80.0) * 0.5;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: an empty bin should only win when the current
    // fit is poor. Give the fresh bin a mild penalty so tight fits beat it,
    // but a bonus when open bins are fragmented.
    if bin_residual == bin_capacity {
        score += 35.0; // default handicap: prefer existing bins
        // If existing bins are heavily fragmented, opening fresh is attractive.
        if mean_residual > 0.0 {
            let frag = mean_residual / bin_capacity as f64;
            if frag > 0.55 {
                score -= (frag - 0.55) * 120.0;
            }
        }
        // Late in the stream, consolidate rather than open.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Modulo coupling: post_residual congruent classes mod 10 — residuals that
    // are multiples of the min size are more reusable by future items.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 5.0;
    }

    // Mild pressure to keep the number of open bins low.
    score += open_bins_count as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: overwhelming reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let dead = post_residual > 0 && post_residual < 10;
    if dead {
        score += 120.0 * (10 - post_residual) as f64;
        // Last-chance bin: accepting a small dead gap is better than opening a bin.
        if fitting_bins_count == 1 {
            score -= 90.0;
        }
        // If the next item could actually use the dead gap, soften penalty.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 60.0;
        } else if next_item_size > post_residual && next_item_size <= mean_residual {
            score += 40.0; // gap is truly unusable for the future
        }
    }

    // Reward snug fits in the mid-range (post_residual close to 0 relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize leaving large residuals when the bin is already crowded with open bins.
    score += 0.35 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when all open bins would leave bad gaps
    // or the item barely fits anywhere.
    if bin_residual == bin_capacity {
        let all_bad = fitting_bins_count > 0 && fitting_bins_count <= 1;
        if all_bad || dead {
            score -= 45.0;
        } else {
            score += 25.0 + 2.0 * open_bins_count as f64;
        }
        // Early in stream, prefer opening bins to build a spread of residuals.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if progress < 0.2 {
            score -= 15.0;
        }
    }

    // Mean-residual coupling: prefer bins whose residual is below average
    // (keeps large residuals available for large future items).
    if (bin_residual as f64) > mean_residual {
        score += 8.0;
    } else {
        score -= 4.0;
    }

    // Lookahead: if next item fits exactly in the post-residual, strong bonus.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 80.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post-residual (tight fit), but heavily reward
    // exact 2-step lookahead matches where the NEXT item fits perfectly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Perfect: next item exactly fills this bin afterwards.
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Next item still fits here: mild reward proportional to slack.
            score -= 8.0 + 0.05 * (post_residual - next_item_size) as f64;
        } else {
            // Next item cannot use the remaining space: penalize dead space,
            // worse when the leftover is small and unusable.
            let dead = post_residual as f64;
            if dead < 10.0 {
                score += 12.0 - dead; // tiny unusable sliver
            } else {
                score += 2.0; // moderate leftover, maybe reusable later
            }
        }
    } else {
        // Last item: just minimize leftover.
        score += 0.0;
    }

    // Prefer bins with residual already below mean (well-utilized bins):
    // placing here consolidates waste instead of spreading it.
    score += 0.15 * (bin_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when existing bins could fit reasonably
    // (new-bin candidate has bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 30.0;
        } else {
            score -= 5.0; // no alternative: new bin is fine
        }
    }

    // Late-stream consolidation: near the end, favor packing into
    // existing bins even more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress > 0.8 && bin_residual != bin_capacity {
        score -= 10.0 * progress;
    }

    // Slight preference for balancing load across bins early on.
    score += 0.02 * (open_bins_count as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) nonlinearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that cannot fit the next item (lookahead-aware).
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if (post_residual as f64) < nx {
            // dead space too small for next item: penalize proportionally
            score += 0.5 * post_residual as f64;
        } else {
            // post residual can host next item: reward
            score -= 8.0 * (1.0 - (post_residual as f64 / nx - 1.0).min(3.0) / 3.0);
        }
        // If this bin already could host next item too, extra reward (chaining)
        if bin_residual >= item_size + next_item_size {
            score -= 6.0;
        }
    } else {
        // Last item: just fill as tightly as possible
        score -= 10.0 * tightness;
    }

    // Last-chance bin bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin should usually lose to good fits,
    // but win when all open bins give awful fits.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin; cheaper late in the stream? actually
        // opening bins is unavoidable; make new bin attractive when open bins
        // are fragmented (low mean residual) or many bins already tight.
        score = (bin_capacity as f64) * 0.85; // default moderately high
        let frag = 1.0 - mean_residual / (bin_capacity as f64).max(1.0);
        score -= 20.0 * frag; // fragmented state favors fresh bin
        if fitting_bins_count == 0 {
            score -= 60.0; // no alternative
        }
        if next_item_size > 0 && (next_item_size as f64) <= bin_capacity as f64 {
            score -= 2.0; // fresh bin always fits next item
        }
    } else {
        // Prefer bins with residual close to item size (best-fit bias)
        let waste_ratio = (bin_residual - item_size) as f64 / (bin_capacity as f64);
        score += 15.0 * waste_ratio * waste_ratio;
    }

    // Mild time-horizon coupling: early on, be conservative with new bins;
    // late in stream, fill greedily.
    let t = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - t) * 2.0 * (post_residual as f64 / bin_capacity as f64);

    // Mild pressure to use existing bins when many are open.
    score -= (open_bins_count.min(20) as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let prog = step_index as f64 / total_items.max(1) as f64;
    let fill = 1.0 - post / cap;

    let mut score = post;

    // Smooth polynomial coupling: prefer high fill fraction, amplified as stream progresses.
    let coupling = (fill * fill * (2.0 - fill)) * (0.5 + prog) * cap;
    score -= 0.8 * coupling;

    // Dead-space penalty: quadratic in post_residual relative to capacity.
    score += 0.15 * (post * post) / cap;

    // Lookahead: reward if next item fits in the post residual (smooth falloff).
    if next_item_size > 0 {
        let gap = (post - next_item_size as f64).max(0.0);
        score -= 12.0 * (1.0 - gap / cap).max(0.0);
        // Penalize if next item would not fit (wasted space ahead).
        if next_item_size as f64 > post {
            score += 0.3 * (next_item_size as f64 - post);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 25.0 * (0.5 + fill);
    }

    // New-bin candidate handling: opening a new bin should only win when fits are poor.
    if bin_residual == bin_capacity {
        // Baseline new-bin score: neutral-ish, penalized mildly; grows with open bins.
        score = cap * (0.9 + 0.02 * open_bins_count as f64);
        // If current item leaves a nice residual elsewhere, new bin is less attractive.
        if post < cap * 0.5 {
            score += 10.0;
        }
    }

    // Slight preference to keep mean residual low (balance load).
    score += 0.05 * (post - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: leftovers divisible by small
    // units (10/20/25/50) are more likely to be reused by future items.
    let cap = bin_capacity as f64;
    let pr = post_residual;
    if pr > 0 {
        let mut harmony = 0.0;
        if pr % 50 == 0 { harmony += 14.0; }
        else if pr % 25 == 0 { harmony += 10.0; }
        else if pr % 20 == 0 { harmony += 9.0; }
        else if pr % 10 == 0 { harmony += 6.0; }
        else if pr % 5 == 0 { harmony += 3.0; }
        score -= harmony;

        // Integer-division thresholds on the leftover: classify dead space.
        // Tiny leftovers (<10) are dead space -> penalize strongly.
        if pr < 10 {
            score += 30.0 - 2.0 * pr as f64;
        } else if pr < 20 {
            score += 6.0;
        }
        // Perfect fit is ideal.
        if pr == 0 {
            score -= 40.0;
        }
    }

    // Fraction-of-capacity coupling: reward filling to a "clean" fraction
    // of the bin (>= 80% full) since dense bins waste less overall.
    let fill_frac = (bin_residual - post_residual) as f64 / cap;
    if fill_frac >= 0.8 {
        score -= 12.0 * fill_frac;
    } else {
        score += 4.0 * (0.8 - fill_frac);
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // this placement chains perfectly -> big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0;
        } else if next_item_size <= pr {
            // Next item fits, but how harmonically? Prefer small waste after chain.
            let chained_waste = pr - next_item_size;
            score -= 8.0 - (chained_waste as f64).min(8.0);
            if chained_waste % 10 == 0 && chained_waste > 0 {
                score -= 4.0;
            }
        } else {
            // Next item won't fit here; mildly penalize leaving a large
            // unusable-for-next gap unless it's a harmonic leftover.
            if pr >= next_item_size.saturating_sub(10) && pr < next_item_size {
                score += 5.0;
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening
    // a new bin unless the fit would be terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate handling: an empty bin has perfect residual but
    // should only win when no open bin gives a good (harmonic) fit.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 55.0;
        // If many bins are open and mean residual is large, opening a new
        // bin is relatively cheaper (dispersal strategy).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * (mean_residual / cap) * (1.0 - progress);
        // Early in the stream, new bins are cheaper (build diversity).
        score -= 15.0 * (1.0 - progress);
    }

    // Mild pressure against accumulating too many open bins late in stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual != bin_capacity {
        score += (open_bins_count as f64) * progress * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold even the
    // minimum item (size 1..=3) are pure waste; penalize them heavily.
    if post_residual > 0 && post_residual <= 3 {
        score += 60.0;
    }
    // Larger unusable gaps (below typical small item sizes) are also dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Reward tight fits: the smaller post_residual is relative to bin_capacity,
    // the better the packing (subtract proportionally).
    score -= (bin_capacity - post_residual) as f64 * 0.15;

    // Open-bin pressure: when many bins are already open, discourage opening new
    // ones; penalize the fresh-bin candidate (bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 * 0.8;
        // If this is the only fitting bin, opening a new bin wastes the leftover.
        let last_chance_bonus = if fitting_bins_count == 1 { -40.0 } else { 0.0 };
        score += 20.0 + pressure + last_chance_bonus;
    }

    // Last-chance bin: strongly favor using it to avoid a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Lookahead: if the next item fits exactly into the post_residual, reward
    // this placement (creates a perfect follow-up fit).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    }
    // If next item cannot fit into post_residual but would fit an empty bin,
    // slightly penalize leaving a gap that strands the next item.
    if next_item_size > post_residual as u32 && post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Mean residual coupling: prefer bins whose residual is below the mean
    // (i.e., nearly full bins) to consolidate open bins.
    let residual_f = post_residual as f64;
    if mean_residual > residual_f {
        score -= 5.0;
    } else {
        score += 5.0;
    }

    // Stream progression: early on, be slightly more willing to open new bins
    // (cheap now, more flexibility later); later, conserve bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward a post-residual that matches the next item exactly.
    if next_item_size > 0 {
        let diff = (post_residual as f64 - next_item_size as f64).abs();
        if diff == 0.0 {
            score -= 40.0; // perfect two-item pairing
        } else if post_residual >= next_item_size {
            score -= 15.0 * (1.0 - diff / (bin_capacity as f64));
            // bonus if next item fits leaving another near-perfect residual pattern
            if post_residual - next_item_size < 10 {
                score -= 8.0;
            }
        } else {
            // next item cannot use the leftover: dead space penalty scaled by gap
            score += 0.5 * (next_item_size as f64 - post_residual as f64);
        }
    } else {
        // last item: minimize leftover directly
        score += 0.3 * post_residual as f64;
    }

    // Penalize residuals far from mean residual structure (unbalanced bins)
    score += 0.2 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bin: strong reward to use it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin, unless the current item
    // would leave a large unusable remainder in every open bin.
    if bin_residual == bin_capacity {
        let waste_elsewhere = if next_item_size > 0 && post_residual < next_item_size {
            (next_item_size - post_residual) as f64
        } else {
            0.0
        };
        let new_bin_penalty = 30.0 + 0.4 * (bin_capacity as f64 - item_size as f64);
        score += new_bin_penalty - 0.8 * waste_elsewhere;
    }

    // Slight late-stream tightening: prefer tighter packing as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.1 * progress * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: post_residual too small to ever be useful
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward if next item fits into post_residual (chaining)
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 18.0;
        } else {
            // penalize leaving residual that neither fits next item nor is useful
            score += 6.0 * (next_item_size as f64 - post_residual as f64) / 100.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Prefer bins with residual below mean residual (consolidating fuller bins)
    score += 0.35 * (bin_residual as f64 - mean_residual);

    // Time horizon: early in stream, tolerate opening new bins less; late, prefer tight packing
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize early, allow late when open bins are crowded
        let crowding = (open_bins_count as f64).ln().max(1.0);
        score += 20.0 + 15.0 * (1.0 - progress) - 8.0 * crowding;
    } else {
        // Late in stream, prefer filling existing bins even more aggressively
        score -= 10.0 * progress;
    }

    // Mild penalty for too many open bins
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.8 * progress * x);

    // Smooth penalty for large dead space, amplified later in the stream
    score += 40.0 * x * x * (0.5 + progress);

    // Reward tight fits (small post_residual) more strongly as stream advances
    score -= 30.0 * (1.0 - x) * (1.0 - x) * (0.3 + 0.7 * progress);

    // Penalize opening a new bin when existing bins fit, more so late in stream
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 25.0 + 40.0 * progress;
    }

    // Last-chance bin bonus (only bin that fits): smooth reward
    if fitting_bins_count == 1 {
        score -= 20.0 * (1.0 - progress * 0.5);
    }

    // Lookahead: favor bins leaving room for the next item
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if n <= pr {
            score -= 12.0 * (1.0 - (pr - n) / cap);
        } else {
            score += 10.0 * (n - pr) / cap;
        }
    }

    // Slight pressure against bin sprawl
    score += open_bins_count as f64 * 0.05 * progress;

    // Mean residual coupling: prefer bins near the mean
    score += 5.0 * ((pr - mean_residual) / cap).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: exact-fit classes are prized.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Reward near-exact fits (post_residual small but not wastefully tiny).
    if post_residual == 0 {
        score -= 60.0; // perfect fit
    } else if post_residual <= 10 {
        score -= 40.0;
    } else if post_residual <= 20 {
        score -= 20.0;
    }

    // Modulo classes: residuals that are multiples of common item sizes (10, 20, 25)
    // are reusable by future items; penalize "odd" dead space.
    if post_residual > 0 {
        let reusable = (post_residual % 10 == 0) || (post_residual % 20 == 0) || (post_residual % 25 == 0);
        if reusable {
            score -= 12.0;
        } else {
            score += 6.0;
        }
        // Fractional capacity classes: residual in (0, cap/4] is nearly dead space.
        if post < cap * 0.1 {
            score += 4.0;
        } else if post > cap * 0.5 {
            score -= 8.0; // keeps bin flexible for medium items
        }
    }

    // Lookahead coupling: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 55.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.6;
        } else {
            // Next item won't fit here regardless; slight penalty for wasting flexibility.
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin fit is poor.
    if bin_residual == bin_capacity {
        score += 45.0 - 0.25 * mean_residual;
        // Early in stream, opening bins is cheaper (need spread).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 25.0 * (1.0 - progress);
    }

    // Congestion: many open bins with slack -> prefer filling existing ones.
    if open_bins_count > 4 && post_residual > 0.0 {
        score -= 0.5 * (open_bins_count as f64).ln();
    }

    // Mild preference for tighter residual overall.
    score += 0.05 * (mean_residual - post).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10.0 - post_residual as f64);
    }
    if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 60.0;
    }

    // Reward leaving room for the next item (lookahead k=2).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.25 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 {
        // Gap can't fit next item: dead space penalty scaled by gap size.
        score += 0.3 * post_residual as f64;
    }

    // Open-bins pressure: penalize contributing to bin sprawl lightly,
    // but reward using existing bins when many are open.
    score += 0.5 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when residual is tiny and item is large,
    // or when no open bin is a good home. Slight bias against opening new bins.
    if bin_residual == bin_capacity {
        score += 15.0;
        if item_size > 70 {
            score -= 10.0;
        }
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    }

    // Progress-aware mild tightening: later in stream, prefer tighter packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 3.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 35.0;
    } else if post_residual <= 10 {
        score -= 18.0;
    }

    // 2-step lookahead: reward bins whose leftover can host the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Leftover too small for next item: penalize dead space.
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Compare against mean residual: prefer bins that are already relatively full.
    let cap = bin_capacity as f64;
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize opening a new bin when open bins exist, scaled by stream progress.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 25.0 + 20.0 * progress;
    }

    // Mild penalty for leaving large unusable gaps.
    if post_residual > 0 && next_item_size > 0 && post_residual < 10 && post_residual < next_item_size {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) more aggressively when many bins compete.
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * (1.0 - tightness) * (1.0 - tightness);

    // Penalize dead space that is too small for likely future items (sizes 1..100).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 30 {
        score += 8.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // Mild dispersion penalty: prefer bins when competition is low.
        score += 2.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // Lookahead: reward bins whose post residual can host the next item exactly well.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0; // perfect pairing
        } else if post_residual >= next_item_size {
            score -= 10.0; // next item still fits
        } else {
            score += 6.0; // next item forced elsewhere
        }
    }

    // Global state coupling: when mean residual is high, prefer filling fuller bins
    // to consolidate space; when mean residual is low, opening bins is cheaper.
    let mean_gap = (mean_residual - post_residual as f64).abs();
    score += 0.3 * mean_gap;

    // Time horizon: late in the stream, avoid opening new bins; the new-bin candidate
    // (full residual) gets a penalty that grows with progress.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 20.0 + 80.0 * progress;
        // Early stream: new bins are fine (exploration), slight discount.
        score -= 18.0 * (1.0 - progress);
    }

    // Prefer bins that are already quite full (relative fullness reward).
    let fullness = 1.0 - (bin_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * fullness * fullness;

    // Many open bins: consolidate into existing ones rather than spreading.
    score += 1.5 * (open_bins_count as f64).sqrt();

    // Small regularization toward exact residual ordering.
    score += 0.05 * (post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let pr = post_residual as f64;
    let pn = pr / cap;
    let poly = pn * pn * (1.0 - progress) + pn * progress * progress;
    score += 8.0 * poly * cap * 0.1;

    // Reward tight fits more strongly as stream progresses
    let tightness = 1.0 - pn;
    score -= tightness * tightness * (1.0 + progress) * 6.0;

    // Last-chance bin bonus (avoid opening new bins unnecessarily)
    if fitting_bins_count == 1 {
        score -= 5.0 + 3.0 * progress;
    }

    // Lookahead: penalize wasting space needed by the next item
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if pr >= ns {
            let waste = (pr - ns) / cap;
            score += waste * waste * 4.0;
        }
        // Reward leaving exactly enough room for the next item
        let gap = (pr - ns).abs() / cap;
        score -= (1.0 - gap) * gap * 3.0;
    }

    // Mild penalty for opening a new bin when many bins are open
    if bin_residual == bin_capacity {
        score += 4.0 + 2.0 * (1.0 - progress) + 0.05 * open_bins_count as f64;
    }

    // Coupling with mean residual: prefer bins below mean residual (tighter bins)
    let dev = (mean_residual - pr) / cap;
    score += dev * dev * 2.0 - dev * 1.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how "usable" is the leftover space?
    // Residuals that are multiples of common small item sizes (10..20) are
    // reusable; awkward residuals (< 10, or odd small slivers) are dead space.
    let r = post_residual;
    if r == 0 {
        score -= 60.0; // perfect fit
    } else if r < 10 {
        score += 25.0; // dead sliver
    } else {
        let reusable = (r % 10 == 0) as f64 * 12.0
            + (r % 20 == 0) as f64 * 8.0
            + (r % 25 == 0) as f64 * 6.0
            + (r % 50 == 0) as f64 * 5.0;
        score -= reusable;
    }

    // Lookahead coupling: if next item fits exactly into post_residual,
    // strongly reward; if next item cannot fit, penalize mildly.
    if next_item_size > 0 {
        if next_item_size == r {
            score -= 40.0;
        } else if next_item_size < r {
            let gap = (r - next_item_size) as f64;
            score -= 10.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            score += 8.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate: only prefer when current bin fit is poor.
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        score -= 15.0 * tightness;
        if post_residual > 70 {
            score += 20.0; // would leave a mostly-empty new bin
        }
    }

    // Progression: early in stream, encourage consolidation into few bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 6.0 * (1.0 - progress) * (mean_residual - post_residual as f64).abs() / bin_capacity as f64;

    // Prefer bins whose residual is below mean (use up small leftovers first).
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
