    if bin_residual == bin_capacity {
        score += 30.0 + 0.2 * item_size as f64;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // New bin can host both items if they sum near capacity.
            if item_size + next_item_size >= 90 {
                score -= 70.0;
            }
