pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (low post_residual), with non-linear shaping
    let mut score = pr;

    // Smooth non-linear polynomial coupling of post_residual with stream progress:
    // later in the stream, dead space becomes more costly (superlinear penalty)
    let dead_penalty = norm_pr * norm_pr * (1.0 + 2.0 * progress);
    score += 40.0 * dead_penalty;

    // Reward near-perfect fits more strongly as the stream progresses
    let tightness = 1.0 - norm_pr;
    score -= 30.0 * tightness * tightness * tightness * (0.5 + progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // If many bins can fit the item, mild penalty so scarce-fit bins get priority
    if fitting_bins_count > 1 {
        score += 3.0 * (fitting_bins_count as f64 - 1.0).ln();
    }

    // Lookahead coupling: if next item fits exactly into the post-residual, reward
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let gap = (pr - nxt) / cap;
            score -= 20.0 * (1.0 - gap) * (1.0 - gap);
        } else {
            // next item won't fit here: penalize bins whose residual is awkwardly large
            score += 10.0 * norm_pr * (1.0 - progress);
        }
    }

    // Slight preference for keeping mean residual balanced (avoid fragmentation)
    score += 0.05 * (mean_residual - pr).abs();

    // New-bin candidate (empty bin): make it attractive only when residuals are bad
    if (bin_residual as f64 - cap).abs() < 1e-9 {
        let pressure = norm_pr.min(1.0); // 0 for empty bin itself
        let _ = pressure;
        score = cap * (1.0 + 0.5 * progress) - 15.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead-space taxonomy via modulo arithmetic.
    let pr = post_residual;
    let cap = bin_capacity as f64;

    // Perfect-fill bonus: residual exactly zero is ideal.
    if pr == 0 {
        score -= 1000.0;
    }

    // Harmonic residual classes: residuals that are exact divisors of capacity
    // (e.g. 50, 25, 20, 10) can be re-filled perfectly by common item sizes.
    if pr > 0 {
        if bin_capacity % pr == 0 {
            score -= 12.0; // harmonic slot: likely reusable
        }
        // Half / quarter capacity fractions are premium slots.
        if pr == bin_capacity / 2 {
            score -= 20.0;
        }
        if pr == bin_capacity / 4 || pr == (3 * bin_capacity) / 4 {
            score -= 8.0;
        }
    }

    // Penalize tiny dead space: post_residual in (0, 10) is nearly unusable
    // since item sizes >= 1 but small residuals waste capacity.
    if pr > 0 && pr < 10 {
        score += 25.0;
    }

    // Modulo-10 banding: items come in deciles; a residual that is a multiple
    // of 10 aligns with likely future item sizes.
    if pr % 10 == 0 {
        score -= 6.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly favor this bin (perfect chain).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 60.0;
        } else if next_item_size <= pr {
            // next item fits: penalize proportional leftover after the chain
            let chain_left = pr - next_item_size;
            score += chain_left as f64 * 0.3;
            if chain_left > 0 && bin_capacity % chain_left == 0 {
                score -= 5.0;
            }
        } else {
            // next item cannot use this bin's residual: mild penalty scaled
            // by how far off it is, modulated by progress through the stream.
            let progress = step_index as f64 / total_items.max(1) as f64;
            score += ((next_item_size - pr) as f64) * (0.1 + 0.2 * progress);
        }
    }

    // Last-chance logic: if this is the only fitting bin, avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Crowding pressure: with many open bins, prefer tightening existing ones
    // (best-fit bias) to avoid bin proliferation.
    score -= (open_bins_count as f64).ln().max(0.0) * 2.0;

    // Mean-residual anchoring: bins far from the mean residual get a nudge
    // toward selection when their residual is small (tight packing).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    // New-bin candidate: the empty bin has post_residual == capacity. Make it
    // unattractive unless no open bin fits well (large post_residual penalty
    // already handles this), but keep a small baseline cost.
    if bin_residual == bin_capacity {
        score += 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

