        if fitting_bins_count > 0 && post_residual < 10 {
            // Existing bins fit but poorly -> new bin is competitive.
            score -= 12.0;
        }
    } else {
        // Lookahead: penalize placements that block a similar-sized next item.
        if next_item_size > 0 && next_item_size <= bin_residual && next_item_size > post_residual {
            score += 8.0;
