        if next_item_size > 0 && post_residual == next_item_size {
            score -= 10.0;
        }
    }

    // Mean-residual coupling: if average open residual is small, wasting
    // space here is costlier; if it is large, prefer spreading load.
    if (post_residual as f64) > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.3;
    } else {
        score -= (mean_residual - post_residual as f64) * 0.2;
    }

    // Late-stream urgency: as the stream ends, prefer closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * (0.4 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
