    if bin_residual == bin_capacity {
        // Base cost of opening a new bin (discourage frivolous bin opening).
        score += 30.0;
        // More attractive late in the stream? Slightly cheaper early to build pool.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 10.0 * progress;
        // If existing bins are fragmented (low mean residual), a new bin is fine.
        score -= (mean_residual / bin_capacity as f64).max(0.0) * 15.0;
        // If many bins already open, prefer using them.
        score += open_bins_count as f64 * 1.5;
    } else {
        // Reward using existing bins, more so when many are open.
        score -= 2.0;
        // Prefer bins with residual close to item size (best-fit shaping)
        let diff = (bin_residual - item_size) as f64;
        score += diff * 0.05;
    }

    // Mild preference for filling nearly-full bins to consolidate load.
    let fill_ratio = 1.0 - bin_residual as f64 / bin_capacity as f64;
    score -= fill_ratio * 6.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post-residual, with smooth non-linear polynomial coupling to stream progress.
    let mut score = pr;

    // Polynomial shaping of post-residual: penalize tiny dead space more as stream advances.
    let shape = norm_pr * norm_pr * (1.0 - norm_pr) * (1.0 - norm_pr);
    score += 60.0 * shape * (0.3 + 0.9 * progress);

    // Reward tight fits smoothly (low post residual), stronger late in the stream.
    score -= 12.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (0.4 + 0.8 * progress);

    // Last-chance bin: smooth bonus when this is the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 8.0 + 10.0 * progress;
    } else {
        score += 2.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Lookahead coupling: if the next item fits in the post-residual, reward; else penalize smoothly.
    if next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        if gap >= 0.0 {
            score -= 6.0 * (1.0 - gap / cap);
        } else {
            score += 4.0 * ((-gap) / cap);
        }
    }

    // Deviation from mean residual: smooth quadratic penalty for outlier residuals.
    let dev = (pr - mean_residual) / cap;
    score += 15.0 * dev * dev * (0.5 + progress);

    // New-bin candidate handling: make empty bin mildly attractive early, costly late.
    if bin_residual == bin_capacity {
        score += 5.0 - 14.0 * progress;
    }

    // Mild preference for consolidating into fewer bins.
    score += 0.05 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues mod 10 create "waste bands".
    let residue = post_residual % 10;
    score -= (10 - residue) as f64 * 0.4; // prefer residuals landing near multiples of 10

    // Dead-space penalty for tiny unusable residuals (below typical small item size)
    if post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 8.0;
    }

    // Integer-division thresholds: post_residual buckets via capacity fractions
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    if post_residual < quarter {
        score += 4.0; // nearly-full bin: good to fill tightly
    } else if post_residual > half {
        score -= 2.0; // leaving a big hole is fine only if next item can use it
    }

    // Lookahead coupling: does next_item_size fit exactly into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let gap = post_residual - next_item_size;
            score -= 12.0; // next item fits
            if gap == 0 {
                score -= 15.0; // perfect harmonic closure
            } else if gap < 10 {
                score += 6.0; // creates new dead space
            }
            // harmonic class match: next_item_size residue aligns with post_residual class
            if (post_residual % 10) >= (next_item_size % 10) {
                score -= 3.0;
            }
        } else {
            score += 5.0; // next item won't fit here regardless
        }
    }

    // Last-chance bonus: only this bin can fit the item
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a bin unless current placement is bad
    if bin_residual == bin_capacity {
        score += 55.0;
        // allow new bin if mean residual is small (open bins nearly full)
        if mean_residual < 15.0 {
            score -= 40.0;
        }
        if open_bins_count == 0 {
            score -= 100.0;
        }
        // late in stream, prefer consolidating
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Prefer tighter fits: small post_residual relative to item size
    score += (item_size as f64) / (bin_capacity as f64) * 2.0;

    // Modulo coupling on item_size harmonic class
    let cls = item_size / 10;
    score -= cls as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item well
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual >= next_item_size {
            // next item can also fit here: strong reward, tighter match is better
            score -= 60.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // next item cannot follow: penalize proportionally to the leftover dead space
            score += 0.5 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Prefer bins tighter than the mean residual (best-fit flavor)
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // Mild penalty for opening a brand-new bin when open bins exist
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 25.0;
    }

    // Slight preference for reusing bins as the stream progresses
    score += 0.05 * (step_index as f64 / total_items.max(1) as f64) * (bin_residual == bin_capacity) as i32 as f64 * 10.0;

    score
}
